(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("dio-roman-history-3-e", [{"sp": "HDR", "t": "Ῥωμαϊκὴ Ἱστορία (Βιβλία ΛϚʹ–Μʹ)"}, {"sp": "HDR", "t": "Βιβλίον ΛϚʹ", "st": "36"}, {"sp": "N", "t": "… φείδεται. δυναστείας τε ἐρῶν καὶ τοῖς Κρησὶ τοῖς ὁμολογήσασιν αὐτῷ προσέβαλε, καὶ οὔτε τὰς σπονδὰς προτεινομένων σφῶν ἐφρόντιζε, κακῶσαί τε αὐτοὺς πρὶν τὸν Πομπήιον ἐπελθεῖν ἠπείγετο. ὅ τε γὰρ Ὀκτάουιος ἄνευ δυνάμεως παρών (οὐδὲ γὰρ οὐδὲ ἐπὶ πολέμῳ τινὶ ἀλλ’ ἐπὶ παραλήψει τῶν πόλεων ἐπέπεμπτο) ἡσυχίαν ἦγε· καὶ Κορνήλιος Σισέννας ὁ τῆς Ἑλλάδος ἄρχων ἦλθε μὲν ἐς τὴν Κρήτην, ὡς ταῦτ’ ἐπύθετο, καὶ παρῄνεσε τῷ Μετέλλῳ φείσασθαι τῶν δήμων, οὐ μέντοι καὶ ἀντέπραξέ τι μὴ πείσας. ἄλλοις τε οὖν πολλοῖς ἐκεῖνος ἐλυμήνατο, καὶ Ἐλευθέραν τὴν πόλιν ἐκ προδοσίας ἑλὼν ἠργυρολόγησε· πύργον γάρ τινα οἱ προδιδόντες ἔκ τε πλίνθων πεποιημένον καὶ μέγιστον δυσμαχώτατόν τε ὄντα ὄξει συνεχῶς νυκτὸς διέβρεξαν, ὥστε θραυστὸν γενέσθαι. καὶ μετὰ τοῦτο Λάππαν, καίτοι τοῦ Ὀκταουίου αὐτὴν κατέχοντος, ἐκ προσβολῆς εἷλε, καὶ ἐκεῖνον μὲν οὐδὲν κακὸν εἰργάσατο, τοὺς δὲ δὴ", "st": "36.18"}, {"sp": "N", "t": "Κίλικας τοὺς σὺν αὐτῷ ὄντας ἔφθειρεν. ἀγανακτήσας οὖν ἐπὶ τούτῳ ὁ Ὀκτάουιος οὐκέθ’ ἡσύχασεν, ἀλλὰ πρότερον μὲν τῷ τοῦ Σισέννου στρατῷ (νοσήσας γὰρ ἐκεῖνος ἐτεθνήκει) χρώμενος ἐπεβοήθει πῃ τοῖς κακουμένοις, ἔπειτα δ’ ἀνακομισθέντων αὐτῶν πρός τε τὸν Ἀριστίωνα ἐς Ἱεράπυδνα ἦλθε καὶ μετ’ αὐτοῦ ἐπολέμει· οὗτος γὰρ ὡς τότε ἐκ τῆς Κυδωνίας ἀπεχώρησε Λούκιόν τέ τινα Βάσσον ἀνταναχθέντα οἱ ἐνίκησε καὶ τὰ Ἱεράπυδνα κατέλαβε. καὶ χρόνον μέν τινα ἐκαρτέρησαν, τοῦ δὲ δὴ Μετέλλου ἐπιόντος σφίσι τό τε τεῖχος ἐξέλιπον, καὶ ἐξαναχθέντες χειμῶνί τε ἐχρήσαντο καὶ ἐς τὴν γῆν ἐκπεσόντες συχνοὺς ἀπέβαλον. κἀκ τούτου ὁ Μέτελλος πᾶσαν τὴν νῆσον ἐχειρώσατο. Κρῆτες μὲν οὖν οὕτως, ἐλεύθεροί τε πάντα τὸν ἔμπροσθεν χρόνον γενόμενοι καὶ δεσπότην ὀθνεῖον μηδένα κτησάμενοι, κατεδουλώθησαν· Μέτελλος δὲ τὴν μὲν ἐπίκλησιν ἀπ’ αὐτῶν ἔλαβε, τὸν δὲ δὴ Πανάρη τόν τε Λασθένη (καὶ γὰρ ἐκεῖνον εἷλεν) οὐκ ἠδυνήθη πέμψαι ἐν τοῖς ἐπινικίοις· ὁ γὰρ Πομπήιος ἀναπείσας τῶν δημάρχων τινὰ προαφείλετο αὐτοὺς ὡς καὶ ἑαυτῷ κατὰ τὴν ὁμολογίαν, ἀλλ’ οὐκ ἐκείνῳ προσχωρήσαντας.", "st": "36.19"}, {"sp": "N", "t": "λέξω δὲ ἤδη καὶ τὰ κατὰ τοῦτον πῶς ἐγένετο. οἱ καταποντισταὶ ἐλύπουν μὲν ἀεὶ τοὺς πλέοντας, ὥσπερ καὶ τοὺς ἐν τῇ γῇ οἰκοῦντας οἱ τὰς λῃστείας ποιούμενοι· οὐ γὰρ ἔστιν ὅτε ταῦτ’ οὐκ ἐγένετο, οὐδ’ ἂν παύσαιτό ποτε ἕως δἂν ἡ αὐτὴ φύσις ἀνθρώπων ᾖ. ἀλλὰ πρότερον μὲν ἔν τε τόποις τισὶ κἀν τῇ ὡραίᾳ μόνῃ, κατ’ ὀλίγους, καὶ ἐν τῇ γῇ καὶ ἐν τῇ θαλάσσῃ ἐλῄστευον· τότε δέ, ἐξ οὗ πολλαχῇ τε ἅμα καὶ συνεχῶς ἐπολεμήθη, καὶ πολλαὶ μὲν πόλεις ἀνάστατοι ἐγένοντο, πᾶσι δὲ καὶ τοῖς διαφεύγουσιν αὐτῶν αἱ τιμωρίαι ἐπηρτῶντο καὶ ἀδεὲς οὐδενὶ οὐδὲν ἦν, πάμπολλοι πρὸς λῃστείαν ἐτράποντο. καὶ τὰ μὲν ἐν ταῖς ἠπείροις λῃστικά, ἅτε καὶ ἐν ὀφθαλμοῖς τῶν δήμων μᾶλλον ὄντα, καὶ τήν τε αἴσθησιν τῆς βλάβης ἐγγύθεν καὶ τὴν σύλληψιν οὐ πάνυ χαλεπὴν ἔχοντα, ῥᾷόν πως κατελύετο, τὰ δὲ ἐν τῇ θαλάσσῃ ἐπὶ πλεῖστον ἐπηυξήθη. τῶν γὰρ Ῥωμαίων πρὸς τοὺς ἀντιπολέμους ἀσχολίαν ἀγόντων ἐπὶ πολὺ ἤκμασαν, πολλαχόσε τε περιπλέοντες καὶ πάντας τοὺς ὁμοίους σφίσι προστιθέμενοι, ὥστε τινὰς αὐτῶν καὶ ἐν συμμαχίας λόγῳ συχνοῖς ἐπικουρῆσαι.", "st": "36.20"}, {"sp": "N", "t": "καὶ εἴρηται μὲν ὅσα μετὰ τῶν ἄλλων ἔπραξαν. ἐπεὶ δ’ οὖν καὶ ἐκεῖνα διελύθη, οὐκ ἐπαύσαντο, ἀλλ’ αὐτοὶ καθ’ ἑαυτοὺς πολλὰ καὶ δεινὰ τούς τε Ῥωμαίους καὶ τοὺς συμμάχους σφῶν ἐκακούργησαν. οὔτε γὰρ κατ’ ὀλίγους ἔτι ἀλλὰ στόλοις μεγάλοις ἔπλεον, καὶ στρατηγοὺς εἶχον, ὥστε καὶ ὄνομα αὐτοὺς μέγα κεκτήσθαι· ἦγόν τε καὶ ἔφερον πρώτους μὲν καὶ μάλιστα τοὺς πλέοντας (οὐδὲ γὰρ τὴν χειμερινὴν ὥραν ἀσφαλῆ αὐτοῖς παρεῖχον, ἀλλ’ ὑπό τε τῆς τόλμης καὶ ὑπὸ τοῦ ἔθους τῆς τε εὐπραγίας καὶ τότ’ ἐπ’ ἀδείας ταῖς ναυτιλίαις ἐχρῶντο), ἔπειτα καὶ τοὺς ἐν τοῖς λιμέσιν ὄντας. καὶ γὰρ εἴ τις ἀνταναχθῆναί σφισιν ἐτόλμησε, μάλιστα μὲν ἡττηθεὶς ἀπώλετο, εἰ δὲ καὶ ἐνίκησεν, ἀλλ’ ἑλεῖν γε αὐτῶν οὐδένα ὑπὸ τοῦ ταχυναυτεῖν σφας ἐδύνατο, καὶ οὕτως ὑποστρέφοντες διὰ βραχέος ὡς καὶ κεκρατηκότες, τὰ μὲν ἔτεμνον καὶ κατεπίμπρων, οὐχ ὅτι χωρία καὶ ἀγρούς, ἀλλὰ καὶ πόλεις ὅλας, τὰ δὲ καὶ ᾠκειοῦντο, ὥστε καὶ χειμάδια καὶ ὁρμητήρια καθάπερ ἐν φιλίᾳ γῇ ποιεῖσθαι.", "st": "36.21"}, {"sp": "N", "t": "προχωρούντων δὲ αὐτοῖς τούτων καὶ ἐς τὴν ἤπειρον ἀνέβαινον, καὶ πολλὰ καὶ ἐκείνους τοὺς μηδὲ χρωμένους τῇ θαλάσσῃ ἐλύπουν. καὶ ταῦτα οὐ τὴν ἔξω συμμαχίδα αὐτῶν μόνον ἀλλὰ καὶ τὴν Ἰταλίαν αὐτὴν ἐποίουν· τά τε γὰρ κέρδη τὰ αὐτόθεν μείζω σχήσειν καὶ πάντας τοὺς λοιποὺς ἐπὶ πλέον ἐκφοβήσειν, ἂν μηδὲ ἐκείνης ἀπέχωνται, νομίζοντες, ἔς τε τὰς ἄλλας τὰς ταύτῃ πόλεις καὶ ἐς αὐτὰ τὰ Ὤστια ἐσέπλεον καὶ τάς τε ναῦς ἔκαιον καὶ πάνθ’ ἥρπαζον. καὶ τέλος, ὡς οὐδεμία σφῶν ἐπιστροφὴ ἐγίγνετο, τάς τε διατριβὰς ἐν τῇ γῇ ἐποιοῦντο, καὶ τοὺς ἀνθρώπους, ὅσους μὴ διώλλυσαν, τά τε σῦλα, ὅσα ἐλάμβανον, ἀδεῶς ὥς γε καὶ ἐν οἰκείᾳ διετίθεντο. καὶ ἐλῄστευον μὲν ἄλλοι ἄλλοθι (οὐ γάρ που ἐν πάσῃ ἅμα τῇ θαλάσσῃ οἱ αὐτοὶ κακουργεῖν ἐδύναντο), τοσαύτῃ μέντοι φιλίᾳ πρὸς ἀλλήλους ἐχρῶντο ὥστε σφᾶς καὶ χρήματα καὶ ἐπικουρίας καὶ τοῖς πάνυ ἀγνῶσιν ὡς καὶ οἰκειοτάτοις πέμπειν. καὶ διὰ τοῦτό γε οὐχ ἥκιστα ἴσχυσαν, ὅτι τούς τε θεραπεύοντάς τινας αὐτῶν πάντες ἐτίμων καὶ τοὺς προσκρούσαντάς τισι πάντες ἐλεηλάτουν.", "st": "36.22"}, {"sp": "N", "t": "ἐς τοσοῦτον μὲν δὴ τὰ τῶν καταποντιστῶν ἤρθη ὥστε καὶ μέγαν καὶ συνεχῆ καὶ ἀπροφύλακτον καὶ ἄπιστον τὸν πόλεμον αὐτῶν γενέσθαι· οἱ δὲ δὴ Ῥωμαῖοι ἤκουον μέν που αὐτά, καί τινα καὶ ἑώρων (οὔτε γὰρ ἄλλο τι τῶν ἐπακτῶν ἐφοίτα σφίσι καὶ ἡ σιτοπομπία παντελῶς ἀπεκέκλειτο), οὐ μέντοι καὶ μεγάλην, ὅτε γε ἐχρῆν, φροντίδα αὐτῶν ἐποιήσαντο, ἀλλ’ ἐξέπεμπον μὲν καὶ ναυτικὰ καὶ στρατηγούς, ὥς που καθ’ ἕκαστον τῶν προσαγγελλομένων ἐκινοῦντο, ἔπραττον δ’ οὐδέν, ἀλλὰ καὶ πολὺ πλείω τοὺς συμμάχους δι’ αὐτῶν ἐκείνων ἐταλαιπώρουν, μέχρις οὗ ἐν παντὶ ἐγένοντο. τότε δὲ συνελθόντες ἐβουλεύσαντο ἐπὶ πολλὰς ἡμέρας ὅ τι καὶ χρὴ πρᾶξαι. τῇ τε γὰρ συνεχείᾳ τῶν κινδύνων τετρυχωμένοι, καὶ μέγαν καὶ πολὺν τὸν πρὸς αὐτοὺς πόλεμον ὁρῶντες ὄντα, καὶ οὔθ’ ἅμα πᾶσί σφισιν οὔτ’ αὖ καθ’ ἑκάστους προσπολεμῆσαι δυνατὸν εἶναι νομίζοντες (ἀλλήλοις τε γὰρ συνεβοήθουν, καὶ πανταχοῦ ἅμα ἀμήχανον ἦν αὐτοὺς ἀμύνασθαι) ἔν τε ἀπορίᾳ καὶ ἀνελπιστίᾳ τοῦ κατορθώσειν τι πολλῇ ἐγένοντο, πρὶν δὴ Αὖλός τις Γαβίνιος δήμαρχος γνώμην ἔδωκεν, εἴτ’ οὖν τοῦ Πομπηίου καθέντος αὐτόν, εἴτε καὶ ἄλλως χαρίσασθαί οἱ ἐθελήσας (οὐ γάρ που καὶ ὑπ’ εὐνοίας αὐτὸ τῆς τοῦ κοινοῦ ἐποίησε· κάκιστος γὰρ ἀνὴρ ἦν), στρατηγὸν ἕνα αὐτοκράτορα ἐφ’ ἅπαντας αὐτοὺς ἐκ τῶν ὑπατευκότων ἑλέσθαι, τρισί τε ἔτεσιν ἄρξοντα καὶ δυνάμει παμπληθεῖ μεθ’ ὑποστρατήγων πολλῶν χρησόμενον. ἄντικρυς μὲν γὰρ τὸ τοῦ Πομπηίου ὄνομα οὐκ εἶπεν· εὔδηλον δὲ ἦν ὅτι, ἂν ἅπαξ τι τοιοῦτον ὁ ὅμιλος ἀκούσῃ, ἐκεῖνον αἱρήσεται.", "st": "36.23"}, {"sp": "N", "t": "καὶ ἔσχεν οὕτω· τήν τε γὰρ ἐσήγησιν αὐτοῦ ἀπεδέξαντο, καὶ πρὸς τὸν Πομπήιον παραχρῆμα πάντες πλὴν τῆς γερουσίας ἀπέκλιναν. αὕτη γὰρ πᾶν ὁτιοῦν ὑπὸ τῶν λῃστῶν παθεῖν μᾶλλον ἢ ἐκείνῳ τοσαύτην ἡγεμονίαν ἐγχειρίσαι ᾑρεῖτο· καὶ ὀλίγου καὶ ἀπέκτειναν τὸν Γαβίνιον ἐν αὐτῷ τῷ συνεδρίῳ. ὑπεκδράντος δ’ οὖν πῃ αὐτοῦ μαθόντες οἱ πολλοὶ τὴν τῶν βουλευτῶν γνώμην ἐθορύβησαν, ὥστε καὶ ἐπ’ αὐτοὺς συγκαθημένους ἐφορμῆσαι· καὶ εἴ γε μὴ ἐξεκεχωρήκεσαν, πάντως ἂν αὐτοὺς διεφθάρκεσαν. οἱ μὲν δὴ οὖν ἄλλοι σκεδασθέντες διέλαθον, Πίσωνα δὲ τὸν Γάιον τὸν ὕπατον (ἐπὶ γὰρ ἐκείνου τοῦ τε Ἀκιλίου ταῦτ’ ἐγίγνετο) συλληφθέντα καὶ μέλλοντα καὶ ἀντὶ τῶν ἄλλων ἀπόλλυσθαι ὁ Γαβίνιος ἐξῃτήσατο. ἐκ δὲ τούτου οἱ δυνατοὶ αὐτοὶ μὲν τὴν ἡσυχίαν ἦγον, ἀσμενίζοντες ἄν τίς σφας ζῆν ἐάσῃ, τοὺς δὲ δημάρχους τοὺς ἐννέα ἀνέπεισαν ἐναντιωθῆναι τῷ Γαβινίῳ. καὶ αὐτῶν οἱ μὲν ἄλλοι φοβηθέντες τὸ πλῆθος οὐδὲν ἀντεῖπον, Λούκιος δὲ δή τις Τρεβέλλιος καὶ Λούκιος Ῥώσκιος ἐτόλμησαν μέν, οὐκ ἠδυνήθησαν δὲ οὔτ’ εἰπεῖν τι ὧν ὑπέσχηντο οὔτε πρᾶξαι. ἐπειδὴ γὰρ ἡ κυρία ἡμέρα, ἐν ᾗ τὴν γνώμην ἐπικυρωθῆναι ἔδει, ἐνέστη, τάδε ἐγένετο. ὁ Πομπήιος ἐπιθυμῶν μὲν πάνυ ἄρξαι, καὶ ἤδη γε ὑπό τε τῆς ἑαυτοῦ φιλοτιμίας καὶ ὑπὸ τῆς τοῦ δήμου σπουδῆς οὐδὲ τιμὴν ἔτι τοῦτο, ἀλλ’ ἀτιμίαν τὸ μὴ τυχεῖν αὐτοῦ νομίζων εἶναι, τὴν δὲ ἀντίταξιν τῶν δυνατῶν ὁρῶν, ἠβουλήθη δοκεῖν ἀναγκάζεσθαι. ἦν μὲν γὰρ καὶ ἄλλως ὡς ἥκιστα προσποιούμενος ἐπιθυμεῖν ὧν ἤθελε· τότε δὲ καὶ μᾶλλον, διά τε τὸ ἐπίφθονον ἄν γε ἑκὼν τῆς ἀρχῆς ἀντιποιήσηται, καὶ διὰ τὸ εὐκλεὲς ἄν γε καὶ ἄκων ὥς γε καὶ ἀξιοστρατηγητότατος ὢν ἀποδειχθῇ, ἐπλάττετο.", "st": "36.24"}, {"sp": "N", "t": "καὶ παρελθὼν ἔφη “χαίρω μὲν τιμώμενος ὑφ’ ὑμῶν, ὦ Κυιρῖται· φύσει τε γὰρ πάντες ἄνθρωποι καὶ ἐγκαλλωπίζονται ταῖς παρὰ τῶν πολιτῶν εὐεργεσίαις, καὶ ἐγώ, ἅτε δὴ πολλάκις τῆς παρ’ ὑμῶν τιμῆς ἀπολελαυκώς, οὐκ ἔχω πῶς κατ’ ἀξίαν ἡσθῶ τοῖς παροῦσιν· οὐ μέντοι οὔθ’ ὑμῖν νομίζω προσήκειν ἀπλήστως οὕτω πρός με διακεῖσθαι, οὔτε ἐμοὶ διὰ παντὸς ἔν τινι ἡγεμονίᾳ εἶναι. αὐτός τε γὰρ ἐκ παίδων κέκμηκα, καὶ ὑμᾶς δεῖ καὶ περὶ τοὺς ἄλλους σπουδάζειν. ἢ οὐ μέμνησθε ὅσα μὲν ἐν τῷ πρὸς τὸν Κίνναν πολέμῳ ἐταλαιπώρησα, καίτοι κομιδῇ νέος ὤν, ὅσα δὲ ἔν τε τῇ Σικελίᾳ καὶ ἐν τῇ Ἀφρικῇ ἔκαμον, μηδέπω καθαρῶς ἐς ἐφήβους τελῶν, ὅσα δὲ ἐν τῇ Ἰβηρίᾳ ἐκινδύνευσα, μηδὲ βουλεύων πω; ἐφ’ οἷς ἅπασιν οὐχ ὅτι ἀχάριστοι πρός με ἐγένεσθε ἐρῶ. πόθεν; πολλοῦ γε καὶ δεῖ· πρὸς γὰρ τοῖς ἄλλοις ὧν πολλῶν καὶ μεγάλων παρ’ ὑμῶν ἠξιώθην, καὶ αὐτὸ τὸ πιστευθῆναί με τὴν ἐπὶ τὸν Σερτώριον στρατηγίαν, μηδενὸς ἄλλου μήτ’ ἐθελήσαντος μήτε δυνηθέντος αὐτὴν ὑποστῆναι, τό τε ἐπινίκια καὶ ἐπ’ ἐκείνῃ παρὰ τὸ νενομισμένον πέμψαι μεγίστην μοι τιμὴν ἤνεγκεν. ἀλλ’ ὅτι πολλὰς μὲν φροντίδας πολλοὺς δὲ κινδύνους ὑπέμεινα, κατατέτριμμαι μὲν τὸ σῶμα, πεπόνημαι δὲ τὴν γνώμην. μὴ γὰρ ὅτι νέος ἔτ’ εἰμὶ λογίζεσθε, μηδ’ ὅτι ἔτη τόσα καὶ τόσα γέγονα ἀριθμεῖσθε. ἂν γάρ τοι καὶ τὰς στρατείας ἃς ἐστράτευμαι καὶ τοὺς κινδύνους οὓς κεκινδύνευκα ἀναριθμήσητε, πολύ γε πλείους αὐτοὺς τῶν ἐτῶν εὑρήσετε, καὶ μᾶλλον οὕτω πιστεύσετε ὅτι οὔτε πρὸς τοὺς πόνους οὔτε πρὸς τὰς φροντίδας καρτερεῖν ἔτι δύναμαι.", "st": "36.25"}, {"sp": "N", "t": "εἰ δ’ οὖν τις καὶ πρὸς ταῦτα ἀντέχοι, ἀλλ’ ὁρᾶτε ὅτι καὶ ἐπίφθονα καὶ μισητὰ πάντα τὰ τοιαῦτά ἐστιν· ἅπερ ὑμεῖς μὲν ἐν οὐδενὶ λόγῳ τίθεσθε (οὐδὲ γὰρ καλῶς ἔχει προσποιεῖσθαί τι ὑμᾶς αὐτῶν), ἐμοὶ μέντοι βαρύτατα ἂν γένοιτο, καὶ ὁμολογῶ γε μηδ’ ὑφ’ ἑνὸς οὕτω τῶν ἐν τοῖς πολέμοις δεινῶν μήτε ἐκταράττεσθαι μήτε λυπεῖσθαι ὡς ὑπὸ τῶν τοιούτων. τίς μὲν γὰρ ἂν εὖ φρονῶν ἡδέως παρ’ ἀνθρώποις φθονοῦσιν αὐτῷ ζῴη, τίς δ’ ἂν δημόσιόν τι διοικῆσαι προθυμηθείη μέλλων, ἂν μὲν ἀποτύχῃ, δίκην ὑφέξειν, ἂν δὲ κατορθώσῃ, ζηλοτυπηθήσεσθαι; ἀλλ’ ἐμοὶ μὲν καὶ διὰ ταῦτα καὶ διὰ τἆλλα συγχωρήσατε τήν τε ἡσυχίαν ἄγειν καὶ τὰ ἐμαυτοῦ πράττειν, ἵν’ ἤδη ποτὲ καὶ τῶν οἰκείων ἐπιμεληθῶ καὶ μὴ κατατριφθεὶς ἀπόλωμαι· ἐπὶ δὲ δὴ τοὺς καταποντιστὰς ἄλλον χειροτονήσατε. συχνοὶ δέ εἰσι καὶ βουλόμενοι ναυαρχῆσαι καὶ δυνάμενοι, καὶ νεώτεροι καὶ πρεσβύτεροι, ὥστε τὴν αἵρεσιν ὑμῖν ῥᾳδίαν ἐκ πολλῶν γενέσθαι. οὐ γάρ που ἐγὼ μόνος ὑμᾶς φιλῶ ἢ καὶ μόνος ἐμπείρως τῶν πολεμικῶν ἔχω, ἀλλὰ καὶ ὁ δεῖνα καὶ ὁ δεῖνα, ἵνα μὴ καὶ χαρίζεσθαί τισι δόξω ὀνομαστὶ καταλέξας.”", "st": "36.26"}, {"sp": "N", "t": "ταῦτα αὐτοῦ δημηγορήσαντος ὁ Γαβίνιος ὑπολαβὼν εἶπεν “Πομπήιος μέν, ὦ Κυιρῖται, καὶ αὐτὸ τοῦτο ἄξιον τῶν ἑαυτοῦ ἠθῶν ποιεῖ, μήτε ἐφιέμενος τῆς ἀρχῆς μήτε διδομένην οἱ αὐτὴν ἐξ ἐπιδρομῆς δεχόμενος. οὔτε γὰρ ἄλλως ἀγαθοῦ ἀνδρός ἐστιν ἄρχειν ἐπιθυμεῖν καὶ τὰ πράγματ’ ἔχειν ἐθέλειν· κἀν τούτῳ προσήκει πάντα τὰ προσταττόμενα μετ’ ἐπισκέψεως ὑφίστασθαι, ἵν’ αὐτὰ καὶ ἀσφαλῶς ὁμοίως πράξῃ. τὸ μὲν γὰρ προπετὲς ἐν ταῖς ὑποσχέσεσιν, ὀξύτερον καὶ ἐν ταῖς πράξεσι τοῦ καιροῦ γιγνόμενον, πολλοὺς σφάλλει, τὸ δ’ ἀκριβὲς ἀπ’ ἀρχῆς καὶ ἐν τοῖς ἔργοις ὅμοιον διατελεῖ ὂν καὶ πάντας ὀνίνησιν. ὑμᾶς δὲ δὴ χρὴ μὴ τὸ τούτῳ κεχαρισμένον ἀλλὰ τὸ τῇ πόλει συμφέρον ἑλέσθαι. οὐ γάρ που τοὺς σπουδαρχοῦντας ἀλλὰ τοὺς ἐπιτηδείους προστάττειν τοῖς πράγμασι προσήκει· ἐκείνους μὲν γὰρ πάνυ πολλούς, τοιοῦτον δὲ δή τινα ἄλλον οὐδένα εὑρήσετε. μέμνησθε δὲ ὅσα καὶ οἷα ἐπάθομεν ἐν τῷ πρὸς τὸν Σερτώριον πολέμῳ στρατηγοῦ δεόμενοι, καὶ ὅτι οὐδένα ἕτερον οὔτε τῶν νεωτέρων οὔτε τῶν πρεσβυτέρων ἁρμόζοντα αὐτῷ εὕρομεν, ἀλλὰ τοῦτον καὶ τότε μηδέπω μήθ’ ἡλικίαν ἔχοντα μήτε βουλεύοντα καὶ ἀντὶ ἀμφοτέρων τῶν ὑπάτων ἐξεπέμψαμεν. βουλοίμην μὲν γὰρ ἂν πολλοὺς ὑμῖν ἀγαθοὺς ἄνδρας εἶναι, καὶ εἴγε καὶ εὔξασθαι δεῖ, εὐξαίμην ἄν· ἐπεὶ δ’ οὔτ’ εὐχῆς τὸ πρᾶγμα τοῦτό ἐστιν οὔτ’ αὐτόματόν τῳ παραγίγνεται, ἀλλὰ δεῖ καὶ φῦναί τινα πρὸς αὐτὸ ἐπιτηδείως, καὶ μαθεῖν τὰ πρόσφορα, καὶ ἀσκῆσαι τὰ προσήκοντα, καὶ παρὰ πάντα ἀγαθῇ τύχῃ χρῆσθαι, ἅπερ που σπανιώτατα ἂν τῷ αὐτῷ ἀνδρὶ συμβαίη, χρὴ πάντας ὑμᾶς ὁμοθυμαδόν, ὅταν τις τοιοῦτος εὑρεθῇ, καὶ σπουδάζειν αὐτὸν καὶ καταχρῆσθαι αὐτῷ, κἂν μὴ βούληται. καλλίστη γὰρ ἡ τοιαύτη βία καὶ τῷ ποιήσαντι καὶ τῷ παθόντι γίγνεται, τῷ μὲν ὅτι σωθείη ἂν ὑπ’ αὐτῆς, τῷ δὲ ὅτι σώσειεν ἂν τοὺς πολίτας, ὑπὲρ ὧν καὶ τὸ σῶμα καὶ τὴν ψυχὴν ὅ γε χρηστὸς καὶ φιλόπολις ἑτοιμότατα ἂν ἐπιδοίη.", "st": "36.27"}, {"sp": "N", "t": "ἢ οἴεσθε ὅτι Πομπήιος οὗτος ἐν μὲν μειρακίῳ καὶ στρατεύεσθαι καὶ στρατηγεῖν καὶ τὰ ὑμέτερα αὔξειν καὶ τὰ τῶν συμμάχων σώζειν τά τε τῶν ἀνθισταμένων προσκτᾶσθαι ἐδύνατο, νῦν δὲ ἀκμάζων καὶ ἐν ταύτῃ τῇ ἡλικίᾳ ὢν ἐν ᾗ πᾶς τις ἄριστος αὐτὸς αὑτοῦ γίγνεται, καὶ ἐμπειρίαν ἐκ τῶν πολέμων πλείστην ὅσην προσειληφώς, οὐκ ἂν ὑμῖν χρησιμώτατος γένοιτο; ἀλλ’ ὃν ἔφηβον ὄντα ἄρχειν εἵλεσθε, τοῦτον ἄνδρα γεγονότα ἀποδοκιμάσετε; καὶ ᾧ ἱππεῖ ἔτ’ ὄντι τοὺς πολέμους ἐκείνους ἐνεχειρίσατε, τούτῳ βουλῆς γεγονότι τὴν στρατείαν ταύτην οὐ πιστεύσετε; καὶ οὗ καὶ πρὶν ἀκριβῶς πειραθῆναι, μόνου πρὸς τὰ τότε κατεπείξαντα ὑμᾶς ἐδεήθητε, τούτῳ νῦν, ἱκανώτατα αὐτοῦ πεπειραμένοι, τὰ παρόντα οὐδὲν ἧττον ἐκείνων ἀναγκαῖα ὄντα οὐκ ἐπιτρέψετε; καὶ ὃν οὐδὲ ἄρχειν ἔτι πω καὶ τότε δυνάμενον ἐπὶ τὸν Σερτώριον ἐχειροτονήσατε, τοῦτον ὑπατευκότα ἤδη ἐπὶ τοὺς καταποντιστὰς οὐκ ἐκπέμψετε; ἀλλὰ μήθ’ ὑμεῖς ἄλλως πως ποιήσητε, καὶ σύ, ὦ Πομπήιε, πείσθητι καὶ ἐμοὶ καὶ τῇ πατρίδι. ταύτῃ γὰρ γεγέννησαι καὶ ταύτῃ τέθραψαι· καὶ δεῖ σε τοῖς τε συμφέρουσιν αὐτῇ δουλεύειν, καὶ ὑπὲρ αὐτῶν μήτε πόνον τινὰ μήτε κίνδυνον ἐξίστασθαι, ἀλλὰ κἂν ἀποθανεῖν ἀνάγκη σοι γένηται, μὴ τὴν εἱμαρμένην ἀναμεῖναι ἀλλὰ τῷ προστυχόντι", "st": "36.28"}, {"sp": "N", "t": "θανάτῳ χρῆσθαι. γελοῖος δὲ δήπουθέν εἰμι ταῦτα ἐγὼ σοὶ παραινῶν, ὅστις ἐν τοσούτοις καὶ τηλικούτοις πολέμοις καὶ τὴν ἀνδρείαν καὶ τὴν πρὸς τὴν πατρίδα εὔνοιαν ἐπιδέδειξαι. πείσθητι οὖν καὶ ἐμοὶ καὶ τούτοις, μηδὲ ὅτι τινὲς φθονοῦσι φοβηθῇς, ἀλλὰ καὶ δι’ αὐτὸ τοῦτο μᾶλλον σπούδασον, ὥστε πρός τε τὴν παρὰ τῶν πλειόνων φιλίαν καὶ πρὸς τὰ κοινῇ πᾶσιν ἡμῖν συμφέροντα καὶ τῶν βασκαινόντων σε καταφρόνει. καὶ εἴγε καὶ λυπῆσαί τι αὐτοὺς ἐθέλεις, καὶ διὰ τοῦτο ἄρξον, ἵνα καὶ ἐκείνους ἀνιάσῃς παρὰ γνώμην αὐτῶν καὶ ἡγεμονεύσας καὶ εὐδοκιμήσας, καὶ αὐτὸς ἄξιον σεαυτοῦ τέλος τοῖς προκατειργασμένοις ἐπαγάγῃς, πολλῶν καὶ μεγάλων κακῶν ἡμᾶς ἀπαλλάξας.”", "st": "36.29"}, {"sp": "N", "t": "τοιαῦτα δὴ τοῦ Γαβινίου εἰπόντος ὁ Τρεβέλλιος ἐπειράθη μὲν ἀντειπεῖν, ὡς δ’ οὐδενὸς λόγου ἔτυχεν, ἠναντιοῦτο μὴ τὴν ψῆφον δοθῆναι. ὁ οὖν Γαβίνιος ἀγανακτήσας τὴν μὲν περὶ τοῦ Πομπηίου διαψήφισιν ἐπέσχεν, ἑτέραν δὲ περὶ αὐτοῦ ἐκείνου ἀντεσῆγε· καὶ ἔδοξεν ἑπτακαίδεκα φυλαῖς ταῖς πρώταις χρηματισάσαις ἀδικεῖν τε αὐτὸν καὶ μηκέτι χρῆναι δημαρχεῖν. μελλούσης οὖν καὶ τῆς ὀκτωκαιδεκάτης τὰ αὐτὰ ψηφιεῖσθαι μόλις ποτὲ ὁ Τρεβέλλιος ἐσιώπησεν. ἰδὼν δὲ τοῦτο ὁ Ῥώσκιος φθέγξασθαι μὲν οὐδὲν ἐτόλμησε, τὴν δὲ δὴ χεῖρα ἀνατείνων δύο ἄνδρας ἐκέλευέ σφας ἑλέσθαι, ὅπως ἔν γε τούτῳ τῆς δυναστείας ⟨τι⟩ τῆς τοῦ Πομπηίου παρατέμοιτο. ταῦτ’ οὖν αὐτοῦ χειρονομοῦντος ὁ ὅμιλος μέγα καὶ ἀπειλητικὸν ἀνέκραγεν, ὥστε κόρακά τινα ὑπερπετόμενόν σφων ἐκπλαγῆναι καὶ πεσεῖν ὥσπερ ἐμβρόντητον. γενομένου δὲ τούτου ἐκεῖνος μὲν τὴν ἡσυχίαν οὐ τῇ γλώττῃ ἔτι μόνον ἀλλὰ καὶ τῇ χειρὶ ἤγαγεν, ὁ δὲ δὴ Κάτουλος ἄλλως μὲν ἐσιώπα, τοῦ δὲ δὴ Γαβινίου προτρεψαμένου τι αὐτὸν εἰπεῖν, ὅτι τά τε πρῶτα τῆς βουλῆς ἦν καὶ ἐδόκει δι’ ἐκείνου καὶ τοὺς ἄλλους ὁμογνωμονήσειν σφίσι (καὶ γὰρ ἤλπιζεν αὐτόν, ἐξ ὧν τοὺς δημάρχους πάσχοντας εἶδε, συνεπαινέσειν), λόγου τε ἔτυχεν, ἐπειδὴ καὶ ᾐδοῦντο πάντες αὐτὸν καὶ ἐτίμων ὡς τὰ συμφέροντά σφισι καὶ λέγοντα ἀεὶ καὶ πράττοντα, καὶ ἐδημηγόρησε τοιάδε.", "st": "36.30"}, {"sp": "N", "t": "“ὅτι μὲν ἐς ὑπερβολήν, ὦ Κυιρῖται, πρὸς τὸ πλῆθος ὑμῶν ἐσπούδακα, πάντες που σαφῶς ἐπίστασθε· τούτου δὲ δὴ οὕτως ἔχοντος ἐμοὶ μὲν ἀναγκαῖόν ἐστι πάντα ἁπλῶς, ἃ γιγνώσκω συμφέρειν τῇ πόλει, μετὰ παρρησίας εἰπεῖν, καὶ ὑμῖν προσῆκον ἀκοῦσαί τε μεθ’ ἡσυχίας αὐτῶν καὶ μετὰ τοῦτο βουλεύσασθαι· θορυβήσαντες μὲν γὰρ ἴσως τι καὶ χρήσιμον δυνηθέντες ἂν μαθεῖν οὐχὶ λήψεσθε, προσέχοντες δὲ τοῖς λεγομένοις πάντως τι τῶν συμφερόντων ὑμῖν ἀκριβῶς εὑρήσετε. ἐγὼ τοίνυν πρῶτον μὲν καὶ μάλιστά φημι δεῖν μηδενὶ ἑνὶ ἀνδρὶ τοσαύτας κατὰ τὸ ἑξῆς ἀρχὰς ἐπιτρέπειν. τοῦτο γὰρ καὶ ἐν τοῖς νόμοις ἀπηγόρευται καὶ πείρᾳ σφαλερώτατον ὂν πεφώραται. οὔτε γὰρ τὸν Μάριον ἄλλο τι ὡς εἰπεῖν τοιοῦτον ἐποίησεν ἢ ὅτι τοσούτους τε ἐν ὀλιγίστῳ χρόνῳ πολέμους ἐνεχειρίσθη καὶ ὕπατος ἑξάκις ἐν βραχυτάτῳ ἐγένετο, οὔτε τὸν Σύλλαν ἢ ὅτι τοσούτοις ἐφεξῆς ἔτεσι τὴν ἀρχὴν τῶν στρατοπέδων ἔσχε καὶ μετὰ τοῦτο δικτάτωρ, εἶθ’ ὕπατος ἀπεδείχθη. οὐ γάρ ἐστιν ἐν τῇ τῶν ἀνθρώπων φύσει ψυχήν, μὴ ὅτι νέαν ἀλλὰ καὶ πρεσβυτέραν, ἐν ἐξουσίαις ἐπὶ πολὺν χρόνον ἐνδιατρίψασαν τοῖς πατρίοις ἔθεσιν ἐθέλειν ἐμμένειν.", "st": "36.31"}, {"sp": "N", "t": "καὶ τοῦτο μὲν οὐχ ὡς καὶ κατεγνωκώς τι τοῦ Πομπηίου λέγω, ἀλλ’ ὅτι μήτ’ ἄλλως συνενεγκόν ποτε ὑμῖν φαίνεται μήτε ἐκ τῶν νόμων ἐπιτέτραπται. καὶ γὰρ εἴτε τιμὴν τοῖς ἀξιουμένοις αὐτοῦ φέρει, πᾶσιν αὐτῆς, οἷς γε ἐπιβάλλει, προσήκει τυγχάνειν (τοῦτο γάρ ἐστιν ἡ δημοκρατία), εἴτε κάματον, καὶ τούτου πρὸς τὸ μέρος πάντας μεταλαμβάνειν δεῖ (τοῦτο γάρ ἐστιν ἡ ἰσομοιρία). ἔτι τοίνυν ἐν μὲν τῷ τοιούτῳ πολλούς τε ἐν ταῖς πράξεσιν ἐγγυμνάζεσθαι, καὶ ῥᾳδίαν ὑμῖν τὴν αἵρεσιν τῶν πιστευθῆναι δυναμένων πρὸς πάντα τὰ πρακτέα ἀπὸ τῆς πείρας ὑπάρχειν συμβαίνει, ἐκείνως δὲ δὴ πολλὴν τὴν σπάνιν καὶ τῶν ἀσκησόντων τὰ προσήκοντα καὶ τῶν ἐπιτραπησομένων ἀνάγκη πᾶσα γίγνεσθαι· καὶ διὰ τοῦτό γε οὐχ ἥκιστα ἐν τῷ πρὸς τὸν Σερτώριον πολέμῳ στρατηγοῦ ἠπορήσατε, ὅτι τὸν πρὸ τούτου χρόνον τοῖς αὐτοῖς ἐπὶ πολὺ ἐχρῆσθε. ὥστ’ εἰ καὶ κατὰ τὰ ἄλλα πάντα ἄξιός ἐστι Πομπήιος ἐπὶ τοὺς καταποντιστὰς χειροτονηθῆναι, ἀλλ’ ὅτι γε παρά τε τὰ διατεταγμένα ἐν τοῖς νόμοις καὶ παρὰ τὰ διεληλεγμένα ἐν τοῖς ἔργοις αἱρεθείη ἄν, ἥκιστα καὶ ὑμῖν καὶ τούτῳ προσήκει αὐτὸ πραχθῆναι.", "st": "36.32"}, {"sp": "N", "t": "πρῶτον μὲν οὖν τοῦτο καὶ μάλιστα λέγω, δεύτερον δὲ ἐκεῖνο, ὅτι τεταγμένως ἐκ τῶν νόμων τάς τε ἀρχὰς καὶ τὰς ἡγεμονίας λαμβανόντων καὶ ὑπάτων καὶ στρατηγῶν καὶ τῶν ἀντὶ τούτων ἀρχόντων, οὔτ’ ἄλλως καλῶς ὑμῖν ἔχει παριδόντας αὐτοὺς καινήν τινα ἀρχὴν ἐπεσαγαγέσθαι οὔτε συμφέρει. τίνος μὲν γὰρ ἕνεκα καὶ τοὺς ἐνιαυσίους ἄρχοντας χειροτονεῖτε, εἴγε μηδὲν αὐτοῖς πρὸς τὰ τοιαῦτα χρήσεσθε; οὐ γάρ που ἵν’ ἐν τοῖς περιπορφύροις ἱματίοις περινοστῶσιν, οὐδ’ ἵνα τὸ ὄνομα μόνον τῆς ἀρχῆς περιβεβλημένοι τοῦ ἔργου αὐτῆς στέρωνται. πῶς δ’ οὐχὶ καὶ τούτοις καὶ τοῖς ἄλλοις ἅπασι τοῖς τι πράττειν τῶν πολιτικῶν προαιρουμένοις ἀπεχθήσεσθε, ἂν τὰς μὲν πατρίους ἀρχὰς καταλύητε καὶ τοῖς ἐκ τῶν νόμων χειροτονουμένοις μηδὲν ἐπιτρέπητε, ξένην δέ τινα καὶ μηπώποτε γεγενημένην ἡγεμονίαν ἰδιώτῃ προστάξητε;", "st": "36.33"}, {"sp": "N", "t": "εἰ γάρ τοι καὶ παρὰ τὰς ἐπετησίους ἀρχὰς ἀνάγκη τις εἴη ἑτέραν ἑλέσθαι, ἔστι καὶ τούτου παράδειγμα ἀρχαῖον, λέγω δὲ τὸν δικτάτορα. καὶ τοῦτον μέντοι τοιοῦτον ὄντα οὔτε ἐπὶ πᾶσί ποτε τοῖς πράγμασιν οἱ πατέρες ἡμῶν οὔτε ἐπὶ πλείω χρόνον ἑξαμήνου κατεστήσαντο. ὥστ’ εἰ μὲν τοιούτου τινὸς δεῖσθε, ἔξεστιν ὑμῖν, μήτε παρανομήσασι μήτ’ ὀλιγώρως ὑπὲρ τῶν κοινῶν βουλευσαμένοις, δικτάτορα εἴτε Πομπήιον εἴτε καὶ ἄλλον τινὰ προχειρίσασθαι, ἐφ’ ᾧ μήτε πλείω τοῦ τεταγμένου χρόνον μήτε ἔξω τῆς Ἰταλίας ἄρξῃ. οὐ γάρ που ἀγνοεῖτε ὅτι καὶ τοῦτο δεινῶς οἱ πατέρες ἡμῶν ἐφυλάξαντο, καὶ οὐκ ἂν εὑρεθείη δικτάτωρ οὐδεὶς ἄλλοσε πλὴν ἑνὸς ἐς Σικελίαν, καὶ ταῦτα μηδὲν πράξαντος, αἱρεθείς. εἰ δ’ οὔτε δεῖται ἡ Ἰταλία τοιούτου τινός, οὔτ’ ἂν ὑμεῖς ὑπομείναιτε ἔτι οὐχ ὅτι τὸ ἔργον τοῦ δικτάτορος ἀλλ’ οὐδὲ τὸ ὄνομα (δῆλον δὲ ἐξ ὧν πρὸς τὸν Σύλλαν ἠγανακτήσατε), πῶς δ’ ἂν ὀρθῶς ἔχοι καινὴν ἡγεμονίαν, καὶ ταύτην ἐς ἔτη τρία καὶ ἐπὶ πᾶσιν ὡς εἰπεῖν καὶ τοῖς ἐν τῇ Ἰταλίᾳ καὶ τοῖς ἔξω πράγμασιν, ἀποδειχθῆναι; ὅσα γὰρ ἐκ τοῦ τοιούτου δεινὰ ταῖς πόλεσι συμβαίνει, καὶ ὅσοι διὰ τὰς παρανόμους φιλαρχίας τόν τε δῆμον ἡμῶν πολλάκις ἐτάραξαν καὶ αὐτοὶ ⟨αὑτοὺς⟩ μυρία κακὰ εἰργάσαντο, πάντες ὁμοίως ἐπίστασθε.", "st": "36.34"}, {"sp": "N", "t": "ὥστε περὶ μὲν τούτων παύομαι λέγων· τίς γὰρ οὐκ οἶδεν ὅτι οὔτ’ ἄλλως καλῶς ἔχει οὔτε συμφέρει ἑνί τινι τὰ πράγματα προστάσσεσθαι καὶ ἕνα τινὰ πάντων τῶν ὑπαρχόντων ἡμῖν ἀγαθῶν κύριον γίγνεσθαι, κἂν τὰ μάλιστα ἄριστός τις ᾖ; αἵ τε γὰρ μεγάλαι τιμαὶ καὶ αἱ ὑπέρογκοι ἐξουσίαι καὶ τοὺς τοιούτους ἐπαίρουσι καὶ διαφθείρουσιν. ἐκεῖνο δὲ δὴ σκοπεῖν ὑμᾶς ἀξιῶ, ὅτι οὐδὲ οἷόν τέ ἐστιν ἕνα ἄνδρα πάσης τῆς θαλάσσης ἐπάρξαι καὶ πάντα τὸν πόλεμον τοῦτον ὀρθῶς διοικῆσαι. δεῖ μὲν γὰρ ὑμᾶς, εἴπερ τι τῶν δεόντων ποιήσετε, πανταχῇ ἅμα αὐτοῖς πολεμῆσαι, ἵνα μὴ συνιστάμενοι πρὸς ἀλλήλους, μηδ’ αὖ τὰς ἀναφυγὰς πρὸς τοὺς οὐ πολεμουμένους ἔχοντες, δύσληπτοι γένωνται. τοῦτο δὲ οὐδένα ἂν τρόπον εἷς τις ἄρξας πρᾶξαι δυνηθείη· πῶς γὰρ ἂν ὑπὸ τὰς αὐτὰς ἡμέρας ἔν τε τῇ Ἰταλίᾳ καὶ ἐν τῇ Κιλικίᾳ, τῇ τε Αἰγύπτῳ καὶ τῇ Συρίᾳ, τῇ τε Ἑλλάδι καὶ τῇ Ἰβηρίᾳ, τῷ τε Ἰονίῳ καὶ ταῖς νήσοις πολεμήσειε; πολλοὺς μὲν δὴ διὰ τοῦτο καὶ στρατιώτας καὶ στρατηγοὺς ἐπιστῆναι δεῖ τοῖς πράγμασιν,", "st": "36.35"}, {"sp": "N", "t": "εἴπερ τι ὄφελος αὐτῶν ἔσται· εἰ δὲ δή τις ἐκεῖνό φησιν, ὅτι κἂν ἑνί τῳ πάντα τὸν πόλεμον ἐπιτρέψητε, πάντως που καὶ ναυάρχους καὶ ὑπάρχους πολλοὺς ἕξει, πῶς οὐ πολὺ δικαιότερον καὶ συμφορώτερον (ἐγὼ γὰρ ἂν εἴποιμι) καὶ τί κωλύει τούτους αὖ τοὺς ὑπάρξειν ἐκείνῳ μέλλοντας καὶ προχειρισθῆναι ὑφ’ ὑμῶν ἐπ’ αὐτὸ τοῦτο καὶ τὴν ἡγεμονίαν παρ’ ὑμῶν αὐτοτελῆ λαβεῖν; οὕτω μὲν γὰρ καὶ φροντιοῦσι τοῦ πολέμου μᾶλλον, ἅτε καὶ ἰδίαν ἕκαστος αὐτῶν μερίδα πεπιστευμένος καὶ ἐς μηδένα ἕτερον τὴν ὑπὲρ αὐτῆς ἀμέλειαν ἀνενεγκεῖν δυνάμενος, καὶ φιλοτιμήσονται πρὸς ἀλλήλους ἀκριβέστερον, ἅτε καὶ αὐτοκρατεῖς ὄντες καὶ τὴν δόξαν ὧν ἂν ἐργάσωνται αὐτοὶ κτησόμενοι· ἐκείνως δὲ τίνα μὲν ὁμοίως οἴεσθε … ἄλλῳ τῳ ὑποκείμενον, τίνα δ’ ἀπροφασίστως ὁτιοῦν ποιήσειν, μέλλοντα μὴ ἑαυτῷ ἀλλ’ ἑτέρῳ κρατήσειν; Ὥσθ’ ὅτι μὲν εἷς οὐδ’ ἂν δύναιτο τοσοῦτον ἅμα πόλεμον πολεμῆσαι, καὶ παρ’ αὐτοῦ Γαβινίου ὡμολόγηται· πολλοὺς γοῦν τῷ χειροτονηθησομένῳ συνεργοὺς ἀξιοῖ δοθῆναι. λοιπὴ δὲ δὴ σκέψις ἐστὶ πότερόν ποτε ἄρχοντας αὐτοὺς ἢ ὑπάρχοντας, καὶ στρατηγοὺς ἢ ὑποστρατήγους, καὶ πρὸς τοῦ δήμου παντὸς ἐπ’ αὐτοκράτορός τινος ἡγεμονίας ἢ πρὸς ἐκείνου μόνου ἐφ’ ὑπηρεσίᾳ αὐτοῦ, πεμφθῆναι δεῖ. οὐκοῦν ὅτι μὲν καὶ νομιμώτερον καὶ συμφορώτερον καὶ πρὸς τἆλλα πάντα καὶ πρὸς αὐτοὺς τοὺς λῃστὰς τοῦθ’ ὅπερ ἐγὼ λέγω ἐστί, πᾶς ἄν τις ὑμῶν ὁμολογήσειε. χωρὶς δὲ τούτου καὶ ἐκεῖνο ὁρᾶτε οἷόν ἐστι, τὸ πάσας ὑμῶν τὰς ἄλλας ἀρχὰς ἐπὶ τῇ τῶν καταποντιστῶν προφάσει καταλυθῆναι, καὶ μηδεμίαν αὐτῶν μήτε ἐν τῇ Ἰταλίᾳ μήτε ἐν τῇ ὑπηκόῳ τὸν χρόνον τοῦτον … ”", "st": "36.36"}, {"sp": "N", "t": "… τῆς δὲ Ἰταλίας ἀντὶ ὑπάτου ἐπὶ τρία ἔτη, προσέταξαν αὐτῷ ὑποστρατήγους τε πεντεκαίδεκα καὶ τὰς ναῦς ἁπάσας, τά τε χρήματα καὶ τὰ στρατεύματα ὅσα ἂν ἐθελήσῃ λαβεῖν ἐψηφίσαντο. καὶ ἐκεῖνά τε καὶ ἡ γερουσία καὶ ἄκουσα ἐπεκύρωσε, καὶ τἆλλα ὅσα πρόσφορα ἐς αὐτὰ ἦν ἑκάστοτε ἐγίγνωσκεν, ἄλλως τε καὶ ἐπειδὴ τοῦ Πίσωνος μὴ ἐπιτρέψαντος τοῖς ὑπάρχοις καταλόγους ἐν τῇ Γαλατίᾳ τῇ Ναβωνησίᾳ, ἧς ἦρχε, ποιήσασθαι, δεινῶς ὁ ὅμιλος ἠγανάκτησε· καὶ εὐθύς γ’ ἂν αὐτὸν ἐκ τῆς ἀρχῆς ἐξήλασαν, εἰ μὴ ὁ Πομπήιος παρῃτήσατο. παρασκευασάμενος οὖν ὡς τό τε πρᾶγμα καὶ τὸ φρόνημα αὐτοῦ ἀπῄτει, πᾶσαν ἅμα τὴν θάλασσαν, ὅσην οἱ καταποντισταὶ ἐλύπουν, τὰ μὲν αὐτός, τὰ δὲ καὶ διὰ τῶν ὑποστρατήγων περιέπλευσε, καὶ τὰ πλείω αὐτῆς αὐτοετὲς ἡμέρωσε. πολλῇ μὲν γὰρ καὶ τῇ παρασκευῇ τῇ τε τοῦ ναυτικοῦ καὶ τῇ τῶν ὁπλιτῶν ἐχρῆτο, ὥστε καὶ ἐν τῇ θαλάσσῃ καὶ ἐν τῇ γῇ ἀνυπόστατος εἶναι, πολλῇ δὲ καὶ τῇ φιλανθρωπίᾳ τῇ πρὸς τοὺς ὁμολογοῦντάς οἱ, ὥστε καὶ ὑπὸ τοῦ τοιούτου παμπόλλους προσποιήσασθαι· οἱ γὰρ ἄνθρωποι ταῖς τε δυνάμεσιν ἡττώμενοι καὶ τῆς χρηστότητος αὐτοῦ πειρώμενοι προθυμότατα αὐτῷ προσεχώρουν. τά τε γὰρ ἄλλα αὐτῶν ἐπεμελεῖτο, καὶ ὅπως μηδ’ αὖθίς ποτε ἐς ἀνάγκην πονηρῶν ἔργων ὑπὸ πενίας ἀφίκωνται, καὶ χώρας σφίσιν ὅσας ἐρήμους ἑώρα, καὶ πόλεις ὅσαι ἐποίκων ἐδέοντο, ἐδίδου. καὶ ἄλλαι τε ἐκ τούτου συνῳκίσθησαν καὶ ἡ Πομπηιόπολις ἐπικληθεῖσα· ἔστι δὲ ἐν τῇ Κιλικίᾳ τῇ παραθαλασσίᾳ καὶ ἐπεπόρθητο ὑπὸ τοῦ Τιγράνου, Σόλοι πρότερον ὠνομασμένη.", "st": "36.37"}, {"sp": "N", "t": "ἐπὶ μὲν δὴ τοῦ Ἀκιλίου τοῦ τε Πίσωνος ταῦτά τε οὕτως ἐγένετο, καὶ κατὰ τῶν δεκασμοῦ περὶ τὰς ἀρχὰς ἁλισκομένων ἐνομοθετήθη πρὸς αὐτῶν τῶν ὑπάτων μήτ’ ἄρχειν μήτε βουλεύειν σφῶν μηδένα, ἀλλὰ καὶ χρήματα προσοφλισκάνειν. ἐπειδὴ γὰρ ἥ τε τῶν δημάρχων δυναστεία ἐς τὸ ἀρχαῖον ἐπανεληλύθει; καὶ πολλοὶ τῶν ὑπὸ τῶν τιμητῶν διαγεγραμμένων ἀναλαβεῖν τρόπον τινὰ τὴν βουλείαν ἐσπούδαζον, συστάσεις καὶ παρακελευσμοὶ παμπληθεῖς ἐφ’ ἁπάσαις ταῖς ἀρχαῖς ἐγίγνοντο. ἔπραξαν δὲ τοῦθ’ οἱ ὕπατοι οὐχ ὅτι καὶ ἤχθοντο τῷ πράγματι (αὐτοὶ γὰρ διασπουδάσαντες ἀπεδείχθησαν, καὶ ὅ γε Πίσων καὶ γραφεὶς ἐπὶ τούτῳ καὶ πρὸς ἑνὸς καὶ πρὸς ἑτέρου τινὸς ἐξεπρίατο τὸ μὴ κατηγορηθῆναι) ἀλλ’ ὅτι ἠναγκάσθησαν ὑπὸ τῆς γερουσίας. αἴτιον δὲ ὅτι Γάιός τις Κορνήλιος δημαρχῶν πικρότατα ἐπιτίμια τάξαι κατ’ αὐτῶν ἐπεχείρησε καὶ αὐτὰ καὶ ὁ ὅμιλος ᾑρεῖτο. ἡ γὰρ βουλὴ συνιδοῦσα ὅτι τὸ μὲν ὑπερβάλλον τῶν τιμωρημάτων ἐν μὲν ταῖς ἀπειλαῖς ἔκπληξίν τινα ἔχει, οὔτε δὲ τοὺς κατηγορήσοντας οὔτε τοὺς καταψηφιουμένους τῶν ὑπαιτίων, ἅτε καὶ ἀνηκέστων αὐτῶν ὄντων, ῥᾳδίως εὑρίσκει, τὸ δὲ δὴ μέτριον ἔς τε τὰς κατηγορίας συχνοὺς προάγει καὶ τὰς καταψηφίσεις οὐκ ἀποτρέπει, μεταρρυθμίσαι πῃ τὴν ἐσήγησιν αὐτοῦ καὶ τοῖς ὑπάτοις νομοθετῆσαι", "st": "36.38"}, {"sp": "N", "t": "αὐτὴν ἐκέλευσεν. ἐπεὶ δὲ αἵ τε ἀρχαιρεσίαι προεπηγγελμέναι ἦσαν, καὶ κατὰ τοῦτ’ οὐδὲν προνομοθετηθῆναι πρὸ αὐτῶν ἐξῆν, καὶ οἱ σπουδαρχιῶντες πολλὰ καὶ κακὰ ἐν τῷ διακένῳ τούτῳ ἐποίουν, ὥστε καὶ σφαγὰς γίγνεσθαι, τόν τε νόμον ἐψηφίσαντο καὶ πρὸ ἐκείνων ἐσενεχθῆναι καὶ φρουρὰν τοῖς ὑπάτοις δοθῆναι. ἀγανακτήσας οὖν ἐπὶ τούτοις ὁ Κορνήλιος γνώμην ἐποιήσατο μὴ ἐξεῖναι τοῖς βουλευταῖς μήτε ἀρχήν τινι ἔξω τῶν νόμων αἰτήσαντι διδόναι μήτ’ ἄλλο μηδὲν τῶν τῷ δήμῳ προσηκόντων ψηφίζεσθαι· τοῦτο γὰρ ἐνενομοθέτητο μὲν ἐκ τοῦ πάνυ ἀρχαίου, οὐ μέντοι καὶ τῷ ἔργῳ ἐτηρεῖτο. θορύβου τε ἐπ’ αὐτῷ πολλοῦ συμβάντος (καὶ γὰρ ἀντέπρασσον τῶν τε ἄλλων τῶν ἐκ τῆς γερουσίας συχνοὶ καὶ ὁ Πίσων) τάς τε ῥάβδους αὐτοῦ ὁ ὄχλος συνέτριψε καὶ αὐτὸν διασπάσασθαι ἐπεχείρησεν. ἰδὼν οὖν τὴν ὁρμὴν αὐτῶν ὁ Κορνήλιος τότε μέν, πρὶν ἐπιψηφίσαι τι, διαφῆκε τὸν σύλλογον, ὕστερον δὲ προσέγραψε τῷ νόμῳ τήν τε βουλὴν πάντως περὶ αὐτῶν προβουλεύειν καὶ τὸν", "st": "36.39"}, {"sp": "N", "t": "δῆμον ἐπάναγκες ἐπικυροῦν τὸ προβούλευμα. καὶ οὕτως ἐκεῖνόν τε διενομοθέτησε καὶ ἕτερον τοιόνδε. οἱ στρατηγοὶ πάντες τὰ δίκαια καθ’ ἃ δικάσειν ἔμελλον, αὐτοὶ συγγράφοντες ἐξετίθεσαν· οὐ γάρ πω πάντα τὰ δικαιώματα τὰ περὶ τὰ συμβόλαια διετέτακτο. ἐπεὶ οὖν οὔτε ἐσάπαξ τοῦτ’ ἐποίουν οὔτε τὰ γραφέντα ἐτήρουν, ἀλλὰ πολλάκις αὐτὰ μετέγραφον καὶ συχνὰ ἐν τούτῳ πρὸς χάριν ἢ καὶ κατ’ ἔχθραν τινῶν, ὥσπερ εἰκός, ἐγίγνετο, ἐσηγήσατο κατ’ ἀρχάς τε εὐθὺς αὐτοὺς τὰ δίκαια οἷς χρήσονται προλέγειν, καὶ μηδὲν ἀπ’ αὐτῶν παρατρέπειν. τό τε σύμπαν οὕτως ἐπιμελὲς τοῖς Ῥωμαίοις κατὰ τὸν χρόνον ἐκεῖνον τὸ μηδὲν δωροδοκεῖσθαι ἐγένετο ὥστε πρὸς τῷ τοὺς ἐλεγχομένους κολάζειν καὶ τοὺς κατηγοροῦντας αὐτῶν ἐτίμων. τοῦ γοῦν Κόττου τοῦ Μάρκου τὸν μὲν ταμίαν Πούπλιον Ὄππιον ἐπί τε δώροις καὶ ἐπὶ ὑποψίᾳ ἐπιβουλῆς ἀποπέμψαντος, αὐτοῦ δὲ πολλὰ ἐκ τῆς Βιθυνίας χρηματισαμένου, Γάιον Κάρβωνα τὸν κατηγορήσαντα αὐτοῦ τιμαῖς ὑπατικαῖς καίπερ δεδημαρχηκότα μόνον, ἐσέμνυναν. καὶ οὗτος μὲν τῆς τε Βιθυνίας καὶ αὐτὸς ὕστερον ἄρξας, καὶ μετριώτερον οὐδὲν τοῦ Κόττου πλημμελήσας, ἀντικατηγορήθη ὑπὸ τοῦ υἱέος αὐτοῦ καὶ ἀνθεάλω· πολλῷ γάρ που ῥᾷον ἄλλοις ἐπιτιμῶσί τινες ἢ ἑαυτοῖς παραινοῦσι, καὶ προχειρότατά γε ἐφ’ οἷς τιμωρίας ἀξίους τοὺς πέλας εἶναι νομίζουσιν αὐτοὶ ποιοῦσιν, ὥστε μηδεμίαν πίστιν ἐξ ὧν ἑτέροις ἐγκαλοῦσιν, ὅτι καὶ μισοῦσιν αὐτά, λαμβάνειν·", "st": "36.40"}, {"sp": "N", "t": "Λούκιος δὲ δὴ Λούκουλλος τὴν μὲν στρατηγίαν τὴν οἴκοι διῆρξε, τῆς δὲ δὴ Σαρδοῦς ἄρξαι μετ’ αὐτὴν λαχὼν οὐκ ἠθέλησε, μισήσας τὸ πρᾶγμα διὰ τοὺς πολλοὺς τοὺς οὐδὲν ὑγιὲς ἐν τοῖς ἔθνεσι δρῶντας. ὅτι γὰρ ἐπιεικὴς ἦν, ἱκανώτατα διέδειξεν· τοῦ γὰρ Ἀκιλίου συντριβῆναι τὸν δίφρον αὐτοῦ, ἐφ’ οὗ ἐδίκαζε, κελεύσαντος ὅτι παριόντα ποτὲ αὐτὸν ἰδὼν οὐκ ἐξανέστη, οὔτ’ ὀργῇ ἐχρήσατο καὶ ὀρθοστάδην μετὰ τοῦτο καὶ αὐτὸς καὶ οἱ συνάρχοντες αὐτοῦ δι’ ἐκεῖνον διεδίκασαν.", "st": "36.41"}, {"sp": "N", "t": "Ἐσήνεγκε μὲν οὖν καὶ ὁ Ῥώσκιος νόμον, ἐσήνεγκε δὲ καὶ ὁ Γάιος ὁ Μάλλιος, ὅτε ἐδημάρχησεν. ἀλλ’ ἐκεῖνος μέν (τὰς γὰρ τῶν ἱππέων τὰς ἐν τοῖς θεάτροις ἕδρας ἀκριβῶς ἀπὸ τῶν ἄλλων ἀφώρισε) καὶ ἔπαινον ἐπ’ αὐτῷ ἔλαβεν, ὁ δὲ δὴ Μάλλιος καὶ δίκην ὀλίγου ὑπέσχε· τῷ γὰρ ἔθνει τῷ τῶν ἀπελευθέρων ἔν τε τῇ ἐσχάτῃ τοῦ ἔτους ἡμέρᾳ καὶ πρὸς ἑσπέραν, παρασκευάσας τινὰς ἐκ τοῦ ὁμίλου, ψηφίσασθαι μετὰ τῶν ἐξελευθερωσάντων σφᾶς ἔδωκεν. ἐπεὶ δὲ ἡ βουλὴ εὐθὺς τῇ ὑστεραίᾳ, ἐν αὐτῇ τῇ νουμηνίᾳ ἐν ᾗ Λούκιός τε Τούλλιος καὶ Αἰμίλιος Λέπιδος ὑπατεύειν ἤρξαντο, τὸν νόμον αὐτοῦ ἀπεψηφίσατο, φοβηθείς, ἐπειδὴ τὸ πλῆθος δεινῶς ἠγανάκτει, τὰ μὲν πρῶτα ἔς τε τὸν Κράσσον καὶ ἐς ἄλλους τινὰς τὴν γνώμην ἀνῆγεν, ὡς δ’ οὐδεὶς ἐπίστευέν οἱ, τὸν Πομπήιον καὶ ἀπόντα ἐκολάκευσεν, ἄλλως τε καὶ ὅτι τὸν Γαβίνιον πλεῖστον παρ’ αὐτῷ δυνάμενον ᾔσθετο· τόν τε γὰρ τοῦ Τιγράνου καὶ τὸν τοῦ Μιθριδάτου πόλεμον, τήν τε Βιθυνίαν καὶ τὴν Κιλικίαν ἅμα", "st": "36.42"}, {"sp": "N", "t": "ἀρχὴν αὐτῷ προσέταξεν. ἀγανάκτησις μὲν γὰρ καὶ ἀντιλογία καὶ τότε παρὰ τῶν δυνατῶν, διά τε τἆλλα καὶ διότι ὅ τε Μάρκιος καὶ ὁ Ἀκίλιος πρὶν τὸν χρόνον σφίσι τῆς ἀρχῆς ἐξήκειν κατελύοντο, ἐγένετο· ὁ δὲ ὅμιλος, καίτοι μικρὸν ἔμπροσθεν τοὺς ἄνδρας τοὺς καταστήσοντας τὰ ἑαλωκότα, ὡς καὶ διαπεπολεμηκὼς ἐξ ὧν σφίσιν ὁ Λούκουλλος ἐπεστάλκει, πέμψας, ὅμως ἐψηφίσατο αὐτά, ἐναγόντων σφᾶς ἐς τὰ μάλιστα τοῦ τε Καίσαρος καὶ τοῦ Κικέρωνος τοῦ Μάρκου. οὗτοι γὰρ αὐτοῖς συνηγωνίσαντο οὐχ ὅτι καὶ συμφέρειν αὐτὰ τῇ πόλει ἐνόμιζον, οὐδ’ ὅτι τῷ Πομπηίῳ χαρίσασθαι ἤθελον· ἀλλ’ ἐπειδὴ καὶ ὣς γενήσεσθαι ἔμελλε, Καῖσαρ μὲν τόν τε ὄχλον ἅμα ἐθεράπευσεν ἅτε καὶ ὁρῶν ὅσῳ τῆς βουλῆς ἐπικρατέστεροι ἦσαν, καὶ ἑαυτῷ τό τι τῶν ὁμοίων ψηφισθῆναί ποτε παρεσκεύασε, κἀν τούτῳ καὶ τὸν Πομπήιον καὶ ἐπιφθονώτερον καὶ ἐπαχθέστερον ἐκ τῶν διδομένων οἱ ποιῆσαι, ὅπως σφίσι πρὸς κόρου θᾶσσον γένηται, ἠθέλησε, Κικέρων δὲ τήν τε πολιτείαν ἄγειν ἠξίου, καὶ ἐνεδείκνυτο καὶ τῷ πλήθει καὶ τοῖς δυνατοῖς ὅτι, ὁποτέροις ἄν σφων πρόσθηται, πάντως αὐτοὺς ἐπαυξήσει. ἐπημφοτέριζέ τε γὰρ καὶ ποτὲ μὲν τὰ τούτων ἔστι δ’ ὅτε καὶ τὰ ἐκείνων, ἵν’ ὑπ’ ἀμφοτέρων σπουδάζηται, ἔπραττε. τοὺς γοῦν βελτίους πρότερον προαιρεῖσθαι λέγων, καὶ διὰ τοῦτο καὶ ἀγορανομῆσαι μᾶλλον ἢ δημαρχῆσαι ἐθελήσας, τότε πρὸς τοὺς", "st": "36.43"}, {"sp": "N", "t": "συρφετώδεις μετέστη. καὶ μετὰ τοῦτο δίκης τέ τινος τῷ Μαλλίῳ πρὸς τῶν δυνατῶν παρασκευασθείσης, καὶ ἐκείνου χρόνον τινὰ ἐμποιῆσαι αὐτῇ σπουδάζοντος, τά τε ἄλλα κατ’ αὐτοῦ ἔπραττε, καὶ μόλις αὐτόν (ἐστρατήγει γὰρ καὶ τὴν ἡγεμονίαν τοῦ δικαστηρίου εἶχεν) ἐς τὴν ὑστεραίαν ἀνεβάλετο, πρόφασιν ἐπ’ ἐξόδῳ τὸ ἔτος εἶναι ποιησάμενος. κἀν τούτῳ δυσχεράναντος τοῦ ὁμίλου ἐσῆλθέ τε ἐς τὸν σύλλογον αὐτῶν, ἀναγκασθεὶς δῆθεν ὑπὸ τῶν δημάρχων, καὶ κατά τε τῆς βουλῆς κατέδραμε καὶ συναγορεύσειν τῷ Μαλλίῳ ὑπέσχετο. καὶ ὁ μὲν ἐκ τούτου τά τε ἄλλα κακῶς ἤκουε καὶ αὐτόμολος ὠνομάζετο, τάραχος δέ τις εὐθὺς ἐπιγενόμενος ἐκώλυσε τὸ δικαστήριον συναχθῆναι. Πούπλιός τε γὰρ Παῖτος καὶ Κορνήλιος Σύλλας, ἀδελφιδοῦς ἐκείνου τοῦ πάνυ Σύλλου, ὕπατοί τε ἀποδειχθέντες καὶ δεκασμοῦ ἁλόντες ἐπεβούλευσαν τοὺς κατηγορήσαντάς σφων Κότταν τε καὶ Τορκουᾶτον Λουκίους, ἄλλως τε καὶ ἐπειδὴ αὐτοὶ ἀνθῃρέθησαν, ἀποκτεῖναι. καὶ παρεσκευάσθησαν μὲν ἄλλοι τε καὶ Γναῖος Πίσων καὶ Λούκιος Κατιλίνας ἀνὴρ θρασύτατος (ᾐτήκει δὲ καὶ αὐτὸς τὴν ἀρχήν, καὶ διὰ τοῦτο ὀργὴν ἐποιεῖτο), οὐ μέντοι καὶ ἠδυνήθησάν τι δρᾶσαι διὰ τὸ τήν τε ἐπιβουλὴν προμηνυθῆναι καὶ φρουρὰν τῷ τε Κόττᾳ καὶ τῷ Τορκουάτῳ παρὰ τῆς βουλῆς δοθῆναι· … δόγμα τι κατ’ αὐτῶν γενέσθαι, εἰ μὴ δήμαρχός τις ἠναντιώθη. ἐπεὶ δ’ οὗν καὶ ὣς ὁ Πίσων ἐθρασύνετο, ἐφοβήθη τε ἡ γερουσία μή τι συνταράξῃ, καὶ εὐθὺς αὐτὸν ἐς Ἰβηρίαν, πρόφασιν ὡς καὶ ἐπ’ ἀρχήν τινα, ἔπεμψε. καὶ ὁ μὲν ἐνταῦθα ὑπὸ τῶν ἐπιχωρίων, ἀδικήσας", "st": "36.44"}, {"sp": "N", "t": "τι αὐτούς, ἐσφάγη· Πομπήιος δὲ τὸ μὲν πρῶτον ὡς καὶ ἐπὶ τὴν Κρήτην τόν τε Μέτελλον πλευσούμενος ἡτοιμάζετο, μαθὼν δὲ τὰ δεδογμένα προσεποιεῖτο μὲν ἄχθεσθαι ὡς καὶ πρότερον, καὶ τοῖς ἀντιστασιώταις ὡς καὶ πράγματα ἀεί ποτε αὐτῷ, τοῦ καὶ πταῖσαί τι, παρέχουσιν ἐπεκάλει, ἀσμεναίτατα δὲ αὐτὰ ἀναδεξάμενος Κρήτην μὲν καὶ τἆλλα τὰ ἐν τῇ θαλάσσῃ, εἴ πού τι ἀδιοίκητον κατελέλειπτο, παρ’ οὐδὲν ἔτ’ ἤγαγε, πρὸς δὲ δὴ τὸν τῶν βαρβάρων πόλεμον παρεσκευάζετο. κἀν τούτῳ βουληθεὶς τῆς τοῦ Μιθριδάτου διανοίας πειρᾶσθαι, πέμπει τὸν Μητροφάνη φιλίους αὐτῷ λόγους φέροντα. καὶ ὃς τότε μὲν ἐν ὀλιγωρίᾳ αὐτὸν ἐποιήσατο (τοῦ γὰρ Ἀρσάκου τοῦ τῶν Πάρθων βασιλέως ἀποθανόντος ἐν τῷ χρόνῳ τούτῳ Φραάτην τὸν διάδοχον αὐτοῦ προσεδόκησεν οἰκειώσεσθαι), ἐπεὶ δ’ ὁ Πομπήιος τὴν φιλίαν τῷ Φραάτῃ διὰ ταχέων ἐπὶ τοῖς αὐτοῖς προσυνέθετο καὶ ἐς τὴν Ἀρμενίαν αὐτὸν τὴν τοῦ Τιγράνου προεμβαλεῖν ἀνέπεισε, πυθόμενος τοῦτο κατέδεισε, καὶ πρεσβευσάμενος εὐθὺς σύμβασιν ἔπραττε. κελεύσαντος δὲ αὐτῷ τοῦ Πομπηίου τά τε ὅπλα καταθέσθαι καὶ τοὺς αὐτομόλους ἐκδοῦναι οὐκ ἔσχε καιρὸν βουλεύσασθαι· ἀκούσαντες γὰρ ταῦτα οἱ ἐν τῷ στρατοπέδῳ αὐτοῦ ὄντες, καὶ φοβηθέντες οἵ τε αὐτόμολοι (πολλοὶ δὲ ἦσαν) μὴ ἐκδοθῶσι, καὶ οἱ βάρβαροι μὴ ἄνευ ἐκείνων πολεμεῖν ἀναγκασθῶσιν, ἐθορύβησαν. κἂν ἐξειργάσαντό τι τὸν Μιθριδάτην, εἰ μὴ ψευσάμενος ὅτι οὐκ ἐπὶ σπονδαῖς ἀλλ’ ἐπὶ κατασκοπῇ τῆς τῶν Ῥωμαίων παρασκευῆς τοὺς πρέσβεις ἔπεμψε, μόλις αὐτοὺς κατέσχεν.", "st": "36.45"}, {"sp": "N", "t": "ὁ οὖν Πομπήιος ἐπειδὴ πολεμητέα οἱ ἔγνω εἶναι, τά τε ἄλλα παρεσκευάσατο καὶ τοὺς Οὐαλεριείους προσκατελέξατο. καὶ αὐτῷ ἐν τῇ Γαλατίᾳ ἤδη ὄντι ὁ Λούκουλλος ἀπαντήσας διαπεπολεμῆσθαί τε πάντα ἔφη καὶ μηδὲν ἔτι στρατείας δεῖσθαι, καὶ διὰ τοῦτο καὶ τοὺς ἄνδρας τοὺς ὑπὸ τῆς βουλῆς πρὸς τὴν διοίκησιν αὐτῶν πεμφθέντας ἤδη παρεῖναι. ὡς δ’ οὐκ ἐπείσθη ἐπαναχωρῆσαι, πρὸς λοιδορίας ἐτράπετο, τά τε ἄλλα καὶ πολυπράγμονα καὶ φιλοπόλεμον καὶ φιλαρχοῦντα αὐτὸν ἀποκαλῶν. ὁ οὖν Πομπήιος βραχὺ αὐτοῦ φροντίσας ἀπεῖπε μηδένα ἔτ’ αὐτῷ πειθαρχῆσαι, καὶ ἐπὶ τὸν Μιθριδάτην ἠπείχθη, σπουδὴν ἔχων ὅτι τάχιστά οἱ συμμῖξαι.", "st": "36.46"}, {"sp": "N", "t": "καὶ ὃς τέως μὲν ἔφευγε (ταῖς γὰρ δυνάμεσιν ἠλαττοῦτο) καὶ τήν τε ἐν ποσὶν ἀεὶ ἔκειρε, καὶ ἐπλάνα τε αὐτὸν ἅμα καὶ ἐπιδεῖσθαι τῶν ἐπιτηδείων ἐποίει· ἐπεὶ δὲ ἐκεῖνος ἐς τὴν Ἀρμενίαν διά τε τοῦτο καὶ ὡς ἐρήμην αὐτὴν αἱρήσων ἐνέβαλεν, οὕτω δὴ δείσας μὴ προκαταληφθῇ ἦλθέ τε ἐς αὐτήν, καὶ λόφον ἀντικαταλαβὼν ὀχυρὸν τῷ μὲν παντὶ στρατῷ ἡσύχαζεν, ἐλπίζων τοὺς μὲν Ῥωμαίους ἀπορίᾳ τῶν τροφῶν ἐκτρυχώσειν (αὐτὸς γὰρ ἅτε ἐν ὑπηκόῳ χώρᾳ πολλαχόθεν αὐτῶν εὐπόρει), τῶν δὲ δὴ ἱππέων ἀεί τινας ἐς τὸ πεδίον ψιλὸν ὂν καταπέμπων τούς τε προστυγχάνοντάς σφισιν ἐκάκου, καὶ ἐξαυτομολοῦντας ἐπὶ τούτῳ συχνοὺς ἐδέχετο. ὁ οὖν Πομπήιος ἐνταῦθα μὲν οὐκ ἐθάρσησεν αὐτοῖς συμβαλεῖν, μεταστρατοπεδευσάμενος δὲ ἑτέρωσε, ὅθεν ὑλώδους τοῦ πέριξ χωρίου ὄντος ἧττον ὑπό τε τοῦ ἱππικοῦ καὶ ὑπὸ τοῦ τοξικοῦ τοῦ τῶν ἐναντίων λυπηθήσεσθαι ἔμελλεν, ἐλόχισεν ᾗ καιρὸς ἦν, καὶ ὀλίγοις τισὶν ἐκ τοῦ προφανοῦς τῷ στρατοπέδῳ τῶν βαρβάρων προσμίξας ἐτάραξέ τε αὐτούς, καὶ ὑπαγαγὼν ἐς ὃ ἐβούλετο πολλοὺς ἀπέκτεινε. θαρσήσας τε ἐκ τούτου καὶ κατὰ τὴν χώραν ἄλλους ἄλλῃ ἐπὶ τὰ ἐπιτήδεια ἔπεμπεν.", "st": "36.47"}, {"sp": "N", "t": "ὁ οὖν Μιθριδάτης, ἐπειδὴ ταῦτά τε ἀσφαλῶς ἐπορίζετο, καὶ τὴν Ἀναῖτιν χώραν τῆς τε Ἀρμενίας οὖσαν καὶ θεῷ τινι ἐπωνύμῳ ἀνακειμένην διά τινων ἐχειρώσατο, κἀκ τούτου καὶ ἄλλοι συχνοὶ πρὸς αὐτὸν ἀπέκλινον, καὶ αὐτῷ καὶ οἱ τοῦ Μαρκίου στρατιῶται προσεγένοντο, ἐφοβήθη καὶ οὐκέτι κατὰ χώραν ἔμεινεν, ἀλλ’ αὐτίκα τε τῆς νυκτὸς ἄρας ἔλαθε, καὶ μετὰ ταῦτα νυκτοπορῶν ἐς τὴν τοῦ Τιγάνου Ἀρμενίαν προῄει. καί οἱ ὁ Πομπήιος ἐπηκολούθει μὲν ἐπιθυμῶν διὰ μάχης ἐλθεῖν, οὐ μέντοι καὶ πρότερον οὔτε μεθ’ ἡμέραν (οὐ γὰρ ἐξῄεσαν ἐκ τοῦ στρατοπέδου) οὔτε νύκτωρ ἐτόλμησε τοῦτο ποιῆσαι (τὴν γὰρ ἀγνωσίαν τῶν χωρίων ἐδεδίει) πρίν σφας πρὸς τῇ μεθορίᾳ γενέσθαι· τότε γὰρ εἰδὼς αὐτοὺς διαφεύγειν μέλλοντας ἠναγκάσθη νυκτομαχῆσαι. γνοὺς οὖν τοῦτο προαπῆρε, μεσημβριάζοντας τοὺς βαρβάρους λαθών, ᾗ πορεύεσθαι ἔμελλον· καὶ ἐντυχών τινι χωρίῳ κοίλῳ μεταξὺ γηλόφων τινῶν ὄντι, ἐνταῦθα τό τε στράτευμα ἐπὶ τὰ μετέωρα ἀνεβίβασε καὶ τοὺς πολεμίους ὑπέμεινεν. ἐπειδή τε ἐκεῖνοι μετά τε ἀδείας καὶ ἄνευ προφυλακῆς, ἅτε μήτε ἔμπροσθε δεινόν τι πεπονθότες καὶ τότε ἐς τὸ ἀσφαλὲς ἤδη προχωροῦντες ὥστε μηδὲ ἐφέψεσθαί σφισιν ἔτι τοὺς Ῥωμαίους ἐλπίζειν, ἐς τὸ κοῖλον ἐσῆλθον, ἐπέθετο αὐτοῖς ἐν τῷ σκότῳ· οὔτε γὰρ ἄλλο τι φῶς εἶχον οὔτε ἐκ τοῦ οὐρανοῦ τι ἔλαμπεν.", "st": "36.48"}, {"sp": "N", "t": "ἐγένετο δὲ ἡ μάχη τοιάδε. πρῶτον μὲν οἱ σαλπικταὶ πάντες ἅμα τὸ πολεμικὸν ἀπὸ συνθήματος ἐβόησαν, ἔπειτα δὲ οἵ τε στρατιῶται καὶ ὁ λοιπὸς ὄχλος πᾶς ἐπηλάλαξε, καὶ οἱ μὲν τὰ δόρατα πρὸς τὰς ἀσπίδας, οἱ δὲ καὶ λίθους πρὸς τὰ χαλκᾶ σκεύη προσεπέκρουσαν. καί σφων τὴν ἠχὴν τὰ ὄρη ἔγκοιλα ὄντα καὶ ὑπεδέξατο καὶ ἀνταπέδωκε φρικωδεστάτην, ὥστε τοὺς βαρβάρους ἐξαπιναίως ἔν τε τῇ νυκτὶ καὶ ἐν τῇ ἐρημίᾳ αὐτῶν ἀκούσαντας δεινῶς ἐκπλαγῆναι ὡς καὶ δαιμονίῳ τινὶ πάθει περιπεπτωκότας. κἀν τούτῳ οἱ Ῥωμαῖοι πανταχόθεν ἀπὸ τῶν μετεώρων λίθοις τοξεύμασιν ἀκοντίοις βάλλοντες πάντως γέ τινας ὑπὸ τοῦ πλήθους αὐτῶν ἐτίτρωσκον καὶ ἐς πᾶν κακοῦ σφας κατέστησαν· οὔτε γὰρ ἐς παράταξιν ἀλλ’ ἐς πορείαν ἐσταλμένοι, καὶ ἐν ταὐτῷ τοῖς τε ἵπποις καὶ ταῖς καμήλοις καὶ παντοδαποῖς σκεύεσι καὶ οἱ ἄνδρες καὶ αἱ γυναῖκες ἀναστρεφόμενοι, καὶ οἱ μὲν ἐπὶ κελήτων, οἱ δὲ ἐφ’ ἁρμάτων τῶν τε καμαρῶν καὶ τῶν ἁρμαμαξῶν ἀναμὶξ ὀχούμενοι, καὶ οἱ μὲν ἤδη τιτρωσκόμενοι, οἱ δὲ προσδεχόμενοι τρωθήσεσθαι, ἐταράσσοντο, κἀκ τούτου ῥᾷον, ἅτε καὶ ἀλλήλοις ἐμπελαζόμενοι, ἐφθείροντο. καὶ ταῦτα μέν, ἕως ἄπωθεν ἐβάλλοντο, ἔπασχον· ἐπεὶ δὲ ἐξαναλώσαντες οἱ Ῥωμαῖοι τὴν πόρρωθεν ἀλκὴν ἐπικατέδραμόν σφισιν, ἐφονεύετο μὲν τὰ περιέσχατα (καὶ ἐξήρκει πρὸς τὸν θάνατον αὐτοῖς μία πληγὴ ἅτε καὶ ψιλοῖς οὖσι τοῖς πλείοσι), συνεπιέζετο δὲ τὰ μέσα, πάντων ἐπ’ αὐτὰ ὑπὸ τοῦ πέριξ δέους χωρούντων. καὶ οὕτω καὶ ὑπ’ ἀλλήλων ὠθούμενοι καὶ συμπατούμενοι διώλλυντο, οὐδ’ εἶχον οὐδὲν οὔτε ἑαυτοῖς ἐπαρκέσαι οὔτε ἐς τοὺς πολεμίους τολμῆσαι· ἱππῆς γὰρ καὶ τοξόται τὸ πλεῖστον ὄντες ἄποροι μὲν ἐν τῷ σκότῳ προϊδέσθαι τι, ἄποροι δὲ ἐν τῇ στενοχωρίᾳ μηχανήσασθαι ἐγίγνοντο. ἐπειδὴ δὲ ἡ σελήνη ἀνέτειλεν, οἱ μὲν ἔχαιρον ὡς καὶ ἐν τῷ φωτὶ πάντως τινὰς ἀμυνούμενοι. κἂν ὠφελήθησάν τι, εἰ μὴ οἱ Ῥωμαῖοι κατόπιν αὐτὴν ἔχοντες, πολλήν σφισι πλάνην, τοτὲ μὲν τῇ τοτὲ δὲ τῇ προσπίπτοντες, καὶ ἐν τῇ ὄψει καὶ ἐν τῷ ἔργῳ ἐνεποίουν. πάμπολλοί τε γὰρ ὄντες καὶ ἐπὶ βαθύτατον κοινῇ πάντες ἀποσκιάζοντες ἔσφαλλον αὐτούς, ἐν ᾧ γε οὔπω προσέμισγόν σφισιν· ἐς γὰρ τὸ κενὸν οἱ βάρβαροι, ὡς καὶ ἐγγὺς αὐτῶν ὄντων, μάτην ἔπαιον, καὶ ὁμόσε χωρήσαντες ἐν τῇ σκιᾷ μὴ προσδεχόμενοι ἐτιτρώσκοντο. καὶ οὕτως ἀπέθανον αὐτῶν πολλοὶ καὶ ἑάλωσαν οὐκ ἐλάττους. συχνοὶ δὲ καὶ διέφυγον, ἄλλοι τε καὶ ὁ Μιθριδάτης.", "st": "36.49"}, {"sp": "N", "t": "καὶ τότε μὲν πρὸς τὸν Τιγράνην ἠπείγετο· ἐπεὶ δὲ προπέμψας πρὸς αὐτὸν οὐδὲν φίλιον εὕρετο, ὅτι τοῦ υἱέος αὐτῷ Τιγράνου στασιάσαντος ἐκεῖνον μὲν πάππον αὐτοῦ ὄντα αἴτιον τῆς διαφορᾶς ὑπετόπησε γεγονέναι, καὶ διὰ τοῦτο οὐχ ὅπως αὐτὸν ἐδέξατο, ἀλλὰ καὶ τοὺς προπεμφθέντας ὑπ’ αὐτοῦ συνέλαβε καὶ κατέδησε, διαμαρτὼν ὧν ἤλπισεν ἔς τε τὴν Κολχίδα ἀπετράπετο, καὶ ἐκεῖθεν πεζῇ πρός τε τὴν Μαιῶτιν καὶ πρὸς τὸν Βόσπορον, τοὺς μὲν πείθων, τοὺς δὲ καὶ βιαζόμενος, ἀφίκετο, καὶ τήν τε χώραν ἐκομίσατο, τὸν Μαχάρην τὸν παῖδα τὸν τὰ τῶν Ῥωμαίων ἀνθελόμενον καὶ τότε αὐτῆς κρατοῦντα καταπλήξας ὥστε μηδὲ ἐς ὄψιν αὐτῷ ἐλθεῖν, καὶ ἐκεῖνον διὰ τῶν συνόντων οἱ, τήν τε ἄδειάν σφισι καὶ χρήματα δώσειν ὑπισχνούμενος, ἀπέκτεινεν. ἐν ᾧ δὲ ταῦτ’ ἐγίγνετο, ὁ Πομπήιος ἔπεμψε μὲν τοὺς ἐπιδιώξοντας αὐτόν, ἐπεὶ δὲ ἔφθη ὑπὲρ τὸν Φᾶσιν ἐκδράς, πόλιν ἐν τῷ χωρίῳ ἐν ᾧ ἐνενικήκει συνῴκισε, τοῖς τραυματίαις καὶ τοῖς ἀφηλικεστέροις τῶν στρατιωτῶν αὐτὴν δούς. καί σφισι καὶ τῶν περιχώρων ἐθελονταὶ πολλοὶ συνῴκησαν, καὶ εἰσὶ καὶ νῦν, Νικοπολῖταί τε ὠνομασμένοι καὶ ἐς τὸν Καππαδοκικὸν νομὸν συντελοῦντες.", "st": "36.50"}, {"sp": "N", "t": "καὶ ὁ μὲν ταῦτ’ ἐποίει· ὁ δὲ δὴ Τιγράνης ὁ τοῦ Τιγράνου παῖς παραλαβών τινας τῶν πρώτων, ἐπεὶ οὐ καθ’ ἡδονὴν αὐτοῖς ὁ γέρων ἦρχε, πρός τε τὸν Φραάτην κατέφυγε, καὶ περισκοποῦντα αὐτὸν διὰ τὰς συνθήκας τὰς πρὸς τὸν Πομπήιον γενομένας ὅ τι χρὴ πρᾶξαι, ἐς τὴν Ἀρμενίαν ἐμβαλεῖν ἀνέπεισε. καὶ ἦλθον μὲν μέχρι τῶν Ἀρταξάτων, πᾶσαν τὴν ἐν ποσὶ χειρούμενοι, καὶ αὐτοῖς ἐκείνοις προσέβαλον· ὁ γὰρ Τιγράνης ὁ γέρων ἐς τὰ ὄρη φοβηθείς σφας ἀνέφυγεν· ἐπεὶ μέντοι χρόνου τε τῇ προσεδρείᾳ δεῖν ἔδοξε, καὶ διὰ τοῦτο ὁ Φραάτης μέρος τι τῆς δυνάμεως τῷ παιδὶ αὐτοῦ καταλιπὼν ἐς τὴν οἰκείαν ἀνεχώρησεν, ἀντεπῆλθέ τε ἐνταῦθα ὁ πατὴρ αὐτῷ μονωθέντι καὶ ἐνίκησε. φυγὼν οὖν ἐκεῖνος τὸ μὲν πρῶτον πρὸς τὸν Μιθριδάτην τὸν πάππον ὥρμησεν, ἐπεὶ δὲ ἔμαθεν αὐτὸν ἡττημένον καὶ βοηθείας μᾶλλον δεόμενον ἢ τινι ἐπικουρῆσαι δυνάμενον, προσεχώρησε τοῖς Ῥωμαίοις, καὶ αὐτῷ ὁ Πομπήιος ἡγεμόνι χρησάμενος ἔς τε τὴν Ἀρμενίαν καὶ ἐπὶ τὸν πατέρα αὐτοῦ ἐστράτευσε.", "st": "36.51"}, {"sp": "N", "t": "καὶ ὃς μαθὼν τοῦτο καὶ καταδείσας ἐπεκηρυκεύσατό τε εὐθὺς αὐτῷ καὶ τοὺς πρέσβεις τοὺς τοῦ Μιθριδάτου ἐξέδωκεν. ἐπειδή τε, ἐναντιωθέντος οἱ τοῦ υἱέος, οὐδενὸς μετρίου ἔτυχεν, ἀλλὰ καὶ ὣς ὁ Πομπήιος τόν τε Ἀράξην διέβη καὶ τοῖς Ἀρταξάτοις ἐπλησίασεν, οὕτω δὴ τήν τε πόλιν αὐτῷ παρέδωκε καὶ ἐς τὸ στρατόπεδον αὐτοῦ ἐθελοντὴς ἧκεν, ἐν μέσῳ ἑαυτὸν ὅτι μάλιστα τοῦ τε προτέρου ἀξιώματος καὶ τῆς τότε ταπεινότητος σκευάσας, ὅπως αἰδέσεώς τε καὶ ἐλέου ἅμα ἄξιος αὐτῷ φανείη· τὸν μὲν γὰρ χιτῶνα τὸν μεσόλευκον καὶ τὸν κάνδυν τὸν ὁλοπόρφυρον ἐξέδυ, τὴν δὲ δὴ τιάραν τό τε ἀνάδημα εἶχε. Πομπήιος δὲ ἀπὸ μὲν τοῦ ἵππου κατεβίβασεν αὐτόν, ῥαβδοῦχόν τινα πέμψας (προσήλαυνε γὰρ ὡς καὶ ἐς αὐτὸ τὸ ἔρυμα κατὰ τὸ σφέτερον ἔθος ἱππεύσων), ἐσελθόντα δὲ αὐτοποδίᾳ καὶ τό τε διάδημα ἀπορρίψαντα καὶ ἐς τὴν γῆν πεσόντα προσκυνοῦντά τε ἰδὼν ἠλέησε, καὶ ἀναπηδήσας ἐξανέστησέ τε αὐτόν, καὶ ταινιώσας τῷ ἀναδήματι ἔς τε τὴν πλησίαν ἕδραν ἐκάθισε καὶ παρεμυθήσατο, εἰπὼν ἄλλα τε καὶ ὅτι οὐ τὴν τῶν Ἀρμενίων βασιλείαν ἀπολωλεκὼς ἀλλὰ καὶ τὴν τῶν Ῥωμαίων φιλίαν προσειληφὼς εἴη. καὶ ὁ μὲν τούτοις τε αὐτὸν ἀνεκτήσατο καὶ ἐπὶ", "st": "36.52"}, {"sp": "N", "t": "δεῖπνον ἐκάλεσεν· ὁ δὲ υἱός (ἐκάθητο δὲ ἐκ τοῦ ἐπὶ θάτερα τοῦ Πομπηίου) οὔθ’ ὑπανέστη τῷ πατρὶ οὔτ’ ἄλλο τι αὐτὸν ἐδεξιώσατο, ἀλλὰ καὶ ἐπὶ τὸ δεῖπνον κληθεὶς οὐκ ἀπήντησεν. ὅθεν ὑπό γε τοῦ Πομπηίου μάλιστα ἐμισήθη. τῇ γοῦν ὑστεραίᾳ διακούσας αὐτῶν τῷ μὲν πρεσβυτέρῳ τὴν πατρῴαν πᾶσαν ἀρχὴν ἀπέδωκε· τὰ γὰρ προσκτηθέντα ὑπ’ αὐτοῦ (ἦν δὲ ἄλλα τε καὶ τῆς Καππαδοκίας τῆς τε Συρίας μέρη, ἥ τε Φοινίκη καὶ ἡ Σωφανηνὴ χώρα τοῖς Ἀρμενίοις πρόσορος οὐ σμικρά) παρείλετο αὐτοῦ, καὶ προσέτι καὶ χρήματα αὐτὸν ᾔτησεν· τῷ δὲ νεωτέρῳ τὴν Σωφανηνὴν μόνην ἀπένειμε. καὶ ἔτυχον γὰρ οἱ θησαυροὶ ἐν αὐτῇ ὄντες, ἠμφεσβήτησέ τε περὶ αὐτῶν ὁ νεανίσκος, καὶ ἁμαρτὼν (οὐ γὰρ εἶχεν ὁ Πομπήιος ὁπόθεν ἄλλοθεν τὰ ὡμολογημένα κομίσηται) ἠγανάκτησε καὶ δρασμὸν ἐβουλεύσατο. ὁ οὖν Πομπήιος προμαθὼν τοῦτο ἐκεῖνόν τε ἐν φυλακῇ ἀδέσμῳ ἐποιήσατο, καὶ πέμψας πρὸς τοὺς τὰ χρήματα φυλάττοντας τῷ πατρὶ αὐτοῦ πάντα σφᾶς δοῦναι ἐκέλευσεν. ἐπειδή τε μήθ’ ὑπήκουσαν, λέγοντες τὸν νεανίσκον, οὗπερ ἡ χώρα ἤδη ἐνομίζετο, χρῆναί σφισι τοῦτο προστάξαι, ἔπεμψεν αὐτὸν πρὸς τὰ φρούρια. καὶ ὁ μὲν κεκλειμένα αὐτὰ εὑρὼν προσῆλθέ τε ἐγγύς, καὶ ἐκέλευσε καὶ ἄκων αὐτὰ ἀνοιχθῆναι· ὡς δ’ οὐδὲν μᾶλλον ἐπείθοντο, προϊσχόμενοι ὅτι μὴ ἑκούσιος ἀλλ’ ἀναγκαστὸς τὴν πρόσταξιν ἐποιεῖτο, ἐχαλέπηνεν ὁ Πομπήιος καὶ ἔδησε τὸν Τιγράνην. καὶ οὕτως ὅ τε γέρων τοὺς θησαυροὺς παρέλαβε, καὶ αὐτὸς ἔν τε τῇ χώρᾳ τῇ Ἀναΐτιδι καὶ πρὸς τῷ ποταμῷ τῷ Κυρνῳ τριχῇ νείμας τὸν στρατὸν παρεχείμασε, τά τε ἄλλα παρὰ τοῦ Τιγράνου συχνὰ καὶ χρήματα πολλῷ πλείω τῶν ὁμολογηθέντων λαβών. ἀφ’ οὗπερ οὐχ ἥκιστα καὶ ἐκεῖνον ἔς τε τοὺς φίλους καὶ ἐς τοὺς συμμάχους οὐ πολλῷ ὕστερον ἐσέγραψε, καὶ τὸν υἱὸν αὐτοῦ ἐς τὴν Ῥώμην μετὰ φρουρᾶς ἐσήγαγεν.", "st": "36.53"}, {"sp": "N", "t": "οὐ μέντοι καὶ ἐν ἡσυχίᾳ διεχείμασεν. Ὀροίσης γὰρ Ἀλβανῶν τῶν ὑπὲρ τοῦ Κύρνου οἰκούντων βασιλεύς, τὸ μέν τι καὶ τῷ Τιγράνῃ τῷ νεωτέρῳ φίλῳ οἱ ὄντι χαρίσασθαι βουληθείς, τὸ δὲ δὴ πλεῖστον δείσας μὴ καὶ ἐς τὴν Ἀλβανίδα οἱ Ῥωμαῖοι ἐσβάλωσι, καὶ νομίσας ὅτι, ἂν ἐν τῷ χειμῶνι ἀδοκήτοις σφίσι καὶ μὴ καθ’ ἓν στρατοπεδευομένοις προσπέσῃ, πάντως τι ἐξεργάσεται, ἐστράτευσεν ἐπ’ αὐτοὺς παρ’ αὐτὰ τὰ Κρόνια, καὶ αὐτὸς μὲν ἐπὶ Μέτελλον Κέλερα, παρ’ ᾧ ὁ Τιγράνης ἦν, ἤλασεν, ἄλλους δὲ ἐπὶ τὸν Πομπήιον καὶ ἄλλους ἐπὶ Λούκιον Φλάκκον τὸν τῆς τριτημορίδος ἄρχοντα ἔπεμψεν, ὅπως πάντες ἅμα ταραχθέντες μὴ συμβοηθήσωσιν ἀλλήλοις. οὐ μὴν καὶ διεπράξατο οὐδαμόθι οὐδέν· ἐκεῖνόν τε γὰρ ὁ Κέλερ ἰσχυρῶς ἀπεκρούσατο, καὶ ὁ Φλάκκος ἐπειδὴ πολὺν τὸν περίβολον τῆς ταφρείας ὄντα ἀδύνατος ἦν ὑπὸ τοῦ μεγέθους σῶσαι, ἑτέραν ἔνδοθεν ἐποιήσατο, καὶ δόξαν ἀπ’ αὐτοῦ τοῖς ἐναντίοις ὡς καὶ φοβηθεὶς ἐμβαλών, ἐπεσπάσατο αὐτοὺς εἴσω τῆς ἔξωθεν τάφρου, κἀνταῦθα μὴ προσδεχομένοις σφίσιν ἐπεκδραμὼν πολλοὺς μὲν ἐν χερσί, πολλοὺς δὲ καὶ φεύγοντας ἐφόνευσε. κἀν τούτῳ ὁ Πομπήιος προμαθών τε τὴν πείρασιν τῶν βαρβάρων ἣν ἐπὶ τοὺς ἄλλους ἐπεποίηντο, προαπήντησε τοῖς ἐφ’ ἑαυτὸν ἐπιοῦσιν ἀπροσδόκητος, καὶ κρατήσας ἐπὶ τὸν Ὀροίσην εὐθὺς ὥσπερ εἶχεν ἠπείχθη. καὶ ἐκεῖνον μὲν οὐ κατέλαβεν (ἀπωσθείς τε γὰρ ὑπὸ τοῦ Κέλερος καὶ μαθὼν καὶ τὰ τῶν ἄλλων πταίσματα ἔφυγε), τῶν μέντοι Ἀλβανῶν συχνοὺς περὶ τὴν τοῦ Κύρνου διάβασιν συλλαβὼν ἔφθειρε. κἀκ τούτου δεηθεῖσιν αὐτοῖς ἐσπείσατο· ἄλλως μὲν γὰρ καὶ σφόδρα ἐπεθύμει ἐς τὴν χώραν αὐτῶν ἀντεμβαλεῖν, διὰ δὲ δὴ τὸν χειμῶνα ἡδέως τὸν πόλεμον ἀνεβάλετο.", "st": "36.54"}, {"sp": "HDR", "t": "Βιβλίον ΛΖʹ", "st": "37"}, {"sp": "N", "t": "τάδε ἔνεστιν ἐν τῷ τριακοστῷ ἑβδόμῳ τῶν Δίωνος Ῥωμαϊκῶν<br>α. ὡς ὁ Πομπήιος πρὸς Ἴβηρας τοὺς ἐν τῇ Ἀσίᾳ ἐπολέμησεν.<br>β. ὡς Πομπήιος τὸν Πόντον τῇ Βιθυνίᾳ προσένειμεν.<br>γ. ὡς Πομπήιος τήν τε Συρίαν καὶ τὴν Φοινίκην ὑπηγάγετο.<br>δ. ὡς Μιθριδάτης ἀπέθανε.<br>ε. περὶ τῶν Ἰουδαίων.<br>ς. ὡς Πομπήιος καταστησάμενος τὰ ἐν τῇ Ἀσίᾳ εἰς Ῥώμην ἐπανῆλθε.<br>ς. περὶ Κικέρωνος καὶ Κατιλίνου καὶ τῶν ὑπ’ αὐτῶν πραχθέντων.<br>η. περὶ Καίσαρος καὶ Πομπηίου καὶ Κράσσου καὶ τῆς συνωμοσίας αὐτῶν.<br>χρόνου πλῆθος ἔτη ἕξ, ἐν οἷς ἄρχοντες οἱ ἀριθμούμενοι οἵδε ἐγένοντο<br>λ. Αὐρήλιος Μ. υἱ. Κόττας<br>λ. Μάλλιος Λ. υἱ. Τορκουᾶτος ὑπ.<br>λ. Ἰούλιος Λ. υἱ. καῖσαρ<br>γ. Μάρκιος Γ. υἱ. Φίγουλος ὑπ.<br>μ. Τούλλιος Μ. υἱ. Κικέρων<br>γ. Ἀντώνιος Μ. υἱ. ὑπ.<br>Δέκιμος Ἰούνιος Μ. υἱ. Σιλανός<br>λ. Λικίννιος Λ. υἱ. Μουρήνας ὑπ.<br>μ. Πούπιος μ. υἱ. Πίσων<br>μ. Οὐαλέριος μ. υἱ. Μεσσάλας Νιγρός ὑπ.<br>λ. Ἀφράνιος Αὔλ. υἱ.<br>κ. Καικίλιος Κ. υἱ. Μέτελλος Κέλερ ὑπ.", "st": "37.0"}, {"sp": "N", "t": "τότε μὲν δὴ ταῦτ’ ἔπραξε, τῷ δ’ ἐπιγιγνομένῳ ἔτει, τοῦ τε Κόττου τοῦ Λουκίου καὶ τοῦ Τορκουάτου τοῦ Λουκίου ὑπατευόντων, ἐπολέμησε μὲν καὶ τοῖς Ἀλβανοῖς, ἐπολέμησε δὲ καὶ τοῖς Ἴβηρσι. καὶ προτέροις γε τούτοις καὶ παρὰ γνώμην ἠναγκάσθη συνενεχθῆναι· Ἀρτώκης γὰρ ὁ βασιλεὺς αὐτῶν (νέμονται δὲ ἐπ’ ἀμφότερα τοῦ Κύρνου, τῇ μὲν τοῖς Ἀλβανοῖς, τῇ δὲ τοῖς Ἀρμενίοις πρόσοροι) φοβηθεὶς μὴ καὶ ἐφ’ ἑαυτὸν τράπηται, πρέσβεις μὲν ὡς καὶ ἐπὶ φιλίᾳ πρὸς αὐτὸν ἔπεμψε, παρεσκευάζετο δὲ ὅπως ἐν τῷ θαρσοῦντι καὶ διὰ τοῦτο ἀνελπίστῳ οἱ ἐπίθηται. προμαθὼν οὖν καὶ τοῦτο ὁ Πομπήιος ἔς τε τὴν χώραν αὐτοῦ προενέβαλε, πρὶν ἱκανῶς τε αὐτὸν ἑτοιμάσασθαι καὶ τὴν ἐσβολὴν δυσχερεστάτην οὖσαν προκατασχεῖν, καὶ ἔφθη καὶ πρὸς τὴν πόλιν τὴν Ἀκρόπολιν ὠνομασμένην προχωρήσας, πρὶν καὶ αἰσθέσθαι τὸν Ἀρτώκην ὅτι παρείη. ἦν δὲ ἐπ’ αὐτοῖς τοῖς στενοῖς, ἔνθεν μὲν … τοῦ Καυκάσου παρατείνοντος, οὗ καὶ ἐπὶ τῇ φυλακῇ τῶν ἐσβολῶν ὠχύρωτο. ὅ τε οὖν Ἀρτώκης ἐκπλαγεὶς οὐδένα καιρὸν ὥστε συντάξασθαι ἔσχεν, ἀλλὰ διαβὰς τὸν ποταμὸν τὴν γέφυραν κατέπρησε, καὶ οἱ ἐν τῷ τείχει πρός τε τὴν φυγὴν αὐτοῦ, καὶ ἅμα καὶ μάχῃ νικηθέντες, ἐνέδοσαν. κρατήσας οὖν τῶν διόδων ὁ Πομπήιος φρουράν τε ἐπ’ αὐταῖς κατεστήσατο, καὶ ἐκεῖθεν ὁρμώμενος πᾶσαν τὴν ἐντὸς τοῦ ποταμοῦ κατεστρέψατο.", "st": "37.1"}, {"sp": "N", "t": "μέλλοντος δ’ αὖ καὶ τὸν Κύρνον διαβήσεσθαι, πέμπει πρὸς αὐτὸν ὁ Ἀρτώκης εἰρήνην τε αἰτῶν, καὶ γέφυραν τά τε ἐπιτήδεια ἑκών οἱ παρέξειν ὑπισχνούμενος. καὶ ἐποίησε μὲν ἑκάτερον ὡς καὶ συμβησόμενος, δείσας δέ, ἐπειδὴ εἶδεν αὐτὸν διαβεβηκότα, πρὸς τὸν Πέλωρον, ἐν τῇ ἀρχῇ καὶ ἐκεῖνον τῇ αὐτοῦ ῥέοντα, ἀπέφυγεν· ὃν γὰρ ἐξῆν αὐτῷ κωλῦσαι διαβῆναι, τοῦτον ἐπισπασάμενος ἀπεδίδρασκεν. ἰδὼν οὖν τοῦθ’ ὁ Πομπήιος ἐπεδίωξέ τε αὐτὸν καὶ καταλαβὼν ἐνίκησε· δρόμῳ γάρ, καὶ πρὶν τοὺς τοξότας αὐτοῦ τῇ σφετέρᾳ τέχνῃ χρήσασθαι, ὁμόσε σφίσιν ἐχώρησε καὶ δι’ ἐλαχίστου αὐτοὺς ἐτρέψατο. γενομένου δὲ τούτου Ἀρτώκης μὲν τόν τε Πέλωρον διαβὰς καὶ τὴν γέφυραν καὶ τὴν ἐκείνου καύσας ἔφυγε, τῶν δ’ ἄλλων οἱ μὲν ἐν χερσίν, οἱ δὲ καὶ τὸν ποταμὸν πεζῇ περαιούμενοι ἀπέθανον· συχνοὶ δὲ καὶ κατὰ τὰς ὕλας σκεδασθέντες ἡμέρας μέν τινας ἀπὸ τῶν δένδρων ὑπερυψήλων ὄντων ἀποτοξεύοντες διεγένοντο, ἔπειτα δὲ καὶ αὐτοὶ ὑποτμηθέντων τῶν δένδρων ἐφθάρησαν. καὶ οὕτω καὶ ὁ Ἀρτώκης ἐπεκηρυκεύσατο μὲν αὖθις τῷ Πομπηίῳ καὶ δῶρα ἔπεμψεν· ἐκείνου δὲ δὴ ταῦτα μέν, ὅπως τὰς σπονδὰς ποιήσεσθαι ἐλπίσας μὴ περαιτέρω ποι προχωρήσῃ, λαβόντος, τὴν δ’ εἰρήνην οὐχ ὁμολογήσαντος δώσειν ἂν μὴ τοὺς παῖδάς οἱ ὁμήρους προαποστείλῃ, χρόνον τινὰ ἐπέσχε, μέχρις οὗ οἱ Ῥωμαῖοι καὶ τὸν Πέλωρον διαβατόν πῃ τοῦ θέρους γενόμενον οὐ χαλεπῶς, ἄλλως τε καὶ μηδενὸς κωλύοντος, ἐπεραιώθησαν. οὕτω δὲ δὴ τούς τε παῖδας αὐτῷ ἔπεμψε, καὶ μετὰ τοῦτο καὶ συνηλλάγη.", "st": "37.2"}, {"sp": "N", "t": "κἀκ τούτου μαθὼν ὁ Πομπήιος οὐ πόρρω τὸν Φᾶσιν ὄντα, καὶ νομίσας ἔς τε τὴν Κολχίδα παρ’ αὐτὸν καταβήσεσθαι καὶ ἐκεῖθεν ἐπὶ τὸν Μιθριδάτην ἐς τὸν Βόσπορον πορεύσεσθαι, προῄει μὲν ᾗ διενοεῖτο, καὶ τούς τε Κόλχους καὶ τοὺς προσχώρους σφίσι, τὰ μὲν πείθων, τὰ δὲ καὶ ἐκφοβῶν, διῆλθε· αἰσθόμενος δὲ ἐνταῦθα ὅτι ἥ τε ἐπὶ τῆς ἠπείρου κομιδὴ διὰ πολλῶν καὶ ἀγνώστων καὶ πολεμικῶν ἐθνῶν, καὶ ἡ διὰ τῆς θαλάσσης χαλεπωτέρα διά τε τὸ ἀλίμενον τῆς χώρας καὶ διὰ τοὺς ἐνοικοῦντας αὐτὴν εἴη, τῷ μὲν Μιθριδάτῃ τὸ ναυτικὸν ἐφορμεῖν ἐκέλευσεν ὥστε ἐκεῖνόν τε τηρῆσαι μηδαμόσε ἐκπλεῦσαι καὶ τὴν ἐπαγωγὴν αὐτοῦ τῶν ἐπιτηδείων ἀφελέσθαι, αὐτὸς δὲ ἐπὶ τοὺς Ἀλβανοὺς οὐ τὴν συντομωτάτην, ὅπως σφᾶς καὶ ὑπὸ τούτου πρὸς ταῖς σπονδαῖς ἀνελπίστους καταλάβῃ, ἀλλ’ ἐς τὴν Ἀρμενίαν ἐπανελθὼν ἐτράπετο. καὶ τόν τε Κύρνον, ᾗ πορεύσιμος ὑπὸ τοῦ θέρους ἐγεγόνει, πεζῇ διέβη, τήν τε ἵππον κατὰ τὸν ῥοῦν καὶ τὰ σκευοφόρα ἑξῆς, εἶτα τοὺς πεζοὺς διιέναι κελεύσας, ἵν’ οἵ τε ἵπποι τὸ σφοδρὸν αὐτοῦ τοῖς σώμασί σφων διαχέωσι, καὶ ἐκ τῶν σκευοφόρων εἴ πού τι καὶ ὣς περιτραπείη, ἔς τε τοὺς ἐπὶ θάτερα παρακολουθοῦντας ἐμπίπτῃ καὶ μὴ περαιτέρω καταφέρηται· κἀντεῦθεν πρὸς τὸν Καμβύσην πορευόμενος ὑπὸ μὲν τῶν πολεμίων οὐδὲν δεινὸν ἔπαθεν, ὑπὸ δὲ δὴ τοῦ καύματος καὶ διὰ τοῦτο καὶ τοῦ δίψους ἰσχυρῶς μετὰ παντὸς τοῦ στρατοῦ, καίτοι νυκτὸς τὸ πολὺ τῆς ὁδοῦ διελθών, ἐταλαιπώρησεν· οἱ γὰρ ἀγωγοί σφων, ἐκ τῶν αἰχμαλώτων ὄντες, οὐ τὴν ἐπιτηδειοτάτην αὐτοὺς ἤγαγον. οὐ μὴν οὐδ’ ὁ ποταμὸς ἐν δέοντί σφισιν ἐγένετο· ψυχρότατόν τε γὰρ τὸ ὕδωρ ὄν, καὶ ἀθρόον ὑπ’ αὐτῶν ποθέν, συχνοῖς ἐλυμήνατο. ὡς δ’ οὖν οὐδὲ ἐνταῦθα ἀντίπαλόν τι αὐτοῖς ὤφθη, πρὸς τὸν Ἄβαντα προσεχώρησαν, ὕδωρ μόνον ἐπιφερόμενοι· τὰ γὰρ ἄλλα παρ’ ἑκόντων τῶν ἐπιχωρίων ἐλάμβανον, καὶ διὰ τοῦτο οὐδ’ ἐκακούργουν οὐδέν.", "st": "37.3"}, {"sp": "N", "t": "καί σφισι διαβεβηκόσιν ἤδη τὸν ποταμὸν ὁ Ὀροίσης προσιὼν ἠγγέλθη. ὁ οὖν Πομπήιος βουληθεὶς αὐτόν, πρὶν τὸ τῶν Ῥωμαίων πλῆθος γνῶναι, ἐς μάχην ὑπαγαγέσθαι, μὴ καὶ αἰσθόμενος αὐτοῦ ἀναχωρήσῃ, τούς τε ἱππέας προέταξε, προειπών σφισιν ἃ ποιήσουσι, καὶ τοὺς λοιποὺς ὄπισθεν αὐτῶν ἔς τε τὰ γόνατα κεκλιμένους καὶ ταῖς ἀσπίσι συγκεκαλυμμένους ἔχων ἀτρεμεῖν ἐποίησεν, ὥστε τὸν Ὀροίσην μὴ πρότερον μαθεῖν αὐτοὺς παρόντας πρὶν ἐν χερσὶ γενέσθαι. κἀκ τούτου ἐκεῖνός τε τῶν ἱππέων ὡς καὶ μόνων ὄντων καταφρονήσας συνέμιξέ σφισι, καὶ δι’ ὀλίγου τραπέντας ἐξεπίτηδες ἀνὰ κράτος ἐπεδίωξε· καὶ οἱ πεζοὶ ἀναστάντες ἐξαίφνης καὶ διαστάντες τοῖς μὲν σφετέροις ἀσφαλῆ τὴν φυγὴν διὰ μέσου σφῶν παρέσχον, τοὺς δὲ πολεμίους ἀπερισκέπτως τῇ διώξει χρωμένους ἐσδεξάμενοι συχνοὺς ἐκυκλώσαντο. καὶ οὗτοί τε τοὺς ἔνδον ἔκοπτον, καὶ οἱ ἱππῆς, οἱ μὲν ἐπὶ δεξιά, οἱ δὲ ἐπὶ θάτερα αὐτῶν περιελθόντες, κατὰ νώτου τοῖς ἔξω τῆς κυκλώσεως προσέπεσον. καὶ ἐκεῖ τε πολλοὺς ἐφόνευσαν ἑκάτεροι, καὶ ἑτέρους ἐς τὰς ὕλας καταφυγόντας κατέπρησαν, “ἰὼ Κρόνια ” πρὸς τὴν ἐπίθεσίν σφων τὴν τότε γενομένην ἐπιλέγοντες.", "st": "37.4"}, {"sp": "N", "t": "πράξας δὲ ταῦθ’ ὁ Πομπήιος καὶ τὴν χώραν ἐπιδραμὼν τοῖς τε Ἀλβανοῖς εἰρήνην ἔδωκε, καὶ ἄλλοις τισὶ τῶν παρὰ τὸν Καύκασον μέχρι τῆς Κασπίας θαλάσσης, ἐς ἣν ἀπὸ τοῦ Πόντου τὸ ὄρος ἀρξάμενον τελευτᾷ, κατοικούντων ἐπικηρυκευσαμένοις ἐσπείσατο. Φραάτης δὲ ἔπεμψε μὲν πρὸς αὐτὸν ἀνανεώσασθαι τὰς συνθήκας ἐθέλων· ὡς γὰρ ἐκεῖνόν τε οὕτω φερόμενον ἑώρα, καὶ τῆς Ἀρμενίας τοῦ τε Πόντου τοῦ ταύτῃ οἱ ὑποστράτηγοι αὐτοῦ τὰ λοιπὰ προσκατεστρέφοντο, ὅ τε Γαβίνιος καὶ ὑπὲρ τὸν Εὐφράτην μέχρι τοῦ Τίγριδος προεχώρησεν, ἐφοβήθη τε αὐτοὺς καὶ τὴν σύμβασιν βεβαιώσασθαι ἐπεθύμησεν· οὐ μέντοι καὶ διεπράξατό τι. ὁ γὰρ Πομπήιος πρός τε τὰ παρόντα καὶ πρὸς τὰς ἐξ αὐτῶν ἐλπίδας κατεφρόνησεν αὐτοῦ, καὶ τά τε ἄλλα ὑπερφρόνως τοῖς πρέσβεσιν ἐλάλησε, καὶ τὴν χώραν τὴν Κορδουηνήν, ὑπὲρ ἧς πρὸς τὸν Τιγράνην διεφέρετο, ἀπῄτησεν. ἐπειδή τε ἐκεῖνοι μηδέν, ἅτε μηδὲ ἐπεσταλμένοι τι περὶ αὐτῆς, ἀπεκρίναντο, ἔγραψε μέν τινα τῷ Φραάτῃ, οὐκ ἀνέμεινε δὲ ἀντιπεμφθῆναί τι, ἀλλ’ ἐς τὴν χώραν τὸν Ἀφράνιον παραχρῆμα ἔστειλε, καὶ κατασχὼν αὐτὴν ἀμαχεὶ τῷ Τιγράνῃ ἔδωκε. καὶ ὁ μὲν Ἀφράνιος διὰ τῆς Μεσοποταμίας ἐς τὴν Συρίαν παρὰ τὰ συγκείμενα πρὸς τὸν Πάρθον κομιζόμενος ἐπλανήθη, καὶ πολλὰ ὑπό τε τοῦ χειμῶνος καὶ ὑπὸ τῆς σπάνεως τῶν τροφῶν ἐκακώθη· κἂν ἀπώλοντο, εἰ μὴ Καρραῖοι, Μακεδόνων τε ἄποικοι ὄντες καὶ ἐνταῦθά που οἰκοῦντες, ὑπέλαβόν τε αὐτὸν καὶ παρέπεμψαν.", "st": "37.5"}, {"sp": "N", "t": "ταῦτά τε πρὸς τὸν Φραάτην ἀπὸ τῆς παρούσης οἱ δυνάμεως ἔπραξε, σαφέστατα τοῖς πλεονεκτεῖν βουλομένοις ἐπιδείξας ὅτι πάντα ἐκ τῶν ὅπλων ἤρτηται, καὶ ὁ ἐν αὐτοῖς κρατῶν νομοθέτης ὧν βούλεται ἀναγκαῖος γίγνεται, καὶ προσέτι καὶ πρὸς τὴν ἐπίκλησιν αὐτοῦ ὕβρισεν, ᾗπερ πρός τε τοὺς ἄλλους πάντας ἠγάλλετο καὶ πρὸς αὐτοὺς τοὺς Ῥωμαίους, οὗτοί τε αὖ πρὸς ἐκεῖνον ἀεί ποτε ἐκέχρηντο. βασιλέως γὰρ αὐτοῦ βασιλέων καλουμένου, τό τε τῶν βασιλέων ὄνομα περιέκοψε καὶ βασιλεῖ αὐτῷ μόνον ἐπιστέλλων ἔγραψε, καίτοι τῷ Τιγράνῃ τῷ αἰχμαλώτῳ καὶ τοῦτο παρὰ τὸ νομιζόμενον αὐτὸς δούς, ὅτε τὰ ἐπινίκια αὐτοῦ ἐν τῇ Ῥώμῃ ἔπεμψεν. ὁ οὖν Φραάτης καίπερ δεδιώς τε αὐτὸν καὶ θεραπεύων, ἠγανάκτησεν ἐπὶ τούτῳ ὡς καὶ τῆς βασιλείας ἐστερημένος, καὶ πέμψας πρέσβεις πάντα τε ὅσα ἠδίκητο ἐπεκάλει οἱ, καὶ τὸν Εὐφράτην ἀπηγόρευε μὴ διαβαίνειν. ἐπειδή τε οὐδὲν μέτριον ἀπεκρίνατο, εὐθὺς ἐπὶ τὸν Τιγράνην μετὰ τοῦ υἱέος αὐτοῦ, ᾧ τὴν θυγατέρα ἐδεδώκει, ἐστράτευσεν, ἐν τῷ ἦρι ἐν ᾧ Λούκιός τε Καῖσαρ καὶ Γάιος Φίγουλος ὑπάτευον· καὶ νικηθεὶς μάχῃ ἔπειθ’ ὕστερον ἀντεπεκράτησε. τοῦ τε Τιγράνου τὸν Πομπήιον ἐν Συρίᾳ ὄντα ἐπικαλεσαμένου, πρέσβεις τε αὖθις πρὸς αὐτὸν ἀπέστειλε, καὶ πολλὰ μὲν ἐκείνου κατηγόρησε, πολλὰ δὲ καὶ ἐς τοὺς Ῥωμαίους ὑπεσήμηνεν, ὥστε τὸν Πομπήιον καὶ αἰσχυνθῆναι καὶ καταπλαγῆναι.", "st": "37.6"}, {"sp": "N", "t": "οὔκουν οὔτε τῷ Τιγράνῃ ἐπεκούρησεν οὔτε πρὸς τὸν Φραάτην πολέμιόν τι ἔτ’ ἔπραξε, πρόφασιν ποιησάμενος τὸ μήτε ἐκείνην οἱ τὴν στρατείαν προστετάχθαι καὶ τὸν Μιθριδάτην ἐν ὅπλοις ἔτ’ εἶναι. ἀρκεῖσθαί τε τοῖς κατειργασμένοις ἔφασκε, καὶ οὐκ ἐβούλετο. … μὴ πλειόνων ὀρεγόμενος καὶ περὶ ἐκείνοις, ὥσπερ που καὶ ὁ Λούκουλλος, πταίσῃ. τοιαῦτα γὰρ ἐφιλοσόφει, καὶ τό τε πλεονεκτεῖν δεινὸν καὶ τὸ τῶν ἀλλοτρίων ἐφίεσθαι ἄδικον εἶναι τότε ἔλεγεν ὅτ’ οὐκέτ’ αὐτοῖς χρῆσθαι ἐδύνατο. τάς τε γὰρ τοῦ Πάρθου δυνάμεις δείσας, καὶ τὸ ἀστάθμητον τῶν πραγμάτων φοβηθείς, οὔτε τὸν πόλεμον καίτοι πολλῶν ἐναγόντων ἀνείλετο, καὶ τὰ ἐγκλήματα τοῦ βαρβάρου ἐφαύλισεν, ἀντειπὼν μὲν οὐδέν, φήσας δὲ ὑπὲρ ὁρίων τινῶν τὴν διαφορὰν αὐτῷ πρὸς τὸν Τιγράνην εἶναι, περὶ ὧν δικάσειν σφίσιν ἄνδρας τρεῖς. οὓς καὶ ἔπεμψεν· καὶ αὐτοὺς ὡς ἀληθῶς ἐκεῖνοι διαιτητὰς ἐπιγραψάμενοι πάντα τὰ πρὸς ἀλλήλους ἐγκλήματα διελύσαντο, ὀργιζόμενος μὲν ὁ Τιγράνης ὅτι τῆς ἐπικουρίας οὐκ ἔτυχε, βουλόμενος δὲ ὁ Φραάτης περιεῖναι τὸν Ἀρμένιον, ὅπως καὶ συμμάχῳ ποτὲ αὐτῷ, εἰ δεηθείη, κατὰ τῶν Ῥωμαίων χρήσαιτο. καὶ γὰρ εὖ ἠπίσταντο ἀμφότεροι ὅτι, ὁπότερος ἂν αὐτῶν τοῦ ἑτέρου κρατήσῃ, τῶν τε πραγμάτων τοῖς Ῥωμαίοις προκόψει καὶ αὐτὸς εὐχειρωτότερός σφισι γενήσεται. ἐκεῖνοι μὲν δὴ διὰ ταῦτα κατηλλάγησαν, Πομπήιος δὲ ἔν τε τῇ Ἀσπίδι καὶ τότε ἐχείμασε, καὶ τά τε ἄλλα τὰ ἔτ’ ἀνθιστάμενα προσηγάγετο, καὶ Συμφόριον τεῖχος Στρατονίκης οἱ προδούσης ἔλαβεν. αὕτη δὲ γυνή τε τοῦ Μιθριδάτου οὖσα, καὶ ὀργὴν αὐτῷ ὅτι ἐγκατελείφθη ἔχουσα, τούς τε φρουροὺς ἐς παρασκευὴν δὴ τροφῆς ἐξέπεμψε καὶ τοὺς Ῥωμαίους ἐδέξατο, καίτοι παιδὸς αὐτῆς παρὰ …", "st": "37.7"}, {"sp": "N", "t": "… τοῦτο μόνον ἐν τῇ αγορανομίᾳ ἐπῃνέθη, ἀλλ’ ὅτι καὶ τὰ Ῥωμαῖα καὶ τὰ Μεγαλήσια πολυτελέστατα ἐποίησεν, ἔτι δὲ καὶ μονομάχων ἀγῶνας ἐπὶ τῷ πατρὶ μεγαλοφρονέστατα διέθηκεν. ἐγένετο μὲν γὰρ τῶν δαπανηθέντων ἐς αὐτὰ τὰ μὲν κοινῇ. αὐτῷ πρὸς τὸν συνάρχοντα Μᾶρκον Βίβουλον, τὰ δὲ καὶ ἰδίᾳ· τοσοῦτον δὲ δὴ ἐν τούτοις ὑπερῆρεν ὥστε καὶ τὴν ἐπ’ ἐκείνοις δόξαν σφετερίσασθαι καὶ δοκεῖν ἅπαντα αὐτὸς ἀνηλωκέναι. ὁ οὖν Βίβουλος αὐτὸς ἐπισκώπτων ἔλεγεν ὅτι τὸ αὐτὸ τῷ Πολυδεύκει πεπονθὼς εἴη· τοῦ γάρ τοι ναοῦ κοινοῦ οἱ πρὸς τὸν ἀδελφὸν τὸν Κάστορα ὄντος, ἐπ’ ἐκείνου μόνου ἡ ἐπωνυμία αὐτοῦ γίγνεται.", "st": "37.8"}, {"sp": "N", "t": "ἐπὶ μὲν οὖν τούτοις ἔχαιρον οἱ Ῥωμαῖοι, τὰ δὲ δὴ τέρατα καὶ πάνυ αὐτοὺς ἐθορύβει. ἐν γὰρ τῷ Καπιτωλίῳ ἀνδριάντες τε πολλοὶ ὑπὸ κεραυνῶν συνεχωνεύθησαν καὶ ἀγάλματα ἄλλα τε καὶ Διὸς ἐπὶ κίονος ἱδρυμένον, εἰκών τέ τις λυκαίνης σύν τε τῷ Ῥώμῳ καὶ σὺν τῷ Ῥωμύλῳ ἱδρυμένη ἔπεσε, τά τε γράμματα τῶν στηλῶν ἐς ἃς οἱ νόμοι ἐσεγράφοντο συνεχύθη καὶ ἀμυδρὰ ἐγένετο. τά τε οὖν ἄλλα ἐξεθύοντο τοῖς μάντεσι πειθόμενοι, καὶ τῷ Διὶ ἄγαλμα μεῖζον, πρός τε τὰς ἀνατολὰς καὶ πρὸς τὴν ἀγορὰν βλέπον, ὅπως αἱ συνωμοσίαι ὑφ’ ὧν ἐταράττοντο ἐκφανεῖεν, ἱδρυθῆναι ἐψηφίσαντο. ταῦτά τε ἐν ἐκείνῳ τῷ ἔτει συνέβη, καὶ οἱ τιμηταὶ περὶ τῶν ὑπὲρ τὸν Ἠριδανὸν οἰκούντων διενεχθέντες (τῷ μὲν γὰρ ἐς τὴν πολιτείαν αὐτοὺς ἐσάγειν ἐδόκει, τῷ δὲ οὔ’ οὐδὲν οὐδὲ τῶν ἄλλων ἔπραξαν, ἀλλὰ καὶ τὴν ἀρχὴν ἀπεῖπον. καὶ διὰ τοῦτο καὶ οἱ διάδοχοι αὐτῶν ἐν τῷ ὑστέρῳ ἔτει οὐδὲν ἐποίησαν, ἐμποδισάντων σφᾶς τῶν δημάρχων πρὸς τὸν τῆς βουλῆς κατάλογον, δέει τοῦ μὴ τῆς γερουσίας αὐτοὺς ἐκπεσεῖν. κἀν τούτῳ πάντες οἱ ἐν τῇ Ῥώμῃ διατρίβοντες, πλὴν τῶν τὴν νῦν Ἰταλίαν οἰκούντων, ἐξέπεσον Γαΐου τινὸς Παπίου δημάρχου γνώμῃ, ἐπειδὴ ἐπεπόλαζον καὶ οὐκ ἐδόκουν ἐπιτήδειοί σφισιν εἶναι συνοικεῖν.", "st": "37.9"}, {"sp": "N", "t": "τῷ δὲ ἐχομένῳ ἔτει, τοῦ τε Φιγούλου καὶ τοῦ Καίσαρος τοῦ Λουκίου ἀρχόντων, βραχέα μέν, μνήμης δ’ οὖν ἄξια πρὸς τοὺς τῶν ἀνθρωπείων πραγμάτων παραλόγους συνηνέχθη. ὅ τε γὰρ τὸν Λουκρήτιον ἐκ τῆς τοῦ Σύλλου προστάξεως ἀποκτείνας, καὶ ἕτερός τις συχνοὺς τῶν ἐπικηρυχθέντων ὑπ’ αὐτοῦ φονεύσας, καὶ κατηγορήθησαν ἐπὶ ταῖς σφαγαῖς καὶ ἐκολάσθησαν, τοῦ Καίσαρος τοῦ Ἰουλίου τοῦθ’ ὅτι μάλιστα παρασκευάσαντος. οὕτω καὶ τοὺς πάνυ ποτὲ δυνηθέντας ἀσθενεστάτους αἱ μεταβολαὶ τῶν πραγμάτων πολλάκις ποιοῦσι. τοῦτό τε οὖν παρὰ δόξαν τοῖς πολλοῖς ἐχώρησε, καὶ ὅτι καὶ ὁ Κατιλίνας ἐπὶ τοῖς αὐτοῖς ἐκείνοις αἰτίαν (πολλοὺς γὰρ καὶ αὐτὸς τῶν ὁμοίων ἀπεκτόνει) λαβὼν ἀπελύθη. καὶ δὴ καὶ ἐκ τούτου χείρων τε πολὺ ἐγένετο, καὶ διὰ τοῦτο καὶ ἀπώλετο· τοῦ γὰρ δὴ Κικέρωνος τοῦ Μάρκου μετὰ Γαΐου Ἀντωνίου ὑπατεύσαντος, ὅτε Μιθριδάτης οὐδὲν ἔτι δεινὸν τοὺς Ῥωμαίους εἰργάσατο ἀλλὰ καὶ αὐτὸς ἑαυτὸν διέφθειρεν, ἐπεχείρησεν ἐκεῖνος τήν τε πολιτείαν νεωτερίζειν καὶ τοὺς συμμάχους ἐπ’ αὐτῇ συνιστὰς ἐς φόβον σφᾶς οὐ σμικροῦ πολέμου ἐνέβαλεν. ἐπράχθη δὲ ὧδε ἑκάτερον.", "st": "37.10"}, {"sp": "N", "t": "ὁ Μιθριδάτης αὐτὸς μὲν οὐχ ὑπεῖκε ταῖς συμφοραῖς, ἀλλὰ τῇ βουλήσει πλέον ἢ τῇ δυνάμει νέμων ἐνενόει, ἄλλως τε καὶ ἐπειδὴ ὁ Πομπήιος ἐν τῇ Συρίᾳ διέτριβε, πρός τε τὸν Ἴστρον διὰ τῶν Σκυθῶν ἐλθεῖν, κἀντεῦθεν ἐς τὴν Ἰταλίαν ἐσβαλεῖν· φύσει τε γὰρ μεγαλοπράγμων ὤν, καὶ πολλῶν μὲν πταισμάτων, πολλῶν δὲ καὶ εὐτυχημάτων πεπειραμένος, οὐδὲν οὔτε ἀτόλμητον οὔτε ἀνέλπιστόν οἱ εἶναι ἐνόμιζεν. εἰ δὲ δὴ καὶ σφαλείη, συναπολέσθαι τῇ βασιλείᾳ μετὰ ἀκεραίου τοῦ φρονήματος μᾶλλον ἢ στερηθεὶς αὐτῆς ἔν τε ταπεινότητι καὶ ἐν ἀδοξίᾳ ζῆν ἤθελεν. αὐτὸς μὲν οὖν ἐπὶ τούτοις ἔρρωτο· ὅσῳ γὰρ τῇ τοῦ σώματος ἀσθενείᾳ ἀπεμαραίνετο, τοσούτῳ τῇ τῆς γνώμης ῥώμῃ ἰσχυρίζετο, ὥστε καὶ τὴν ἐκείνου ἀρρωστίαν τοῖς ταύτης λογισμοῖς ἀναλαμβάνειν· οἱ δ’ ἄλλοι οἱ συνόντες αὐτῷ, ὡς τά τε τῶν Ῥωμαίων ἰσχυρότερα καὶ τὰ τοῦ Μιθριδάτου ἀσθενέστερα ἀεὶ ἐγίγνετο (τά τε γὰρ ἄλλα καὶ ὁ σεισμὸς μέγιστος δὴ τῶν πώποτε συνενεχθεὶς αὐτοῖς πολλὰς τῶν πόλεων ἔφθειρεν), ἠλλοιοῦντο, καὶ τά τε στρατιωτικὰ ἐκινεῖτο, καὶ παῖδάς τινας αὐτοῦ συναρπάσαντές τινες πρὸς τὸν Πομπήιον ἐκόμισαν.", "st": "37.11"}, {"sp": "N", "t": "Ἐπ’ οὖν τούτοις τοὺς μὲν ἐφώρα καὶ ἐκόλαζε, τοὺς δὲ καὶ ἐξ ὑποψίας ὀργῇ προκατελάμβανε, καὶ ἦν πρὸς οὐδένα ἔτι πιστός, ἀλλὰ καὶ τῶν λοιπῶν τέκνων ὑποτοπήσας τινὰ ἀπέσφαξεν. ἰδὼν οὖν ταῦτα υἱός τις αὐτοῦ Φαρνάκης, καὶ ἐκεῖνόν τε ἅμα φοβηθεὶς καὶ παρὰ τῶν Ῥωμαίων τὴν βασιλείαν (καὶ γὰρ ἀνὴρ ἤδη ἦν) λήψεσθαι προσδοκήσας, ἐπεβούλευσεν αὐτῷ. φωραθεὶς δέ (πολλοὶ γὰρ καὶ φανερῶς καὶ λάθρᾳ πάντα τὰ πραττόμενα ὑπ’ αὐτοῦ ἐπολυπραγμόνουν) εὐθὺς ἄν, εἴπερ τι καὶ τὸ βραχύτατον εὐνοίας οἱ δορυφόροι τῷ γέροντι εἶχον, ἐδικαιώθη· νῦν δὲ καίτοι σοφώτατος ὁ Μιθριδάτης ἐς πάντα τὰ βασιλικὰ γενόμενος, οὐκ ἔγνω ὅτι οὐδὲν οὐδενὶ οὔτε τὰ ὅπλα οὔτε τὰ πλήθη τῶν ὑπηκόων ἄνευ τῆς παρ’ αὐτῶν φιλίας ἰσχύει, ἀλλὰ καὶ ὅσῳ τις ἂν πλείω, μὴ μέντοι καὶ πιστὰ αὐτὰ ἔχῃ, χαλεπώτερα αὐτῷ γίγνεται. ὁ γοῦν Φαρνάκης μετά τε τῶν προπαρεσκευασμένων καὶ μετὰ τῶν ὑπὸ τοῦ πατρὸς πρὸς τὴν σύλληψιν αὐτοῦ πεμφθέντων (ῥᾷστα γὰρ αὐτοὺς ᾠκειώσατο) καὶ ἐπ’ αὐτὸν ἄντικρυς τὸν πατέρα ἠπείχθη. πυθόμενος δὲ τοῦτο ὁ γέρων (ἦν δὲ ἐν Παντικαπαίῳ) στρατιώτας τινὰς ἐπὶ τὸν υἱόν, ὡς καὶ αὐτὸς ἐφεψόμενός σφισι, προέπεμψε. καὶ τούτους τε ἐκεῖνος διὰ βραχέος, ἅτε μηδ’ αὐτοὺς φιλοῦντας τὸν Μιθριδάτην, ἀπετρέψατο, καὶ τὴν πόλιν ἑκουσίαν ἔλαβε, τόν τε πατέρα ἐς τὸ βασίλειον καταφυγόντα ἀπέκτεινεν.", "st": "37.12"}, {"sp": "N", "t": "ἐπεχείρησε μὲν γὰρ ἑαυτὸν διαχρήσασθαι, καὶ τάς τε γυναῖκας καὶ τοὺς παῖδας τοὺς λοιποὺς φαρμάκῳ προαπαλλάξας τὸ λοιπὸν ἐξέπιεν, οὐ μέντοι οὔτε δι’ ἐκείνου οὔτε διὰ ξίφους αὐτοχειρίᾳ ἀποφθαρῆναι ἠδυνήθη. τό τε γὰρ φάρμακον, καίτοι θανάσιμον ὄν, οὐ συνεῖλεν αὐτόν, ἐπειδὴ πολλῇ καθ’ ἑκάστην ἡμέραν προφυλακῇ ἀλεξιφαρμάκων ἐκεκράτυντο· καὶ ἡ τοῦ ξίφους πληγὴ διά τε τὴν τῆς χειρὸς αὐτοῦ ἀπό τε τῆς ἡλικίας καὶ ἀπὸ τῶν περιεστηκότων ἀσθένειαν καὶ διὰ τὴν φαρμάκου ὁποιουδηποτοῦν λῆψιν ἀπημβλύνθη. ὡς οὖν οὔτε δι’ ἑαυτοῦ ἀνηλίσκετο καὶ πέρα τοῦ καιροῦ χρονίζειν ἐδόκει, προσέπεσόν τε αὐτῷ ἐκεῖνοι οὓς ἐπὶ τὸν υἱὸν ἐπεπόμφει, καὶ συνετάχυναν τοῖς ξίφεσι καὶ ταῖς λόγχαις τὸν ὄλεθρον. Μιθριδάτης μὲν δὴ ποικιλωτάτῃ ἀεὶ καὶ μεγίστῃ τῇ τύχῃ χρησάμενος, οὐδὲ τὴν τελευτὴν τοῦ βίου ἁπλῆν ἔσχεν· ἐπεθύμησέ τε γὰρ ἀποθανεῖν μὴ βουλόμενος, καὶ αὐτὸς ἑαυτὸν ἀποκτεῖναι σπουδάσας οὐκ ἠδυνήθη, ἀλλὰ τοῦτο μὲν φαρμάκῳ τοῦτο δὲ καὶ ξίφει αὐθέντης τε ἅμα", "st": "37.13"}, {"sp": "N", "t": "ἐγένετο καὶ ὑπὸ τῶν ἐχθρῶν ἀπεσφάγη· Φαρνάκης δὲ τό τε σῶμα αὐτοῦ τῷ Πομπηίῳ ταριχεύσας, ἔλεγχον τοῦ πεπραγμένου, ἔπεμψε, καὶ ἑαυτὸν τήν τε ἀρχὴν παρέδωκε. καὶ ὃς τῷ μὲν Μιθριδάτῃ οὐδὲν ἐλυμήνατο, ἀλλὰ καὶ ἐν τοῖς πατρῴοις ἠρίοις ταφῆναι αὐτὸν ἐκέλευσε· τὸ γὰρ πολέμιον αὐτοῦ συναποσβηκέναι τῇ ψυχῇ νομίζων οὐδὲν ἔτι τῷ νεκρῷ μάτην ὠργίζετο· τὴν μέντοι βασιλείαν τοῦ Βοσπόρου μισθὸν τῷ Φαρνάκῃ τῆς μιαιφονίας ἐχαρίσατο, καὶ ἔς γε τοὺς φίλους τούς τε συμμάχους αὐτὸν ἀνέγραψεν. ὡς οὖν ἐκεῖνός τε ἀπωλώλει καὶ τὰ τῆς ἀρχῆς αὐτοῦ πάντα πλὴν ὀλίγων κατέστραπτο (τείχη γάρ τινα φρουροὶ ἔξω τοῦ Βοσπόρου ἔτι καὶ τότε ἔχοντες οὐκ εὐθὺς ὡμολόγησαν, οὐχ ὅτι καὶ ἀνθίστασθαί οἱ διενοοῦντο, ἀλλ’ ὅτι ἐφοβοῦντο μὴ τὰ χρήματα, ἃ ἐφύλασσον, προδιαρπάσαντές τινες ἐκείνοις τὴν αἰτίαν προσθῶσι, καὶ διὰ τοῦτο ἀνέμενον, αὐτῷ βουλόμενοι τῷ Πομπηίῳ πάντα", "st": "37.14"}, {"sp": "N", "t": "ἐπιδεῖξαι), ὡς οὖν τά τε ἐνταῦθα κατείργαστο καὶ ὁ Φραάτης ἡσυχίαν ἦγεν, ἥ τε Συρία καὶ ἡ Φοινίκη καθειστήκει, τρέπεται πρὸς Ἀρέταν. οὗτος δὲ Ἀραβίων μὲν τῶν νῦν τοῖς Ῥωμαίοις δουλευόντων μέχρι τῆς Ἐρυθρᾶς θαλάσσης ἐβασίλευε, πλεῖστα δὲ δὴ τὴν Συρίαν πρότερον λυπήσας, καὶ διὰ τοῦτο μάχῃ πρὸς τῶν Ῥωμαίων ἀμυνόντων αὐτῇ νικηθείς, ὅμως καὶ τότε ἔτ’ ἐπολέμει. ἐπ’ οὖν τοῦτον τούς τε πλησιοχώρους αὐτῷ ὁ Πομπήιος ἐλάσας ἀκονιτί τε αὐτοὺς προσηγάγετο καὶ φρουρᾷ παρέδωκε. κἀντεῦθεν ἐπὶ τὴν Συρίαν τὴν Παλαιστίνην ὡς καὶ τὴν Φοινίκην κακώσαντας, ὥρμησεν. ἦρχον δὲ αὐτῶν Ὑρκανός τε καὶ Ἀριστόβουλος ἀδελφοί, καὶ ἐτύγχανον ὑπὲρ τῆς τοῦ σφετέρου θεοῦ, ὅστις ποτὲ οὗτός ἐστιν, ἱερωσύνης (οὕτω γὰρ τὴν βασιλείαν σφῶν ὠνόμαζον) αὐτοί τε διαφερόμενοι καὶ τὰς πόλεις στασιάζοντες. ὁ οὖν Πομπήιος Ὑρκανὸν μὲν οὐδεμίαν ἀξιόχρεων ἰσχὺν ἔχοντα ἀμαχεὶ εὐθὺς προσέθετο, Ἀριστόβουλον δὲ ἐς χωρίον τι κατακλείσας ὁμολογῆσαί οἱ ἠνάγκασε, καὶ ἐπειδὴ μήτε τὰ χρήματα μήτε τὸ φρούριον παρεδίδου, ἔδησεν αὐτόν. κἀκ τούτου τοὺς μὲν ἄλλους ῥᾷον προσεποιήσατο, τὰ δὲ Ἱεροσόλυμα", "st": "37.15"}, {"sp": "N", "t": "πολιορκῶν πράγματα ἔσχε. τὴν μὲν γὰρ ἄλλην πόλιν, ἐσδεξαμένων αὐτὸν τῶν τὰ τοῦ Ὑρκανοῦ φρονούντων, ἀπραγμόνως ἔλαβεν, αὐτὸ δὲ τὸ ἱερὸν προκατασχόντων τῶν ἑτέρων οὐκ ἀπόνως εἷλεν· ἐπί τε γὰρ μετεώρου ἦν καὶ περιβόλῳ ἰδίῳ ὠχύρωτο. καὶ εἴ γε ἐν πάσαις ταῖς ἡμέραις ὁμοίως ἠμύνοντο, οὐκ ἂν αὐτὸ ἐχειρώσατο· νῦν δὲ τὰς τοῦ Κρόνου δὴ ὠνομασμένας διαλείποντες, καὶ οὐδὲν τὸ παράπαν ἐν αὐταῖς δρῶντες, παρέδωκαν τοῖς Ῥωμαίοις καιρὸν ἐν τῷ διακένῳ τούτῳ τὸ τεῖχος διασεῖσαι. μαθόντες γὰρ τὴν πτόησιν αὐτῶν ταύτην τὸν μὲν ἄλλον χρόνον οὐδὲν σπουδῇ ἔπραττον, ταῖς δὲ δὴ ἡμέραις ἐκείναις ὁπότε ἐκ τῆς περιτροπῆς ἐπέλθοιεν, ἐντονώτατά οἱ προσέβαλλον. καὶ οὕτως ἑάλωσάν τε ἐν τῇ τοῦ Κρόνου ἡμέρᾳ μηδ’ ἀμυνόμενοι, καὶ πάντα τὰ χρήματα διηρπάσθη. ἥ τε βασιλεία τῷ Ὑρκανῷ ἐδόθη, καὶ ὁ Ἀριστόβουλος ἀνηνέχθη. ταῦτα μὲν τότε ἐν τῇ Παλαιστίνῃ ἐγένετο· οὕτω γὰρ τὸ σύμπαν ἔθνος, ὅσον ἀπὸ τῆς Φοινίκης μέχρι τῆς Αἰγύπτου παρὰ τὴν θάλασσαν τὴν ἔσω παρήκει, ἀπὸ παλαιοῦ κέκληται. ἔχουσι δὲ καὶ ἕτερον ὄνομα ἐπίκτητον· ἥ τε γὰρ χώρα", "st": "37.16"}, {"sp": "N", "t": "Ἰουδαία καὶ αὐτοὶ Ἰουδαῖοι ὠνομάδαται· ἡ δὲ ἐπίκλησις αὕτη ἐκείνοις μὲν οὐκ οἶδ’ ὅθεν ἤρξατο γενέσθαι, φέρει δὲ καὶ ἐπὶ τοὺς ἄλλους ἀνθρώπους ὅσοι τὰ νόμιμα αὐτῶν, καίπερ ἀλλοεθνεῖς ὄντες, ζηλοῦσι. καὶ ἔστι καὶ παρὰ τοῖς Ῥωμαίοις τὸ γένος τοῦτο, κολουσθὲν μὲν πολλάκις, αὐξηθὲν δὲ ἐπὶ πλεῖστον, ὥστε καὶ ἐς παρρησίαν τῆς νομίσεως ἐκνικῆσαι. κεχωρίδαται δὲ ἀπὸ τῶν λοιπῶν ἀνθρώπων ἔς τε τἆλλα τὰ περὶ τὴν δίαιταν πάνθ’ ὡς εἰπεῖν, καὶ μάλισθ’ ὅτι τῶν μὲν ἄλλων θεῶν οὐδένα τιμῶσιν, ἕνα δέ τινα ἰσχυρῶς σέβουσιν. οὐδ’ ἄγαλμα οὐδὲν οὐδ’ ἐν αὐτοῖς ποτε τοῖς Ἱεροσολύμοις ἔσχον, ἄρρητον δὲ δὴ καὶ ἀειδῆ αὐτὸν νομίζοντες εἶναι περισσότατα ἀνθρώπων θρησκεύουσι. καὶ αὐτῷ νεών τε μέγιστον καὶ περικαλλέστατον, πλὴν καθ’ ὅσον ἀχανής τε καὶ ἀνώροφος ἦν, ἐξεποίησαν, καὶ τὴν ἡμέραν τὴν τοῦ Κρόνου καλουμένην ἀνέθεσαν, καὶ ἄλλα τε ἐν αὐτῇ ἰδιαίτατα πολλὰ ποιοῦσι, καὶ ἔργου οὐδενὸς σπουδαίου προσάπτονται. καὶ τὰ μὲν κατ’ ἐκεῖνον, τίς τε ἔστι καὶ ὅθεν οὕτως ἐτιμήθη, ὅπως τε περὶ αὐτὸν ἐπτόηνται, πολλοῖς τε εἴρηται καὶ οὐδὲν τῇδε τῇ ἱστορίᾳ", "st": "37.17"}, {"sp": "N", "t": "προσήκει· τὸ δὲ δὴ ἐς τοὺς ἀστέρας τοὺς ἑπτὰ τοὺς πλάνητας ὠνομασμένους τὰς ἡμέρας ἀνακεῖσθαι κατέστη μὲν ὑπ’ Αἰγυπτίων, πάρεστι δὲ καὶ ἐπὶ πάντας ἀνθρώπους, οὐ πάλαι ποτὲ ὡς λόγῳ εἰπεῖν ἀρξάμενον· οἱ γοῦν ἀρχαῖοι Ἕλληνες οὐδαμῇ αὐτό, ὅσα γε ἐμὲ εἰδέναι, ἠπίσταντο. ἀλλ’ ἐπειδὴ καὶ πάνυ νῦν τοῖς τε ἄλλοις ἅπασι καὶ αὐτοῖς τοῖς Ῥωμαίοις ἐπιχωριάζει, καὶ ἤδη καὶ τοῦτό σφισι πάτριον τρόπον τινά ἐστι, βραχύ τι περὶ αὐτοῦ διαλεχθῆναι βούλομαι, πῶς τε καὶ τίνα τρόπον οὕτω τέτακται. ἤκουσα δὲ δύο λόγους, ἄλλως μὲν οὐ χαλεποὺς γνωσθῆναι, θεωρίας δέ τινος ἐχομένους. εἰ γάρ τις τὴν ἁρμονίαν τὴν διὰ τεσσάρων καλουμένην, ἥπερ που καὶ τὸ κῦρος τῆς μουσικῆς συνέχειν πεπίστευται, καὶ ἐπὶ τοὺς ἀστέρας τούτους, ὑφ’ ὧν ὁ πᾶς τοῦ οὐρανοῦ κόσμος διείληπται, κατὰ τὴν τάξιν καθ’ ἣν ἕκαστος αὐτῶν περιπορεύεται ἐπαγάγοι, καὶ ἀρξάμενος ἀπὸ τῆς ἔξω περιφορᾶς τῆς τῷ Κρόνῳ δεδομένης, ἔπειτα διαλιπὼν δύο τὰς ἐχομένας τὸν τῆς τετάρτης δεσπότην ὀνομάσειε, καὶ μετ’ αὐτὴν δύο αὖ ἑτέρας ὑπερβὰς ἐπὶ τὴν ἑβδόμην ἀφίκοιτο, κἀν τῷ αὐτῷ τούτῳ τρόπῳ αὐτάς τε ἐπανιὼν καὶ τοὺς ἐφόρους σφῶν θεοὺς ἀνακυκλῶν ἐπιλέγοι ταῖς ἡμέραις, εὑρήσει πάσας αὐτὰς μουσικῶς πως", "st": "37.18"}, {"sp": "N", "t": "τῇ τοῦ οὐρανοῦ διακοσμήσει προσηκούσας. εἷς μὲν δὴ οὗτος λέγεται λόγος, ἕτερος δὲ ὅδε. τὰς ὥρας τῆς ἡμέρας καὶ τῆς νυκτὸς ἀπὸ τῆς πρώτης ἀρξάμενος ἀριθμεῖν, καὶ ἐκείνην μὲν τῷ Κρόνῳ διδούς, τὴν δὲ ἔπειτα τῷ Διί, καὶ τρίτην Ἄρει, τετάρτην ἡλίῳ, πέμπτην Ἀφροδίτῃ, ἕκτην Ἑρμῇ, καὶ ἑβδόμην σελήνῃ, κατὰ τὴν τάξιν τῶν κύκλων καθ’ ἣν οἱ Αἰγύπτιοι αὐτὴν νομίζουσι, καὶ τοῦτο καὶ αὖθις ποιήσας, πάσας τε οὕτω τὰς τέσσαρας καὶ εἴκοσιν ὥρας περιελθών, εὑρήσεις τὴν πρώτην τῆς ἐπιούσης ἡμέρας ὥραν ἐς τὸν ἥλιον ἀφικνουμένην. καὶ τοῦτο καὶ ἐπ’ ἐκείνων τῶν τεσσάρων καὶ εἴκοσιν ὡρῶν κατὰ τὸν αὐτὸν τοῖς πρόσθε λόγον πράξας, τῇ σελήνῃ τὴν πρώτην τῆς τρίτης ἡμέρας ὥραν ἀναθήσεις, κἂν οὕτω καὶ διὰ τῶν λοιπῶν πορεύῃ, τὸν προσήκοντα ἑαυτῇ θεὸν ἑκάστη ἡμέρα λήψεται.", "st": "37.19"}, {"sp": "N", "t": "ταῦτα μὲν οὕτω παραδέδοται· Πομπήιος δὲ ἐπειδὴ καὶ ἐκεῖνα κατέπραξεν, πρός τε τὸν Πόντον αὖθις ἦλθε, καὶ παραλαβὼν τὰ τείχη ἔς τε τὴν Ἀσίαν κἀντεῦθεν ἐς τὴν Ἑλλάδα τήν τε Ἰταλίαν ἐκομίσθη. πολλὰς μὲν δὴ οὖν μάχας ἐνίκησε, πολλοὺς δὲ καὶ δυνάστας καὶ βασιλέας τοὺς μὲν προσεπολεμώσατο, τοὺς δὲ καὶ ὁμολογίᾳ προσεποιήσατο, πόλεις τε ὀκτὼ ἀπῴκισε, καὶ χώρας προσόδους τε συχνὰς τοῖς Ῥωμαίοις ἀπέδειξε, τά τε πλείω ἔθνη τῶν ἐν τῇ Ἀσίᾳ τῇ ἠπείρῳ τότε αὐτοῖς ὄντων νόμοις τε ἰδίοις καὶ πολιτείαις κατεστήσατο καὶ διεκόσμησεν, ὥστε καὶ δεῦρο αὐτοὺς τοῖς ὑπ’ ἐκείνου νομισθεῖσι χρῆσθαι. ἀλλὰ ταῦτα μέν, καίπερ μεγάλα τε ὄντα καὶ μηδενὶ τῶν πρόσθε Ῥωμαίων πραχθέντα, καὶ τῇ τύχῃ καὶ τοῖς συστρατευσαμένοις οἱ ἀναθείη ἄν τις· ὃ δὲ δὴ μάλιστα αὐτοῦ τε τοῦ Πομπηίου ἔργον ἐγένετο καὶ θαυμάσαι διὰ πάντων ἄξιόν ἐστι, τοῦτο νῦν ἤδη φράσω. πλείστην μὲν γὰρ ἰσχὺν καὶ ἐν τῇ θαλάσσῃ καὶ ἐν τῇ ἠπείρῳ ἔχων, πλεῖστα δὲ χρήματα ἐκ τῶν αἰχμαλώτων πεπορισμένος, δυνάσταις τε καὶ βασιλεῦσι συχνοῖς ᾠκειωμένος, τούς τε δήμους ὧν ἦρξε πάντας ὡς εἰπεῖν δι’ εὐνοίας εὐεργεσίαις κεκτημένος, δυνηθείς τ’ ἂν δι’ αὐτῶν τήν τε Ἰταλίαν κατασχεῖν καὶ τὸ τῶν Ῥωμαίων κράτος πᾶν περιποιήσασθαι, τῶν μὲν πλείστων ἐθελοντὶ ἂν αὐτὸν δεξαμένων, εἰ δὲ καὶ ἀντέστησάν τινες, ἀλλ’ ὑπ’ ἀσθενείας γε πάντως ἂν ὁμολογησάντων, οὐκ ἠβουλήθη τοῦτο ποιῆσαι, ἀλλ’ εὐθύς, ἐπειδὴ τάχιστα ἐς τὸ Βρεντέσιον ἐπεραιώθη, τὰς δυνάμεις πάσας αὐτεπάγγελτος, μήτε τῆς βουλῆς μήτε τοῦ δήμου ψηφισαμένου τι περὶ αὐτῶν, ἀφῆκεν, οὐδὲν οὐδὲ τοῦ ἐς τὰ νικητήρια αὐταῖς χρήσασθαι φροντίσας. ἐπειδὴ γὰρ τά τε τοῦ Μαρίου καὶ τὰ τοῦ Σύλλου ἐν μίσει τοῖς ἀνθρώποις ἠπίστατο ὄντα, οὐκ ἠθέλησε φόβον τινὰ αὐτοῖς οὐδ’ ἐπ’ ὀλίγας ἡμέρας, ὅτι τι τῶν ὁμοίων πείσονται, παρασχεῖν.", "st": "37.20"}, {"sp": "N", "t": "οὔκουν οὐδ’ ὄνομα οὐδέν, καίτοι πολλὰ ἀπὸ τῶν κατειργασμένων λαβεῖν ἂν δυνηθείς, προσεκτήσατο. τὰ μὲν γὰρ ἐπινίκια, λέγω δὴ τὰ μείζω νομιζόμενα, καίπερ οὐχ ὅσιον ὂν ἔκ γε τῶν πάνυ πατρίων ἄνευ τῶν συννικησάντων τινὶ πεμφθῆναι, ὅμως ψηφισθέντα ἐδέξατο. καὶ αὐτὰ μὲν ἅπαξ ἀπὸ πάντων τῶν πολέμων ἤγαγε, τρόπαια δὲ ἄλλα τε πολλὰ καὶ καλῶς κεκοσμημένα καθ’ ἕκαστον τῶν ἔργων καὶ τὸ βραχύτατον ἔπεμψε, καὶ ἐπὶ πᾶσιν ἓν μέγα, πολυτελῶς τε κεκοσμημένον καὶ γραφὴν ἔχον ὅτι τῆς οἰκουμένης ἐστίν. οὐ μέντοι καὶ ἐπωνυμίαν τινὰ προσεπέθετο, ἀλλὰ καὶ μόνῃ τῇ τοῦ Μάγνου, ἥνπερ που καὶ πρὸ ἐκείνων τῶν ἔργων ἐκέκτητο, ἠρκέσθη. οὐ μὴν οὐδ’ ἄλλην τινὰ τιμὴν ὑπέρογκον λαβεῖν διεπράξατο, ἢ τοῖς γε ψηφισθεῖσιν ἀπόντι οἱ πλὴν ἅπαξ ἐχρήσατο. ἦν δὲ ταῦτα δαφνηφορεῖν τε αὐτὸν κατὰ πάσας ἀεὶ τὰς πανηγύρεις, καὶ τὴν στολὴν τὴν μὲν ἀρχικὴν ἐν πάσαις αὐταῖς, τὴν δὲ ἐπινίκιον ἐν τοῖς τῶν ἵππων ἀγῶσιν ἐνδύνειν. ταῦτα γὰρ αὐτῷ, συμπράσσοντος ἐς τὰ μάλιστα τοῦ Καίσαρος, καὶ παρὰ τὴν τοῦ Κάτωνος τοῦ Μάρκου γνώμην, ἐδόθη.", "st": "37.21"}, {"sp": "N", "t": "καὶ περὶ μὲν ἐκείνου, ὅστις τε ἦν καὶ ὅτι τοὺς πολλοὺς ἐθεράπευε, τόν τε Πομπήιον ἄλλως μὲν καθῄρει, δι’ ὧν δὲ δὴ τῷ τε ὁμίλῳ χαριεῖσθαι καὶ αὐτὸς ἰσχύσειν ἔμελλε προσεποιεῖτο, προείρηται· ὁ δὲ δὴ Κάτων οὗτος ἦν ἐκ τοῦ τῶν Πορκίων γένους καὶ τὸν Κάτωνα τὸν πάνυ ἐζήλου, πλὴν καθ’ ὅσον παιδείᾳ Ἑλληνικῇ μᾶλλον αὐτοῦ ἐκέχρητο. ἤσκει δὲ τὰ τοῦ πλήθους ἀκριβῶς, καὶ ἕνα μὲν ἀνθρώπων οὐδένα ἐθαύμαζε, τὸ δὲ δὴ κοινὸν ὑπερηγάπα, καὶ πᾶν μὲν τὸ ὑπὲρ τοὺς ἄλλους πεφυκὸς ὑποψίᾳ δυναστείας ἐμίσει, πᾶν δὲ τὸ δημοτικὸν ἐλέῳ τῆς ἀσθενείας ἐφίλει. καὶ δημεραστής τε ὡς οὐδεὶς ἄλλος ἐγίγνετο, καὶ τὴν ὑπὲρ τοῦ δικαίου παρρησίαν καὶ μετὰ κινδύνων ἐποιεῖτο. καὶ ταῦτα μέντοι πάντα οὔτε πρὸς ἰσχὺν οὔτε πρὸς δόξαν ἢ τιμήν τινα, ἀλλ’ αὐτῆς ἕνεκα τῆς τε αὐτονόμου καὶ τῆς ἀτυραννεύτου διαίτης ἔπραττε. τοιοῦτος οὖν δή τις ὢν ἔς τε τὸ κοινὸν τότε πρῶτον παρῆλθε καὶ πρὸς τὰ ψηφιζόμενα, καίπερ μηδεμίαν τῷ Πομπηίῳ ἔχθραν ἔχων, ἀλλ’ ὅτι γε ἔξω τῶν πατρίων ἦν, ἀντεῖπεν.", "st": "37.22"}, {"sp": "N", "t": "ἀπόντι μὲν δὴ οὖν αὐτῷ ταῦτ’ ἔδοσαν, ἐλθόντι δὲ οὐδέν, πάντως ἄν που καὶ ἕτερα προσθέντες, εἴπερ ἠθελήκει· ἄλλοις γοῦν τισιν ἐν ἐλάττονι αὐτοῦ κράτει γενομένοις πολλὰ καὶ ὑπέρογκα πολλάκις ἔνειμαν. καὶ ὅτι γε καὶ ἐκεῖνα ἄκοντες ἔπραξαν, δῆλόν ἐστιν. ὁ οὖν Πομπήιος εὖ εἰδὼς ὅτι πάνθ’ ὅσα ἐν ταῖς δυναστείαις τοῖς ἰσχύουσί τι παρὰ τῶν πολλῶν γίγνεται, τήν τε ὑπόνοιαν, κἂν τὰ μάλιστα ἐθελούσιοί τι ψηφίσωνται, ὡς καὶ κατὰ βίαν ἐκ τῆς τῶν κρατούντων παρασκευῆς διδόμενα ἔχει, καὶ δόξαν οὐδεμίαν τοῖς λαβοῦσιν αὐτά, ὡς καὶ μὴ παρ’ ἑκόντων ἀλλὰ ἀναγκασθέντων, μηδ’ ἀπ’ εὐνοίας ἀλλ’ ἐκ κολακείας ὑπάρξαντά σφισι φέρει, οὐκ ἐπέτρεψεν ἀρχὴν οὐδενὶ οὐδὲν ἐσηγήσασθαι. καὶ πολύ γε τοῦτο βέλτιον εἶναι ἔλεγεν ἢ ψηφισθέντα μὴ προσίεσθαι· ἐν μὲν γὰρ τῷ μῖσός τε ἐπὶ τῇ δυναστείᾳ ὑφ’ ἧς ἐγιγνώσκετο, καὶ ὑπερηφανίαν καὶ ὕβριν τῷ μὴ δέχεσθαι τὰ διδόμενα παρὰ τῶν κρειττόνων δῆθεν ἢ πάντως γε τῶν ὁμοίων ἐνεῖναι, ἐν δὲ τῷ ἑτέρῳ τὸ δημοτικὸν ὄντως καὶ ὄνομα καὶ ἔργον, οὐκ ἀπ’ ἐνδείξεως ἀλλ’ ἐξ ἀληθείας, ὑπάρχειν. τὰς γάρ τοι ἀρχὰς καὶ τὰς ἡγεμονίας ἔξω τῶν πατρίων ὀλίγου πάσας λαβών, τὰ γοῦν ἄλλα τοιαῦτα, ἐξ ὧν μήτε ὠφελῶν τινα μήτε ὠφελούμενος φθόνον ἄλλως καὶ μῖσος καὶ πρὸς αὐτῶν τῶν διδόντων αὐτὰ σχήσειν ἔμελλεν, οὐκ ἐδέχετο.", "st": "37.23"}, {"sp": "N", "t": "καὶ ταῦτα μὲν ἀνὰ χρόνον ἐγένετο, τότε δὲ οἱ Ῥωμαῖοι πολέμων ἀνάπαυσιν τὸν λοιπὸν τοῦ ἔτους χρόνον ἔσχον, ὥστε καὶ τὸ οἰώνισμα τὸ τῆς ὑγιείας ὠνομασμένον διὰ πάνυ πολλοῦ ποιῆσαι. τοῦτο δὲ δὴ μαντείας τις τρόπος ἐστί, πύστιν τινὰ ἔχων εἰ ἐπιτρέπει σφίσιν ὁ θεὸς ὑγίειαν τῷ δήμῳ αἰτῆσαι, ὡς οὐχ ὅσιον ὂν οὐδὲ αἴτησιν αὐτῆς, πρὶν συγχωρηθῆναι, γενέσθαι. καὶ ἐτελεῖτο κατ’ ἔτος ἡμέρᾳ, ἐν ᾗ μηδὲν στρατόπεδον μήτε ἐπὶ πόλεμον ἐξῄει μήτ’ ἀντιπαρετάττετό τισι μήτε ἐμάχετο. καὶ διὰ τοῦτο ἐν τοῖς συνεχέσι κινδύνοις, καὶ μάλιστα τοῖς ἐμφυλίοις, οὐκ ἐποιεῖτο· ἄλλως τε γὰρ παγχάλεπόν σφισιν ἦν καθαρὰν ἀπὸ πάντων αὐτῶν ἡμέραν ἀκριβῶς τηρῆσαι, καὶ προσέτι καὶ ἀτοπώτατον, κακὰ αὐτοὺς ἐν ταῖς στάσεσιν ἑκουσίους ἀμύθητα ἀλλήλοις παρέχοντας, καὶ μέλλοντας, ἄν τε ἡττηθῶσιν ἄν τε καὶ νικήσωσι, κακοῦσθαι, ἔπειτα σωτηρίαν παρὰ τοῦ θείου προσαιτεῖν.", "st": "37.24"}, {"sp": "N", "t": "ἀμέλει καὶ τότε ἠδυνήθη μέν πως τὸ οἰώνισμα ἐκεῖνο ποιηθῆναι, οὐ μέντοι καὶ καθαρὸν ἐγένετο. ἔξεδροι γάρ τινες ὄρνιθες ἐπέπταντο, καὶ διὰ τοῦτ’ ἀνεμαντεύσαντο. καὶ ἄλλα τε αὐτοῖς σημεῖα οὐκ αἴσια συνηνέχθη· κεραυνοί τε γὰρ ἐν αἰθρίᾳ πολλοὶ ἔπεσον, καὶ ἡ γῆ ἰσχυρῶς ἐσείσθη, εἴδωλά τε πολλαχόθι ἀνθρώπων ἐφαντάσθη, καὶ λαμπάδες ἀνεκὰς ἐς τὸν οὐρανὸν ἀπὸ τῶν δυσμῶν ἀνέδραμον, ὥστε πάντα τινὰ καὶ ἰδιώτην τὰ σημαινόμενα ἀπ’ αὐτῶν προγνῶναι. οἱ γὰρ δήμαρχοι τὸν Ἀντώνιον τὸν ὕπατον ὁμοιοτροπώτατόν σφισιν ὄντα προσλαβόντες, ὁ μέν τις τοὺς παῖδας τῶν ὑπὸ τοῦ Σύλλου ἐκπεσόντων πρὸς τὰς ἀρχὰς ἦγεν, ὁ δὲ τῷ τε Παίτῳ τῷ Πουπλίῳ καὶ τῷ Σύλλᾳ τῷ Κορνηλίῳ τῷ μετ’ αὐτοῦ ἁλόντι τό τε βουλεύειν καὶ τὸ ἄρχειν ἐξεῖναι ἐδίδου. ἄλλος χρεῶν ἀποκοπάς, ἄλλος κληρουχίας καὶ ἐν τῇ Ἰταλίᾳ καὶ ἐν τῷ ὑπηκόῳ γενέσθαι ἐσηγεῖτο. καὶ ταῦτα μὲν πρός τε τοῦ Κικέρωνος καὶ πρὸς τῶν ἄλλων τῶν ὁμογνωμονούντων οἱ προκαταληφθέντα, πρὶν ἔργον τι ἀπ’ αὐτῶν συμβῆναι,", "st": "37.25"}, {"sp": "N", "t": "ἐπαύθη· Τίτος δὲ δὴ Λαβιῆνος Γάιον Ῥαβίριον ἐπὶ τῷ τοῦ Σατουρνίνου φόνῳ γραψάμενος πλεῖστόν σφισι τάραχον παρέσχεν. ὅ τε γὰρ Σατουρνῖνος πρὸ ἕξ που καὶ τριάκοντα ἐτῶν ἐτεθνήκει, καὶ τὰ κατὰ τὸν πόλεμον τὸν πρὸς αὐτὸν οἱ ὕπατοι τότε παρὰ τῆς βουλῆς προσετετάχατο, ὥστε ἡ γερουσία ἄκυρος ἐκ τοῦ δικαστηρίου ἐκείνου τῶν ψηφισμάτων ἐγίγνετο. κἀκ τούτου πᾶς ὁ κόσμος τῆς πολιτείας ἐταράττετο. ὁ μὲν γὰρ Ῥαβίριος οὐδ’ ὡμολόγει τὸν φόνον, ἀλλ’ ἄπαρνος ἦν· οἱ δὲ δήμαρχοι τήν τε ἰσχὺν καὶ τὴν ἀξίωσιν τῆς βουλῆς καταλῦσαι παντελῶς ἐσπούδαζον, καὶ ἐξουσίαν ἑαυτοῖς τοῦ πάνθ’ ὅσα βούλοιντο ποιεῖν προπαρεσκεύαζον· διὰ γὰρ δὴ τοῦ τά τε τῷ συνεδρίῳ δόξαντα καὶ τὰ πρὸ τοσούτων ἐτῶν πραχθέντα εὐθύνεσθαι τοῖς τέ τι τῶν ὁμοίων ἐπιχειροῦσι ἄδεια ἐδίδοτο καὶ αἱ τιμωρίαι αὐτῶν ἐκολούοντο. ἡ οὖν γερουσία δεινὸν μὲν καὶ ἄλλως ἐνόμιζεν εἶναι ἄνδρα βουλευτὴν μήτ’ ἀδικοῦντά τι καὶ ἐς γῆρας ἤδη προεληλυθότα ἀπολεῖσθαι, πολλῷ δὲ δὴ μᾶλλον ἠγανάκτει ὅτι τό τε πρόσχημα τῆς πολιτείας διεβάλλετο καὶ τὰ πράγματα", "st": "37.26"}, {"sp": "N", "t": "τοῖς φαυλοτάτοις ἐπετρέπετο. σπουδαί τε οὖν ταραχώδεις καὶ φιλονεικίαι ἀφ’ ἑκατέρων περί τε τοῦ δικαστηρίου, τῶν μὲν ὅπως μὴ συναχθῇ, τῶν δὲ ἵνα καθιζήσῃ δικαιούντων, καὶ ἐπειδὴ τοῦτο διά τε τὸν Καίσαρα καὶ δι’ ἄλλους τινὰς ἐνίκησε, περί γε τῆς κρίσεως αὖθις συνέβησαν. καὶ ἦν γὰρ αὐτὸς ἐκεῖνος καὶ μετὰ τοῦ Καίσαρος τοῦ Λουκίου δικάζων (οὐ γὰρ ἁπλῶς, ἀλλὰ τὸ δὴ λεγόμενον περδουελλίωνος ὁ Ῥαβίριος ἐκρίθη), κατεψηφίσαντο αὐτοῦ, καίτοι μὴ πρὸς τοῦ δήμου κατὰ τὰ πάτρια, ἀλλὰ πρὸς αὐτοῦ τοὺ στρατηγοῦ οὐκ ἐξὸν αἱρεθέντες. καὶ ἐφῆκε μὲν ὁ Ῥαβίριος, πάντως δ’ ἂν καὶ παρὰ τῷ δήμῳ ἑάλω, εἰ μὴ ὁ Μέτελλος ὁ Κέλερ οἰωνιστής τε ὢν καὶ στρατηγῶν ἐνεπόδισεν· ἐπειδὴ γὰρ οὔτε ἄλλως ἐπείθοντό οἱ, οὔθ’ ὅτι παρὰ τὰ νενομισμένα ἡ κρίσις ἐγεγόνει ἐνεθυμοῦντο, ἀνέδραμεν ἐς τὸ Ἰανίκουλον πρὶν καὶ ὁτιοῦν σφας ψηφίσασθαι, καὶ τὸ σημεῖον τὸ στρατιωτικὸν κατέσπασεν, ὥστε μηδὲν ἔτ’ αὐτοῖς ἐξεῖναι διαγνῶναι.", "st": "37.27"}, {"sp": "N", "t": "τοῦτο δέ, τὸ κατὰ τὸ σημεῖον, τοιόνδε τί ἐστι. πολλῶν τὸ ἀρχαῖον πολεμίων τῇ πόλει προσοικούντων, φοβούμενοι μή ποτε ἐκκλησιαζόντων σφῶν κατὰ τοὺς λόχους ἐπίθωνταί τινες τῇ πόλει τὸ Ἰανίκουλον καταλαβόντες, ἐνόμισαν μὴ πάντες ἅμα ψηφίζεσθαι, ἀλλά τινας ἀεὶ ἐνόπλους τὸ χωρίον ἐκεῖνο ἐκ διαδοχῆς φυλάττειν. καὶ αὐτό, ἕως μὲν ἡ ἐκκλησία ἦν, ἐφρούρουν, ὁπότε δὲ διαλυθήσεσθαι ἔμελλε, τό τε σημεῖον καθῃρεῖτο καὶ οἱ φύλακες ἀπηλλάσσοντο· οὐ γὰρ ἐξῆν μὴ φρουρουμένου τοῦ χωρίου ἐκείνου οὐδὲν ἔτι χρηματισθῆναι. τοῦτο δὲ ἐν μόναις ταῖς κατὰ τοὺς λόχους ἀθροιζομέναις ἐκκλησίαις ἐγίγνετο, ὅτι τε ἔξω τοῦ τείχους, καὶ ὅτι πάντες οἱ τὰ ὅπλα ἔχοντες ἀνάγκην εἶχον ἐς αὐτὰς συνιέναι· καὶ ἔτι καὶ νῦν ὁσίας ἕνεκα ποιεῖται. οὕτω μὲν δὴ τότε ἥ τε ἐκκλησία καθαιρεθέντος τοῦ σημείου διελύθη καὶ ὁ Ῥαβίριος ἐσώθη· ἐξῆν μὲν γὰρ τῷ Λαβιήνῳ καὶ αὖθις δικάσασθαι, οὐ", "st": "37.28"}, {"sp": "N", "t": "μέντοι καὶ ἐποίησεν αὐτό· ὁ δὲ δὴ Κατιλίνας ὧδέ τε καὶ διὰ τάδε ἀπώλετο. ἔδοξε τῇ βουλῇ, τήν τε ὑπατείαν καὶ τότε αἰτήσαντος αὐτοῦ καὶ πᾶν ὁτιδήποτε ἐνεδέχετο ὅπως ἀποδειχθῇ μηχανωμένου, δέκα ἐτῶν φυγήν, τοῦ Κικέρωνος ἐς τὰ μάλιστα ἐνάγοντος, τοῖς ἐπιτιμίοις τοῖς ἐπὶ τῷ δεκασμῷ τεταγμένοις προσνομοθετῆσαι. τοῦτ’ οὖν καὶ ἐκεῖνος δι’ ἑαυτόν, ὅπερ που καὶ ἀληθὲς ἦν, ἐγνῶσθαι νομίσας ἐπεχείρησε μέν, χεῖρά τινα παρασκευάσας, τὸν Κικέρωνα καὶ ἄλλους τινὰς τῶν πρώτων ἐν αὐταῖς ταῖς ἀρχαιρεσίαις, ἵν’ ὕπατος εὐθὺς χειροτονηθῇ, φονεῦσαι, οὐκ ἠδυνήθη δέ. ὁ γὰρ Κικέρων προμαθὼν τὸ ἐπιβούλευμα τῇ τε γερουσίᾳ ἐμήνυσεν αὐτὸ καὶ κατηγορίαν αὐτοῦ πολλὴν ἐποιήσατο· ἐπειδή τε οὐκ ἔπεισέ σφας ψηφίσασθαί τι ὧν ἠξίου (οὔτε γὰρ πιθανὰ ἐξηγγελκέναι καὶ διὰ τὴν ἑαυτοῦ ἔχθραν καταψεύδεσθαι τῶν ἀνδρῶν ὑπωπτεύθη), ἐφοβήθη ἅτε καὶ προσπαρωξυγκὼς τὸν Κατιλίναν, καὶ οὐκ ἐτόλμησεν ἁπλῶς ἐς τὴν ἐκκλησίαν ἐσελθεῖν ὥσπερ εἰώθει, ἀλλὰ τούς τε ἐπιτηδείους συνεπηγάγετο παρεσκευασμένους ἀμῦναί οἱ εἴ τι δεινὸν γένοιτο, καὶ θώρακα, τῆς τε ἑαυτοῦ ἀσφαλείας καὶ τῆς ἐκείνων διαβολῆς ἕνεκα, ὑπὸ μὲν τὴν ἐσθῆτα, παραφαίνων δ’ αὐτὸν ἐξεπίτηδες, ἐνεδύσατο. ἔκ τε οὖν τούτου, καὶ ὅτι καὶ ἄλλως φήμη τις ἐγένετο ὅτι ἐπιβουλεύεται, ὅ τε δῆμος δεινῶς ἠγανάκτησε καὶ οἱ συνομωμοκότες τῷ Κατιλίνᾳ φοβηθέντες αὐτὸν ἡσύχασαν.", "st": "37.29"}, {"sp": "N", "t": "καὶ οὕτως ὕπατοί τε ἕτεροι ᾑρέθησαν, καὶ ἐκεῖνος οὐκέτι λάθρᾳ, οὐδὲ ἐπὶ τὸν Κικέρωνα τούς τε σὺν αὐτῷ μόνους, ἀλλὰ καὶ ἐπὶ πᾶν τὸ κοινὸν τὴν ἐπιβουλὴν συνίστη. ἐκ γὰρ τῆς Ῥώμης αὐτῆς τούς τε κακίστους καὶ καινῶν ἀεί ποτε πραγμάτων ἐπιθυμητάς, κἀκ τῶν συμμάχων ὡς ὅτι πλείστους, χρεῶν τε ἀποκοπὰς καὶ γῆς ἀναδασμούς, ἄλλα τε ἐξ ὧν μάλιστα δελεάσειν αὐτοὺς ἤμελλεν, ὑπισχνούμενός σφισι συνῆγε. καὶ τούς γε πρώτους αὐτῶν καὶ δυνατωτάτους (ἦσαν δὲ ἄλλοι τε καὶ Ἀντώνιος ὁ ὕπατος) καὶ ἐς ἀθεμίτων ὁρκωμοσιῶν ἀνάγκην προήγαγε· παῖδα γάρ τινα καταθύσας, καὶ ἐπὶ τῶν σπλάγχνων αὐτοῦ τὰ ὅρκια ποιήσας, ἔπειτ’ ἐσπλάγχνευσεν αὐτὰ μετὰ τῶν ἄλλων. συνέπραττον δὲ αὐτῷ τὰ μάλιστα τὰ μὲν ἐν τῇ Ῥώμῃ ὅ τε ὕπατος καὶ ὁ Λέντουλος ὁ Πούπλιος ὁ μετὰ τὴν ὑπατείαν ἐκ τῆς γερουσίας ἐκπεσών (ἐστρατήγει γὰρ ὅπως τὴν βουλείαν ἀναλάβῃ), τὰ δὲ ἐν ταῖς Φαισούλαις, ἐς ἃς οἱ στασιῶται αὐτοῦ συνελέγοντο, Γάιός τις Μάλλιος, τῶν τε πολεμικῶν ἐμπειρότατος (μετὰ γὰρ τῶν τοῦ Σύλλου λοχαγῶν ἐστράτευτο ) καὶ πολυδαπανώτατος ὤν· σύμπαντα γοῦν ὅσα τότε ἐκτήσατο, καίπερ πάμπολλα ὄντα, κακῶς καταναλώσας ἑτέρων ἔργων ὁμοίων ἐπεθύμει.", "st": "37.30"}, {"sp": "N", "t": "παρασκευαζομένων οὖν ταῦτα αὐτῶν, μηνύεται τῷ Κικέρωνι πρότερα μὲν τὰ ἐν τῷ ἄστει γιγνόμενα διὰ γραμμάτων τινῶν, ἃ τὸν μὲν γράψαντα οὐκ ἐδήλου, τῷ δὲ δὴ Κράσσῳ καὶ ἄλλοις τισὶ τῶν δυνατῶν ἐδόθη, καὶ ἐπ’ αὐτοῖς δόγμα ἐκυρώθη, ταραχήν τε εἶναι καὶ ζήτησιν τῶν αἰτίων αὐτῆς γενέσθαι· δεύτερα δὲ τὰ ἀπὸ τῆς Τυρσηνίδος, καὶ προσεψηφίσαντο τοῖς ὑπάτοις τὴν φυλακὴν τῆς τε πόλεως καὶ τῶν ὅλων αὐτῆς πραγμάτων, καθάπερ εἰώθεσαν· καὶ γὰρ τούτῳ τῷ δόγματι προσεγράφη τὸ διὰ φροντίδος αὐτοὺς σχεῖν ὥστε μηδεμίαν ἀποτριβὴν τῷ δημοσίῳ συμβῆναι. γενομένου δὲ τούτου καὶ φρουρᾶς πολλαχόθι καταστάσης τὰ μὲν ἐν τῷ ἄστει οὐκέτ’ ἐνεωτερίσθη, ὥστε καὶ ἐπὶ συκοφαντίᾳ τὸν Κικέρωνα διαβληθῆναι, τὰ δὲ ἐκ τῶν Τυρσηνῶν ἀγγελλόμενα τήν τε αἰτίαν ἐπιστώσατο καὶ βίας ἐπ’ αὐτοῖς γραφὴν τῷ Κατιλίνᾳ παρεσκεύασε.", "st": "37.31"}, {"sp": "N", "t": "καὶ ὃς τὰ μὲν πρῶτα καὶ πάνυ αὐτὴν ἑτοίμως, ὡς καὶ ἀπὸ χρηστοῦ τοῦ συνειδότος, ἐδέξατο, καὶ πρός τε τὴν δίκην δῆθεν ἡτοιμάζετο, καὶ τῷ Κικέρωνι αὐτῷ τηρεῖν ἑαυτόν, ὅπως δὴ μὴ φύγῃ που, παρεδίδου. μὴ προσδεξαμένου δὲ ἐκείνου τὴν φρουρὰν αὐτοῦ, παρὰ τῷ Μετέλλῳ τῷ στρατηγῷ τὴν δίαιταν ἑκούσιος ἐποιεῖτο, ἵν’ ὡς ἥκιστα ὑποπτευθῇ νεωτερίζειν τι, μέχρις ἂν καὶ ἐκ τῶν αὐτόθε συνωμοτῶν ἰσχυρόν τι προσλάβῃ. ὡς δ’ οὐδέν οἱ προεχώρει (ὅ τε γὰρ Ἀντώνιος φοβηθεὶς ὑπεστέλλετο καὶ ὁ Λέντουλος ἥκιστα δραστήριος ἦν), προεῖπεν αὐτοῖς νυκτὸς ἐς οἰκίαν τινὰ συλλεγῆναι, καὶ λαθὼν τὸν Μέτελλον ἦλθέ τε πρὸς αὐτοὺς καὶ ἐπετίμησέ σφισιν ἐπί τε τῇ ἀτολμίᾳ καὶ ἐπὶ τῇ μαλακίᾳ. κἀκ τούτου διεξελθὼν ὅσα τε πείσοιντο φωραθέντες καὶ ὅσων τεύξοιντο κατορθώσαντες, οὕτως αὐτοὺς καὶ ἐπέρρωσε καὶ παρώξυνεν ὥσθ’ ὑποσχέσθαι δύο τινὰς ἔς τε τὴν τοῦ Κικέρωνος οἰκίαν ἅμα τῇ ἡμέρᾳ ἐσᾴξειν", "st": "37.32"}, {"sp": "N", "t": "κἀνταῦθα αὐτὸν φονεύσειν. ὡς δὲ καὶ τοῦτο προεμηνύθη (ὁ γὰρ Κικέρων πολὺ δυνάμενος, συχνούς τε ἐκ τῶν συνηγορημάτων τοὺς μὲν οἰκειούμενος, τοὺς δὲ ἐκφοβῶν, πολλοὺς τοὺς διαγγέλλοντάς οἱ τὰ τοιαῦτα ἔσχε), μεταστῆναι ἡ γερουσία τὸν Κατιλίναν ἐψηφίσατο. καὶ ὃς ἀσμένως τε ἐπὶ τῇ προφάσει ταύτῃ ἐξεχώρησε, καὶ πρὸς τὰς Φαισούλας ἐλθὼν τόν τε πόλεμον ἄντικρυς ἀνείλετο, καὶ τὸ ὄνομα καὶ τὴν σκευὴν τῶν ὑπάτων λαβὼν καὶ τοὺς προσυνειλεγμένους ὑπὸ τοῦ Μαλλίου συνεκρότει, κἀν τούτῳ καὶ ἄλλους τινάς, πρῶτον μὲν ἐκ τῶν ἐλευθέρων, ἔπειτα δὲ καὶ ἐκ τῶν δούλων, προσεποιεῖτο. ὅθενπερ καὶ οἱ Ῥωμαῖοι τήν τε βίαν αὐτοῦ κατεψηφίσαντο, καὶ τὸν Ἀντώνιον ἐς τὸν πόλεμον, ἀγνοοῦντές που τὴν συνωμοσίαν σφῶν, ἔστειλαν, αὐτοί τε τὴν ἐσθῆτα μετέβαλον. καὶ διὰ ταῦτα καὶ ὁ Κικέρων κατὰ χώραν ἔμεινεν· εἰλήχει γὰρ τῆς Μακεδονίας ἄρξαι, οὔτε δὲ ἐς ἐκείνην (τῷ γὰρ συνάρχοντι αὐτῆς διὰ τὴν περὶ τὰς δίκας σπουδὴν ἐξέστη) οὔτε ἐς τὴν Γαλατίαν τὴν πλησίον, ἣν ἀντέλαβε, διὰ τὰ παρόντα ἐξήλασεν, ἀλλ’ αὐτὸς μὲν τὴν πόλιν διὰ φυλακῆς ἐποιήσατο, ἐς δὲ τὴν Γαλατίαν τὸν Μέτελλον, ὅπως μὴ καὶ ὁ Κατιλίνας αὐτὴν σφετερίσηται, ἔπεμψε.", "st": "37.33"}, {"sp": "N", "t": "καὶ ἐν καιρῷ γε ἐς τὰ μάλιστα τοῖς Ῥωμαίοις κατέμεινε. παρασκευαζομένου γὰρ τοῦ Λεντούλου καταπρῆσαί τέ τινας καὶ σφαγὰς ἐργάσασθαι μετά τε τῶν ἄλλων τῶν συνομωμοκότων καὶ μετὰ Ἀλλοβρίγων, οὓς κατὰ πρεσβείαν παρόντας ἀνέπεισε συμφρονῆσαί τε αὐτῷ … καὶ συλλαβὼν τοὺς ἐπ’ αὐτὴν σταλέντας ἔς τε τὸ βουλευτήριον μετὰ τῶν γραμμάτων ἐσήγαγε, καὶ ἄδειαν αὐτοῖς δοὺς πᾶσαν οὕτω τὴν συνωμοσίαν ἤλεγξε. κἀκ τούτου ὁ Λέντουλος ἀπειπεῖν τὴν στρατηγίαν ὑπὸ τῆς γερουσίας ἀναγκασθεὶς ἐν φρουρᾷ μετὰ τῶν ἄλλων τῶν συλληφθέντων ἐγένετο, καὶ οἱ λοιποὶ ἀνεζητοῦντο. καὶ ταῦτα καὶ τῷ δήμῳ ὁμοίως ἤρεσε, καὶ μάλιστ’ ἐπειδή, τοῦ Κικέρωνος δημηγοροῦντός τι περὶ αὐτῶν, τὸ ἄγαλμα τὸ τοῦ Διὸς ἔς τε τὸ Καπιτώλιον παρ’ αὐτὸν τὸν καιρὸν τῆς ἐκκλησίας ἀνιδρύθη καὶ κατὰ τὴν ὑφήγησιν τῶν μάντεων πρός τε τὰς ἀνατολὰς καὶ πρὸς τὴν ἀγορὰν βλέπον ἀνετέθη. ἐπειδὴ γὰρ ἐκεῖνοί τε συνωμοσίαν τινὰ ἐξελεγχθήσεσθαι ἐκ τῆς τοῦ ἀγάλματος στάσεως εἰρήκεσαν, καὶ ἡ ἀνάθεσις αὐτοῦ τοῖς φωραθεῖσι συνέβαινε, τό τε θεῖον ἐμεγάλυνον καὶ τοὺς τὴν αἰτίαν λαβόντας δι’ ὀργῆς μᾶλλον ἐποιοῦντο.", "st": "37.34"}, {"sp": "N", "t": "διῆλθε μὲν οὖν λόγος ὅτι καὶ ὁ Κράσσος ἐν αὐτοῖς εἴη, καὶ τοῦτο καὶ τῶν συλληφθέντων τις ἐμήνυσεν, οὐ μέντοι πολλοὶ ἐπίστευσαν· οἱ μὲν γὰρ ἀρχὴν οὐδ’ ἠξίουν τοιοῦτό τι ἐς αὐτὸν ὑποπτεύειν, οἱ δὲ καὶ ἐκ τῶν ὑπαιτίων ὑπετόπουν αὐτό, ὅπως βοηθείας τινὸς διὰ τοῦτο παρ’ αὐτοῦ, ὅτι πλεῖστον ἐδύνατο, τύχωσι, λογοποιεῖσθαι. εἰ δ’ οὖν τισι καὶ πιστὸν ἐδόκει εἶναι, ἀλλ’ οὔτι γε ἐδικαίουν ἄνδρα τε ἐν τοῖς πρώτοις σφῶν ὄντα ἀπολέσαι καὶ τὴν πόλιν ἐπὶ πλεῖον ἐκταράξαι. ὥστε τοῦτο μὲν παντελῶς διέπεσε· παρασκευαζομένων δὲ δὴ πολλῶν καὶ δούλων καὶ ἐλευθέρων, τῶν μὲν ὑπὸ δέους, τῶν δὲ καὶ οἴκτῳ τοῦ τε Λεντούλου καὶ τῶν ἄλλων, ἐξαρπάσαι πάντας αὐτοὺς ὅπως μὴ ἀποθάνωσι, προπυθόμενος τοῦθ’ ὁ Κικέρων τό τε Καπιτώλιον καὶ τὴν ἀγορὰν τῆς νυκτὸς φρουρᾷ προκατέσχε, καί τινα παρὰ τοῦ δαιμονίου χρηστὴν ἐλπίδα ἅμα τῇ ἕῳ λαβών, ὅτι ἱερῶν ἐν τῇ οἰκίᾳ αὐτοῦ ὑπὸ τῶν ἀειπαρθένων ὑπὲρ τοῦ δήμου ποιηθέντων τὸ πῦρ ἐπὶ μακρότατον παρὰ τὸ εἰκὸς ἤρθη, τὸν μὲν δῆμον τοῖς στρατηγοῖς ὁρκῶσαι ἐς τὸν κατάλογον, εἰ δή τις χρεία στρατιωτῶν γένοιτο, ἐκέλευσεν, αὐτὸς δὲ ἐν τούτῳ τὴν βουλὴν ἤθροισε, καί σφας συνταράξας τε καὶ ἐκφοβήσας ἔπεισε θάνατον τῶν συνειλημμένων καταγνῶναι.", "st": "37.35"}, {"sp": "N", "t": "ἐγένοντο μὲν γὰρ ἀμφίβολοι, καὶ παρ’ ὀλίγον αὐτοὺς ἀπέλυσαν. ὁ γὰρ Καῖσαρ, πάντων τῶν πρὸ αὐτοῦ ψηφισαμένων ἀποθανεῖν σφας, γνώμην ἔδωκε δῆσαί τε αὐτοὺς καὶ ἐς πόλεις ἄλλους ἄλλῃ καταθέσθαι, τῶν οὐσιῶν ἐστερημένους, ἐπὶ τῷ μήτε περὶ ἀδείας ἔτι αὐτῶν χρηματισθῆναί τί ποτε, κἂν διαδρᾷ τις, ἐν πολεμίων μοίρᾳ τὴν πόλιν ἐξ ἧς ἂν φύγῃ εἶναι· καὶ τοῦτο πάντες οἱ μετὰ ταῦτα ἀποφηνάμενοι μέχρι τοῦ Κάτωνος ἐψηφίσαντο, ὥστε καὶ τῶν προτέρων τινὰς μεταγνῶναι. ἐπεὶ δὲ οὗτος αὐτός τε τὸν θάνατον αὐτῶν κατεδίκασε καὶ τοὺς λοιποὺς πάντας ὁμοψήφους ἐποιήσατο, οὕτω δὴ ἐκεῖνοί τε ἐκ τῆς νικώσης ἐκολάσθησαν, καὶ ἐπ’ αὐτοῖς καὶ θυσία καὶ ἱερομηνία ἐψηφίσθη, ὃ μηπώποτε ἐπὶ τοιούτῳ τινὶ ἐγεγόνει· καὶ οἱ ἄλλοι οἱ μηνυθέντες ἐζητοῦντο, καί τινες καὶ ἐπὶ τῷ μελλῆσαι συμφρονήσειν αὐτοῖς ὑποπτευθέντες εὐθύνοντο. καὶ τὰ μὲν ἄλλα οἱ ὕπατοι διῴκουν, Αὖλον δὲ Φούλουιον ἄνδρα βουλευτὴν αὐτὸς ὁ πατὴρ ἀπέσφαξεν, οὔτι γε καὶ μόνος, ὥς γέ τισι δοκεῖ, τοῦτ’ ἐν ἰδιωτείᾳ ποιήσας· συχνοὶ γὰρ δὴ καὶ ἄλλοι, οὐχ ὅτι ὕπατοι ἀλλὰ καὶ ἰδιῶται, παῖδάς σφων ἀπέκτειναν.", "st": "37.36"}, {"sp": "N", "t": "τότε μὲν δὴ τόδε ἐγένετο, καὶ τὰς αἱρέσεις τῶν ἱερέων, γράψαντος μὲν τοῦ Λαβιήνου, σπουδάσαντος δὲ τοῦ Καίσαρος, ἐς τὸν δῆμον αὖθις ὁ ὅμιλος παρὰ τὸν τοῦ Σύλλου νόμον ἐπανήγαγεν, ἀνανεωσάμενος τὸν τοῦ Δομιτίου. ὁ γὰρ Καῖσαρ τοῦ Μετέλλου τοῦ Εὐσεβοῦς τελευτήσαντος τῆς τε ἱερωσύνης αὐτοῦ, καίτοι καὶ νέος καὶ μηδέπω ἐστρατηγηκώς, ἐπεθύμησε, καὶ ἐν τῷ πλήθει τὴν ἐλπίδα αὐτῆς, διά τε τἆλλα καὶ ὅτι τῷ τε Λαβιήνῳ κατὰ τοῦ Ῥαβιρίου συνηγώνιστο καὶ τὸν Λέντουλον ἀποθανεῖν οὐκ ἐψήφιστο, λαβὼν τοῦτό τε ἔπραξε, καὶ ἀρχιέρεως. τῶν ποντιφίκων, καίπερ ἄλλων τε τῆς τιμῆς πολλῶν καὶ τοῦ Κατούλου μάλιστα ἀντιποιουμένων, ἀπεδείχθη. καὶ γὰρ θεραπεῦσαι καὶ κολακεῦσαι πάντα τινὰ καὶ τῶν τυχόντων ἑτοιμότατος ἐγένετο, καὶ οὔτε λόγου οὔτε ἔργου οὐδενὸς ἐς τὸ κατατυχεῖν ὧν ἐσπούδαζεν ἐξίστατο· οὐδὲ ἔμελέν οἱ τῆς αὐτίκα ταπεινότητος πρὸς τὴν ἐκ τοῦ ἔπειτα ἰσχύν, ἀλλ’ ὧν ἐπεχείρει πρωτεῦσαι, τούτους ὡς καὶ κρείττονας ὑπήρχετο.", "st": "37.37"}, {"sp": "N", "t": "τῷ μὲν οὖν Καίσαρι διὰ ταῦθ’ οἱ πολλοὶ προσφιλεῖς ἦσαν, τὸν δὲ δὴ Κικέρωνα ἐν ὀργῇ ἐπὶ τῷ τῶν πολιτῶν θανάτῳ ποιούμενοι τά τε ἄλλα ἤχθαιρον, καὶ τέλος ἀπολογεῖσθαί τε καὶ καταλέξαι πάνθ’ ὅσα ἐν τῇ ὑπατείᾳ ἐπεποιήκει τῇ τελευταίᾳ τῆς ἀρχῆς ἡμέρᾳ ἐθελήσαντα (πάνυ γάρ που ἡδέως οὐχ ὅπως ὑφ’ ἑτέρων ἐπῃνεῖτο, ἀλλὰ καὶ αὐτὸς ἑαυτὸν ἐνεκωμίαζεν) ἐσίγασαν, οὐδὲ ἐπέτρεψαν αὐτῷ ἔξω τι τοῦ ὅρκου φθέγξασθαι, συναγωνιστῇ Μετέλλῳ Νέπωτι δημαρχοῦντι χρησάμενοι, πλὴν καθ’ ὅσον ἀντιφιλονεικήσας προσεπώμοσεν ὅτι σεσωκὼς τὴν πόλιν εἴη.", "st": "37.38"}, {"sp": "N", "t": "καὶ ὁ μὲν καὶ ἐκ τούτου πολὺ μᾶλλον ἐμισήθη, Κατιλίνας δὲ ἐν ἀρχῇ εὐθὺς τοῦ ἔτους ἐν ᾧ Ἰούνιός τε Σιλανὸς καὶ Λούκιος Λικίννιος ἦρξαν ἀπεφθάρη. τέως μὲν γὰρ καίπερ δύναμιν οὐκ ὀλίγην ἔχων ἐκαραδόκει τὰ τοῦ Λεντούλου καὶ διέμελλεν ἐλπίζων, ἂν φθάσωσιν ὅ τε Κικέρων καὶ οἱ σὺν αὐτῷ σφαγέντες, ῥᾳδίως τὰ λοιπὰ προσκατεργάσεσθαι· ἐπεὶ δὲ ἐκεῖνόν τε ἀπολωλότα ἐπύθετο καὶ τῶν συνόντων οἱ συχνοὺς μεθισταμένους διὰ τοῦτ’ ᾔσθετο, ὅ τε Ἀντώνιος καὶ ὁ Μέτελλος ὁ Κέλερ πρὸς ταῖς Φαισούλαις προσεδρεύοντες οὐδαμῇ προελθεῖν αὐτῷ ἐπέτρεπον, ἀποκινδυνεῦσαι ἠναγκάσθη, καί (ἦσαν γὰρ δίχα ἐστρατοπεδευμένοι) πρὸς τὸν Ἀντώνιον ἐτράπετο, καίπερ τῷ ἀξιώματι προέχοντα τοῦ Μετέλλου καὶ δύναμιν πλείω περιβεβλημένον. αἴτιον δὲ ὅτι ἐλπίδα αὐτοῦ κατὰ τὸ συνώμοτον ἐθελοκακήσειν ἔσχεν. ὑποπτεύσας οὖν τοῦτ’ ἐκεῖνος, καὶ μήτε δι’ εὐνοίας ἔτ’ αὐτῷ ἅτε ἀσθενεῖ ὄντι ὤν (πρός τε γὰρ τὰς δυνάμεις τινῶν καὶ πρὸς τὰ ἑαυτῶν συμφέροντα καὶ τὰς ἔχθρας τάς τε φιλίας οἱ πολλοὶ ποιοῦνται), καὶ προσκαταδείσας μή πως προθύμως σφᾶς ἀγωνιζομένους ἰδὼν ἐξονειδίσῃ τι καὶ προενέγκῃ οἱ τῶν ἀπορρήτων, αὐτὸς μὲν νοσεῖν προεφασίσατο, Μάρκῳ δὲ Πετρεΐῳ τὴν", "st": "37.39"}, {"sp": "N", "t": "μάχην ἐπέτρεψε. συμβαλὼν οὖν οὗτός σφισι τὸν Κατιλίναν καὶ ἄλλους τρισχιλίους προθυμότατα ἀγωνιζομένους οὐκ ἀναιμωτὶ κατέκοψεν· οὔτε γὰρ ἔφυγεν αὐτῶν οὐδείς, καὶ ἐν χώρᾳ πάντες ἔπεσον, ὥστε καὶ αὐτοὺς τοὺς κρατήσαντας πολὺ τῶν κοινῶν ὀδύρασθαι, ὅτι καὶ τοιούτους καὶ τοσούτους, εἰ καὶ δικαίως, ἀλλὰ καὶ πολίτας τε καὶ συμμάχους ἀπωλωλέκεσαν. ὁ δ’ οὖν Ἀντώνιος τήν τε κεφαλὴν αὐτοῦ ἐς τὸ ἄστυ, ὅπως πιστεύσαντες αὐτὸν τετελευτηκέναι μηδὲν ἔτι δεδίωσιν, ἔπεμψε, καὶ αὐτοκράτωρ ἐπὶ τῇ νίκῃ, καίτοι τοῦ ἀριθμοῦ τῶν πεφονευμένων ἐλάττονος παρὰ τὸ νενομισμένον ὄντος, ἐπεκλήθη. βουθυτηθῆναί τε ἐψηφίσθη, καὶ τὴν ἐσθῆτα ὡς καὶ πάντων τῶν δεινῶν ἀπηλλαγμένοι μετέβαλον.", "st": "37.40"}, {"sp": "N", "t": "οὐ μὴν οἵ γε σύμμαχοι οἱ μετασχόντες τῷ Κατιλίνᾳ τῶν πραγμάτων καὶ τότε ἔτι περιόντες ἡσύχαζον, ἀλλὰ καὶ δέει τῆς τιμωρίας ἐταράττοντο. καὶ ἐκείνους μὲν στρατηγοὶ καθ’ ἑκάστους πεμφθέντες προκατέλαβον τρόπον τινὰ ἐσκεδασμένους καὶ ἐτιμωρήσαντο· ἕτεροι δὲ τῶν λανθανόντων μηνύσει Λουκίου Οὐεττίου ἀνδρὸς ἱππέως, συγκοινωνήσαντος μέν σφισι τῆς συνωμοσίας, τότε δὲ ἐπ’ ἀδείᾳ αὐτοὺς ἐκφαίνοντος, ἐλεγχόμενοι ἐδικαιοῦντο, μέχρις οὗ ἐσαγγείλας τινὰς τά τε ὀνόματα αὐτῶν ἐς δελτίον ἐγγράψας ὕστερον καὶ ἄλλους συχνοὺς προσεγγράψαι ἠθέλησεν. ὑποπτεύσαντες γὰρ αὐτὸν οἱ βουλευταὶ μηδὲν ὑγιὲς πράττειν, τὸ μὲν γραμματεῖον οὐκέτ’ αὐτῷ ἔδωκαν, μὴ καὶ ἀπαλείψῃ τινάς, εἰπεῖν δὲ ἀπὸ γλώσσης ἐκέλευσαν ὅσους παραλελοιπέναι ἔφασκε. καὶ οὕτως αἰδεσθεὶς καὶ φοβηθεὶς οὐκέτι πολλοὺς ἐνέδειξε. θορύβου δ’ οὖν καὶ ὣς ἔν τε τῇ πόλει καὶ παρὰ τοῖς συμμάχοις ἀγνοίᾳ τῶν ὠνομασμένων ὄντος, καὶ τῶν μὲν περὶ σφίσιν αὐτοῖς μάτην θορυβουμένων, τῶν δὲ καὶ ἐς ἑτέρους οὐκ ὀρθῶς ὑποπτευόντων, ἔδοξε τῇ γερουσίᾳ τὰ ὀνόματα αὐτῶν ἐκτεθῆναι. κἀκ τούτου οἵ τε ἀναίτιοι κατέστησαν καὶ τοῖς ὑπευθύνοις δίκαι ἐγένοντο. καὶ αὐτῶν οἱ μὲν παρόντες, οἱ δὲ καὶ ἐρήμην ὦφλον.", "st": "37.41"}, {"sp": "N", "t": "Κατιλίνας μὲν ταῦτ’ ἐποίησε καὶ οὕτω κατελύθη, καὶ ἐπὶ πλεῖόν γε τῆς τῶν πραχθέντων ἀξίας ὄνομα πρὸς τὴν τοῦ Κικέρωνος δόξαν καὶ πρὸς τοὺς λόγους τοὺς κατ’ αὐτοῦ λεχθέντας ἔσχε· Κικέρων δὲ ὀλίγου μὲν καὶ παραχρῆμα ἐπὶ τῇ τοῦ Λεντούλου τῶν τε ἄλλων τῶν δεθέντων σφαγῇ ἐκρίθη. τὸ δὲ ἔγκλημα τοῦτο λόγῳ μὲν ἐκείνῳ ἐπεφέρετο, ἔργῳ δὲ ἐπὶ τῇ βουλῇ κατεσκευάζετο· ὡς γὰρ οὐκ ἐξόν σφισιν ἄνευ τοῦ δήμου θάνατον πολίτου τινὸς καταψηφίσασθαι, πολλὴν καταβοὴν ἐν τῷ ὁμίλῳ πρὸς τοῦ Μετέλλου τοῦ Νέπωτος ὅτι μάλιστα εἶχον. οὐ μὴν καὶ ὦφλε τότε οὐδέν· τῆς γὰρ γερουσίας ἄδειαν πᾶσι τοῖς διαχειρίσασι τὰ τότε πραχθέντα δούσης, καὶ προσέτι καὶ προειπούσης ὅτι, κἂν αὖθίς τις εὐθῦναί τινα αὐτῶν τολμήσῃ, ἔν τε ἐχθροῦ καὶ ἐν πολεμίου μοίρᾳ ἔσται, ἐφοβήθη τε ὁ Νέπως καὶ οὐδὲν ἔτ’ ἐκίνησεν.", "st": "37.42"}, {"sp": "N", "t": "ἔν τε οὖν τούτῳ ἡ βουλὴ ἐπεκράτησε, καὶ ἐν ἐκείνῳ ὅτι τὸν Πομπήιον τοῦ Νέπωτος μεταπεμφθῆναι σὺν τῷ στρατεύματι (ἐν γὰρ τῇ Ἀσίᾳ ἔτ’ ἦν) προφάσει μὲν τοῦ τὰ παρόντα κατασταθῆναι, ἐλπίδι δὲ τοῦ δι’ αὐτοῦ, ἅτε τὰ τοῦ πλήθους φρονοῦντος, ἰσχύσειν ἐν οἷς ἐτάρασσεν, ἐσηγησαμένου, διεκώλυσαν αὐτὸ κυρωθῆναι. τὰ μὲν γὰρ πρῶτα ὅ τε Κάτων καὶ Κύιντος Μινούκιος δημαρχοῦντες ἀντέλεγον τοῖς γραφεῖσι, καὶ τόν τε γραμματέα τὸν ἀναγιγνώσκοντα τὴν γνώμην ἐπέσχον, καὶ τοῦ Νέπωτος τὸ γραμματεῖον, ὅπως αὐτὸς ἀναλέξῃ, λαβόντος ἐξήρπασαν, ἐπειδή τε καὶ ὣς ἀπὸ γλώσσης τινὰ εἰπεῖν ἐπεχείρησε, τὸ στόμα αὐτοῦ ἐπέλαβον. μάχης δὲ ἐκ τούτου καὶ ἐκείνων καὶ ἄλλων τινῶν ἑκατέροις βοηθησάντων ξύλοις καὶ λίθοις, ἔτι δὲ καὶ ξίφεσι γενομένης, οἱ βουλευταὶ συνῆλθον αὐθημερὸν ἐς τὸ συνέδριον, καὶ τά τε ἱμάτια ἠλλάξαντο καὶ τοῖς ὑπάτοις τὴν φυλακὴν τῆς πόλεως, ὥστε μηδὲν ἀπ’ αὐτῆς ἀποτριβῆναι, ἐπέτρεψαν. φοβηθεὶς οὖν καὶ τότε ὁ Νέπως ἔκ τε τοῦ μέσου εὐθὺς ἐξεχώρησε, καὶ μετὰ τοῦτο γραφήν τινα κατὰ τῆς βουλῆς ἐκθεὶς πρὸς τὸν Πομπήιον ἀφώρμησε, καίτοι μηδεμίαν αὐτῷ νύκτα ἀπαυλισθῆναι ἐκ τῆς πόλεως ἐξόν.", "st": "37.43"}, {"sp": "N", "t": "γενομένου δὲ τούτου οὐδ’ ὁ Καῖσαρ (ἐστρατήγει δέ’ οὐδὲν ἔτ’ ἐνεωτέρισεν. ἔπραττε μὲν γὰρ ὅπως τὸ μὲν τοῦ Κατούλου ὄνομα ἀπὸ τοῦ ναοῦ τοῦ Διὸς τοῦ Καπιτωλίου ἀφαιρεθείη (κλοπῆς τε γὰρ αὐτὸν ηὔθυνε, καὶ τὸν λογισμὸν τῶν ἀνηλωμένων χρημάτων ἀπῄτει), τῷ δὲ δὴ Πομπηίῳ τὰ λοιπὰ προσεξεργάσασθαι ἐπιτραπείη. ἦν γάρ τινα, ὡς ἐν τηλικούτῳ καὶ τοιούτῳ ἔργῳ, ἡμιτέλεστα· ἢ ἐκεῖνός γε ἐπλάττετο εἶναι, ὅπως ὁ Πομπήιος τήν τε δόξαν τῆς ἐκποιήσεως αὐτοῦ λάβῃ καὶ τὸ αὑτοῦ ὄνομα ἀντεπιγράψῃ. οὐ μὴν οὕτω γε χαρίζεσθαι αὐτῷ ἤθελεν ὥστε καὶ ἐφ’ ἑαυτῷ διὰ τοῦτο ψηφισθῆναί τι τοιοῦτον, οἷον ἐπὶ τῷ Νέπωτι ἐδέδοκτο, ὑπομεῖναι. οὐδὲ γὰρ οὐδὲ ἐκείνου ἕνεκα ταῦτ’ ἐποίει, ἀλλ’ ἵνα αὐτὸς καὶ διὰ τούτων τὸ πλῆθος σφετερίσηται· καίπερ οὕτω πάντες τὸν Πομπήιον ἐδέδισαν (οὐδέπω γὰρ τὰ στρατεύματα ἀφήσων δῆλος ἦν) ὥστε, ἐπειδὴ Μᾶρκον Πίσωνα ὑποστράτηγον πρὸς αἴτησιν ὑπατείας προύπεμψε, τάς τε ἀρχαιρεσίας, ὅπως ἀπαντήσῃ ἐς αὐτάς, ἀναβαλέσθαι, καὶ παρόντα αὐτὸν ὁμοθυμαδὸν ἀποδεῖξαι. καὶ γὰρ ἐκεῖνος οὐχ ὅτι τοῖς φίλοις ἀλλὰ καὶ τοῖς ἐχθροῖς συνέστησεν αὐτόν.", "st": "37.44"}, {"sp": "N", "t": "κἀν τούτῳ ὁ Καῖσαρ, τοῦ Κλωδίου τοῦ Πουπλίου τὴν γυναῖκα αὐτοῦ ἔν τε τῇ οἰκίᾳ καὶ παρὰ τὴν ποίησιν τῶν ἱερῶν, ἅπερ αἱ ἀειπαρθένοι παρά τε τοῖς ὑπάτοις καὶ παρὰ τοῖς στρατηγοῖς ἄγνωστα ἐκ τῶν πατρίων ἐς πᾶν τὸ ἄρρεν ἐπετέλουν, αἰσχύναντος, ἐκείνῳ μὲν οὐδὲν ἐνεκάλεσεν (καὶ γὰρ εὖ ἠπίστατο ὅτι οὐχ ἁλώσεται διὰ τὴν ἑταιρείαν), τὴν δὲ δὴ γυναῖκα ἀπεπέμψατο, εἰπὼν ἄλλως μὲν μὴ πιστεύειν τῷ λεγομένῳ, μὴ μέντοι καὶ συνοικῆσαι ἔτ’ αὐτῇ δύνασθαι, διότι καὶ ὑπωπτεύθη ἀρχὴν μεμοιχεῦσθαι· τὴν γὰρ σώφρονα χρῆναι μὴ μόνον μηδὲν ἁμαρτάνειν, ἀλλὰ μηδ’ ἐς ὑποψίαν αἰσχρὰν ἀφικνεῖσθαι. τότε μὲν ταῦτά τε ἐγένετο, καὶ ἡ γέφυρα ἡ λιθίνη ἡ ἐς τὸ νησίδιον τὸ ἐν τῷ Τιβέριδι ὂν φέρουσα", "st": "37.45"}, {"sp": "N", "t": "κατεσκευάσθη, Φαβρικία κληθεῖσα· τῷ δὲ ἑξῆς ἔτει ἐπί τε Πίσωνος καὶ ἐπὶ Μάρκου Μεσσάλου ὑπάτων μισοῦντές τε ἄλλως οἱ δυνατοὶ τὸν Κλώδιον, καὶ ἅμα καὶ τὸ μίασμα αὐτοῦ ἀποδιοπομπούμενοι, ἐπειδὴ οἱ ποντίφικες ἀνατυθῆναι τὰ ἱερὰ ὡς οὐχ ὁσίως διὰ τοῦτο τελεσθέντα ἔγνωσαν, δικαστηρίῳ αὐτὸν παρέδωκαν, καὶ κατηγορήθη μὲν τῆς τε μοιχείας, καίπερ τοῦ Καίσαρος σιωπῶντος, καὶ τῆς μεταστάσεως τῆς περὶ Νίσιβιν, καὶ προσέτι καὶ ὅτι τῇ ἀδελφῇ συγγίγνοιτο, ἀφείθη δέ, καίτοι τῶν δικαστῶν φρουρὰν παρὰ τῆς βουλῆς, ὅπως μηδὲν κακὸν ὑπ’ αὐτοῦ πάθωσι, καὶ αἰτησάντων καὶ λαβόντων. ἐφ’ ᾧπερ καὶ ὁ Κάτουλος ἐπισκώπτων ἔλεγεν ὅτι τὴν φυλακὴν ᾔτησαν οὐχ ἵνα ἀσφαλῶς τοῦ Κλωδίου καταψηφίσωνται, ἀλλ’ ἵνα αὐτοὶ τὰ χρήματα ἃ ἐδεδωροδοκήκεσαν διασώσωνται. καὶ ὁ μὲν διαφανέστατα τῶν πώποτε τὸ δημόσιον ἀεὶ πρὸ παντὸς προτιμήσας ἐτελεύτησεν οὐ πολλῷ ὕστερον· ἐν δὲ δὴ τῷ ἔτει ἐκείνῳ οἵ τε τιμηταὶ πάντας τοὺς ἐν ταῖς ἀρχαῖς γενομένους ἐς τὸ βουλευτικὸν καὶ ὑπὲρ τὸν ἀριθμὸν ἐσέγραψαν, καὶ ὁ δῆμος ἀπαυστὶ μέχρι τότε τὰς ὁπλομαχίας θεώμενος ἐξανέστη τε μεταξὺ τοῦ ἔργου καὶ ἄριστον εἵλετο. καὶ τοῦτ’ ἐκεῖθεν ἀρξάμενον καὶ νῦν, ὁσάκις ἂν ὁ τὸ κράτος ἔχων ἀγωνοθετῇ, γίγνεται.", "st": "37.46"}, {"sp": "N", "t": "ἐν μὲν οὖν τῇ πόλει ταῦθ’ οὕτως ἐπράχθη, τῶν δὲ Ἀλλοβρίγων τὴν Γαλατίαν τὴν περὶ Νάρβωνα πορθούντων Γάιος Πομπτῖνος ὁ ἄρχων αὐτῆς τοὺς μὲν ὑποστρατήγους ἐπὶ τοὺς πολεμίους ἔπεμψεν, αὐτὸς δὲ ἐν ἐπιτηδείῳ ἱδρυθεὶς ἐπετήρει τὰ γιγνόμενα, ὅπως κατὰ καιρὸν πρὸς τὸ ἀεὶ χρήσιμον καὶ γνώμην σφίσι διδόναι καὶ ἐπαμύνειν δύνηται. καὶ Μάλλιος μὲν Λεντῖνος ἐπὶ Οὐαλεντίαν πόλιν στρατεύσας οὕτως αὐτοὺς κατέπληξεν ὥστε τοὺς πλείους ἐκδρᾶναι καὶ τοὺς λοιποὺς ὑπὲρ εἰρήνης πρεσβεύσασθαι. κἀν τούτῳ συμβοηθησάντων τῶν ἐν τοῖς ἀγροῖς ὄντων καὶ προσπεσόντων αἰφνιδίως τοῦ μὲν τείχους ἀπεώσθη, τὴν δὲ δὴ χώραν ἀδεῶς ἐλεηλάτει, μέχρις οὗ ὅ τε Κατούγνατος ὁ τοῦ παντὸς αὐτῶν ἔθνους στρατηγὸς καί τινες καὶ ἄλλοι τῶν παρὰ τὸν Ἴσαρα οἰκούντων ἐπεκούρησάν σφισι. τότε γὰρ οὐκ ἐτόλμησε μὲν αὐτοὺς ὑπὸ τοῦ πλήθους τῶν πλοίων περαιωθῆναι κωλῦσαι, μὴ καὶ συστραφῶσιν ἰδόντες σφᾶς ἀντιπαρατεταγμένους, ὑλώδους δὲ τοῦ χωρίου μετὰ τὸν ποταμὸν εὐθὺς ὄντος, ἐνέδρας ἐν αὐτῷ ἐποιήσατο, καὶ τοὺς ἀεὶ διαβαίνοντας ὑπολαμβάνων ἔφθειρε. φεύγουσί τέ τισιν ἐπισπόμενος περιέπεσεν αὐτῷ Κατουγνάτῳ· κἂν πασσυδὶ διώλετο, εἰ μὴ χειμὼν σφοδρὸς ἐξαίφνης ἐπιγενόμενος ἐπέσχε τοὺς βαρβάρους", "st": "37.47"}, {"sp": "N", "t": "τῆς διώξεως. καὶ ὁ μὲν μετὰ τοῦτο, τοῦ Κατουγνάτου πόρρω ποι ἀφορμήσαντος, τήν τε χώραν αὖθις κατέδραμε καὶ τὸ τεῖχος παρ’ ᾧ ἐδυστύχησεν ἐξεῖλε· Λούκιος δὲ δὴ Μάριος καὶ Σέρουιος Γάλβας τόν τε Ῥοδανὸν ἐπεραιώθησαν, καὶ τὰ τῶν Ἀλλοβρίγων λυμηνάμενοι τέλος πρὸς Σολώνιον πόλιν ἦλθον, καὶ χωρίον μέν τι ὑπὲρ αὐτῆς ἰσχυρὸν κατέλαβον, μάχῃ τε τοὺς ἀντιστάντας σφίσιν ἐνίκησαν, καί τινα καὶ τοῦ πολίσματος ξυλίνου πῃ ὄντος ἐνέπρησαν, οὐ μέντοι καὶ εἷλον αὐτό· ὁ γὰρ Κατούγνατος ἐπελθὼν ἐκώλυσε. μαθὼν οὖν τοῦτο ὁ Πομ πτῖνος ἐπεστράτευσέ τε ἐπ’ αὐτὸ παντὶ τῷ στρατῷ, καὶ πολιορκήσας σφᾶς ἐχειρώσατο πλὴν τοῦ Κατουγνάτου.", "st": "37.48"}, {"sp": "N", "t": "καὶ ὁ μὲν καὶ τὰ λοιπὰ ῥᾷον ἐκ τούτου προσκατεστρέψατο, Πομπήιος δὲ ἦλθε μὲν ἐς τὴν Ἰταλίαν ἐν τῷ χρόνῳ τούτῳ, καὶ τόν τε Ἀφράνιον τὸν Λούκιον καὶ τὸν Μέτελλον τὸν Κέλερα ὑπάτους ἀποδειχθῆναι ἐποίησεν, ἐλπίσας δι’ αὐτῶν μάτην πάνθ’ ὅσα ἐβούλετο καταπράξειν. ἤθελε μὲν γὰρ ἄλλα τε καὶ ἐν τοῖς μάλιστα χώραν τέ τινα τοῖς συνεστρατευμένοις οἱ δοθῆναι καὶ τὰ πεπραγμένα αὐτῷ πάντ’ ἐπικυρωθῆναι, διήμαρτε δέ σφων τότε. οἵ τε γὰρ δυνατοί, μηδὲ ἐκ τοῦ πρὶν αὐτῷ ἀρεσκόμενοι, διεκώλυσαν αὐτὰ ψηφισθῆναι· καὶ αὐτῶν τῶν ὑπάτων Ἀφράνιος μέν (ὀρχεῖσθαι γὰρ βέλτιον ἤ τι διαπράσσειν ἠπίστατο) πρὸς οὐδὲν αὐτῷ συνήρατο, Μέτελλος δὲ ὀργῇ, ὅτι τὴν ἀδελφὴν αὐτοῦ, καίτοι παῖδας ἐξ αὐτῆς ἔχων, ἀπεπέπεμπτο, καὶ πάνυ πρὸς πάντα ἀντέπραξεν. ὅ τε Λούκουλλος ὁ Λούκιος, ᾧ ποτε ἐν τῇ Γαλατίᾳ ὁ Πομπήιος ἐντυχὼν ὑπερφρόνως ἐκέχρητο, πολύς τε αὐτῷ ἐνέκειτο, καὶ ἐκέλευσεν αὐτὸν ἰδίᾳ καὶ καθ’ ἕκαστον ὧν ἔπραξεν ἐπεξελθεῖν καὶ μὴ πᾶσιν ἅμα αὐτοῖς τὴν κύρωσιν αἰτεῖν. ἄλλως τε γὰρ δίκαιον εἶναι ἔλεγε μὴ πάντα ἁπλῶς ὅσα ἐπεποιήκει, καὶ ἃ μηδείς σφων ἠπίστατο ὁποῖα ἦν, βεβαιωθῆναι ὥσπερ ὑπὸ δεσπότου τινὸς γεγενημένα· καὶ ἐπειδὴ καὶ τῶν ἑαυτοῦ ἔργων κατελελύκει τινά, ἠξίου ἐξετασμὸν ἑκατέρων ἐν τῇ βουλῇ γενέσθαι, ἵν’ ὁπότερ) ἂν", "st": "37.49"}, {"sp": "N", "t": "αὐτοῖς ἀρέσῃ κυρώσωσι. καὶ αὐτῷ καὶ ὁ Κάτων ὅ τε Μέτελλος οἵ τε ἄλλοι οἱ τὰ αὐτά σφισι βουλόμενοι ἰσχυρῶς συνεμάχουν. τοῦ γοῦν δημάρχου, τοῦ τὴν γῆν τοῖς τῷ Πομπηίῳ συνεξητασμένοις κατανεῖμαι ἐσηγουμένου, προσγράψαντος τῇ γνώμῃ τὸ καὶ πᾶσι τοῖς πολίταις, ὅπως τοῦτό τε αὐτὸ ῥᾷον ψηφίσωνται καὶ τὰ πραχθέντα αὐτῷ βεβαιώσωσι, κλήρους τινὰς δοθῆναι, ἐπὶ πᾶν ὁ Μέτελλος ἀνθιστάμενος ἐπεξῆλθεν, ὥστε καὶ ἐς τὸ οἴκημα ὑπ’ αὐτοῦ ἐμβληθῆναι καὶ τὴν γερουσίαν ἐνταῦθα ἀθροῖσαι ἐθελῆσαι. ἐπεί τε ἐκεῖνος (Λούκιος δὲ δὴ Φλάουιος ὠνομάζετο) τό τε βάθρον τὸ δημαρχικὸν ἐν αὐτῇ τῇ ἐσόδῳ αὐτοῦ ἔθηκε, καὶ ἐπ’ αὐτῷ καθεζόμενος ἐμποδὼν ὥστε μηδένα ἐσιέναι ἐγίγνετο, τόν τε τοῖχον τοῦ δεσμωτηρίου διακοπῆναι ἐκέλευσεν ὅπως δι’ αὐτοῦ ἡ βουλὴ ἐσέλθῃ, καὶ ὡς νυκτερεύσων κατὰ χώραν παρεσκευάζετο. μαθὼν οὖν τοῦθ’ ὁ Πομπήιος, καὶ αἰσχυνθείς τε ἅμα καὶ δείσας μὴ καὶ ὁ δῆμος ἀγανακτήσῃ, προσέταξε τῷ Φλαουίῳ ἀπαναστῆναι. ἔλεγε μὲν γὰρ ὡς τοῦ Μετέλλου τοῦτ’ ἀξιώσαντος, οὐ μὴν ἐπιστεύετο· τὸ γὰρ φρόνημα αὐτοῦ κατάδηλον πᾶσιν ἦν. ἀμέλει τῶν ἄλλων δημάρχων ἐξελέσθαι αὐτὸν βουληθέντων οὐκ ἠθέλησεν. οὔκουν οὐδ’ αὖθις ἀπειλήσαντι τῷ Φλαουίῳ μηδὲ ἐς τὸ ἔθνος ὃ ἐπεκεκλήρωτο ἐπιτρέψειν αὐτῷ, εἰ μὴ συγχωρήσειέν οἱ διανομοθετῆσαι, ἐξελθεῖν, ὑπεῖξεν, ἀλλὰ καὶ πάνυ ἄσμενος ἐν τῇ πόλει κατέμεινεν. ὁ οὖν Πομπήιος ἐπειδὴ μηδὲν διά τε τὸν Μέτελλον καὶ διὰ τοὺς ἄλλους διεπράξατο, ἔφη μὲν φθονεῖσθαί τε ὑπ’ αὐτῶν καὶ τῷ πλήθει τοῦτο δηλώσειν, φοβηθεὶς δὲ μὴ καὶ ἐκείνου διαμαρτὼν μείζω αἰσχύνην ὄφλῃ, κατέβαλε τὴν ἀξίωσιν. καὶ ὁ μὲν οὕτω γνοὺς ὅτι μηδὲν ὄντως ἴσχυεν, ἀλλὰ τὸ μὲν ὄνομα καὶ τὸν φθόνον ἐφ’ οἷς ἠδυνήθη ποτὲ εἶχεν, ἔργῳ δὲ οὐδὲν ἀπ’ αὐτῶν ἀπώνητο, μετεμέλετο ὅτι τά τε στρατόπεδα προαφῆκε", "st": "37.50"}, {"sp": "N", "t": "καὶ ἑαυτὸν τοῖς ἐχθροῖς ἐξέδωκε· Κλώδιος δὲ ἐπεθύμησε μὲν διὰ … τοὺς δυνατοὺς ἐπὶ τῇ δίκῃ δημαρχῆσαι, καί τινας τῶν δημαρχούντων προκαθῆκεν ἐσηγήσασθαι τὸ καὶ τοῖς εὐπατρίδαις τῆς ἀρχῆς μεταδίδοσθαι, ὡς δ’ οὐκ ἔπεισε, τήν τε εὐγένειαν ἐξωμόσατο καὶ πρὸς τὰ τοῦ πλήθους δικαιώματα, ἐς αὐτόν σφων τὸν σύλλογον ἐσελθών, μετέστη. καὶ ᾔτησε μὲν εὐθὺς τὴν δημαρχίαν, οὐκ ἀπεδείχθη δὲ ἐναντιωθέντος οἱ τοῦ Μετέλλου· ἐν γένει τε γὰρ αὐτῷ ἦν, καὶ τοῖς πραττομένοις ὑπ’ αὐτοῦ οὐκ ἠρέσκετο. πρόφασιν δὲ ἐποιήσατο ὅτι μὴ κατὰ τὰ πάτρια ἡ ἐκποίησις αὐτοῦ ἐγεγόνει· ἐν γὰρ τῇ ἐσφορᾷ τοῦ φρατριατικοῦ νόμου μόνως ἐξῆν τοῦτο γίγνεσθαι. ταῦτά τε οὖν οὕτως ἐπράχθη, καὶ ἐπειδὴ τὰ τέλη δεινῶς τήν τε πόλιν καὶ τὴν ἄλλην Ἰταλίαν ἐλύπει, ὁ μὲν νόμος ὁ καταλύσας αὐτὰ πᾶσιν ἀρεστὸς ἐγένετο, τῷ δὲ στρατηγῷ τῷ ἐσενεγκόντι αὐτὸν ἀχθόμενοι οἱ βουλευταί (ὁ γὰρ Μέτελλος ὁ Νέπως ἦν) ἦθέλησαν τό τε ὄνομα αὐτοῦ ἀπαλεῖψαι ἀπὸ τοῦ νόμου καὶ ἕτερον ἀντεγγράψαι. καὶ οὐκ ἐπράχθη μὲν τοῦτο, καταφανὲς μέντοι πᾶσιν ἐγένετο ὅτι μηδὲ τὰς εὐεργεσίας παρὰ τῶν φαύλων ἀνδρῶν ἡδέως ἐδέχοντο. κἀν τῷ αὐτῷ τούτῳ χρόνῳ Φαῦστος ὁ τοῦ Σύλλου παῖς ἀγῶνά τε μονομαχίας ἐπὶ τῷ πατρὶ ἐποίησε, καὶ τὸν δῆμον λαμπρῶς εἱστίασε, τά τε λουτρὰ καὶ τὸ ἔλαιον προῖκα αὐτοῖς παρέσχεν.", "st": "37.51"}, {"sp": "N", "t": "ἐν μὲν δὴ τῇ πόλει ταῦτ’ ἐγίγνετο, ὁ δὲ δὴ Καῖσαρ τῆς τε Λυσιτανίας μετὰ τὴν στρατηγίαν ἦρξε, καὶ δυνηθεὶς ἂν τὰ λῃστικά, ἅπερ που ἀεὶ παρ’ αὐτοῖς ἦν, ἄνευ μεγάλου τινὸς πόνου καθήρας ἡσυχίαν ἔχειν, οὐκ ἠθέλησε· δόξης τε γὰρ ἐπιθυμῶν, καὶ τὸν Πομπήιον τούς τε ἄλλους τοὺς πρὸ αὐτοῦ μέγα ποτὲ δυνηθέντας ζηλῶν, οὐδὲν ὀλίγον ἐφρόνει, ἀλλ’ ἤλπιζεν, ἄν τι τότε κατεργάσηται, ὕπατός τε εὐθὺς αἱρεθήσεσθαι καὶ ὑπερφυᾶ ἔργα ἀποδείξεσθαι, διά τε τἆλλα καὶ ὅτι ἐν τοῖς Γαδείροις, ὅτε ἐταμίευε, τῇ μητρὶ συγγίγνεσθαι ὄναρ ἔδοξε, καὶ παρὰ τῶν μάντεων ἔμαθεν ὅτι ἐν μεγάλῃ δυνάμει ἔσται. ὅθενπερ καὶ εἰκόνα Ἀλεξάνδρου ἐνταῦθα ἐν τῷ Ἡρακλέους ἀνακειμένην ἰδὼν ἀνεστέναξε, καὶ κατωδύρατο ὅτι μηδέν πω μέγα ἔργον ἐπεποιήκει. Ἀπ’ οὖν τούτων, ἐξὸν αὐτῷ εἰρηνεῖν, ὥσπερ εἶπον, πρὸς τὸ ὄρος τὸ Ἑρμίνιον ἐτράπετο καὶ ἐκέλευσε τοὺς οἰκήτορας αὐτοῦ ἐς τὰ πεδινὰ μεταστῆναι, πρόφασιν μὲν ὅπως μὴ ἀπὸ τῶν ἐρυμνῶν ὁρμώμενοι λῃστεύωσιν, ἔργῳ δὲ εὖ εἰδὼς ὅτι οὐκ ἄν ποτε αὐτὸ ποιήσειαν, κἀκ τούτου πολέμου τινὰ ἀφορμὴν λήψεται. ὃ καὶ ἐγένετο. τούτους τε οὖν ἐς ὅπλα ἐλθόντας ὑπηγάγετο· καὶ ἐπειδὴ τῶν πλησιοχώρων τινές, δείσαντες μὴ καὶ ἐπὶ σφᾶς ὁρμήσῃ, τούς τε παῖδας καὶ τὰς γυναῖκας τά τε ἄλλα τὰ τιμιώτατα ὑπὲρ τὸν Δώριον ὑπεξέθεντο, τὰς πόλεις σφῶν ἐν ᾧ τοῦτ’ ἔπραττον προκατέσχε, καὶ μετὰ ταῦτα καὶ ἐκείνοις προσέμιξε. προβαλλομένων τε τὰς ἀγέλας αὐτῶν, ὅπως σκεδασθεῖσι τοῖς Ῥωμαίοις πρὸς τὴν τῶν βοσκημάτων ἁρπαγὴν ἐπίθωνται, τὰ τετράποδα", "st": "37.52"}, {"sp": "N", "t": "παρῆκε καὶ αὐτοὺς ὑπολαβὼν ἐνίκησε. κἀν τούτῳ μαθὼν τοὺς τὸ Ἑρμίνιον οἰκοῦντας ἀφεστηκέναι τε καὶ ἐπανιόντα αὐτὸν ἐνεδρεύειν μέλλειν, τότε μὲν ἑτέραν ἀνεχώρησεν, αὖθις δὲ ἐπεστράτευσέ σφισιν, καὶ κρατήσας πρὸς τὸν ὠκεανὸν φεύγοντας αὐτοὺς κατεδίωξεν. ἐπειδή τε τὴν ἤπειρον ἐκλιπόντες ἐς νῆσόν τινα ἐπεραιώθησαν, αὐτὸς μὲν (οὐ γάρ που πλοίων εὐπόρει) κατὰ χώραν ἔμεινε, σχεδίας δὲ συμπήξας μέρος τι τοῦ στρατοῦ δι’ αὐτῶν ἔπεμψε, καὶ συχνοὺς ἀπέβαλε· χηλῇ γάρ τινι πρὸς τῇ νήσῳ οὔσῃ προσσχὼν ὁ τὴν ἡγεμονίαν σφῶν ἔχων, καὶ ὡς καὶ πεζῇ διαβαδίσοντας αὐτοὺς ἐκβιβάσας, ἔπειτα αὐτός τε ὑπὸ τῆς ἀναρροίας ἐκβιασθεὶς ἐξανήχθη καὶ ἐκείνους ἐγκατέλιπε, καὶ αὐτῶν οἱ μὲν ἄλλοι γενναίως ἀμυνόμενοι ἔπεσον, Πούπλιος δὲ δὴ Σκαίουιος μόνος τε περιλειφθεὶς καὶ τῆς ἀσπίδος στερηθεὶς πολλά τε τραυματισθεὶς ἔς τε τὸ ὕδωρ ἐσεπήδησε καὶ διενήξατο. τότε μὲν δὴ ταῦτ’ ἐγένετο· ὕστερον δὲ ὁ Καῖσαρ πλοῖα ἀπὸ Γαδείρων μεταπεμψάμενος ἐς τὴν νῆσον παντὶ τῷ στρατῷ ἐπεραιώθη, καὶ ἀκονιτὶ αὐτούς, κακῶς ὑπὸ σιτοδείας ἔχοντας, παρεστήσατο. κἀντεῦθεν ἐς Βριγάντιον πόλιν Καλλαικίας παραπλεύσας τῷ τε ῥοθίῳ σφᾶς τοῦ πρόσπλου, οὐπώποτε ναυτικὸν ἑορακότας, ἐξεφόβησε καὶ κατεστρέψατο.", "st": "37.53"}, {"sp": "N", "t": "πράξας δὲ ταῦτα καὶ νομίσας ἱκανὴν ἀπ’ αὐτῶν ἐπιβασίαν πρὸς τὴν ὑπατείαν εἰληφέναι σπουδῇ πρὸς τὰς ἀρχαιρεσίας, καὶ πρὶν τὸν διάδοχον ἐλθεῖν, ὥρμησε, καὶ ἠξίου καὶ πρὸ τοῦ πέμψαι τὰ ἐπινίκια, ἐπειδὴ μὴ οἷά τε προδιεορτασθῆναι ἦν, αἰτῆσαι αὐτήν. μὴ τυχὼν δέ, τοῦ Κάτωνος ὅτι μάλιστα ἐναντιωθέντος, ἐκεῖνα μὲν εἴασε· καὶ γὰρ ἤλπιζε πολὺ πλείω καὶ μείζω ὕπατος ἀποδειχθεὶς καὶ ἔργα πράξειν καὶ ἐπινίκια πέμψειν. πρὸς γὰρ τοῖς εἰρημένοις, ἐφ’ οἷς μέγα ἀεί ποτε ἐφρόνει, ἵππος τις αὐτῷ διαφυὰς ἐν ταῖς τῶν προσθίων ποδῶν ὁπλαῖς ἔχων ἐγεννήθη, καὶ ἐκεῖνον μὲν γαυρούμενος ἔφερεν, ἄλλον δὲ ἀναβάτην οὐδένα ἀνεδέχετο. ὥστε καὶ ἐκ τούτου μικρὸν οὐδὲν προσδοκῶν τὰ μὲν νικητήρια ἑκὼν ἀφῆκεν, ἐς δὲ τὴν πόλιν ἐσελθὼν καὶ ἐπαγγειλάμενος τὴν ἀρχὴν οὕτω τούς τε ἄλλους καὶ τὸν Πομπήιον τόν τε Κράσσον ἐξεθεράπευσεν, ὥστε δι’ ἔχθρας ἀλλήλοις ἔτι καὶ τότε αὐτοὺς ὄντας καὶ τὰς ἑταιρείας ἔχοντας, καὶ πρὸς πάνθ’ ὅσα ὁ ἕτερος τὸν ἕτερον ἐθέλοντα αἴσθοιτο ἀντιστασιάζοντας, προσποιήσασθαι, καὶ ὑπὸ πάντων αὐτῶν ὁμοθυμαδὸν ἀποδειχθῆναι. καίτοι τοῦτο τὴν σοφίαν ἐς τὰ μάλιστα αὐτοῦ τεκμηριοῖ, ὅτι τόν τε καιρὸν καὶ τὸ μέτρον τῆς θεραπείας αὐτῶν καὶ ἔγνω καὶ διέθετο οὕτως ὥστ’ ἀμφοτέρους ἅμα καίπερ ἀντιπράττοντάς σφισι προσθέσθαι.", "st": "37.54"}, {"sp": "N", "t": "καὶ οὐδὲ τοῦτ’ αὐτῷ ἀπέχρησεν, ἀλλὰ καὶ αὐτοὺς ἐκείνους συνήλλαξεν, οὐχ ὅτι συνενεχθῆναί σφας ἤθελεν, ἀλλ’ ὅτι δυνατωτάτους τε ἑώρα ὄντας, καὶ εὖ ἠπίστατο ὅτι οὔτε χωρὶς τῆς παρ’ ἐκείνων ἀμφοτέρων ἢ καὶ θατέρου βοηθείας μέγα τι ἰσχύσει, κἂν τὸν ἕτερον ὁποτερονοῦν αὐτῶν προσεταιρίσηται, ἀνταγωνιστήν τε διὰ τοῦτο τὸν ἕτερον ἕξει καὶ πλέον ὑπ’ αὐτοῦ σφαλήσεται ἢ ὑπὸ τοῦ συναιρομένου οἱ κατεργάσεται. τοῦτο μὲν γὰρ προθυμότερον ἐδόκουν αὐτῷ πάντες ἄνθρωποι τοῖς ἐχθροῖς ἀντιπράττειν ἢ συναγωνίζεσθαι τοῖς ἐπιτηδείοις, οὐ κατ’ ἐκεῖνο μόνον ὅτι ἥ τε ὀργὴ καὶ τὸ μῖσος σφοδροτέρας τὰς σπουδὰς πάσης φιλίας ποιεῖ, ἀλλὰ καὶ ὅτι ὁ μὲν ὑπὲρ ἑαυτοῦ ὁ δὲ ὑπὲρ ἑτέρου πράττων τήν τε ἡδονὴν κατορθώσας καὶ τὴν λύπην σφαλεὶς οὐχ ὁμοίας ἔχουσιν· τοῦτο δὲ προχειρότερον ἐμποδίζειν τέ τινας καὶ κωλύειν μηδεμίαν αὔξησιν λαβεῖν ἢ ἐπὶ μέγα προάγειν ἐθέλειν, διά τε τἆλλα καὶ μάλισθ’ ὅτι ὁ μὲν οὐκ ἐῶν τινα αὐξηθῆναι τοῖς τε ἄλλοις ἅμα καὶ ἑαυτῷ χαρίζεται, ὁ δὲ ἐξαίρων τινὰ ἐπαχθῆ αὐτὸν ἀμφοτέροις σφίσι ποιεῖ.", "st": "37.55"}, {"sp": "N", "t": "τούτων δὴ οὖν ἕνεκα καὶ ὁ Καῖσαρ τότε τε αὐτοὺς ὑπῆλθε καὶ μετὰ τοῦτο ἀλλήλοις κατήλλαξεν. οὔτε γὰρ δίχα τούτων δυνήσεσθαί τι ἀεὶ καὶ οὐκ ἂν θατέρῳ ποτὲ αὐτῶν προσκροῦσαι ἐνόμιζεν, οὔτ’ αὖ ἐφοβήθη μὴ καὶ συμφρονήσαντες κρείττους αὑτοῦ γένωνται· πάνυ γὰρ εὖ ἠπίστατο ὅτι τῶν μὲν ἄλλων εὐθὺς διὰ τῆς ἐκείνων φιλίας, αὐτῶν δ’ οὐ πολλῷ ὕστερον δι’ ἀλλήλων κρατήσοι. καὶ ἔσχεν οὕτως. καὶ γὰρ ὁ Πομπήιος ὅ τε Κράσσος ὡς ἀπ’ οἰκείας καὶ αὐτοὶ αἰτίας πρός τε ἀλλήλους, ἐπειδὴ τάχιστα ὥρμησαν, κατελύσαντο καὶ ἐκεῖνον ἐς τὴν κοινωνίαν τῶν πραγμάτων προσέλαβον. Πομπήιος μὲν γὰρ οὔτ’ αὐτὸς ὅσον ἤλπισεν ἰσχύων, καὶ τὸν Κράσσον ἐν δυνάμει ὄντα τόν τε Καίσαρα αὐξανόμενον ὁρῶν, καὶ ἔδεισε μὴ παντάπασιν ὑπ’ αὐτῶν καταλυθῇ, καὶ ἐπήλπισε, προσκοινωνήσας σφίσι τῶν παρόντων, τὴν ἀρχαίαν δι’ αὐτῶν ἐξουσίαν ἀναλήψεσθαι· Κράσσος δὲ ἠξίου τε πάντων ἀπό τε τοῦ γένους καὶ ἀπὸ τοῦ πλούτου περιεῖναι, καὶ ἐπειδὴ τοῦ τε Πομπηίου παρὰ πολὺ ἠλαττοῦτο καὶ τὸν Καίσαρα ἐπὶ μέγα ἀρθήσεσθαι ἐνόμιζεν, ἐς ἀντίπαλον αὐτοὺς ἀλλήλοις καταστῆσαι ἠθέλησεν, ὅπως μηδέτερός σφων ὑπέρσχῃ, προσδοκήσας ἐκείνους τε ἀνταγωνιστὰς ἰσοκρατεῖς ἔσεσθαι, καὶ αὐτὸς ἐν τούτῳ τήν τε ἑκατέρου φιλίαν ἐκκαρπώσεσθαι καὶ ὑπὲρ ἀμφοτέρους τιμηθήσεσθαι. ἀκριβῶς μὲν γὰρ οὔτε τὰ τοῦ πλήθους οὔτε τὰ τῆς βουλῆς ἐπολίτευεν, τῆς δὲ ἰδίας αὐτοῦ δυναστείας ἕνεκα πάντ’ ἔπραττε, καὶ διὰ τοῦθ’ ὑπήρχετό τε ἀμφοτέρους σφᾶς ὁμοίως καὶ τὴν πρὸς ἑκατέρους ἔχθραν ἐξέκλινεν, ἐπὶ τοσοῦτον ἐν τῷ μέρει κεχαρισμένα ἀμφοῖν σπουδάζων ἐφ’ ὅσον ἤμελλε τοῦ μὲν καταθυμίου παντὸς ἑκατέροις αἰτιαθήσεσθαι, τῶν δὲ δυσχερεστέρων μὴ μεταλήψεσθαι.", "st": "37.56"}, {"sp": "N", "t": "οὕτω μὲν δὴ καὶ διὰ ταῦτα οἱ τρεῖς τήν τε φιλίαν συνέθεντο, καὶ ὅρκοις αὐτὴν πιστωσάμενοι τά τε κοινὰ δι’ ἑαυτῶν ἐποιήσαντο, κἀκ τούτου καὶ ἀντεδίδοσάν σφισι καὶ ἀντελάμβανον παρ’ ἀλλήλων ὅσα ἔν τε ἐπιθυμίᾳ εἶχον καὶ πρὸς τὰ παρόντα ἥρμοττεν αὐτοῖς πράττεσθαι. συμφρονησάντων δὲ ἐκείνων καὶ τὰ ἑταιρικά σφων ὡμολόγησαν, καὶ ἐποίουν καὶ οὗτοι μετὰ ἀδείας ὅσα ἤθελον, ἡγεμόσι πρὸς πάντα αὐτοῖς χρώμενοι, ὥστε τὸ σωφρονοῦν ὀλίγον ἔν τε τῷ Κάτωνι, καὶ εἰ δή τις ἄλλος τὰ αὐτὰ αὐτῷ φρονεῖν δοκεῖν ἐβούλετο, καταλειφθῆναι. καθαρῶς μὲν γὰρ καὶ ἄνευ τινὸς ἰδίας πλεονεξίας οὐδεὶς τῶν τότε τὰ κοινὰ πλὴν τοῦ Κάτωνος ἔπραττεν· αἰσχυνόμενοι δέ τινες τοῖς δρωμένοις, καὶ ἕτεροι καὶ ζηλοῦν αὐτὸν ἐφιέμενοι, προσήπτοντο μέν πῃ τῶν πραγμάτων καί τι τῶν ὁμοίων οἱ διεδείκνυντο, οὐ μὴν καὶ διαρκεῖς, ἅτε ἐξ ἐπιτηδεύσεως ἀλλ’ οὐκ ἀπ’ ἀρετῆς ἐμφύτου ὁρμώμενοι, ἦσαν.", "st": "37.57"}, {"sp": "N", "t": "ἐς τοῦτο μὲν δὴ τότε τὰ τῶν Ῥωμαίων πράγματα οἱ ἄνδρες ἐκεῖνοι προήγαγον, ἐπὶ πλεῖστον ὅσον τὴν συνωμοσίαν σφῶν ἀποκρυψάμενοι. ἐποίουν μὲν γὰρ ὅσα ἐδέδοκτό σφισιν, ἐσχηματίζοντο δὲ καὶ προεβάλλοντο τὰ ἐναντιώτατα, ὅπως ἔτ’ ἐπὶ μακρότατον διαλάθωσι, μέχρις ἂν ἱκανῶς παρασκευάσωνται. οὐ μέντοι καὶ τὸ δαιμόνιον τὰ πραττόμενα ὑπ’ αὐτῶν ἠγνόει, ἀλλὰ καὶ πάνυ τοῖς τι συνεῖναι τῶν τοιούτων δυναμένοις εὐθὺς τότε πάντα τὰ ἔπειτα ἀπ’ αὐτῶν ἐσόμενα ἐξέφηνε· χειμών τε γὰρ τοιοῦτος ἐξαίφνης τήν τε πόλιν ὅλην καὶ τὴν χώραν ἅπασαν κατέσχεν ὥστε πάμπολλα μὲν δένδρα πρόρριζα ἀνατραπῆναι, πολλὰς δὲ οἰκίας καταρραγῆναι, τά τε πλοῖα τὰ ἐν τῷ Τιβέριδι καὶ πρὸς τὸ ἄστυ καὶ πρὸς τὰς ἐκβολὰς αὐτοῦ ναυλοχοῦντα βαπτισθῆναι, καὶ τὴν γέφυραν τὴν ξυλίνην διαφθαρῆναι, καί τι καὶ θέατρον πρὸς πανήγυρίν τινα ἐκ θυρῶν ᾠκοδομημένον ἀνετράπη, καὶ ἄνθρωποι παρὰ πάντα ταῦτα παμπληθεῖς ἀπώλοντο. ἐκεῖνα μὲν δὴ οὖν καθάπερ εἰκὼν τῶν μελλόντων σφίσι καὶ ἐν τῇ γῇ καὶ ἐν τῷ ὕδατι συμβήσεσθαι προεδείχθη.", "st": "37.58"}, {"sp": "HDR", "t": "Βιβλίον ΛΗʹ", "st": "38"}, {"sp": "N", "t": "τάδε ἔνεστιν ἐν τῷ τριακοστῷ ὀγδόῳ τῶν Δίωνος Ῥωμαϊκῶν α. ὡς ἐστασίασαν Καῖσαρ καὶ Βίβουλος. β. ως Κικέρων ἔφυγεν. γ. ὡς Κικέρωνα ἐπὶ τῇ φυγῇ Φιλίσκος παρεμυθήσατο. δ. ὡς Καῖσαρ Ἐλουητίοις καὶ Ἀριοουίστῳ ἐπολέμησεν. χρόνου πλῆθος ἔτη δύο, ἐν οἷς ἄρχοντες οἱ ἀριθμούμενοι οἵδε ἐγένοντο Γ. Ἰούλιος Γ. υἱ. Καῖσαρ Μ. Καλπούρνιος Γ. υἱ. Βίβουλος ὑπ. λ. Καλπούρνιος λ. υἱ. Πίσων Αὖλ. Γαβίνιος Αὔλ. υἱ. ὑπ.", "st": "38.0"}, {"sp": "N", "t": "τῷ δὲ ἑξῆς ἔτει ὁ Καῖσαρ τὸ σύμπαν θεραπεῦσαι πλῆθος ἠθέλησεν, ὅπως σφᾶς ἔτι καὶ μᾶλλον σφετερίσηται. βουληθεὶς δὲ καὶ τὰ τῶν δυνατῶν δοκεῖν, ἵνα μὴ καὶ δι’ ἀπεχθείας αὐτῷ ὦσι, πράττειν, εἶπέ σφισι πολλάκις ὅτι οὔτε γράψοι τι ὃ μὴ καὶ ἐκείνοις συνοίσει· καὶ δὴ γνώμην τινὰ περὶ τῆς χώρας, ἣν παντὶ τῷ ὁμίλῳ κατένειμεν, οὕτω συνέγραψεν ὥστε μηδὲ μικρόν τι αὐτῆς αἰτιαθῆναι· καὶ οὐδὲ ταύτην μέντοι ἐσοίσειν, εἰ μὴ βουλομένοις σφίσιν εἴη, ἐπλάττετο. τοῦ μὲν δὴ οὖν νόμου ἕνεκα οὐδεὶς αὐτῷ οὐδὲν ἐπικαλέσαι ἐδύνατο· τό τε γὰρ πλῆθος τῶν πολιτῶν ὑπέρογκον ὄν, ἀφ’ οὗπερ καὶ τὰ μάλιστα ἐστασίαζον, πρός τε τὰ ἔργα καὶ πρὸς γεωργίας ἐτρέπετο, καὶ τὰ πλεῖστα τῆς Ἰταλίας ἠρημωμένα αὖθις συνῳκίζετο, ὥστε μὴ μόνον τοὺς ἐν ταῖς στρατείαις τεταλαιπωρημένους ἀλλὰ καὶ τοὺς ἄλλους ἅπαντας διαρκῆ τὴν τροφὴν ἔχειν μήτε τῆς πόλεως οἴκοθέν τι δαπανωμένης μήτε τῶν δυνατῶν ζημιουμένων, ἀλλὰ καὶ τιμὴν καὶ ἀρχὴν πολλῶν προσλαμβανόντων. τὴν δὲ χώραν τήν τε κοινὴν ἅπασαν πλὴν τῆς Καμπανίδος ἔνεμε (ταύτην γὰρ ἐν τῷ δημοσίῳ ἐξαίρετον διὰ τὴν ἀρετὴν συνεβούλευσεν εἶναι), καὶ τὴν λοιπὴν οὔτε παρὰ ἄκοντός τινος οὔτ’ αὖ ὅσου ἂν οἱ γεωνόμοι βουληθῶσιν, ἀλλὰ πρῶτον μὲν παρ’ ἑκόντων, ἔπειτα δὲ τοσούτου ὅσου ἐν ταῖς ἀπογραφαῖς ἐτετίμητο, ἀγορασθῆναι ἐκέλευσε. χρήματά τε γὰρ πολλὰ ἀπό τε τῆς λείας ἣν ὁ Πομπήιος εἰλήφει καὶ ἀπὸ τῶν φόρων τῶν τε τελῶν τῶν προσκαταστάντων περιεῖναί σφισιν ἔλεγε, καὶ χρῆναι αὐτά, ἅτε καὶ τοῖς τῶν πολιτῶν κινδύνοις πεπορισμένα, ἐς αὐτοὺς ἐκείνους ἀναλωθῆναι. καὶ μέντοι καὶ τοὺς γεωνόμους οὔτ’ ὀλίγους, ὥστε καὶ δυναστείᾳ τινὶ ἐοικέναι, οὔτ’ ἐξ ὑπευθύνων, ὥστε τινὰ δυσχερᾶναι, καθίστη, ἀλλὰ πρῶτον μὲν τοῦ συχνοὺς τῆς τιμῆς μετασχεῖν εἴκοσιν, ἔπειτα δὲ τοὺς ἐπιτηδειοτάτους, πλὴν ἑαυτοῦ. πάνυ γάρ τι τοῦτο προδιωμολογήσατο, ὅπως μὴ δι’ ἑαυτόν τι γράφειν νομισθείη· αὐτὸς μὲν γὰρ τῇ τε εὑρήσει καὶ τῇ ἐσηγήσει τοῦ πράγματος ἠρκεῖτο, ὥς γε ἔλεγε, τῷ δὲ δὴ Πομπηίῳ καὶ τῷ Κράσσῳ τοῖς τε ἄλλοις φανερῶς ἐχαρίζετο.", "st": "38.1"}, {"sp": "N", "t": "ἕνεκα μὲν οὖν τῶν γραφέντων ἀναίτιος ἦν, ὥστε μηδὲ διᾶραι τὸ στόμα ὑπεναντίον οἱ μηδένα τολμῆσαι· καὶ γὰρ προανέγνω αὐτὰ ἐν τῇ βουλῇ, καὶ ὀνομαστὶ ἕνα ἕκαστον αὐτῶν ἀνακαλῶν ἐπηρώτησε μή τί τις αἰτιᾶται, μεταγράψειν ἢ καὶ παντελῶς ἀπαλείψειν, εἴ γέ τῳ μὴ ἀρέσειέ τι, ὑποσχόμενος. τὸ δὲ δὴ σύμπαν καὶ πάνυ πάντες οἱ δυνατοὶ οἵ γε ἔξω τῆς συνωμοσίας ὄντες ἐδυσχέραινον. καὶ αὐτό γε τοῦτο αὐτοὺς ἐς τὰ μάλιστα ἐλύπει, ὅτι τοιαῦτα συγγεγραφὼς ἦν ὥστε μήτε τινὰ αἰτίαν δύνασθαι λαβεῖν καὶ πάντας σφᾶς βαρύνειν· ὑπώπτευον γὰρ αὐτόν, ἐφ’ ᾧπέρ που καὶ ἐγίγνετο, τό τε πλῆθος ἀπ’ αὐτῶν ἀναρτήσεσθαι καὶ ὄνομα καὶ ἰσχὺν καὶ ἐπὶ πάντας ἀνθρώπους ἕξειν. καὶ διὰ τοῦτο, εἰ καὶ μηδείς οἱ ἀντέλεγεν, ἀλλ’ οὔτι γε καὶ συνεπῄνουν. τοῖς μὲν δὴ οὖν ἄλλοις ἐξήρκει τοῦτο, καὶ ἐπηγγέλλοντο μὲν ἀεὶ αὐτῷ προβουλεύσειν, ἐποίουν δὲ οὐδέν, ἀλλὰ διατριβαὶ καὶ ἀναβολαὶ τὴν", "st": "38.2"}, {"sp": "N", "t": "ἄλλως ἐγίγνοντο· ὁ δὲ δὴ Κάτων ὁ Μᾶρκος (ἦν δὲ ἄλλως μὲν ἐπιεικὴς καὶ οὐδενὶ νεοχμῷ ἀρεσκόμενος, οὐ μὴν καὶ ῥώμην τινὰ οὔτε ἐκ φύσεως οὔτε ἐκ παιδείας ἔχων) τοῖς μὲν γεγραμμένοις οὐδὲν οὐδ’ αὐτὸς ἐπεκάλει, τὸ δ’ ὅλον ἠξίου τῇ τε παρούσῃ σφᾶς καταστάσει χρῆσθαι καὶ μηδὲν ἔξω αὐτῆς ποιεῖν. καὶ ἐμέλλησε μὲν ἐπὶ τούτοις ὁ Καῖσαρ ἐς τὸ δεσμωτήριον τὸν Κάτωνα ἐξ αὐτοῦ τοῦ συνεδρίου ἐξελκύσας ἐμβαλεῖν· ἐπεὶ δὲ ἐκεῖνός τε ἑτοιμότατα ἑαυτὸν ἀπάγεσθαι ἐπέδωκε, καὶ τῶν ἄλλων οὐκ ὀλίγοι οἱ ἐφέσποντο, καί τις αὐτῶν Μᾶρκος Πετρέιος ἐπιτιμηθεὶς ὑπ’ αὐτοῦ ὅτι μηδέπω διαφειμένης τῆς βουλῆς ἀπαλλάττοιτο, ἔφη ὅτι μετὰ Κάτωνος ἐν τῷ οἰκήματι μᾶλλον ἢ μετὰ σοῦ ἐνταῦθα εἶναι βούλομαι, κατῃδέσθη, καὶ τόν τε Κάτωνα ἀφῆκε καὶ τὴν γερουσίαν ἀπήλλαξε, τοσοῦτον μόνον ὑπειπὼν ὅτι ἐγὼ μὲν ὑμᾶς καὶ δικαστὰς τοῦ νόμου καὶ κυρίους ἐποιησάμην, ὅπως, εἴ τι μὴ ἀρέσειεν ὑμᾶς, μηδ’ ἐς τὸν δῆμον ἐσενεχθείη· ἐπεὶ δ’ οὐκ ἐθέλετε προβουλεῦσαι, ἐκεῖνος αὐτὸς αἱρήσεται.", "st": "38.3"}, {"sp": "N", "t": "κἀκ τούτου οὐδ’ ἄλλο τι τῇ γερουσίᾳ ἐν τῇ ἀρχῇ ταύτῃ ἐπεκοινώνησεν, ἀλλ’ ἐς τὸν δῆμον ἄντικρυς πάνθ’ ὅσα ἐβούλετο ἐσέφερεν. ἐθελήσας δ’ οὖν καὶ ὣς ὁμογνώμονας τῶν πρώτων τινὰς ἐν τῇ ἐκκλησίᾳ λαβεῖν (καὶ γὰρ ἤλπιζε μετεγνωκέναι τε αὐτοὺς καί πῃ καὶ τὸ πλῆθος φοβηθήσεσθαι) ἤρξατο ἀπὸ τοῦ συνάρχοντος, καὶ ἐπύθετο αὐτοῦ εἰ τὰ τοῦ νόμου μέμφοιτο. ἐπεί τ’ ἐκεῖνος οὐδὲν ἀπεκρίνατο πλὴν ὅτι οὐκ ἂν ἀνάσχοιτο ἐν τῇ ἑαυτοῦ ἀρχῇ νεωτερισθῆναί τι, αὐτός τε πρὸς ἱκετείαν αὐτοῦ ἐτράπετο καὶ τὸν ὅμιλον συνδεηθῆναί οἱ ἔπεισεν, εἰπὼν ὅτι ἕξετε τὸν νόμον ἂν οὗτος ἐθελήσῃ. ὁ οὖν Βίβουλος μέγα ἀναβοήσας “οὐχ ἕξετε,” ἔφη, “τὸν νόμον τοῦτον ἐν τῷ ἔτει τούτῳ, οὐδ’ ἂν πάντες ἐθελήσητε.” καὶ ὁ μὲν ταῦτ’ εἰπὼν ἀπηλλάγη· ὁ δὲ δὴ Καῖσαρ τῶν μὲν ἄλλων τῶν ἐν ταῖς ἀρχαῖς ὄντων οὐδένα ἔτι διήρετο, δείσας μὴ καὶ ἐκείνων τις ἐναντιωθῇ οἱ, τὸν δὲ δὴ Πομπήιον τόν τε Κράσσον καίπερ ἰδιωτεύοντας παραγαγὼν ἐκέλευσε γνώμην περὶ τῶν γεγραμμένων ἀποφήνασθαι, οὐχ ὅτι οὐκ ἠπίστατο τὴν διάνοιαν αὐτῶν (σύμπαντα γὰρ κοινῇ ἔπραττον) ἀλλ’ ἵνα αὐτοῖς τε ἐκείνοις τιμήν, ὅτι καίτοι μηδεμίαν ἀρχὴν ἔχουσιν συμβούλοις περὶ τοῦ νόμου χρῷτο, προσθείη, καὶ τοὺς ἄλλους προσκαταπλήξῃ, ὁμογνώμονας τοὺς πρώτους τε ὁμολογουμένως ἐν τῇ πόλει τότε ὄντας καὶ μέγιστον παρὰ πάντας δυναμένους λαβών, τῷ τε πλήθει καὶ κατ’ αὐτὸ τοῦτο χαρίσαιτο, τεκμηριῶν ὅτι μήτ’ ἀτόπου μήτ’ ἀδίκου τινὸς ὀρέγοιντο, ἀλλ’ ὧν καὶ ἐκεῖνοι καὶ δοκιμασταὶ καὶ ἐπαινέται γίγνοιντο.", "st": "38.4"}, {"sp": "N", "t": "ὅ τε οὖν Πομπήιος μάλα ἀσμένως “οὐκ ἐγώ,” ἔφη, “μόνος, ὦ Κυιρῖται, τὰ γεγραμμένα δοκιμάζω, ἀλλὰ καὶ ἡ ἄλλη βουλὴ πᾶσα, δι’ ὧν οὐχ ὅτι τοῖς μετ’ ἐμοῦ ἀλλὰ καὶ τοῖς μετὰ τοῦ Μετέλλου συστρατευσαμένοις ποτὲ γῆν δοθῆναι ἐψηφίσατο. τότε μὲν οὖν (οὐ γὰρ ηὐπόρει τὸ δημόσιον) εἰκότως ἡ δόσις αὐτῆς ἀνεβλήθη· ἐν δὲ δὴ τῷ παρόντι (παμπλούσιον γὰρ ὑπ’ ἐμοῦ γέγονε) προσήκει καὶ ἐκείνοις τὴν ὑπόσχεσιν καὶ τοῖς ἄλλοις τὴν ἐπικαρπίαν τῶν κοινῶν πόνων ἀποδοθῆναι.” ταῦτ’ εἰπὼν ἐπεξῆλθέ τε καθ’ ἕκαστον τῶν γεγραμμένων, καὶ πάντα αὐτὰ ἐπῄνεσεν, ὥστε τὸν ὅμιλον ἰσχυρῶς ἡσθῆναι. ὁ οὖν Καῖσαρ ἰδὼν τοῦτο ἐκεῖνόν τε ἐπήρετο εἰ βοηθήσοι οἱ προθύμως ἐπὶ τοὺς τἀναντία σφίσι πράττοντας, καὶ τῷ πλήθει παρῄνεσε προσδεηθῆναι πρὸς τοῦτο αὐτοῦ. γενομένου δὲ τούτου ἐπαρθεὶς ὁ Πομπήιος, ὅτι τῆς παρ’ ἑαυτοῦ ἐπικουρίας, καίπερ μηδεμίαν ἡγεμονίαν ἔχοντος, καὶ ὁ ὕπατος καὶ ὁ ὅμιλος ἔχρῃζεν, ἄλλα τε πολλὰ ἀνατιμῶν τε καὶ ἀποσεμνύνων ἑαυτὸν διελέξατο, καὶ τέλος εἶπεν ὅτι, ἄν τις τολμήσῃ ξίφος ἀνελέσθαι, καὶ ἐγὼ τὴν ἀσπίδα ἀναλήψομαι. ταῦθ’ οὕτως ὑπὸ τοῦ Πομπηίου λεχθέντα καὶ Κράσσος ἐπῄνεσεν. ὥστ’ εἰ καί τισι τῶν ἄλλων μὴ ἤρεσκεν, … οι ἄλλως τε ἄνδρες ἀγαθοὶ νομιζόμενοι καὶ πρὸς τὸν Καίσαρα ἐχθρῶς, ὥς γε καὶ ἐδόκουν σφίσιν, ἔχοντες (οὐ γάρ πω ἡ καταλλαγὴ αὐτῶν ἔκδηλος ἦν) συνῄνουν οἷς ἐγεγράφει, πρόθυμοι πρὸς τὴν τοῦ νόμου κύρωσιν ἐγένοντο.", "st": "38.5"}, {"sp": "N", "t": "οὐ μέντοι καὶ ὁ Βίβουλος ἐνεδίδου, ἀλλὰ τρεῖς δημάρχους συναγωνιστὰς προσθέμενος ἐκώλυσε τὸ νομοθέτημα, καὶ τέλος, ἐπειδὴ μηκέτ’ αὐτῷ μηδεμία ἄλλη σκῆψις ἀναβολῆς ὑπελείπετο, ἱερομηνίαν ἐς πάσας ὁμοίως τὰς λοιπὰς τοῦ ἔτους ἡμέρας, ἐν αἷς οὐδ’ ἐς ἐκκλησίαν ὁ δῆμος ἐκ τῶν νόμων συνελθεῖν ἐδύνατο, προηγόρευσε. καὶ ἐπειδὴ ὅ τε Καῖσαρ βραχὺ αὐτοῦ φροντίσας ῥητήν τινα ἡμέραν προεῖπεν ἵν’ ἐν αὐτῇ νομοθετήσῃ, καὶ τὸ πλῆθος νυκτὸς τὴν ἀγορὰν προκατέλαβεν, ἐπῆλθε μετὰ τῶν παρεσκευασμένων, καὶ πρὸς μὲν τὸ Διοσκόρειον, ἀφ’ οὗπερ ἐκεῖνος ἐδημηγόρει, διέπεσεν, τὰ μὲν αἰδοῖ τῶν ἀνθρώπων ὑπεικόντων οἱ, τὰ δὲ καὶ νομιζόντων αὐτὸν μὴ καὶ ἐναντιωθήσεσθαί σφισιν, ὡς δὲ ἄνω τε ἐγένετο καὶ ἀντιλέγειν ἐπειρᾶτο, αὐτός τε κατὰ τῶν ἀναβασμῶν ἐώσθη καὶ αἱ ῥάβδοι αὐτοῦ συνετρίβησαν, πληγάς τε καὶ τραύματα ἄλλοι τε καὶ οἱ δήμαρχοι ἔλαβον. καὶ ὁ μὲν νόμος οὕτως ἐκυρώθη, Βίβουλος δὲ τότε μὲν ἀγαπητῶς ἐσώθη, τῇ δ’ ὑστεραίᾳ ἐπείρασε μὲν ἐν τῷ συνεδρίῳ αὐτὸν λῦσαι, ἐπέρανε δ’ οὐδέν· τῇ γὰρ τοῦ πλήθους σπουδῇ δεδουλωμένοι πάντες ἡσύχαζον. ἀνεχώρησέ τε οὖν οἴκαδε, καὶ οὐκέτι τὸ παράπαν ἐς τὸ κοινὸν μέχρι τῆς τελευταίας τοῦ ἔτους ἡμέρας παρῆλθεν, ἀλλ’ ἐν τῇ οἰκίᾳ καταμένων ἀεὶ τῷ Καίσαρι, ὁσάκις γε ἐνεωτέριζέ τι, ἐνετέλλετο διὰ τῶν ὑπηρετῶν ὅτι ἱερομηνία τε εἴη καὶ οὐδὲν ὁσίως ἐκ τῶν νόμων ἐν αὐτῇ δύναιτο δρᾶσθαι. ἐπεχείρησε μὲν γὰρ αὐτὸν ἐπὶ τούτοις Πούπλιός τις Οὐατίνιος δήμαρχος ἐς τὸ οἴκημα καταθέσθαι, τῶν δὲ συναρχόντων οἱ ἐναντιωθέντων οὐκ ἐνέβαλεν, ἀλλ’ ἐκεῖνός τε οὕτω τῶν πολιτικῶν ἐξέστη καὶ οἱ δήμαρχοι οἱ συνεξετασθέντες αὐτῷ οὐκέτ’ οὐδὲν δημόσιον ἔπραξαν.", "st": "38.6"}, {"sp": "N", "t": "ὁ δ’ οὖν Μέτελλος ὁ Κέλερ ὅ τε Κάτων, καὶ Μᾶρκός τις δι’ αὐτὸν Φαουώνιος, ζηλωτὴς ἐς τὰ μάλιστα αὐτοῦ ὤν, τέως μὲν οὔτ’ ὤμοσαν περὶ τοῦ νόμου (τοῦτο γὰρ ἀρξάμενόν ποτε, ὥσπερ εἶπον, καὶ ἐπὶ τῶν ἄλλων τῶν ἀτόπων ἐγίγνετο) καὶ ἀπισχυρίζοντο, ἄλλως τε καὶ ὁ Μέτελλος ἐς τὸν Νουμιδικὸν ἀναφέρων, μηδέποτε αὐτὸν συνεπαινέσειν· ὡς μέντοι … ἡμέρα ᾗ καὶ ἔμελλον τὰ τεταγμένα ἐπιτίμια ὀφλήσειν, ὤμοσαν, ἤτοι κατὰ τὸ ἀνθρώπειον, ὑφ’ οὗ πολλοὶ ὑπισχνοῦνταί τέ τι καὶ ἀπειλοῦσι ῥᾷον ἢ καὶ τῷ ἔργῳ ἐπεξίασιν, ἢ καὶ ὅτι μάτην ζημιωθήσεσθαι ἔμελλον, μηδὲν ἐκ τῆς ἰσχυρογνωμοσύνης σφῶν τὸ κοινὸν ὠφελήσαντες. ὅ τε οὖν νόμος οὕτως ἐκυρώθη, καὶ προσέτι καὶ ἡ τῶν Καμπανῶν γῆ τοῖς τρία τε πλείω τε ἔτι τέκνα ἔχουσιν ἐδόθη. καὶ διὰ τοῦτο καὶ ἄποικος τῶν Ῥωμαίων ἡ Καπύη τότε πρῶτον ἐνομίσθη. τὸ μὲν οὖν πλῆθος ἐκ τούτων ὁ Καῖσαρ ἀνηρτήσατο, τοὺς δ’ ἱππέας τὸ τριτημόριόν σφισι τῶν τελῶν ἃ ἐμεμίσθωντο ἀφείς· πᾶσαί τε γὰρ αἱ τελωνίαι δι’ αὐτῶν ἐγίγνοντο, καὶ πολλάκις τῆς βουλῆς δεηθέντες ὅπως ἐκδικίας τινὸς τύχωσιν οὐχ εὕροντο, ἄλλων τε καὶ τοῦ Κάτωνος ἀντιπραξάντων. ὡς δ’ οὖν καὶ τοῦτο τὸ ἔθνος μηδ’ ἀντειπόντος τινὸς ᾠκειώσατο, πρῶτον μὲν τὰ πραχθέντα ὑπὸ τοῦ Πομπηίου πάντα, μήτε τοῦ Λουκούλλου μήτ’ ἄλλου τινὸς ἀντιστάντος, ἐβεβαίωσεν, ἔπειτα δὲ καὶ ἄλλα πολλὰ διενομοθέτησε μηδενὸς ἐναντιουμένου. οὐδὲ γὰρ οὐδ’ ὁ Κάτων ἀντεῖπέ τι, καίπερ ἐν τῇ στρατηγίᾳ, ἣν μετὰ ταῦτα οὐ πολλῷ ὕστερον ἔσχε, μηδαμοῦ τῆς τῶν νόμων αὐτοῦ προσηγορίας, ὡς καὶ Ἰουλίων ἐπικαλουμένων, ἐπιμνησθείς· τὰ γὰρ δικαστήρια κατ’ αὐτοὺς ἀποκληρῶν τὸ ὄνομα αὐτῶν γελοιότατα ἀπεκρύπτετο. τούτους μὲν οὖν, ὅτι πάμπολλοί τέ εἰσι καὶ οὐδ’ ὁτιοῦν τῇδε τῇ συγγραφῇ συμβάλλονται,", "st": "38.7"}, {"sp": "N", "t": "παραλείψω· Κύιντος δὲ δὴ Φούφιος Καλῆνος ἀναμὶξ πάντων τὰς ψήφους ἔν γε ταῖς φιλονεικίαις (τά τε κρείττω πρὸς σφᾶς ὡς ἑκάστου τῶν γενῶν ἄγοντος καὶ τὰ ἀτοπώτερα ἐς ἑτέρους ἀπωθοῦντος) οὔσας εὑρών, ἐνομοθέτησε στρατηγῶν χωρὶς αὐτοὺς ὡς ἑκάστους ψηφίζεσθαι, ἵν’ εἰ μὴ καὶ κατ’ ἄνδρα, τῷ κρύφα σφᾶς τοῦτο ποιεῖν, ἀλλὰ τά γε ἔθνη αὐτῶν ἔκδηλα ὅπως φρονοίη γίγνοιτο. τὰ μὲν οὖν ἄλλα αὐτὸς ὁ Καῖσαρ καὶ ἐσηγεῖτο καὶ συνεβούλευε καὶ διέταττε πάντα καθάπαξ τἀν τῇ πόλει, ὡς καὶ μόνος αὐτῆς ἄρχων· ὅθενπερ χαριεντιζόμενοί τινες τὸ μὲν τοῦ Βιβούλου ὄνομα παντάπασιν ἀπεσιώπων, τὸν δὲ δὴ Καίσαρα δὶς καὶ ὠνόμαζον καὶ ἔγραφον, Γάιόν τε Καίσαρα καὶ Ἰούλιον Καίσαρα ὑπατεύειν λέγοντες· τὰ δὲ δὴ καθ’ ἑαυτὸν δι’ ἑτέρων διῆγε. τοῦτο γὰρ δὴ καὶ πάνυ ἰσχυρῶς ἐφυλάξατο, μηδὲν αὐτὸς ἑαυτῷ δοῦναι· καὶ διὰ τοῦτο καὶ ῥᾷον πάνθ’ ὅσων ἐπεθύμει κατειργάσατο. αὐτὸς μὲν γὰρ οὐδενὸς προσδεῖσθαι ἔλεγεν, ἀλλὰ καὶ σφόδρα τοῖς παροῦσιν ἀρκεῖσθαι ἐσκήπτετο· ἕτεροι δέ, ὡς καὶ ἀναγκαίου καὶ χρησίμου τοῖς πράγμασιν αὐτοῦ ὄντος, καὶ ἐσηγήσαντο ὅσα ἠθέλησε καὶ κυρωθῆναι ἐποίησαν, οὐκ ἐν τῷ πλήθει μόνον ἀλλὰ καὶ ἐν αὐτῇ τῇ γερουσίᾳ. ὅ τε γὰρ ὅμιλος τοῦ τε Ἰλλυρικοῦ καὶ τῆς Γαλατίας τῆς ἐντὸς τῶν Ἄλπεων ἄρξαι αὐτῷ μετὰ τριῶν στρατοπέδων ἐπὶ ἔτη πέντε ἔδωκε, καὶ ἡ βουλὴ τήν τε Γαλατίαν τὴν ἐπέκεινα τῶν ὀρῶν καὶ στρατόπεδον ἕτερον προσεπέτρεψε.", "st": "38.8"}, {"sp": "N", "t": "φοβηθεὶς δ’ οὖν καὶ ὣς μή τι ὁ Πομπήιος ἐν τῇ ἀπουσίᾳ αὐτοῦ, ἐπειδὴ ὁ Γαβίνιος ὁ Αὖλος ὑπατεύσειν ἔμελλε, νεωτερίσῃ, ἐκεῖνόν τε ἅμα καὶ τὸν ἕτερον ὕπατον Λούκιον Πίσωνα συγγενείας ἀνάγκῃ προσηταιρίσατο· τῷ μὲν γὰρ Πομπηίῳ τὴν θυγατέρα καίπερ ἄλλῳ τινὶ ἠγγυηκὼς συνῴκισε, καὶ αὐτὸς τὴν τοῦ Πίσωνος ἔγημε. καὶ ὁ μὲν οὕτω πανταχόθεν ἐκρατύνθη, Κικέρων δὲ καὶ Λούκουλλος οὐκ ἀρεσκόμενοι τούτοις ἀποκτεῖναι τόν τε Καίσαρα καὶ τὸν Πομπήιον διὰ Λουκίου τινὸς Οὐεττίου ἐπεχείρησαν μέν, οὐκ ἠδυνήθησαν δέ, ἀλλ’ ὀλίγου καὶ αὐτοὶ προσαπώλοντο. προμηνυθεὶς γὰρ ἐκεῖνος καὶ συλληφθεὶς πρίν τι δρᾶσαι, κατεῖπεν αὐτῶν· καὶ εἴγε μὴ καὶ τὸν Βίβουλον ὡς καὶ συνεπιβουλεύοντά σφισιν ἐσηγγέλκει, πάντως ἄν τι δεινὸν ἐπεπόνθεσαν· νῦν δέ, ὅτι τοῦτον τῷ Πομπηίῳ τὸ πραττόμενον δηλώσαντα ἀμυνόμενος ᾐτιᾶτο, ὑπωπτεύθη μηδὲ ἐπὶ τῶν λοιπῶν ἀληθεύειν, ἀλλ’ ἐκ κατασκευασμοῦ τινος πρὸς συκοφαντίαν τῶν ἀντιστασιωτῶν σφων παρεσκευάσθαι. καὶ περὶ μὲν τούτων ἄλλοι ἄλλα διεθρύλουν· οὐ γάρ που καὶ διηλέγχθη τι, ἀλλὰ ἐς τὸ πλῆθος ὁ Οὐέττιος ἐσαχθείς, καὶ μόνους οὓς εἶπον ὀνομάσας, ἔς τε τὸ οἴκημα ἐσέπεσε, κἀνταῦθα οὐ πολλῷ ὕστερον ἐδολοφονήθη·", "st": "38.9"}, {"sp": "N", "t": "ὕποπτός τε οὖν ἐκ τούτων ὁ Κικέρων τῷ τε Καίσαρι καὶ τῷ Πομπηίῳ γενόμενος ἐβεβαιώσατο τὴν ὑπόνοιαν ἐν τῇ ὑπὲρ τοῦ Ἀντωνίου ἀπολογίᾳ. Οὗτος γὰρ πολλὰ μὲν καὶ δεινὰ καὶ τὸ ὑπήκοον τὸ ἐν τῇ Μακεδονίᾳ, ἄρξας αὐτῆς, καὶ τὸ ἔνσπονδον εἰργάσατο, πολλὰ δὲ καὶ ἀντέπαθε. τά τε γὰρ τῶν Δαρδάνων καὶ τὰ τῶν πλησιοχώρων σφίσι πορθήσας οὐκ ἐτόλμησεν ἐπιόντας αὐτοὺς ὑπομεῖναι, ἀλλ’ ὡς καὶ ἐπ’ ἄλλο τι μετὰ τῶν ἱππέων ὑποχωρήσας ἔφυγεν, καὶ οὕτω τοὺς πεζοὺς ἐκεῖνοι περισχόντες ἔκ τε τῆς χώρας βιαίως ἐξήλασαν καὶ τὴν λείαν προσαφείλοντο. τὸ δ’ αὐτὸ τοῦτο καὶ περὶ τοὺς συμμάχους τοὺς ἐν τῇ Μυσίᾳ ποιήσας ἡττήθη πρὸς τῇ τῶν Ἰστριανῶν πόλει πρὸς τῶν Σκυθῶν τῶν Βασταρνῶν, ἐπιβοηθησάντων αὐτοῖς, καὶ ἀπέδρα. οὐ μέντοι καὶ ἐπὶ τούτοις αἰτίαν ἔσχεν, ἀλλ’ ἐγράφη μὲν ἐπὶ τῇ τοῦ Κατιλίνου συνωμοσίᾳ, ἑάλω δὲ δι’ ἐκεῖνα, καὶ συνέβη αὐτῷ, ὧν μὲν ἐκρίνετο, μὴ ἐλεγχθῆναι, ὧν δ’ οὐκ ᾐτιάζετο, κολασθῆναι. καὶ ὁ μὲν οὕτως ἀπήλλαξεν, ὁ δὲ δὴ Κικέρων ὑπὲρ αὐτοῦ τότε, ἅτε καὶ συνάρξαντός οἱ, ὑπερδικῶν, πλείστην κατὰ τοῦ Καίσαρος ὡς καὶ αἰτίου τῆς δίκης αὐτῷ γεγενημένου καταδρομὴν ἐποιήσατο, καί τινα αὐτὸν καὶ προσελοιδόρησεν.", "st": "38.10"}, {"sp": "N", "t": "ὁ δ’ ἤχθετο μὲν ἐπ’ αὐτοῖς ὥσπερ εἰκὸς ἦν, οὐ μὴν οὔτ’ εἶπεν οὔτ’ ἔπραξεν ὑβριστικὸν ἐς αὐτὸν οὐδέν, καίπερ ὑπατεύων. τοὺς γὰρ πολλοὺς ἔλεγε συχνὰ καὶ μάταια ἐξεπίτηδες ἐς τοὺς κρείττονάς σφων ἐς φιλονεικίαν αὐτοὺς ὑπάγοντας. … ἵν’ ἴσοι σφίσι καὶ ὅμοιοι, ἄν γέ τι ὁμοιότροπον ἀντακούσωσι, δόξωσιν εἶναι· καὶ οὐκ ἠξίου ἀντίπαλον ἐκ τούτου οὐδένα ἑαυτῷ ποιεῖν. καὶ διὰ τοῦτο τοῖς τε ἄλλοις τοῖς τι προπηλακίζουσιν αὐτὸν οὕτω προσεφέρετο, καὶ τότε τὸν Κικέρωνα ὁρῶν οὐχ ἑαυτῷ τι τοσοῦτον λοιδορήσασθαι ἐθέλοντα ὅσον ἀντακοῦσαί τι τῶν ὁμοίων, ὥστε καὶ παρισωθῆναί οἱ, ἐπιθυμοῦντα, βραχύ τε αὐτοῦ ἐφρόντισε καὶ οὐδὲν ὧν ἔλεγε προσεποιήσατο, ἀλλ’ εἴα αὐτὸν ἀφθόνως, καθάπερ τισὶν ἐπαίνοις ἑαυτοῦ, ταῖς λοιδορίαις χρῆσθαι. οὐ μέντοι καὶ παντάπασιν ὀλιγώρως αὐτοῦ ἔσχεν. ἐπιεικεστέραν μὲν γὰρ ὄντως φύσιν εἰλήχει, καὶ οὐ πάνυ ῥᾳδίως ἐθυμοῦτο· συχνοὺς δ’ οὖν, ἅτε καὶ ἐν τοσούτοις πράγμασιν, ἐδικαίου, οὐ μὴν ὥστε καὶ δι’ ὀργῆς ἢ καὶ παραχρῆμα πάντως αὐτὸ ποιεῖν. θυμῷ μὲν δὴ οὐδὲν ἐχαρίζετο, τοῦ δὲ δὴ καιροῦ διεσκόπει, καὶ τούς γε πλείους οὐδὲ αἰσθανομένους μετῄει. οὐ γὰρ ὅπως δόξειεν ἀμύνεσθαί τινας ἔπρασσεν, ἀλλ’ ὅπως ὅτι ἀνεπιφθονώτατα πρὸς τὸ συμφέρον ἑαυτῷ πάντα διοικήσειε. καὶ διὰ τοῦτο καὶ ἀδήλως, καὶ ἐν οἷς ἥκιστα ἄν τις προσεδόκησε, τὰς τιμωρίας ἐπῆγε, τῆς τε φήμης ἕνεκα, τοῦ μὴ δοκεῖν ὀργίλως ἔχειν, καὶ τοῦ μή τινα προαισθανόμενον προφυλάξασθαι ἢ καὶ προποιῆσαί τι δεινὸν αὐτόν, πρὶν παθεῖν, ἐπιχειρῆσαι. οὐ γὰρ τῶν ἤδη γεγονότων μᾶλλόν τι αὐτῷ ἔμελεν ἢ ἵνα τὰ μέλλοντα κωλυθείη. κἀκ τούτου πολλοῖς μὲν καὶ τῶν μεγάλα αὐτὸν λυπησάντων συνεγίγνωσκεν ἢ καὶ ἐπὶ βραχὺ ἐπεξῄει, ὅτι οὐδὲν ἔτι κακουργήσειν αὐτοὺς ἐπίστευε· πολλοὺς δὲ καὶ ἐπὶ πλεῖον τοῦ καθήκοντος ἐς ἀσφάλειαν ἐτιμωρεῖτο, λέγων ὅτι τὸ μὲν … οὐκ ἄν ποτε ἀγένητον … τῆς κολάσεως ὑπερβολῇ πάντως τι δεινὸν πείσεται.", "st": "38.11"}, {"sp": "N", "t": "ἐξ οὖν τούτων τῶν λογισμῶν καὶ τότε αὐτὸς μὲν τὴν ἡσυχίαν ἦγε, τὸν δὲ δὴ Κλώδιον ἀντιχαρίσασθαί τι αὐτῷ, ὅτι τῆς μοιχείας αὐτοῦ οὐ κατηγόρησε, βουλόμενον αἰσθόμενος παρεσκεύασε κρύφα κατὰ τοῦ Κικέρωνος. καὶ πρῶτον μὲν ἐς τὰ τοῦ πλήθους δικαιώματα αὖθις αὐτόν, ὅπως νομίμως ἐκποιηθῇ, συμπράττοντος αὐτῷ καὶ τοῦ Πομπηίου μετέστησεν, ἔπειτα δὲ δήμαρχον εὐθὺς ἀποδειχθῆναι διεπράξατο. οὗτος οὖν ὁ Κλώδιος ἐπεστόμισε μὲν καὶ τὸν Βίβουλον ἐσελθόντα τε ἐς τὴν ἀγορὰν ἐπ’ ἐξόδῳ τῆς ἀρχῆς, καὶ διανοούμενον μετὰ τῆς τοῦ ὅρκου πιστώσεως καὶ περὶ τῶν παρόντων δημηγορῆσαι, ἐπέθετο δὲ καὶ τῷ Κικέρωνι. καὶ ἐπειδὴ μὴ ἐδόκει οἱ ῥᾴδιον εἶναι ἄνδρα πάμπολυ ἐν τῇ πολιτείᾳ διὰ τὴν τῶν λόγων δεινότητα δυνάμενον καταλῦσαι, τρέπεται πρὸς οἰκείωσιν οὐχ ὅτι τοῦ πλήθους, ἀλλὰ καὶ τῶν ἱππέων τῆς τε βουλῆς, παρ’ οἷσπέρ που καὶ ὁ Κικέρων πλεῖστος ἐφέρετο, ἐλπίσας, ἂν τούτους σφετερίσηται, ῥᾳδίως αὐτόν, ἅτε καὶ διὰ φόβον μᾶλλον ἢ δι’ εὔνοιαν ἰσχύοντα, καθαιρήσειν. παμπληθεῖς γὰρ ἐκ τῶν λόγων ἐλύπει, καὶ οὐκ ἐς τοσοῦτον οἵ τι ὠφελούμενοι ὑπ’ αὐτοῦ ᾠκειοῦντο ἐς ὅσον οἱ βλαπτόμενοι ἠλλοτριοῦντο. πρὸς γάρ τοι τῷ τοὺς πλείους τῶν ἀνθρώπων προχειρότερον ἐπὶ τοῖς δυσχερεστέροις ἀγανακτεῖν ἢ τῶν ἀμεινόνων χάριν τισὶν ἔχειν, καὶ τοῖς μὲν συναγορεύσασί σφισιν ἀποδεδωκέναι τὸν μισθὸν νομίζειν, τοὺς δ’ ἀντιδικήσαντας ἀμύνεσθαι τρόπον τινὰ προαιρεῖσθαι, πικροτάτους ἐχθροὺς ἑαυτῷ ἐποίει περιεῖναί τε καὶ τῶν κρατίστων ἀεί ποτε ἐπιχειρῶν καὶ τῇ παρρησίᾳ πρὸς πάντας ὁμοίως ἀκράτῳ καὶ κατακορεῖ χρώμενος, ἅτε καὶ τὴν δόξαν τοῦ δύνασθαι συνεῖναί τε καὶ εἰπεῖν ἃ μηδεὶς ἄλλος, καὶ πρὸ τοῦ χρηστὸς εἶναι δοκεῖν, θηρώμενος. ἔκ τε οὖν τούτου, καὶ διότι μέγιστόν τε ἀνθρώπων ηὔχει καὶ οὐδένα ἐξ ἴσου ἑαυτῷ ἦγεν, ἀλλὰ ἔν τε τοῖς λόγοις ὁμοίως καὶ ἐν τῷ βίῳ πάντας τε ὑπερεφρόνει καὶ ἰσοδίαιτος οὐδενὶ ἠξίου εἶναι, φορτικός τε καὶ ἐπαχθὴς ἦν, καὶ ἀπὸ τούτων καὶ ὑπ’ αὐτῶν ἐκείνων οἷς ἤρεσκε, καὶ ἐφθονεῖτο καὶ ἐμισεῖτο.", "st": "38.12"}, {"sp": "N", "t": "ὁ οὖν Κλώδιος ἐλπίσας αὐτὸν διὰ ταῦτα, ἂν τήν τε βουλὴν καὶ τοὺς ἱππέας τόν τε ὅμιλον προπαρασκευάσηται, ταχὺ κατεργάσεσθαι, τόν τε σῖτον προῖκα εὐθὺς διένειμε (τὸ γὰρ μετρεῖσθαι τοῖς ἀπόροις, τοῦ τε Γαβινίου ἤδη καὶ τοῦ Πίσωνος ὑπατευόντων, ἐσηγήσατο) καὶ τὰ ἑταιρικά, κολλήγια ἐπιχωρίως καλούμενα, ὄντα μὲν ἐκ τοῦ ἀρχαίου, καταλυθέντα δὲ χρόνον τινά, ἀνενεώσατο· τοῖς τε τιμηταῖς ἀπηγόρευσε μήτ’ ἀπαλείφειν ἔκ τινος τέλους μήτ’ ἀτιμάζειν μηδένα, χωρὶς ἢ εἴ τις παρ’ ἀμφοτέροις σφίσι κριθεὶς ἁλοίη. τούτοις οὖν αὐτοὺς δελεάσας καὶ ἕτερόν τινα νόμον ἔγραψε, περὶ οὗ διὰ πλειόνων ἀναγκαῖόν ἐστιν εἰπεῖν, ὅπως σαφέστερος τοῖς πολλοῖς γένηται. τῆς γὰρ μαντείας τῆς δημοσίας ἔκ τε τοῦ οὐρανοῦ καὶ ἐξ ἄλλων τινῶν, ὥσπερ εἶπον, ποιουμένης, τὸ μέγιστον κῦρος ἡ ἐκ τοῦ οὐρανοῦ εἶχεν, οὕτως ὥστε τὰ μὲν ἄλλα οἰωνίσματα πολλὰ καὶ καθ’ ἑκάστην πρᾶξιν, ἐκεῖνο δὲ ἐσάπαξ ἐπὶ πάσῃ τῇ ἡμέρᾳ γίγνεσθαι. τοῦτό τε οὖν ἰδιώτατον ἐν αὐτῷ ἦν, καὶ ὅτι ἐπὶ μὲν τῶν ἄλλων ἁπάντων ἢ ἐπέτρεπε πραχθῆναί τινα, καὶ ἐγίγνετο μηδενὸς ἔτι καθ’ ἕκαστον οἰωνίσματος ἐπαγομένου, ἢ ἐκώλυε, καὶ ἀνεχειρίζετό τι, τὰς δὲ δὴ τοῦ δήμου διαψηφίσεις πάντως ἐπῖσχεν, καὶ ἦν πρὸς αὐτὰς ἀεὶ διοσημία, εἴτε ἐναίσιον εἴτε ἐξαίσιον ἐγένετο. καὶ τὸ μὲν αἴτιον τῆς νομίσεως ταύτης οὐκ ἔχω φράσαι, γράφω δὲ τὰ λεγόμενα. ἐπεὶ οὖν πολλοὶ ἐμποδίζειν ἢ νόμων ἐσφορὰς ἢ ἀρχόντων καταστάσεις ἐς τὸν δῆμον ἐσαγομένας βουλόμενοι προεπήγγελλον ὡς καὶ ἐκ τοῦ οὐρανοῦ τὴν ἡμέραν ἐκείνην μαντευσόμενοι, ὥστε μηδεμίαν ἐν αὐτῇ κύρωσιν τὸν δῆμον σχεῖν, φοβηθεὶς ὁ Κλώδιος μὴ γραψαμένου αὐτοῦ τὸν Κικέρωνα ἀναβολήν τέ τινες ἐκ τοῦ τοιούτου καὶ τριβὴν τῇ δίκῃ ἐμποιήσωσιν, ἐσήνεγκε μηδένα τῶν ἀρχόντων ἐν ταῖς ἡμέραις ἐν αἷς ψηφίσασθαί τι τὸν δῆμον ἀναγκαῖον εἴη, τὰ ἐκ τοῦ οὐρανοῦ γιγνόμενα παρατηρεῖν.", "st": "38.13"}, {"sp": "N", "t": "τοιαῦτα μὲν τότε ἐπὶ τὸν Κικέρωνα συνέγραψε. καὶ ἐπειδὴ ἐκεῖνος, συνεὶς τὸ γιγνόμενον, Λούκιον Νίννιον Κουαδρᾶτον δημαρχοῦντα ἐναντιωθῆναι πᾶσί σφισιν ἀντιπαρεσκεύασεν, ἔδεισε μὴ καὶ θόρυβος ἐκ τούτου καὶ διατριβή τις γένηται, καὶ ὑπῆλθεν αὐτὸν ἀπατήσας. προδιομολογησάμενος γὰρ αὐτῷ μηδ’ ὁτιοῦν, ἂν μηδὲν τῶν νομοθετουμένων ἐμποδίσῃ, κατ’ αὐτοῦ γράψειν, ἔπειτα τὴν ἡσυχίαν καὶ ἐκείνου καὶ τοῦ Νιννίου ἄγοντος διενομοθέτησεν αὐτά, καὶ μετὰ τοῦτο καὶ τῷ Κικέρωνι ἐπεχείρησεν. καὶ ὁ μὲν οὕτω, καίτοι φρονιμώτατος ἀξιῶν εἶναι, τότε ὑπὸ τοῦ Κλωδίου, εἴ γε ἐκεῖνον ἀλλὰ μὴ τὸν Καίσαρα τούς τε ἄλλους τοὺς μετ’ αὐτῶν συνεστηκότας δεῖ λέγειν, ἠπατήθη· ὁ δὲ δὴ νόμος ὃν μετὰ ταῦτα ὁ Κλώδιος ἐσήνεγκεν, ἄλλως μὲν οὐκ ἐδόκει ἐπ’ αὐτῷ τίθεσθαι (οὐδὲ γὰρ τὸ ὄνομα αὐτοῦ εἶχεν ἀλλὰ κατὰ πάντων ἁπλῶς τῶν πολίτην τινὰ ἄνευ τῆς τοῦ δήμου καταγνώσεως ἀποκτενούντων ἢ καὶ ἀπεκτονότων ἐσήγετο), ἔργῳ δὲ ἐπ’ αὐτὸν ὅτι μάλιστα συνεγράφετο. ἔφερε μὲν γὰρ καὶ ἐπὶ πᾶσαν τὴν βουλήν, ὅτι τοῖς τε ὑπάτοις τὴν φυλακὴν τῆς πόλεως, δι’ ἧσπερ καὶ τὰ τοιαῦτά σφισι ποιεῖν ἐξὸν ἐγίγνετο, προσετετάχει, καὶ μετὰ τοῦτο καὶ τοῦ Λεντούλου καὶ τῶν ἄλλων τῶν τότε θανατωθέντων κατεψήφιστο· οὐ μέντοι ἀλλ’ ὁ Κικέρων, ἐπειδὴ καὶ ἐσηγγέλκει περὶ αὐτῶν καὶ ἐσήγητο ἀεὶ καὶ ἐπεψηφίκει καὶ τέλος καὶ τὴν τιμωρίαν σφῶν διά γε τῶν τὰ τοιαῦτα ὑπηρετούντων ἐπεποίητο, καὶ τὴν αἰτίαν μόνος ἢ καὶ μάλιστα ἔσχε. καὶ διὰ τοῦτο τά τε ἄλλα ἰσχυρῶς αὐτῷ ἀντέπρασσε, καὶ τὴν βουλευτικὴν ἐσθῆτα ἀπορρίψας ἐν τῇ ἱππάδι περιενόστει, πάντας τε τούς τι δυναμένους, οὐχ ὅπως τῶν ἐπιτηδείων ἀλλὰ καὶ τῶν ἀντιστασιωτῶν, καὶ μάλιστα τόν τε Πομπήιον καὶ τὸν Καίσαρα ἅτε μηδὲ τὴν ἔχθραν αὐτοῦ προσποιούμενον, καὶ ἡμέρας καὶ νυκτὸς ὁμοίως περιιὼν ἐθεράπευε.", "st": "38.14"}, {"sp": "N", "t": "καὶ ἐβούλοντο γὰρ καὶ ἐκεῖνοι μήτε τὸν Κλώδιον αὐτοὶ παρεσκευακέναι μήτε τοῖς γεγραμμένοις ὑπ’ αὐτοῦ ἀρέσκεσθαι δοκεῖν, τοιάνδε τινὰ ἐπὶ τὸν Κικέρωνα ἀπάτην, σφίσι μὲν εὐπρεπῆ ἐκείνῳ δὲ δὴ ἀφανῆ, προσεξεῦρον. ὁ μὲν γὰρ Καῖσαρ ὑπείκειν αὐτῷ συνεβούλευε, μὴ καὶ κατὰ χώραν μείνας ἀπόληται· καὶ ἵνα γε καὶ μᾶλλον ὑπ’ εὐνοίας τοῦτο ποιεῖν πιστευθῇ, ὑποστρατήγῳ οἱ χρήσεσθαι ὑπισχνεῖτο, ὅπως μὴ μετ’ ὀνείδους ὡς καὶ ὑπεύθυνος ὤν, ἀλλὰ ἐπί τε ἀρχῆς καὶ μετὰ τιμῆς ἐκποδὼν δὴ τῷ Κλωδίῳ γένηται. ὁ δὲ δὴ Πομπήιος τούτου μὲν αὐτόν, τό τε πρᾶγμα ἀπόδρασιν ἄντικρυς ὀνομάζων, καὶ ἐς τὸν Καίσαρα ὥστε καὶ κατ’ ἔχθραν οὐκ ἐπιτηδείως οἱ συμβουλεύοντα ὑποσημαίνων, ἀπέτρεπε, γνώμην δὲ ἐδίδου καταμεῖναι καὶ ἑαυτῷ τε ἅμα καὶ τῇ βουλῇ μετὰ παρρησίας βοηθῆσαι, τόν τε Κλώδιον εὐθὺς ἀμύνασθαι· οὔτε γὰρ διαπράξασθαί τι αὐτὸν παρόντος τε ἐκείνου καὶ ἐναντιουμένου δυνήσεσθαι ἔλεγε, καὶ προσέτι καὶ δίκην δώσειν καὶ ἑαυτοῦ τι πρὸς τοῦτο συμπράξαντος. τοιούτους αὐτῶν λόγους λεγόντων οὐχ ὅτι ἐναντία ἀλλήλοις ἐγίγνωσκον ἀλλ’ ἵν’ ἐκεῖνον ἀνυπόπτως ἀπατήσωσι, τῷ Πομπηίῳ προσέθετο. οὔτε γὰρ προϋπώπτευέ τι ἐς αὐτόν, καὶ ἐπίστευε πάντως ὑπ’ αὐτοῦ σωθήσεσθαι. τῶν τε γὰρ ἄλλων πολλοὶ καὶ ᾐδοῦντο αὐτὸν καὶ ἐτίμων ὥστε καὶ κινδυνεύοντας συχνοὺς τοὺς μὲν παρὰ τῶν δικαστῶν τοὺς δὲ καὶ παρ’ αὐτῶν τῶν κατηγόρων ῥυόμενον· καὶ ὁ Κλώδιος, ἅτε καὶ ἐν γένει ποτὲ αὐτῷ γενόμενος καὶ συστρατεύσας ἐπὶ πολὺν χρόνον, οὐδὲν ὅ τι οὐ κατὰ γνώμην αὐτοῦ ἐδόκει ποιήσειν. τόν τε Γαβίνιον ἄντικρυς, ἅτε καὶ πάνυ φίλον αὐτῷ ὄντα, καὶ τὸν Πίσωνα ἀπό τε τῆς ἐπιεικείας καὶ διὰ τὴν τοῦ Καίσαρος συγγένειαν ὑπάρξειν οἱ προσεδόκησε.", "st": "38.15"}, {"sp": "N", "t": "τούτοις τε οὖν τοῖς λογισμοῖς κρατήσειν ἐλπίσας (καὶ γὰρ ἐθάρσει παρὰ λόγον ὥσπερ ἀνεξετάστως ἐδεδίει), καὶ φοβηθεὶς μὴ καὶ ἐκ πονηροῦ συνειδότος τὴν ἀποδημίαν πεποιῆσθαι δόξῃ, τῷ μὲν Καίσαρι χάριν δή τινα ἔχειν ἔλεγε, τῷ δὲ δὴ Πομπηίῳ ἐπείσθη. καὶ ὁ μὲν οὕτως ἀπατηθεὶς παρεσκευάζετο ὡς καὶ πολὺ τῶν ἐχθρῶν ὑπεροίσων. πρὸς γὰρ δὴ τοῖς εἰρημένοις, οἵ τε ἱππῆς συνελθόντες ἐς τὸ Καπιτώλιον πρέσβεις ὑπὲρ αὐτοῦ πρός τε τοὺς ὑπάτους καὶ τὴν γερουσίαν, ἄλλους τέ τινας ἐκ σφῶν καὶ βουλευτὰς τόν τε Ὁρτήσιον τὸν Κύιντον καὶ Γάιον Κουρίωνα, ἔπεμψαν· καὶ ὁ Νίννιος τά τε ἄλλα αὐτῷ συνῄρετο, καὶ τὴν ἐσθῆτα τῷ πλήθει ὡς καὶ ἐπί τινι κοινῇ συμφορᾷ μεταβαλεῖν παρῄνεσε. καὶ πολλοὶ τοῦτο καὶ τῶν βουλευτῶν ἐποίησαν, καὶ οὐ πρότερόν γε μετεβάλοντο πρὶν τοὺς ὑπάτους σφίσι διὰ προγραφῆς ἐπιτιμῆσαι. Ἀλλ’ ἦν γὰρ τὰ τῶν ἀντιστασιωτῶν αὐτοῦ δυνατώτερα, οὔτε ὁ Κλώδιος χρηματίσασθαί τι ὑπὲρ αὐτοῦ τῷ Νιννίῳ ἐπέτρεψεν, οὔτε Γαβίνιος τὴν πρόσοδον τοῖς ἱππεῦσιν ἐς τὴν βουλὴν ἔδωκεν, ἀλλὰ καὶ ἕνα τινὰ αὐτῶν, ὡς πολὺς ἐνέκειτο, καὶ ἐκ τῆς πόλεως ἐξήλασε, τῷ τε Ὁρτησίῳ καὶ τῷ Κουρίωνι, ὅτι καὶ ἀθροισθεῖσί σφισι συνεγένοντο καὶ τὴν πρεσβείαν ὑπέστησαν, ἐπεκάλει. καὶ αὐτοὺς ὁ Κλώδιος ἐς τὸ πλῆθος ἐσαγαγὼν πληγαῖς ἐπὶ τῇ πρεσβείᾳ διά τινων προπαρεσκευασμένων συνέκοψε. καὶ μετὰ ταῦτα ὅ τε Πίσων, καίπερ εὐνοϊκῶς τῷ Κικέρωνι δοκῶν ἔχειν, καὶ συμβουλεύσας γε αὐτῷ, ὡς ἑώρα ἀδύνατον ὂν ἄλλως αὐτὸν σωθῆναι, προϋπεξέχειν, ὅμως ἐπειδὴ διὰ τοῦτο ἐκεῖνος ὠργίσθη, παρῆλθεν ἐς τὴν ἐκκλησίαν ὅτε πρῶτον ἠδυνήθη (τὰ γὰρ πολλὰ ἠρρώστει), καὶ πυθομένου τοῦ Κλωδίου τίνα γνώμην περὶ τῶν γεγραμμένων ἔχοι, εἶπεν ὅτι οὐδέν μοι οὔτ’ ὠμὸν οὔτε σκυθρωπὸν ἔργον ἀρέσκει· καὶ ὁ Γαβίνιος ἐρωτηθεὶς τὸ αὐτὸ τοῦτο οὐχ ὅπως ἐκεῖνον ἐπῄνεσεν, ἀλλὰ καὶ τῶν ἱππέων τῆς τε βουλῆς προσκατηγόρησεν.", "st": "38.16"}, {"sp": "N", "t": "ὁ μέντοι Καῖσαρ (ἔξω γὰρ τοῦ τείχους ὁ Κλώδιος δι’ αὐτόν, ἐπειδήπερ ἐξεστράτευτο, τὸν ὅμιλον συναγαγὼν καὶ ἐκεῖνον ἐπιγνώμονα τῶν γεγραμμένων ἐποιήσατο) τὴν μὲν παρανομίαν τῶν περὶ τὸν Λέντουλον πραχθέντων κατεψηφίσατο, τὴν μέντοι τιμωρίαν τὴν ἐπ’ αὐτοῖς γραφομένην οὐκ ἐδοκίμασεν· ὅσα μὲν γὰρ περὶ τῶν τότε γενομένων ἐφρόνησε, πάντας εἰδέναι ἔφη (τὴν γὰρ σώζουσάν σφας ψῆφον δεδωκὼς ἦν), οὐ μὴν καὶ προσήκειν ἐπὶ τοῖς παρεληλυθόσι τοιοῦτόν τινα νόμον συγγράφεσθαι. Καῖσαρ μὲν ταῦτ’ εἶπε, Κράσσος δὲ διὰ μὲν τοῦ υἱέος βοήθειάν τινα τῷ Κικέρωνι ἐνεδείκνυτο, αὐτὸς δὲ τὰ τοῦ πλήθους ἔπρασσε. καὶ ὁ Πομπήιος ὑπισχνεῖτο μὲν αὐτῷ τὴν ἐπικουρίαν, σκήψεις δέ τινας ἄλλοτε ἄλλας ποιούμενος καὶ ἀποδημίας συχνὰς ἐπίτηδες στελλόμενος οὐκ ἐπήμυνε. ἰδὼν οὖν ταῦθ’ ὁ Κικέρων καὶ φοβηθεὶς αὖθις ἐπεχείρησε μὲν ὅπλα ἄρασθαι (τά τε γὰρ ἄλλα καὶ τὸν Πομπήιον φανερῶς προεπηλάκιζε), κωλυθεὶς δὲ ὑπό τε τοῦ Κάτωνος καὶ τοῦ Ὁρτησίου, μὴ καὶ ἐμφύλιος ἐκ τούτου πόλεμος γένηται, τότε δὴ καὶ ἄκων μετά τε αἰσχύνης καὶ μετὰ κακοδοξίας, ὡς καὶ ἐκ τοῦ συνειδότος ἐθελοντὴς πεφευγώς, μετέστη. πρὶν δὲ δὴ ἀφορμῆσαι, ἔς τε τὸ Καπιτώλιον ἀνέβη καὶ ἀγαλμάτιόν τι Ἀθηνᾶς ἀνέθηκε, Φυλακίδα αὐτὴν ὀνομάσας. ὑπεξῆλθε δὲ ἐς Σικελίαν· προστάτης τε γὰρ αὐτῶν ἐγεγόνει, καὶ ἐλπίδα πολλὴν ἔν τε τοῖς δήμοις καὶ ἐν τοῖς ἰδιώταις τῷ τε ἄρχοντι αὐτῶν εἶχε τιμηθήσεσθαι. φυγόντος δ’ αὐτοῦ ὁ νόμος τὸ κῦρος, οὐχ ὅπως οὐκ ἐναντιωθέντος τινός, ἀλλὰ καὶ σπουδασάντων ἄλλων τε καὶ αὐτῶν ἐκείνων οἵπερ τὰ τοῦ Κικέρωνος ἀνὰ πρώτους πράττειν ἐδόκουν, ἐπειδήπερ ἅπαξ ἐκποδὼν ἐγεγόνει, ἔλαβε· καὶ ἥ τε οὐσία αὐτοῦ ἐδημεύθη, καὶ ἡ οἰκία ὥσπερ τινὸς πολεμίου κατεσκάφη, τό τε ἔδαφος αὐτῆς ἐς νεὼν ἐλευθερίας ἀνέθηκαν. αὐτῷ τε ἐκείνῳ ἥ τε φυγὴ ἐπετιμήθη καὶ ἡ ἐν τῇ Σικελίᾳ διατριβὴ ἀπερρήθη· τρισχιλίους τε γὰρ καὶ ἑπτακοσίους καὶ πεντήκοντα σταδίους ὑπὲρ τὴν Ῥώμην ὑπερωρίσθη, καὶ προσεπεκηρύχθη ἵν’ εἰ δή ποτε ἐντὸς αὐτῶν φανείη, καὶ αὐτὸς καὶ οἱ ὑποδεξάμενοι αὐτὸν ἀνατὶ διόλωνται.", "st": "38.17"}, {"sp": "N", "t": "καὶ ὁ μὲν ἐς τὴν Μακεδονίαν διὰ τοῦτο μετέστη καὶ ἐκεῖ διέτριβεν ὀδυρόμενος· ἐντυχὼν δ’ αὐτῷ Φιλίσκος τις ἀνὴρ ἔν τε ταῖς Ἀθήναις συγγεγονώς οἱ καὶ τότε κατὰ τύχην συντυχών, “οὐκ αἰσχύνῃ,” ἔφη, “ὦ Κικέρων, θρηνῶν καὶ γυναικείως διακείμενος; ὡς ἔγωγε οὔποτ’ ἄν σε προσεδόκησα οὕτω μαλακισθήσεσθαι, πολλῆς μὲν παιδείας καὶ παντοδαπῆς μετεσχηκότα, πολλοῖς δὲ καὶ συνηγορηκότα.” καὶ ὃς ὑπολαβὼν εἶπεν, “ἀλλ’ οὐδέν τοι ὅμοιόν ἐστιν, ὦ Φιλίσκε, ὑπὲρ ἄλλων τέ τινα λέγειν καὶ ἑαυτῷ συμβουλεύειν. τὰ μὲν γὰρ ὑπὲρ τῶν ἀλλοτρίων λεγόμενα, ἀπὸ ὀρθῆς καὶ ἀδιαφθόρου τῆς γνώμης προϊόντα, καιρὸν ἐς τὰ μάλιστα λαμβάνει· ὅταν δὲ δὴ πάθημά τι τὴν ψυχὴν καταλάβῃ, θολοῦται καὶ σκοτοῦται καὶ οὐδὲν δύναται καίριον ἐννοῆσαι. ὅθεν που πάνυ καλῶς εἴρηται ὅτι ῥᾷον παραινέσαι ἑτέροις ἐστὶν ἢ αὐτὸν παθόντα καρτερῆσαι.” “λέγεις μέν τι,” ἔφη ὁ Φιλίσκος, “ἀνθρώπινον· οὐ μέντοι καὶ ἠξίουν σε, τοσαύτῃ μὲν φρονήσει κεχρημένον τοσαύτην δὲ σοφίαν ἠσκηκότα, μὴ οὐ προπαρεσκευάσθαι πρὸς πάντα τὰ ἀνθρώπινα, ἵν’ εἴ τι καὶ παράλογόν σοι προσπέσοι, μήτι γε καὶ ἄφρακτόν σε εὕροι. ἐπεὶ δ’ οὖν ἐν τούτῳ καθέστηκας, … καὶ γὰρ ἄν τι ὠφελήσαιμί σε διαλεξάμενός τι τῶν προσφόρων, ἵν’ ὥσπερ οἱ τὰ φορτία συναιρόμενοί τισιν ἐπικουφίζουσιν αὐτούς, καὶ ἐγώ σοι τὸ πάθος τοῦτο ἐπελαφρύναιμι, τοσούτῳ ῥᾷον ἐκείνων ὅσῳ μηδὲ τὸ βραχύτατον αὐτοῦ μεταλήψομαι. οὐ γάρ που καὶ ἀπαξιώσεις παραμυθίου τινὸς παρ’ ἑτέρου τυχεῖν. εἰ μὲν γὰρ αὐτάρκης ἑαυτῷ ἦσθα, οὐδὲν ἂν ἡμῖν τῶν λόγων τούτων ἔδει· νῦν δ’ ὅμοιον πέπονθας ὥσπερ εἰ Ἱπποκράτης ἢ Δημοκήδης ἢ καὶ ἄλλος τις τῶν πάνυ ἰατρῶν νοσήματι δυσιάτῳ περιπεσὼν ἀλλοτρίας χειρὸς πρὸς τὴν ἄκεσιν αὐτοῦ προσεδεήθη. ”", "st": "38.18"}, {"sp": "N", "t": "“Ἀλλ’ εἴ γέ τινα,” ἔφη ὁ Κικέρων, “τοιοῦτον ἔχεις λόγον ὥστε τὴν ἀχλύν μου ταύτην ἀπὸ τῆς ψυχῆς ἀφελεῖν καὶ ἐς τὸ ἀρχαῖόν με φῶς ἐπαναγαγεῖν, ἑτοιμότατός εἰμι ἀκούειν. ὥσπερ γὰρ τῶν φαρμάκων, οὕτω δὴ καὶ τῶν λόγων καὶ διαφοραὶ πολλαὶ καὶ δυνάμεις ποικίλαι εἰσίν, ὥστ’ οὐδὲν θαυμαστὸν εἰ καὶ ἐμὲ τὸν λαμπρὸν ἔν τε τῇ γερουσίᾳ καὶ ἐν ταῖς ἐκκλησίαις τοῖς τε δικαστηρίοις σοφίᾳ τινὶ καταιονήσειας.” “φέρε οὖν,” εἶπεν ὁ Φιλίσκος, “ἐπειδήπερ ἀκούειν ἕτοιμος εἶ, σκεψώμεθα πρῶτον μὲν εἰ κακὰ ὡς ἀληθῶς ἐστι ταῦτα τὰ περιεστηκότα σε, ἔπειτα δὲ τίνα τρόπον αὐτὰ ἀκεσόμεθα. ἐγὼ τοίνυν πρῶτον μὲν ἁπάντων ὁρῶ σε ὑγιαίνοντα τῷ σώματι καὶ εὖ μάλα ἐρρωμένον, ὅπερ που πρῶτον κατὰ φύσιν ἀγαθόν ἐστιν ἀνθρώποις, ἔπειτα δὲ τὰ ἐπιτήδεια αὐτάρκη κεκτημένον, ὥστε μήτε πεινῆν μήτε διψῆν ἢ ῥιγοῦν ἢ καὶ ἄλλο τι ἄτοπον ὑπ’ ἀπορίας ὑπομένειν, ὃ δὴ καὶ δεύτερον εἰκότως ἄν τις ἀγαθὸν ἀνθρώπῳ φύσει τιθείη. ὅταν γάρ τινι ἥ τε τοῦ σώματος σύστασις εὖ ἔχῃ καὶ διαρκεῖν ἀφροντιστῶν δύνηται, πάντα τὰ πρὸς εὐδαιμονίαν ἐπιβάλλοντα καρποῦται.”", "st": "38.19"}, {"sp": "N", "t": "ὁ οὖν Κικέρων ὑπολαβὼν ἔφη, “ἀλλ’ οὐδὲν τῶν τοιούτων ὄφελός ἐστιν, ὅταν του τὴν ψυχὴν λυπῇ τι καὶ δάκνῃ· πολλῷ γὰρ πλεῖον αἱ ἐκείνης φροντίδες ταλαιπωροῦσί τινα ἢ αἱ τοῦ σώματος εὐπάθειαι τέρπουσιν. ὥσπερ καὶ ἐγὼ νῦν οὐδὲν οὔτε τῆς τοῦ σώματος ὑγιείας προτιμῶ, νοσῶν γε τὴν γνώμην, οὔτε τῆς τῶν ἐπιτηδείων εὐπορίας· πολλῶν γὰρ ἀπεστέρημαι.” καὶ ὅς, “καὶ τοῦτό σε,” ἔφη, “λυπεῖ; εἰ μὲν γὰρ ἐνδεήσεσθαι τῶν ἀναγκαίων ἔμελλες, λόγον ἄν τινα εἶχεν ἄχθεσθαί σε τοῖς ἀπολωλόσιν· εἰ δὲ ἔκπλεα σοι πάντα τὰ ἐπιτήδεια ὑπάρχει, τί ἀνιᾷ ὅτι μὴ καὶ πλείω κέκτησαι; πᾶν γὰρ τὸ ὑπὲρ τὴν χρείαν τινὶ ὂν περιττόν ἐστι, καὶ ἐν τῷ ἴσῳ καὶ παρὸν καὶ ἀπὸν καθέστηκεν, ἐπεί τοι καὶ πρότερον οὐδὲν δήπου τοῖς μὴ ἀναγκαίοις ἐχρῶ, ὥστε καὶ τότε μὴ εἶναι ὧν μὴ ἔχρῃζες ἢ καὶ νῦν εἶναι ὧν μὴ δέῃ νόμιζε. καὶ γὰρ οὐδὲ πατρῷά σοι τὰ πολλὰ αὐτῶν γέγονεν, ὥστε σε σπουδὴν ἰδιωτέραν περὶ αὐτὰ ποιεῖσθαι, ἀλλὰ ὑπό τε τῆς γλώττης καὶ ὑπὸ τῶν λόγων σου πεπόρισται, δι’ οὓς καὶ ἀπόλωλεν. οὔκουν ἀγανακτεῖν προσήκει εἰ καθάπερ ἐκτήθη τινά, οὕτω καὶ ἀπεβλήθη. οὐδὲ γὰρ οὐδ’ οἱ ναύκληροι πάνυ χαλεπῶς φέρουσι πολλὰ ζημιούμενοι· λογίζεσθαι γάρ, οἶμαι, φρονίμως ἐπίστανται ὅτι ἡ θάλαττα ἡ διδοῦσά σφισιν αὐτὰ καὶ ἀφαιρεῖται.", "st": "38.20"}, {"sp": "N", "t": "καὶ περὶ μὲν τούτων ἱκανά· ἀποχρῆν τε γὰρ ἀνθρώπῳ πρὸς εὐδαιμονίαν τὸ τὰ ἀρκοῦντα κεκτῆσθαι καὶ μηδενὸς ὧν τὸ σῶμα χρῄζει προσδεῖσθαι νομίζω, καὶ πᾶν τὸ περιττὸν καὶ φροντίδας καὶ πράγματα καὶ φθόνους ἔχειν ἡγοῦμαι. ἐπειδὴ δὲ ἔφησθα ὅτι οὐδεμία ἀπόλαυσις τῶν τοῦ σώματος ἀγαθῶν ἐστιν, ἂν μὴ καὶ τὰ τῆς ψυχῆς προσυπάρχῃ τινί, ἔστι μὲν ἀληθὴς ὁ λόγος (ἀδύνατον γάρ, κακῶς αὐτῆς ἐχούσης, μὴ οὐ καὶ τοῦτ’ αὐτῇ συννοσεῖν), ἐγὼ μέντοι πολλῷ ῥᾷον οἴομαι εἶναι τῆς εὐεξίας τῆς γνώμης ἐπιμεληθῆναί τινι ἢ τῆς τοῦ σώματος. τοῦτο μὲν γάρ, ἅτε καὶ σάρκινον ὄν, πολλὰ μὲν ἄτοπα ἐν ἑαυτῷ ἔχει, πολλῆς δὲ ἐπικουρίας παρὰ τοῦ δαιμονίου δεῖται· ἐκείνη δὲ δή, οἷα θειοτέρας φύσεως οὖσα, καὶ ῥυθμίζεσθαι καὶ νουθετεῖσθαι ῥᾳδίως δύναται. οὐκοῦν κἀνταῦθα ἴδωμεν τί τέ σοι τῶν τῆς ψυχῆς ἀγαθῶν ἀπέστη, καὶ τί τῶν κακῶν προσγενόμενον οὐκ ἂν ἀποτριψαίμεθα.", "st": "38.21"}, {"sp": "N", "t": "ὁρῶ τοίνυν ἔγωγε πρῶτον μὲν φρονιμώτατόν σε ἀνθρώπων ὄντα· τεκμήριον δὲ ὅτι πλεῖστα μὲν καὶ τὴν βουλὴν καὶ τὸν δῆμον, ἐν οἷς συνεβούλευσάς τι αὐτοῖς, ἔπεισας, πλεῖστα δὲ καὶ τοὺς ἰδιώτας, ἐν οἷς συνηγόρησάς σφισιν, ὠφέλησας· ἔπειτα δὲ καὶ δικαιότατον· πανταχοῦ γοῦν ὑπέρ τε τῆς πατρίδος καὶ τῶν φίλων ἀνταγωνιζόμενος τοῖς ἐπιβουλεύουσιν αὐτοῖς ἐξήτασαι· καὶ αὐτά γε ταῦτα ἃ νῦν πέπονθας, οὐ δι’ ἄλλο τι συμβέβηκέ σοι ἢ ὅτι πάνθ’ ὑπὲρ τῶν νόμων καὶ τῆς πολιτείας καὶ λέγων καὶ πράττων διετέλεις. καὶ μὴν ὅτι καὶ σωφροσύνης ἐς τὰ πρῶτα ἀνήκεις, αὐτὸ τὸ ἐπιτήδευμά σου δηλοῖ· οὐ γὰρ οἷόν τ’ ἐστὶ δουλεύοντά τινα ταῖς τοῦ σώματος ἡδοναῖς ἐν μέσῳ τε ἀεὶ φαίνεσθαι καὶ ἐν τῇ ἀγορᾷ ἀναστρέφεσθαι, μαρτύρια τὰ ἡμερινὰ ἔργα τῶν νυκτερινῶν ποιούμενον. οὕτω δὲ δὴ τούτων ἐχόντων ἐγὼ μέν σε καὶ ἀνδρειότατον ᾤμην εἶναι, τοσαύτῃ μὲν ῥώμῃ διανοίας τοσαύτῃ δὲ καὶ ἰσχύι λόγων χρώμενον· σὺ δέ, ὡς ἔοικας, αὐτὸς ἑαυτοῦ ἐκπλαγεὶς ὅτι παρά τε τὴν ἐλπίδα καὶ παρὰ τὴν ἀξίαν ἔπταισας, παρῄρησαί τι τοῦ σφόδρα ἀνδρείου. ἀλλὰ τοῦτο μὲν εὐθὺς ἀπολήψῃ· τοιούτων δὲ τῶν κατὰ σὲ ὄντων, καὶ εὖ μὲν ἥκοντος τοῦ σώματος εὖ δὲ καὶ τῆς ψυχῆς, οὐχ ὁρῶ τί τὸ λυποῦν ἐστί σε.”", "st": "38.22"}, {"sp": "N", "t": "ταῦτα αὐτοῦ εἰπόντος ὁ Κικέρων ἔφη “οὐ δοκεῖ οὖν σοι μέγα κακὸν εἶναι ἀτιμία καὶ φυγή, καὶ τὸ μήτ’ οἴκοι διατρίβειν μήτε μετὰ τῶν φίλων εἶναι, ἀλλὰ ἐκ τῆς πατρίδος μεθ’ ὕβρεως ἐκπεπτωκότα ζῆν ἐν ἀλλοτρίᾳ γῇ καὶ ἀλᾶσθαι, φυγάδα προσαγορευόμενον, καὶ γέλωτα μὲν τοῖς ἐχθροῖς αἶσχος δὲ τοῖς οἰκείοις παρέχοντα;” “οὐδαμῇ ἔμοιγε” εἶπεν ὁ Φιλίσκος. “δύο γὰρ τούτων ὄντων ἐξ ὧν συνεστήκαμεν, ψυχῆς τε καὶ σώματος, καὶ ῥητῶν ἑκατέρῳ παρ’ αὐτῆς τῆς φύσεως καὶ ἀγαθῶν καὶ κακῶν δεδομένων, εἰ μέν τι περὶ ταῦθ’ ἁμαρτάνοιτο, καὶ βλαβερὸν ἂν εἰκότως καὶ αἰσχρὸν νομίζοιτο, εἰ δ’ ὀρθῶς ἔχοι, καὶ μᾶλλον ἂν ὠφέλιμον εἴη. ὃ καὶ σοὶ νῦν ὑπάρχει. τὰ γὰρ δὴ ἄλλ’ ἐκεῖνα, αἱ φυγαὶ καὶ αἱ ἀτιμίαι, καὶ εἰ δή τι τοιοῦτον ἕτερον, νόμῳ τε καὶ δοκήσει τινὶ καὶ αἰσχρὰ καὶ κακά ἐστι, καὶ οὐδὲν οὔτε τῷ σώματι οὔτε τῇ ψυχῇ λυμαίνεται. ποῖον μὲν γὰρ ἂν σῶμα εἰπεῖν ἔχοις νενοσηκὸς ἢ καὶ ἀπολωλός, ποίαν δὲ ψυχὴν ἀδικωτέραν ἢ καὶ ἀμαθεστέραν γεγονυῖαν ὑπ’ ἀτιμίας καὶ φυγῆς ἢ καὶ ἄλλου τινὸς τῶν τοιούτων; ἐγὼ μὲν γὰρ οὐχ ὁρῶ. τὸ δὲ αἴτιον ὅτι οὐδέν σφων φύσει κακόν ἐστιν, ὥσπερ οὐδ’ ἡ ἐπιτιμία οὐδ’ ἡ ἐν τῇ πατρίδι διατριβὴ φύσει χρηστή, ἀλλ’ ὁποῖά ποτ’ ἄν τις ἕκαστος ἡμῶν περὶ αὐτὰ δοξάσῃ, τοιαῦτα καὶ δοκεῖ εἶναι. αὐτίκα τὴν ἀτιμίαν οὐκ ἐπὶ τοῖς αὐτοῖς παντελῶς ἄνθρωποι νομίζουσιν, ἀλλ’ ἔστιν ἃ τῶν ἔργων ἐπαίτια παρὰ τισὶν ὄντα παρ ἄλλοις ἐπαινεῖται, καὶ ἕτερα πρὸς τινῶν τιμώμενα πρὸς ἑτέρων κολάζεται· εἰσὶ δὲ οἳ καὶ τὴν ἀρχὴν οὔτε τὸ ὄνομα οὔτε τὸ ἔργον αὐτῆς ἴσασι. καὶ πάνυ εἰκότως· ὅσα γὰρ μὴ προσάπτεται τῶν τῇ φύσει τοῦ ἀνθρώπου προσηκόντων, οὐδ’ ἀνήκειν ἐς αὐτὸν νομίζεται. ὥσπερ ἂν οὖν, εἰ κρίσις τις ἢ καὶ ψήφισμά τι ἐγένετο τὸν δεῖνα νοσεῖν ἢ τὸν δεῖνα αἰσχρὸν εἶναι, γελοιότατον ἂν δήπουθεν ἦν, οὕτω καὶ περὶ τῆς ἀτιμίας ἔχει.", "st": "38.23"}, {"sp": "N", "t": "τὸ δ’ αὐτὸ τοῦτο καὶ περὶ τὴν φυγὴν ἔγωγε ὁρῶ ὄν. ἀποδημία γάρ τις ἄτιμός ἐστιν, ὥστ’ εἴπερ αὐτὴ καθ’ αὑτὴν ἡ ἀτιμία μηδεμίαν κακίαν ἔχει, οὐδὲ τῇ φυγῇ δήπου προστρίψασθαί τι κακὸν δύναται, ἐπεὶ τήν γε ἄλλως συχνοὶ πλεῖστον ὅσον χρόνον οἱ μὲν ἄκοντες οἱ δὲ καὶ ἑκόντες ἀποδημοῦσι, καί τινες καὶ πάντα τὸν βίον καταναλίσκουσι περινοστοῦντες, ὥσπερ ἀεὶ πανταχόθεν ἐξελαυνόμενοι, καὶ οὐδὲν μέντοι παρὰ τοῦτο βλάπτεσθαι νομίζουσιν. οὐ μὴν οὐδὲ διαφέρει τι ἑκούσιόν τινα ἢ μὴ τοῦτο ποιεῖν· οὐδὲ γὰρ οὐδ’ ὁ ἄκων σωμασκῶν ἧττόν τι ἔρρωται τοῦ ἐθελοντὶ αὐτὸ δρῶντος, οὐδ’ ὁ ἄκων ναυτιλλόμενος ἥττω τινὰ ὠφελίαν τοῦ ἑτέρου κτᾶται. καὶ αὐτό γε τοῦτο τὸ ἀκούσιον οὐχ ὁρῶ δυνάμενον ἀνδρὶ φρονίμῳ συμβῆναι. ὥστ’ εἴπερ ἐν τούτῳ τὸ διάφορον τοῦ τε εὖ καὶ τοῦ κακῶς πράττειν ἐστὶν ὅτι τὰ μὲν ἐθελονταὶ ἑτοίμως τὰ δ’ ἄκοντες χαλεπῶς ποιοῦμεν, εὐθεράπευτον· ἐὰν γάρ τοι πάντα τὰ ἀναγκαῖα ἑκούσιοι ὑπομένωμεν καὶ πρὸς μηδὲν αὐτῶν ἡττώμεθα, συνανῄρηται πάντα κἀκεῖνα, ὅσα ἂν ἐν τῷ ἀκουσίῳ θῇ τις εἶναι. καὶ γάρ που καὶ ἀρχαῖος λόγος καὶ μάλα εὖ ἔχων ἐστὶν ὅτι δεῖ ἡμᾶς μὴ ὅσα ἂν βουλώμεθα ἀξιοῦν γίγνεσθαι, ἀλλ’ ὅσα ἂν ἔκ τινος ἀνάγκης γίγνηται βούλεσθαι. οὔτε γὰρ αὐθαίρετον τὸν τοῦ βίου τρόπον ἔχομεν οὔθ’ αὑτῶν ἐσμέν· ἀλλ’ ὅπως ἂν τῇ τύχῃ δόξῃ, καὶ ὁποῖος ἂν ἑκάστῳ ἡμῶν δαίμων ἐκπληρωτὴς τοῦ τεταγμένου δοθῇ, τοιοῦτον ἀνάγκη καὶ ἐκεῖνον ἡμᾶς ποιεῖσθαι.", "st": "38.24"}, {"sp": "N", "t": "ταῦτα μὲν δὴ τοιαῦτά ἐστιν, ἄν τ’ ἐθέλωμεν ἄν τε καὶ μή· εἰ δέ σε οὐχὶ ἡ ἀτιμία αὐτὴ οὐδ’ ἡ φυγὴ αὐτὴ λυπεῖ, ἀλλ’ ὅτι μὴ μόνον μηδὲν ἠδικηκὼς τὴν πατρίδα ἀλλὰ καὶ πολλὰ εὐηργετηκὼς ἠτίμωσαί τε καὶ ἐξελήλασαι, λόγισαι τοῦθ’, ὅτι ἐπειδήπερ ἅπαξ ἐπέπρωτό σοι τοιοῦτό τι παθεῖν, κάλλιστον δήπου καὶ ἄριστον συμβέβηκε τὸ μηδὲν ἀδικήσαντά σε ἐπηρεάσθαι. σὺ μὲν γὰρ πάντα τὰ καθήκοντα τοῖς πολίταις συνεβούλευσας καὶ ἔπραξας, οὐκ ἰδιωτεύων ἀλλ’ ὑπατεύων, οὐδ’ ἰδίᾳ τι πολυπραγμονῶν ἀλλὰ τοῖς τῆς βουλῆς δόγμασι πειθόμενος, οὐ κατὰ στάσιν ἀλλ’ ἐπὶ τῷ βελτίστῳ γενομένοις· ὁ δεῖνα δὲ καὶ ὁ δεῖνα ἐκ δυναστείας καὶ ἐπηρείας πάντα κατὰ σοῦ συνεσκευάσαντο, ὥστ’ ἐκείνοις μὲν καὶ ἄχθεσθαι καὶ λυπεῖσθαι ἐπὶ τῇ ἀδικίᾳ προσήκει, σοὶ δὲ δὴ ἀνδρείως φέρειν τὰ δόξαντα τῷ δαίμονι καὶ καλὸν καὶ ἀναγκαῖόν ἐστιν. οὐ γάρ που μᾶλλον ἂν ἐθελήσαις τῷ τε Κατιλίνᾳ συμπράξας καὶ τῷ Λεντούλῳ συνομόσας, καὶ πάντα μὲν τἀναντία τῶν συμφερόντων τῇ πατρίδι παραινέσας, μηδὲν δὲ τῶν προσταχθέντων σοι ὑπ’ αὐτῆς ποιήσας, οἴκοι μένειν ἀδικήσας ἢ κατορθώσας φυγεῖν. οὐκοῦν εἰ καὶ τῆς δόξης σοι μέλει, πολλῷ που αἱρετώτερόν ἐστι μηδὲν ἀδικήσαντά σε ἐκπεπτωκέναι ἢ κακουργήσαντά τι οἴκοι μεμενηκέναι· τά τε γὰρ ἄλλα καὶ ἡ αἰσχύνη τοῖς ἀδίκως ἐκβαλοῦσί τινα, ἀλλ’ οὐ τῷ κατ’ ἐπήρειαν ἐξελαθέντι προσγίγνεται.", "st": "38.25"}, {"sp": "N", "t": "καίτοι ἔγωγε ἀκούω τοῦθ’, ὅτι οὐκ ἄκων οὐδ’ ἁλοὺς μετέστης, ἀλλ’ ἐθελοντὴς ἐμίσησας τὸν μετ’ αὐτῶν βίον, ἅτε μήτε βελτίους σφᾶς ποιῆσαι δυνάμενος μήτε συναπολέσθαι σφίσιν ὑπομένων, καὶ ἔφυγες οὐ τὴν πατρίδα ἀλλὰ τοὺς ἐπιβουλεύοντας αὐτῇ. ὥστ’ ἐκεῖνοι μὲν καὶ ἄτιμοι καὶ ἐξόριστοι εἶεν ἄν, πάντα τἀγαθὰ ἐκ τῶν ψυχῶν ἐκβεβληκότες, σὺ δὲ ἐπίτιμος καὶ εὐδαίμων, μήτ’ ἀτόπως τινὶ δουλεύων καὶ πάντα τὰ προσήκοντα ἔχων, ἄν τε ἐν Σικελίᾳ ἄν τε ἐν Μακεδονίᾳ ἄν τε καὶ ἄλλοθί που τῆς οἰκουμένης ζῆν ἐθελήσῃς. οὐ γὰρ δήπου τὰ χωρία οὔτε εὐτυχίαν οὔτε κακοδαιμονίαν τινὰ δίδωσιν, ἀλλὰ καὶ αὐτὸς ἕκαστος αὑτῷ καὶ πατρίδα καὶ εὐδαιμονίαν ἀεὶ καὶ πανταχοῦ ποιεῖ. καὶ ταῦθ’ ὁ Κάμιλλος ἐννοήσας ἡδέως ἐν Ἀρδέᾳ κατῴκησε, ταῦθ’ ὁ Σκιπίων λογισάμενος ἀλύπως ἐν Λιτέρνῳ κατεβίω. τί γὰρ δεῖ τὸν Ἀριστείδην, τί δὲ τὸν Θεμιστοκλέα λέγειν, οὓς ἐνδοξοτέρους ἡ φυγὴ ἐποίησεν, τί τὸν Ἀννι … τί τὸν Σόλωνα, ὃς ἑκὼν ἔτη δέκα ἀπεξενώθη; μὴ οὖν μηδὲ σὺ μήτε χαλεπόν τι τῶν τοιούτων, ἃ μήτε τῇ τοῦ σώματος μήτε τῇ τῆς ψυχῆς ἡμῶν φύσει προσήκει, νόμιζε εἶναι, μήτ’ ἀγανάκτει τοῖς προσπεπτωκόσιν. οὐδὲ γὰρ οὐδ’ αἵρεσίς τις ἔστιν ἡμῖν τοῦ ζῆν ὅπως ἂν ἐθελήσωμεν, ὥσπερ εἶπον, ἀλλὰ ἀνάγκη πᾶσα ὑπομένειν ἡμᾶς τὰ δοκοῦντα τῷ δαιμονίῳ. τοῦτο δὲ ἂν μὲν ἐθελονταὶ ποιῶμεν, οὐ λυπησόμεθα, ἂν δὲ ἀκόντως, οὔτε ἐκφευξόμεθά τι τῶν πεπρωμένων, καὶ τὸ μέγιστον τῶν κακῶν προσεπικτησόμεθα, τὸ μάτην ἀνιᾶσθαι. τεκμήριον δὲ ὅτι οἱ μὲν καὶ τὰ ἀτοπώτατα εὐκόλως φέροντες ἐν οὐδενὶ δεινῷ καθεστηκέναι νομίζουσιν, οἱ δὲ καὶ τοῖς ἐλαφροτάτοις βαρυνόμενοι πάντα τὰ ἐξ ἀνθρώπων κακὰ ἔχειν ὑποπτεύουσι· καὶ ἕτεροι, οἱ μὲν καὶ τὰ ἀμείνω κακῶς οἱ δὲ καὶ τὰ χείρω καλῶς μεταχειριζόμενοι, τοιαῦτα καὶ τοῖς ἄλλοις ἑκάτερα δοκεῖν εἶναι ποιοῦσιν οἷα αὑτοῖς εἶναι παρασκευάζουσι.", "st": "38.26"}, {"sp": "N", "t": "καὶ σὺ οὖν ταῦτα λογιζόμενος μήτε τοῖς παροῦσιν ἄχθου, μήτ’, ἂν τοὺς ἐκβαλόντας σε εὐτυχοῦντας πυνθάνῃ, λυποῦ. κουφαὶ μὲν γὰρ καὶ ἐφήμεροι καὶ ἄλλως αἱ τῶν ἀνθρώπων εὐπραγίαι εἰσί, καὶ ὅσῳ ἂν μᾶλλόν τις ἀπ’ αὐτῶν ἐπαύξῃ, ῥᾷον ὥσπερ πνεῦμα πίπτει, μάλιστα δὲ ἐν ταῖς στάσεσιν. ἅτε γὰρ ἐν τεταραγμένοις καὶ ἀκαταστάτοις πράγμασι φερόμενοι μικρόν, μᾶλλον δὲ οὐδέν, τῶν χειμαζομένων διαφέρουσιν, ἀλλ’ ἄνω τε καὶ κάτω, τοτὲ μὲν δεῦρο τοτὲ δὲ ἐκεῖσε, ᾅττουσι· κἂν ἄρα τι καὶ τὸ βραχύτατον σφαλῶσι, παντελῶς βαπτίζονται. καὶ ἵνα γε μήτε τὸν Δροῦσον μήτε τὸν Σκιπίωνα μήτε τοὺς Γράκχους ἢ καὶ ἄλλους τινὰς εἴπω, μέμνησο μὲν ὅπως ὁ Κάμιλλος ὁ φυγὰς ἄμεινον τοῦ Καπιτωλίνου μετὰ ταῦτα ἀπήλλαξε, μέμνησο δὲ ὅσον Ἀριστείδης τοῦ Θεμιστοκλέους ὕστερον διήνεγκεν. ὥστε καὶ σὺ μάλιστα μὲν ἔλπιζε καὶ καταχθήσεσθαι (οὔτε γὰρ ἐξ ἀδικίας ἐξελήλασαι, καὶ ἐπιζητήσουσι μέν σε, ὡς πυνθάνομαι, καὶ αὐτοὶ οἱ ἐκβεβληκότες, ποθήσουσι δὲ πάντες)· ἂν δὲ δὴ καὶ ἐν τοῖς παροῦσιν ἐμμείνῃς, μήτι γε καὶ", "st": "38.27"}, {"sp": "N", "t": "ἀνιαθῇς παρὰ τοῦτο μηδέν. ἂν μὲν γάρ μοι πεισθῇς, καὶ πάνυ ἀγαπήσεις χωρίον τέ τι παραθαλασσίδιον ἔξω πάτου ἐκλεξάμενος, καὶ ἐν αὐτῷ γεωργῶν τε ἅμα καὶ συγγράφων τι, ὡς Ξενοφῶν, ὡς Θουκυδίδης. τό τε γὰρ εἶδος τοῦτο τῆς σοφίας διαρκέστατόν ἐστι καὶ παντὶ μὲν ἀνδρὶ πάσῃ δὲ πολιτείᾳ ἁρμοδιώτατον, καὶ ἡ φυγὴ φέρει τινὰ σχολὴν γονιμωτέραν. ὥστ’ εἴπερ ὄντως ἀθάνατος καθάπερ ἐκεῖνοι γενέσθαι ἐθέλεις, ζήλωσον αὐτούς. τά τε γὰρ ἐπιτήδεια ἀρκοῦντα ἔχεις καὶ οὔτ’ ἀξιώματός τινος προσδέῃ. εἰ γάρ τι καὶ ἐν τούτοις ἀγαθόν ἐστιν, ὑπάτευκας· καὶ πλέον οὐδὲν τοῖς καὶ δεύτερον καὶ τρίτον ἢ καὶ τέταρτον ἄρξασι, πλὴν γραμμάτων ἀριθμοῦ κενῶν, ὑπάρχει, ἃ μήτε ζῶντα μήτ’ ἀποθανόντα τινὰ ὠφελεῖ. οὔκουν ἂν ἕλοιο οὔτε Κορουῖνος οὔτε Μάριος ὁ ἑπτάκις ὑπατεύσας μᾶλλον ἢ Κικέρων εἶναι. οὔτ’ αὖ ἡγεμονίας τινὸς ἐπιθυμεῖς, ὅς γε καὶ τὴν δοθεῖσάν σοι ἐξέστης, καταφρονήσας μὲν τῶν ἀπ’ αὐτῆς κερδῶν, καταφρονήσας δὲ καὶ τῆς ὀλιγοχρονίου τε καὶ ὑπευθύνου πᾶσι τοῖς συκοφαντεῖν ἐθέλουσιν ἐξουσίας. καὶ ταῦτ’ εἶπον οὐχ ὅτι καὶ ἀναγκαῖόν τι αὐτῶν πρὸς εὐδαιμονίαν ἐστίν, ἀλλ’ ὅτι καὶ ἐν τοῖς πολιτικοῖς, ἐπείπερ ἐχρῆν, ἱκανῶς ἐξήτασαι, ἵνα καὶ ἐξ ἐκείνων τὸ διάφορον τῶν βίων μαθὼν τὰ μὲν ἕλῃ τὰ δὲ ἀπώσῃ καὶ τὰ μὲν διώξῃς τὰ δὲ φύγῃς. σμικρὸς γὰρ ὁ βίος ἡμῶν, καὶ δεῖ σε μὴ πάντα αὐτὸν ἄλλοις βιῶναι, ἀλλ’ ἤδη τι καὶ σεαυτῷ χαρίσασθαι. σκέψαι δὲ ὅσον ἥ τε ἡσυχία τῆς ταραχῆς καὶ ἡ εὔροια τῶν θορύβων ἥ τε ἐλευθερία τῆς δουλείας καὶ ἡ ἀσφάλεια τῶν κινδύνων διαφέρει, ἵν’ ἐπιθυμήσῃς ζῆσαι ὡς ἐγώ σοι παραινῶ. οὕτω μὲν γὰρ εὐδαιμονήσεις, καί σου μέγα ὄνομα καὶ τοῦτο ἀεὶ καὶ ζῶντος ἐπὶ τούτῳ καὶ", "st": "38.28"}, {"sp": "N", "t": "τελευτήσαντος ἔσται· ἂν δὲ δὴ τήν τε κάθοδον σπουδάσῃς καὶ τὴν ἐν τῇ πολιτείᾳ λαμπρότητα ζηλώσῃς, δυσχερὲς μὲν οὐδὲν εἰπεῖν βούλομαι, φοβοῦμαι δέ, ἔς τε τὰ πράγματα ἀποβλέπων καὶ τὴν σὴν παρρησίαν ἐννοῶν, τήν τε δύναμιν καὶ τὸ πλῆθος τῶν ἀντιστασιωτῶν σου θεωρῶν, μήποτέ τι καὶ αὖθις σφαλῇς. καὶ εἰ μὲν ἐν φυγῇ γένοιο, μεταγνώσῃ μόνον, εἰ δέ τι ἕτερον ἀνήκεστον πάθοις, οὐδὲ μετανοῆσαι δυνήσῃ. καίτοι πῶς μὲν οὐ δεινόν, πῶς δ’ οὐκ αἰσχρὸν ἀποτμηθῆναί τέ τινος τὴν κεφαλὴν καὶ ἐς τὴν ἀγορὰν τεθῆναι, κἂν οὕτω τύχῃ, καὶ ἄνδρα τινὰ αὐτῇ καὶ γυναῖκα ἐνυβρίσαι; καί με μὴ ὡς φαῦλά σοι οἰωνιζόμενον μισήσῃς, ἀλλ’ ὡς διοσημίαν τινὰ προδεικνύντα φύλαξαι. μηδέ σε ἐξαπατάτω τοῦθ’, ὅτι καὶ φίλους τινὰς τῶν δυνατῶν ἔχεις· οὐδὲν γάρ σε ὠφελήσουσιν οἱ δοκοῦντες φιλεῖν πρὸς τοὺς ἐχθρῶς διακειμένους, ὥσπερ που καὶ πεπείρασαι. οἱ γὰρ δυναστείας ἐρῶντες παρ’ οὐδὲν πάντα τἆλλα πρὸς τὸ τυχεῖν ὧν βούλονται τίθενται, ἀλλὰ καὶ τοὺς φιλτάτους καὶ τοὺς συγγενεστάτους πολλάκις ἀντὶ τῶν ἐχθίστων ἀντικαταλλάσσονται.”", "st": "38.29"}, {"sp": "N", "t": "καὶ Κικέρων μὲν ταῦτα ἀκούσας ῥᾴων πως ἐγένετο, οὐ μέντοι καὶ ἐπὶ πολὺ ἔφυγεν, ἀλλὰ καὶ ὑπ’ αὐτοῦ τοῦ Πομπηίου τοῦ μάλιστα αὐτὸν ἐκβαλόντος κατήχθη. αἴτιον δὲ ὅτι ὁ Κλώδιος τόν τε Τιγράνην τὸν νεώτερον, ἐν δεσμοῖς ἔτι καὶ τότε παρὰ Λουκίῳ Φλαουίῳ ὄντα, πεισθεὶς ὑπὸ χρημάτων ἐξήρπασε καὶ ἀφῆκε, καὶ τὸν Πομπήιον τόν τε Γαβίνιον ἀγανακτήσαντας ἐπὶ τούτῳ περιύβρισε, τοῖς τε ἀμφ’ αὐτοὺς οὖσι καὶ πληγὰς καὶ τραύματα ἔδωκε, καὶ τοῦ ὑπάτου τάς τε ῥάβδους συνέτριψε καὶ τὴν οὐσίαν καθιέρωσεν. ὀργισθεὶς γὰρ διὰ ταῦθ’ ὁ Πομπήιος, ἄλλως τε καὶ ὅτι τῇ ἐξουσίᾳ, ἣν αὐτὸς τοῖς δημάρχοις ἀπεδεδώκει, κατ’ αὐτοῦ ὁ Κλώδιος ἐκέχρητο, ἀνακαλέσασθαι τὸν Κικέρωνα ἠθέλησε, καὶ αὐτῷ τὴν κάθοδον εὐθὺς διὰ τοῦ Νιννίου πράττειν ἤρξατο. καὶ ὃς ἐσήνεγκε μὲν ἐς τὸ βουλευτήριον τὴν ὑπὲρ αὐτοῦ γνώμην, ἀπόντα τὸν Κλώδιον τηρήσας· ἀντιστάντος δέ οἱ ἑτέρου τινὸς δημάρχου, ἐκείνην τε ὡς καὶ τῷ πλήθει κοινώσων ἐξέθηκε, καὶ τῷ Κλωδίῳ πρὸς πάντα καθάπαξ ἠναντιοῦτο. κἀκ τούτου καὶ φιλονεικίαι καὶ τραύματα ἀπ’ αὐτῶν πολλὰ ἑκατέροις ἐγίγνετο. πρὶν δὲ ἢ ἐς τοῦτο ἀφικέσθαι, βουληθεὶς ὁ Κλώδιος τόν τε Κάτωνα ἐκποδών, ὅπως ῥᾷον ὅσα ἔπραττε κατορθώσῃ, ποιήσασθαι, καὶ τὸν Πτολεμαῖον τὸν τότε τὴν Κύπρον ἔχοντα ἀμύνασθαι ὅτι αὐτὸν παρὰ τῶν καταποντιστῶν οὐκ ἐλύσατο, τήν τε νῆσον ἐδήμοσίωσε καὶ πρὸς τὴν διοίκησιν αὐτῆς τὸν Κάτωνα καὶ μάλα ἄκοντα ἀπέστειλε.", "st": "38.30"}, {"sp": "N", "t": "ταῦτα μὲν ἐν τῇ πόλει ἐγίγνετο· Καῖσαρ δὲ εὗρε μὲν οὐδὲν ἐν τῇ Γαλατίᾳ πολέμιον, ἀλλὰ ἀκριβῶς πάντα ἡσύχαζεν, οὐ μέντοι καὶ ἐν εἰρήνῃ διεγένετο, ἀλλὰ αὐτομάτου τὸ πρῶτον πολέμου τινὸς αὐτῷ συμβάντος ἕτερος συνηνέχθη, ὥστ’ αὐτόν, ὅπερ ἐς τὰ μάλιστα ἐπεθύμει, πάντα … καὶ πολεμῆσαι καὶ κατορθῶσαι. Ἐλουήτιοι γὰρ πλήθει τε ἀκμάζοντες καὶ χώραν οὐκ αὐτάρκη τῇ πολυανθρωπίᾳ σφῶν ἔχοντες, μέρος μέν τι ἐκπέμψαι ἐς ἀποικίαν οὐκ ἠθέλησαν, μὴ καὶ διασπασθέντες εὐεπιβουλευτότεροι τοῖς λυπηθεῖσί ποτε ὑπ’ αὐτῶν γένωνται, πάντες δὲ δὴ ἀπαναστῆναι βουληθέντες, ὡς καὶ ἐς ἑτέραν τινὰ καὶ πλείω καὶ βελτίω χώραν μετοικισθησόμενοι, τάς τε κώμας καὶ τὰς πόλεις σφῶν ἁπάσας ἔκαυσαν ὥστε μηδένα μετάμελον τῆς ἀναστάσεως ποιήσασθαι. καί τινας καὶ ἑτέρους τῶν αὐτῶν δεομένους προσλαβόντες ἀπῆραν, Ὀρκετόριγός σφισιν ἡγουμένου, ἐν νῷ ἔχοντες τόν τε Ῥοδανὸν διαβῆναι καὶ πρὸς ταῖς Ἄλπεσί που κατοικισθῆναι. καὶ ἐπειδὴ ὁ Καῖσαρ τήν τε γέφυραν διέκοψε καὶ τἆλλα ὡς κωλύσων αὐτοὺς διαβῆναι ἡτοιμάζετο, ἔπεμψαν πρὸς αὐτὸν δίοδόν τε αἰτούμενοι καὶ προσυπισχνούμενοι μηδὲν τὴν τῶν Ῥωμαίων γῆν κακώσειν. καὶ ὅς, εἰ καὶ τὰ μάλιστα μήτε ἐπίστευεν αὐτοῖς μήτε προχωρῆσαί ποι ἐπιτρέψειν ἔμελλεν, ἀλλ’ ὅτι γε οὐδέπω καλῶς παρεσκεύαστο, βουλεύσεσθαί τε ὑπὲρ ὧν ἠξίουν μετὰ τῶν ὑποστρατήγων ἔφη καὶ τὴν ἀπόκρισιν ἐν ῥητῇ τινι ἡμέρᾳ δώσειν. καί τι καὶ ἐλπίδος, ὡς καὶ ἐπιτρέψων σφίσι τὴν δίοδον, ὑπετείνατο. κἀν τούτῳ τὰ ἐπικαιρότατα διετάφρευσε καὶ ἀπετείχισεν, ὥστ’ ἄπορον αὐτοῖς τὴν ὁδὸν γενέσθαι.", "st": "38.31"}, {"sp": "N", "t": "οἱ οὖν βάρβαροι χρόνον μέν τινα ἐπέσχον, ἔπειτ’ ἐπειδὴ μηδὲν ἤκουσαν κατὰ τὸ συγκείμενον, ἄραντες τὸ μὲν πρῶτον διὰ τῶν Ἀλλοβρίγων ἐπορεύοντο ᾗπερ ὥρμηντο, ἔπειτ’ ἐντυχόντες τοῖς κωλύμασιν ἐς Σηκουανοὺς ἀπετράποντο, καὶ διά τε τούτων καὶ διὰ τῶν Αἰδούων ἐθελοντί σφισι τὴν δίοδον, ἐφ’ ᾧ μηδὲν ἀδικηθῶσι, παρεχόντων διιόντες οὐκ ἐνέμειναν τοῖς ὡμολογημένοις, ἀλλὰ τὴν χώραν αὐτῶν ἐλεηλάτουν. πέμψαντες οὖν οἵ τε Σηκουανοὶ καὶ οἱ Αἴδουοι πρὸς τὸν Καίσαρα ἐπικουρίαν τε παρ’ αὐτοῦ ᾔτουν, καὶ ἐδέοντο μή σφας περιιδεῖν ἀπολομένους. καὶ ἔλεγον μὲν οὐδὲν ὅμοια οἷς ἔπραξαν, ἔτυχον δ’ οὖν ὅμως ὧν ἠξίουν· ὁ γὰρ Καῖσαρ φοβηθεὶς μὴ καὶ ἐπὶ τὴν Τόλοσαν οἱ Ἐλουήτιοι τράπωνται, εἵλετο μετ’ ἐκείνων αὐτοὺς ἀμύνασθαι μᾶλλον ἢ συμφρονήσασί σφισιν, ὅπερ εὔδηλον ἦν ἐσόμενον, πολεμῆσαι. προσπεσὼν οὖν διὰ ταῦτα τοῖς Ἐλουητίοις τὸν Ἄραριν διαβαίνουσι, τοὺς μὲν τελευταίους ἐπακολουθοῦντας ἐν αὐτῷ τῷ πόρῳ διέφθειρε, τοὺς δὲ προκεχωρηκότας ἐς τοσοῦτον ἐκ τοῦ αἰφνιδίου καὶ ἐκ τοῦ τάχους τῆς διώξεως καὶ ἐκ τῆς πύστεως τῶν ἀπολωλότων ἐξέπληξεν ὥστε ἐς ὁμολογίαν", "st": "38.32"}, {"sp": "N", "t": "ἐπὶ χώρᾳ τινὶ ἐθελῆσαι ἐλθεῖν. οὐ μέντοι καὶ συνέβησαν· ἐπειδὴ γὰρ ὁμήρους ᾐτήθησαν, ἠγανάκτησαν οὐχ ὅτι ἠπιστοῦντο, ἀλλ’ ὅτι ἀπηξίουν ὁμήρους τισὶ δοῦναι. καὶ τῶν μὲν σπονδῶν κατεφρόνησαν, προχωροῦντες δὲ αὖθις τήν τε ἵππον τοῦ Καίσαρος, ἀπό τε τοῦ πεζοῦ πολὺ προδραμοῦσαν καὶ τοὺς ὀπισθοφύλακας αὐτῶν παραλυποῦσαν, ὑποστάντες τῷ ἱππικῷ ἐνίκησαν, κἀκ τούτου αὐτοί τε φρόνημα λαβόντες καὶ ἐκεῖνον φυγεῖν διά τε τὴν ἐλάττωσιν, καὶ ὅτι σπανίσας τῶν ἐπιτηδείων πρὸς πόλιν τινὰ ἔξω τῆς ὁδοῦ οὖσαν ἐξετράπετο, νομίσαντες, τοῦ τε πρόσω ἀφεῖντο καὶ ἐπεδίωξαν αὐτόν. ἰδὼν οὖν τοῦτο ὁ Καῖσαρ, καὶ φοβηθεὶς τήν τε ὁρμὴν αὐτῶν καὶ τὸ πλῆθος, τῷ μὲν πεζῷ πρὸς μετέωρόν τι ὥρμησε, τοὺς δὲ ἱππέας προεβάλετο προκινδυνεῦσαί σφισιν, ἕως ἐν ἐπιτηδείῳ παρατάξῃ. τρεψαμένων τε αὖθις αὐτοὺς ἐκείνων, καὶ πρὸς αὐτὸ τὸ ὄρθιον θυμῷ φερομένων, ἐπικατέδραμέ σφισιν ἐξαίφνης, καὶ ἅτε συντεταγμένος σποράδας ἐξ ὑπερδεξίων οὐ χαλεπῶς ἀπεώσατο. τραπομένων δὲ τούτων, ἄλλοι τινὲς τῶν μὴ μαχομένων (ὑπό τε γὰρ τοῦ πλήθους καὶ ὑπὸ τῆς σπουδῆς οὐ πάντες ἅμα παρεγένοντο) προσέμιξαν ἐξαίφνης κατὰ νώτου τοῖς ἐπιδιώκουσί σφας, καὶ ἐθορύβησαν μὲν αὐτούς, πλεῖον δὲ οὐδὲν ἔσχον· ὁ γὰρ Καῖσαρ τοῖς ἱππεῦσι τοὺς φεύγοντας προστάξας αὐτὸς τῷ ὁπλιτικῷ πρὸς ἐκείνους ἐτράπετο, καὶ κρατήσας πρός τε τὰς ἁμάξας ἀμφοτέροις σφίσι συγκαταφυγοῦσιν ἐφέσπετο, κἀνταῦθα αὖθις ἰσχυρῶς ἐπ’ αὐτῶν ἀμυνομένους σφᾶς ἐνίκησε. παθόντες δὲ ταῦθ’ οἱ βάρβαροι δίχα διῃρέθησαν. οἱ μὲν γὰρ ὡμολόγησαν αὐτῷ καὶ ἔς τε τὴν οἰκείαν ὅθεν ἐξανέστησαν ἐπανῆλθον, κἀνταῦθα τὰς πόλεις ἀνορθώσαντες ᾤκησαν· οἱ δὲ οὐκ ἐθελήσαντες τὰ ὁπλα παραδοῦναι πρὸς τὸν Ῥῆνον, ὡς καὶ ἐς τὴν ἀρχαίαν σφῶν γῆν ἐπανελθεῖν δυνάμενοι, ὥρμησαν, καὶ αὐτοὺς οἱ σύμμαχοι τῶν Ῥωμαίων δι’ ὧν διῄεσαν ῥᾳδίως, ἅτε καὶ ὀλίγους καὶ νενικημένους, ἔφθειραν.", "st": "38.33"}, {"sp": "N", "t": "οὕτω μὲν δὴ τὸν πρῶτον πόλεμον ὁ Καῖσαρ ἐπολέμησεν, ἀρξάμενος δὲ ἐκεῖθεν οὐχ ἡσύχασεν, ἀλλ’ αὐτός τε τὸ ἑαυτοῦ βούλημα ἅμα ἀπεπλήρωσε καὶ τοῖς συμμάχοις ἐχαρίσατο. οἵ τε γὰρ Σηκουανοὶ καὶ οἱ Αἴδουοι τήν τε ἐπιθυμίαν αὐτοῦ ἰδόντες καὶ τὰ ἔργα ὁμολογοῦντα ταῖς ἐλπίσιν αἰσθόμενοι, ἐκείνῳ τε εὐεργεσίαν ἅμα καταθέσθαι καὶ τοὺς Κελτοὺς τοὺς ὁμοχώρους σφίσι τιμωρήσασθαι ἠθέλησαν· τὸν γὰρ Ῥῆνον πάλαι ποτὲ διαβάντες τῆς τε χώρας αὐτῶν τινα παρετέτμηντο καὶ αὐτοὺς ὑποτελεῖς ἐπεποίηντο, ὁμήρους σφῶν ἔχοντες. καὶ ἐτύγχανον γὰρ δεόμενοι ὧν ὠρέγετο, ῥᾳδίως αὐτὸν ἀνέπεισαν ἐπικουρῆσαί σφισιν. ἦρχε μὲν γὰρ Ἀριόουιστος τῶν Κελτῶν ἐκείνων, καὶ τήν τε κύρωσιν τῆς βασιλείας παρὰ τῶν Ῥωμαίων εἰλήφει, καὶ ἐς τοὺς φίλους τούς τε συμμάχους αὐτῶν ὑπ’ αὐτοῦ τοῦ Καίσαρος ὑπατεύοντος ἐσεγέγραπτο· πρὸς δὲ δὴ τὴν ἐκ τοῦ πολέμου δόξαν καὶ τὴν ἀπ’ αὐτῆς ἰσχὺν οὐδὲν τούτων ἐφρόντισε, πλὴν καθ’ ὅσον παρὰ τοῦ βαρβάρου πρόφασιν τῆς διαφορᾶς, μὴ καὶ προϋπάρχειν τι ἐς αὐτὸν νομισθῇ, λαβεῖν ἠθέλησε. καὶ διὰ τοῦτο μετεπέμψατο αὐτὸν ὡς καὶ διαλεχθῆναί τι αὐτῷ δεόμενος. ἐπειδή τε οὐχ ὑπήκουσεν, ἀλλὰ καὶ ἔφη ὅτι “εἴ τί μοι βούλεται Καῖσαρ εἰπεῖν, αὐτὸς πρὸς ἐμὲ ἐλθέτω· οὔτε γὰρ ἄλλως καταδεέστερος αὐτοῦ εἰμι, καὶ τὸν χρείαν τινὸς ἔχοντα αὐτὸν πρὸς ἐκεῖνον ἀφικνεῖσθαι δεῖ,” ὀργήν τε ὡς καὶ πάντας τοὺς Ῥωμαίους προπεπηλακικότος αὐτοῦ ἐν τούτῳ ἐποιήσατο, καὶ παραχρῆμα τούς τε ὁμήρους τῶν συμμάχων ἀπῄτησεν αὐτόν, καὶ προσαπηγόρευσεν αὐτῷ μήτε τῆς χώρας σφῶν ἐπιβαίνειν μήτ’ ἐπικουρίας οἴκοθεν ἐπάγεσθαι. ταῦτα δὲ ἔπραξεν οὐχ ὅτι καὶ καταπλήξειν αὐτόν, ἀλλ’ ὅτι ἐξοργιεῖν κἀκ τούτου πρόφασιν τοῦ πολέμου καὶ μεγάλην καὶ εὐπρεπῆ λήψεσθαι ἤλπισεν. ὅπερ ἐγένετο· ἀχθεσθεὶς γὰρ ὁ βάρβαρος τοῖς ἐπιτάγμασι πολλὰ καὶ δεινὰ ἀπεκρίνατο, ὥστε τὸν Καίσαρα λόγους μὲν μηκέτ’ αὐτῷ ἀντιπέμψαι, τὸν δὲ δὴ Οὐεσοντίωνα, τὴν τῶν Σηκουανῶν πόλιν, εὐθύς, καὶ πρὶν αἰσθέσθαι τινά, προκατασχεῖν.", "st": "38.34"}, {"sp": "N", "t": "κἀν τούτῳ οἱ στρατιῶται, ἀγγελίας ἐλθούσης ὅτι τε ὁ Ἀριόουιστος ἰσχυρῶς παρασκευάζεται, καὶ ὅτι καὶ ἕτεροι τῶν Κελτῶν πολλοὶ οἱ μὲν διαβεβήκασιν ἤδη τὸν Ῥῆνον ὡς ἐπὶ βοήθειαν αὐτοῦ, οἱ δὲ καὶ ἐπ’ αὐτῷ τῷ ποταμῷ συνειλέχαται ὅπως ἐξαίφνης σφίσιν ἐπίθωνται, δεινῶς ἠθύμησαν· τά τε γὰρ μεγέθη αὐτῶν καὶ τὸ πλῆθος τό τε θράσος καὶ τὰς ἀπ’ αὐτοῦ προχείρους ἀπειλὰς ἐκπλαγέντες οὕτω διετέθησαν ὡς μηδὲ πρὸς ἀνθρώπους τινὰς ἀλλὰ πρὸς θηρία ἄπορα καὶ ἄγρια προσοισόμενοι. καὶ ἐθρύλουν ὅτι πόλεμον οὔτε προσήκοντα οὔτε ἐψηφισμένον διὰ τὴν ἰδίαν τοῦ Καίσαρος φιλοτιμίαν ἀναιροῖντο, καὶ προσεπηπείλουν ἐγκαταλείψειν αὐτόν, ἂν μὴ μεταβάληται. μαθὼν οὖν ταῦτ’ ἐκεῖνος τῷ μὲν πλήθει τῶν στρατιωτῶν οὐδὲν διελέξατο (οὔτε γὰρ καλὸν ἐνόμιζεν εἶναι τοιαῦτα πρὸς πολλοὺς λέγειν, καὶ ταῦτ’ ἐς τοὺς πολεμίους μέλλοντα ἐκφοιτήσειν, καὶ ἔδεισε μή πως ἀπειθήσαντες θορυβήσωσι καὶ κακόν τι ἐξεργάσωνται), τοὺς δὲ δὴ ὑπάρχους καὶ τοὺς ὑπομείονας ἀθροίσας τοιάδε ἐν αὐτοῖς ἔλεξεν.", "st": "38.35"}, {"sp": "N", "t": "“οὐ τὸν αὐτόν, ὦ ἄνδρες φίλοι, τρόπον ἡγοῦμαι δεῖν ἡμᾶς περί τε τῶν ἰδίων καὶ περὶ τῶν κοινῶν βουλεύεσθαι. οὐδὲ γὰρ τὸν αὐτὸν ὁρῶ σκοπὸν ἰδίᾳ τε ἑκάστῳ καὶ δημοσίᾳ ἅπασιν ὄντα. ἡμῖν μὲν γὰρ τὰ ἐπιεικέστατα καὶ ἀσφαλέστατα, τῷ δὲ δήμῳ τὰ κράτιστα καὶ προαιρεῖσθαι καὶ πράττειν προσήκει. δεῖ μὲν γὰρ καὶ ἐν τοῖς ἰδίοις δραστηρίους εἶναι· τὸ γὰρ ἐπιεικὲς οὐκ ἐθέλει εἰ μὴ καὶ ἐκ τούτου σώζεσθαι· οὐ μὴν ἀλλὰ ἀνὴρ μὲν ὅστις ἀπραγμονέστατός ἐστι, καὶ ἀσφαλέστατος εἶναι δοκεῖ, πόλις δέ, ἄλλως τε καὶ ἀρχὴν ἔχουσα, τάχιστ’ ἂν ὑπὸ τοῦ τοιούτου καταλυθείη. ταῦτα γὰρ οὕτως οὐχ ὑπ’ ἀνθρώπων ταχθέντα ἀλλ’ ὑπ’ αὐτῆς τῆς φύσεως νομοθετηθέντα καὶ ἦν ἀεὶ καὶ ἔστι, καὶ ἔσται μέχριπερ ἂν καὶ τὸ θνητὸν γένος συνεστήκῃ. τούτων οὖν οὕτως ἐχόντων, οὐδ’ ὑμῶν οὐδένα χρὴ τὸ ἴδιον ἡδὺ καὶ ἀσφαλὲς ἐν τῷ παρόντι μᾶλλον ἢ τὸ τοῖς πᾶσι Ῥωμαίοις καὶ εὐπρεπὲς καὶ συμφέρον προσκοπεῖν. λογίζεσθε γὰρ τά τε ἄλλα ὅσα εἰκός ἐστι, καὶ μάλισθ’ ὅτι δεῦρο ἤλθομεν αὐτοί τε τοσοῦτοι καὶ τοιοῦτοι ἔκ τε τῆς βουλῆς καὶ ἐκ τῶν ἱππέων ὄντες, καὶ πλῆθος πολὺ στρατιωτῶν χρήματά τε ἄφθονα λαβόντες, οὐχ ἵνα ῥᾳθυμῶμεν, οὐδ’ ἵνα ἀμελῶμεν, ἀλλ’ ὅπως τά τε τῶν ὑπηκόων ὀρθῶς διοικήσωμεν καὶ τὰ τῶν ἐνσπόνδων ἀσφαλῶς διασώσωμεν, τούς τε ἀδικεῖν ἐπιχειροῦντάς σφας ἀμυνώμεθα, καὶ τὰ ἡμέτερα ἐπαυξήσωμεν. ὡς εἴ γε μὴ ταῦθ’ οὕτω φρονοῦντες ἤλθομεν, τί ποτε καὶ ἀρχὴν ἐξεστρατεύσαμεν, ἀλλ’ οὐ τρόπον γέ τινα οἴκοι καὶ ἐπὶ τοῖς ἰδίοις κατεμείναμεν; καὶ γάρ που καὶ ἄμεινον ἦν μηδ’ ὑποστῆναι τὴν στρατείαν ἢ προσταχθέντας αὐτὴν προδοῦναι. εἰ δ’ οἱ μὲν ὑπὸ τῶν νόμων ἀναγκαζόμενοι τὸ προσταττόμενον ὑπὸ τῆς πατρίδος πράττειν, οἱ δὲ δὴ πλείους ἐθελονταὶ διά τε τὰς τιμὰς καὶ διὰ τὰς ὠφελίας τὰς ἀπὸ τῶν πολέμων περιγιγνομένας πάρεσμεν, πῶς ἂν ἢ καλῶς ἢ ὁσίως ἡμῖν ἔχοι ψεύσασθαι καὶ τὰς τῶν ἐκπεμψάντων ἡμᾶς ἅμα καὶ τὰς ἡμετέρας αὐτῶν ἐλπίδας; ἰδίᾳ μὲν γὰρ οὐδ’ ἂν εἷς οὕτως εὖ πράξειεν ὥστε μὴ οὐ τῷ κοινῷ πταίσαντι συναπολέσθαι· τὸ δὲ δημόσιον εὐτυχοῦν πάσας καὶ τὰς ἑκάστου συμφορὰς ἀναφέρει.", "st": "38.36"}, {"sp": "N", "t": "λέγω δὲ ταῦτα οὐ πρὸς ὑμᾶς, ἄνδρες ἑταῖροί τε καὶ φίλοι, τοὺς ἐνταῦθα ὄντας (οὔτε γὰρ ἄλλως ἀγνοεῖτε αὐτὰ ὥστε καὶ μαθεῖν δεῖσθαι, οὔτ’ ὀλιγώρως αὐτῶν ἔχετε ὥστε καὶ προτροπῆς χρῄζειν), ἀλλ’ ὅτι τινὰς τῶν στρατιωτῶν ᾔσθημαι αὐτούς τε θρυλοῦντας ὡς οὐ προσήκοντα τόνδε τὸν πόλεμον ἀνῃρήμεθα, καὶ τοὺς ἄλλους προσστασιάζοντας, ἵν’ αὐτοί τε βεβαιοτέραν ἐκ τῶν παρ’ ἐμοῦ λόγων τὴν ὑπὲρ τῆς πατρίδος προθυμίαν ποιήσησθε, καὶ ἐκείνους πάνθ’ ἃ προσήκει διδάξητε· πλείω γὰρ ἂν παρ’ ὑμῶν ἰδίᾳ καὶ πολλάκις ἀκούοντες αὐτὰ ὠφεληθεῖεν ἢ παρ’ ἐμοῦ ἅπαξ πυθόμενοι. λέγετε τοίνυν αὐτοῖς ὅτι οἱ πρόγονοι ἡμῶν οὐκ οἴκοι μένοντες, οὐδὲ τὰς στρατείας ὀκνοῦντες, οὐδὲ τοὺς πολέμους φεύγοντες, οὐδὲ τὰς ῥᾳθυμίας διώκοντες τηλικαύτην τὴν πόλιν ἐποίησαν, ἀλλὰ ταῖς γνώμαις πάντα τὰ προσήκοντα προχείρως τολμῶντες καὶ τοῖς σώμασι πάντα τὰ ἀρέσαντα προθύμως ἐκπονοῦντες, καὶ τὰ μὲν ἴδια ὡς ἀλλότρια ἀεί ποτε παραβαλλόμενοι, τὰ δὲ δὴ τῶν πέλας ὡς καὶ οἰκεῖα ἑτοίμως κτώμενοι, καὶ μήτε εὐδαιμονίαν ἄλλο τι ἢ τὸ τὰ δέοντα πράττειν νομίζοντες, μήτε δυστυχίαν ἄλλο τι ἢ τὸ μετ’ ἀπραξίας ἡσυχάζειν ἡγούμενοι. τοιγαροῦν ἐκ τούτων τῶν πολιτευμάτων αὐτοί τε, ὀλίγιστοι τὸ κατ’ ἀρχὰς γενόμενοι καὶ πόλιν οὐδεμίαν ἧς οὐκ ἐλάττω τὸ πρῶτον νεμόμενοι, Λατίνους ἐκράτησαν, Σαβίνους ἐνίκησαν, Τυρσηνοὺς Οὐόλσκους Ὀπικοὺς Λευκανοὺς Σαυνίτας ἐχειρώσαντο, πᾶσαν ἑνὶ λόγῳ τὴν ἐντὸς τῶν Ἄλπεων γῆν κατεστρέψαντο, πάντας τοὺς ἀλλοφύλους", "st": "38.37"}, {"sp": "N", "t": "τοὺς ἐπελθόντας σφίσιν ἀπεώσαντο, καὶ αὐτοὺς καὶ οἱ μετὰ ταῦτα Ῥωμαῖοι οἵ τε πατέρες ἡμῶν ζηλώσαντες οὐκ ἠρκέσθησαν τοῖς παροῦσιν, οὐδ’ ἠγάπησαν οἷς παρέλαβον, ἀλλ’ ὄλεθρον μὲν αὑτῶν σαφῆ τὴν ῥᾳστώνην, σωτηρίαν δὲ ἀκριβῆ τὴν ταλαιπωρίαν νομίσαντες εἶναι, καὶ φοβηθέντες μὲν μὴ μείναντα αὐτὰ ἐφ’ ἑαυτῶν κατατριφθείη καὶ καταγηράσειεν, αἰσχυνθέντες δὲ εἰ τοσαῦτα παραδεξάμενοι μηδὲν ἐπικτήσαιντο, πολλῷ πλείω καὶ μείζω προσκατειργάσαντο. τί γὰρ ἄν τις καθ’ ἕκαστον λέγοι τὴν Σαρδώ, τὴν Σικελίαν, τοὺς Μακεδόνας, τοὺς Ἰλλυριούς, τὴν Ἑλλάδα, τὴν Ἀσίαν τὴν περὶ τὴν Ἰωνίαν, Βιθυνούς, Ἴβηρας, Ἄφρους; καίτοι συχνὰ μὲν ἂν χρήματα ἔδοσαν αὐτοῖς Καρχηδόνιοι ὥστε μὴ ἐκεῖσε ἐκπλεῦσαι, συχνὰ δὲ Φίλιππος καὶ Περσεὺς ὥστε μὴ ἐπ’ αὐτοὺς στρατεῦσαι, πολλὰ Ἀντίοχος, πολλὰ οἱ παῖδες αὐτοῦ καὶ ἔγγονοι ὥστε ἐπὶ τῆς Εὐρώπης καταμεῖναι. ἀλλ’ οὔτε ἐκεῖνοι πρό τε τῆς δόξης καὶ πρὸ τοῦ μεγέθους τῆς ἀρχῆς ἀργεῖν τε ἀκλεῶς καὶ πλουτεῖν ἀδεῶς εἵλοντο, οὔτ’ αὐτῶν ἡμῶν οἱ πρεσβύτεροι οἱ καὶ νῦν ἔτ’ ὄντες, ἀλλ’ ἅτε εὖ εἰδότες ὅτι διὰ τῶν αὐτῶν ἐπιτηδευμάτων καὶ κτᾶται τὰ ἀγαθὰ καὶ σώζεται, πολλὰ μὲν ἐβεβαιώσαντο τῶν προϋπαρχόντων, πολλὰ δὲ καὶ προσεκτήσαντο. τί γὰρ δεῖ κἀνταῦθα καθ’ ἕκαστον ἐπεξιέναι τὴν Κρήτην, τὸν Πόντον, τὴν Κύπρον, τὴν Ἰβηρίαν τὴν Ἀσιανήν, τὴν Ἀλβανίαν τὴν ἐκεῖ, Σύρους ἀμφοτέρους, Ἀρμενίους ἑκατέρους, Ἀραβίους, Παλαιστίνους; ὧν οὐδὲ τὰ ὀνόματα πρότερον ἀκριβῶς εἰδότες νῦν τῶν μὲν αὐτοὶ δεσπόζομεν, τὰ δὲ ἑτέροις ἐχαρισάμεθα, ὥστε ἐξ αὐτῶν καὶ προσόδους καὶ δυνάμεις καὶ τιμὰς καὶ συμμαχίας προσειληφέναι.", "st": "38.38"}, {"sp": "N", "t": "τοιαῦτα γοῦν ἔχοντες παραδείγματα, μήτε τὰ τῶν πατέρων ἔργα καταισχύνητε μήτε τὴν ἀρχὴν μεγίστην ἤδη οὖσαν προῆσθε. οὐδὲ γὰρ οὐδ’ ἀπ’ ἴσης ἡμῖν τε καὶ τοῖς ἄλλοις τοῖς μηδὲν τῶν ὁμοίων κεκτημένοις βουλευτέον ἐστίν. ἐκείνοις μὲν γὰρ ἐξαρκεῖ ῥᾳστωνεύειν καὶ μετὰ ἀσφαλείας ἄλλοις ὑποπεπτωκέναι, ἡμῖν δ’ ἀναγκαῖόν ἐστι καὶ πονεῖν καὶ στρατεύεσθαι καὶ μετὰ κινδύνων τὴν παροῦσαν εὐδαιμονίαν φυλάττειν. πολλοὶ γὰρ ἐπιβουλεύουσιν αὐτῇ· πᾶν γὰρ τὸ ὑπεραῖρόν τινας καὶ ζηλοῦται καὶ φθονεῖται, κἀκ τούτου πόλεμος ἀίδιός ἐστιν ἅπασι τοῖς καταδεεστέροις πρὸς τοὺς ἔν τινι αὐτῶν ὑπερέχοντας. ἢ οὖν ἀπὸ πρώτης ἐχρῆν μηδὲν διαφερόντως ἡμᾶς τῶν ἄλλων ἀνθρώπων ηὐξῆσθαι, ἤ, ἐπείπερ τηλικοῦτοι γεγόναμεν καὶ τοσαῦτα κεκτήμεθα, πέπρωταί τε ἢ ἄρχειν τῶν ἄλλων ἐγκρατῶς ἢ καὶ αὐτοὺς παντελῶς ἀπολέσθαι (τοῖς γὰρ ἔς τε ἀξίωμα τοσοῦτον καὶ ἐς δύναμιν τηλικαύτην προκεχωρηκόσιν ἀδύνατόν ἐστιν ἀκινδύνως ἰδιωτεῦσαι), πειθώμεθα τῇ τύχῃ, μηδὲ ἑκοῦσαν αὐτὴν καὶ αὐτεπάγγελτον τοῖς τε πατράσιν ἡμῶν ὑπάρξασαν καὶ ἡμῖν παραμένουσαν ἀπωσώμεθα. ἔσται δὲ τοῦτο οὐκ ἂν τὰ ὅπλα ῥίψωμεν, οὐδ’ ἂν τὰς τάξεις ἐκλίπωμεν, οὐδ’ ἂν διὰ κενῆς οἴκοι καθώμεθα ἢ καὶ παρὰ τοῖς συμμάχοις πλανώμεθα, ἀλλὰ ἂν τά τε ὅπλα διὰ χειρὸς ἀεὶ ἔχωμεν (οὕτω γὰρ μόνως εἰρήνη σώζεται) καὶ τὰ ἔργα τοῦ πολέμου διὰ κινδύνων ἀσκῶμεν (οὕτω γὰρ μόνως οὐκ ἀεὶ πολεμήσομεν), τοῖς τε δεομένοις τῶν συμμάχων ἀπροφασίστως ἐπικουρῶμεν (οὕτω γὰρ πολὺ πλείους ἕξομεν) καὶ τοῖς ἀεί τι παρακινοῦσι τῶν πολεμίων μὴ ἐπιτρέπωμεν (οὕτω γὰρ οὐδεὶς ἔθ’ ἡμᾶς ἀδικεῖν ἐθελήσει).", "st": "38.39"}, {"sp": "N", "t": "εἰ μὲν γάρ τις τῶν θεῶν ἐγγυητὴς ἡμῖν ἐγένετο ὅτι, κἂν ταῦτα μὴ ποιῶμεν, οὔτε τις ἡμῖν ἐπιβουλεύσει καὶ πάνθ’ ὅσα κεκτήμεθα ἀσφαλῶς ἀεὶ καρπωσόμεθα, αἰσχρὸν μὲν ἂν ἦν εἰπεῖν ὅτι τὴν ἡσυχίαν ἄγειν ἐχρῆν, ὅμως δ’ οὖν εἶχον ἄν τινα σκῆψιν εὐπρεπῆ οἱ μηδὲν τῶν δεόντων πράττειν βουλόμενοι. εἰ δ’ ἀνάγκη τε τοὺς κεκτημένους τινὰ ὑπὸ πολλῶν ἐπιβουλεύεσθαι, καὶ προσήκει τὰς ἐπιθέσεις αὐτῶν προκαταλαμβάνεσθαι, καὶ οἱ μὲν ἐπὶ τοῖς οἰκείοις ἡσυχάζοντες καὶ περὶ τούτοις κινδυνεύουσιν, οἱ δὲ ἐκ περιουσίας τῷ πολέμῳ καὶ κατὰ τῶν ἀλλοτρίων χρώμενοι καὶ ἐκεῖνα φυλάσσουσιν (οὐδεὶς γὰρ περὶ τοῖς ἑαυτοῦ δεδιὼς τῶν τοῦ πέλας ἐφίεται· ὁ γὰρ περὶ τῶν ὑπαρχόντων οἱ φόβος ἰσχυρῶς τοῦ πολυπραγμονεῖν τὰ μὴ προσήκοντα αὐτὸν ἀποτρέπει), τί τοῦτο λέγει τις, ὡς οὐ χρὴ ἡμᾶς ἀεί τι προσκτᾶσθαι; οὐ μέμνησθε, τὰ μὲν ἀκηκοότες τὰ δὲ ἑορακότες, ὅτι οὔτε τῶν ἐν τῇ Ἰταλίᾳ γενῶν οὐδὲν πρότερον ἀπέσχετο τοῦ τῇ πατρίδι ἡμῶν ἐπιβουλεύειν πρὶν τοὺς πολέμους ἐν τῇ ἐκείνων χώρᾳ τοὺς προγόνους ἡμῶν ποιήσασθαι, οὔτε οἱ Ἠπειρῶται πρὶν ἐς τὴν Ἑλλάδα αὐτοὺς περαιωθῆναι; οὐ Φίλιππος μελλήσας καὶ ἐπὶ τὴν Ἰταλίαν στρατεύσειν, πρὶν φθάσαντας τὴν ἐκείνου κακῶς ποιῆσαι· οὐ Περσεύς, οὐκ Ἀντίοχος, οὐ Μιθριδάτης, πρὶν τὰ αὐτὰ αὐτοὺς ἐργάσασθαι. καὶ τί τἆλλα λέγοι τις ἄν; ἀλλ’ οἱ Καρχηδόνιοι, τέως μὲν οὐδὲν δεινὸν ἀφ’ ἡμῶν ἐν τῇ Ἀφρικῇ εἶχον, ἔς τε τὴν Ἰταλίαν διέπλεον καὶ τὴν χώραν κατέτρεχον τάς τε πόλεις ἐπόρθουν καὶ παρ’ ὀλίγον καὶ τὸ ἄστυ αὐτὸ εἷλον, ἐπειδὴ δ’ ἀντιπολεμεῖσθαι ἤρξαντο, παντάπασιν ἐκ τῆς γῆς ἡμῶν ἐξέδρασαν. τὰ δ’ αὐτὰ ταῦτα καὶ περὶ τῶν Γαλατῶν καὶ Κελτῶν ἄν τις εἰπεῖν ἔχοι. καὶ γὰρ οὗτοι, μέχρι μὲν ἐντὸς τῶν Ἄλπεων ἐμένομεν, πολλάκις αὐτὰς ὑπερέβησαν καὶ πολλὰ τῆς Ἰταλίας ἐπόρθησαν· ἐπεὶ δὲ ἐτολμήσαμέν ποτε ἔξω τε τῶν ὅρων ἐκστρατεῦσαι καὶ τὸν πόλεμόν σφισι περιστῆσαι, καί τινα καὶ τῆς χώρας αὐτῶν ἀπετεμόμεθα, οὐκέτ’ οὐδένα πόλεμον ἀπ’ αὐτῶν ἐν τῇ Ἰταλίᾳ, πλὴν ἅπαξ, εἴδομεν. ὅταν οὖν τούτων οὕτως ἐχόντων λέγῃ τις ὅτι οὐ χρὴ πολεμεῖν ἡμᾶς, οὐδὲν ἄλλο φησὶν ἢ ὅτι οὐ χρὴ πλουτεῖν, οὐ χρὴ ἑτέρων ἄρχειν, οὐκ ἐλευθέρους, οὐ Ῥωμαίους εἶναι. ὥσπερ οὖν ἄν, εἴπερ τι τούτων εἶπέ τις, οὐκ ἂν ἠνέσχεσθε ἀλλὰ κἂν ἐν χερσὶν αὐτὸν ἀπεκτείνατε, οὕτω καὶ νῦν, ὦ ἄνδρες ἑταῖροι, πρὸς τοὺς ἐκεῖνα λέγοντας διατίθεσθε, μὴ τοῖς ῥήμασί σφων ἀλλὰ τοῖς ἔργοις τὸν νοῦν τεκμαιρόμενοι. οὐκοῦν ὅτι μὲν οὕτω χρὴ φρονεῖν, οὐδέν’ ἂν", "st": "38.40"}, {"sp": "N", "t": "ἀντειπεῖν ὑμῶν νομίζω· εἰ δ’ ὅτι μήτε ἐξήτασται περὶ τοῦ πολέμου τούτου παρὰ τῇ βουλῇ καὶ παρὰ τῷ δήμῳ μὴ ἐψήφισται, διὰ τοῦτό τις ἧττον οἴεται δεῖν ἡμᾶς προθυμηθῆναι, λογισάσθω τοῦθ’, ὅτι πάντες οἱ πόλεμοι ὅσοι πώποτε γεγόνασιν ἡμῖν, οἱ μὲν ἐκ παρασκευῆς καὶ προεπαγγέλσεως οἱ δὲ καὶ ἐπὶ καιροῦ συμβεβήκασι. καὶ διὰ τοῦτο ὅσα μὲν ἂν οἴκοι τε μενόντων ἡμῶν καὶ τὴν ἡσυχίαν ἀγόντων κινηθῇ καὶ ἐκ πρεσβείας τινὸς τὴν ἀρχὴν τῶν ἐγκλημάτων λάβῃ, καὶ σκέψιν ὑπὲρ αὐτῶν καὶ δεῖ καὶ ἀναγκαῖόν ἐστι γίγνεσθαι καὶ ψῆφον ἐπάγεσθαι, καὶ μετὰ τοῦτο τούς τε ὑπάτους ἢ καὶ στρατηγοὺς προστάττεσθαί σφισι καὶ τὰς δυνάμεις ἐκπέμπεσθαι· ὅσα δ’ ἂν ἐξεληλυθότων ἤδη καὶ ἐξεστρατευμένων τινῶν ἐκφανῇ, ταῦτ’ οὐκέτ’ ἐς διαγνώμην ἄγεσθαι χρή, ἀλλ’ ὡς καὶ δεδογμένα καὶ κεκυρωμένα ὑπ’ αὐτῆς τῆς χρείας προκαταλαμβάνεσθαι πρὶν αὐξηθῆναι. ἢ τίνος μὲν ἕνεκα ὑμᾶς ἐνταῦθ’ ὁ δῆμος ἐξέπεμψεν, τίνος δ’ ἕνεκα ἐμὲ μετὰ τὴν ὑπατείαν εὐθὺς ἔστειλε, τοῦτο μὲν ἐπὶ πέντε ἔτη καθάπαξ, ὃ μήπω πρότερον ἐγεγόνει, ἄρχειν ἑλόμενος, τοῦτο δὲ τέσσαρσι στρατοπέδοις ὁπλίσας, εἰ μὴ καὶ πολεμῆσαι πάντως ἡμᾶς δεήσειν ἐνόμιζεν; οὐ γάρ που ἵνα μάτην τρεφώμεθα, οὐδ’ ἵνα τάς τε πόλεις τὰς συμμαχίδας καὶ τὴν χώραν τὴν ὑπήκοον περιιόντες χαλεπώτεροι καὶ τῶν πολεμίων αὐτοῖς γιγνώμεθα, — οὐδ’ ἂν εἷς ταῦτα φήσειεν, — ἀλλ’ ἵνα τὴν οἰκείαν φυλάξωμεν, ἵνα τὴν τῶν πολεμίων πορθήσωμεν, ἵν’ ἄξιόν τι καὶ τοῦ πλήθους καὶ τῶν ἀναλωμάτων ἐργασώμεθα. οὐκοῦν ἐν τούτῳ καὶ οὗτος ὁ πόλεμος καὶ πᾶς ὁστισοῦν ἄλλος καὶ ἐπιτέτραπται ἡμῖν καὶ ἐγκεχείρισται. καὶ πάνυ γε φρονίμως ἐποίησαν ἐφ’ ἡμῖν τὸ τίσι πολεμητέον εἶναι διαγνῶναι καταλιπόντες καὶ μὴ αὐτοὶ τὸν πόλεμον ψηφισάμενοι. οἱ μὲν γὰρ οὔτ’ ἀκριβῶσαι τὰ τῶν συμμάχων τοσοῦτον αὐτῶν ἀφεστηκότες ἠδυνήθησαν ἄν, καὶ πρὸς εἰδότας καὶ προπαρεσκευασμένους τοὺς πολεμίους οὐκ ἂν ὁμοίως ἐπιτηδείως προσηνέχθησαν· ἡμεῖς δὲ δὴ κριταὶ ἅμα καὶ λειτουργοὶ τοῦ πολέμου γιγνόμενοι, καὶ προσέτι καὶ ἐπ’ αὐτοφώρους τοὺς ἐχθροὺς τὰ ὅπλα εὐθὺς ἐπιφέροντες, οὔτ’ ἀνεξετάστως οὔτ’ ἀδίκως οὔτ’ ἀπροφυλάκτως αὐτὸν ποιησόμεθα.", "st": "38.41"}, {"sp": "N", "t": "καί μοι εἴ τις ὑμῶν ἐκεῖνο ὑπολαμβάνει, τί δὴ τηλικοῦτον ὁ Ἀριόουιστος πεπλημμέληκεν ὥστ’ ἀντὶ φίλου καὶ συμμάχου πολέμιος ἡμῖν γενέσθαι, σκοπείτω τοῦθ’, ὅτι τοὺς ἀδικεῖν τι ἐπιχειροῦντας οὐκ ἐφ’ οἷς ποιοῦσι μόνον ἀλλὰ καὶ ἐφ’ οἷς φρονοῦσιν ἀμύνασθαι δεῖ, καὶ τήν τε αὔξησιν αὐτῶν πρὶν καὶ βλαβῆναί τι προκαταλαμβάνειν, καὶ μὴ περιμείναντας κακῶς ἔργῳ παθεῖν, τότε τιμωρεῖσθαι. ὅτι τοίνυν καὶ ἐχθρὸς καὶ ἔχθιστός ἐστιν ἡμῖν, πῶς ἂν ἄλλως μᾶλλον ἐλεγχθείη ἢ ἐξ ὧν ἐποίησεν; πέμψαντος γάρ μου πρὸς αὐτὸν φιλικῶς ὅπως ἔλθῃ τε πρὸς ἡμᾶς καὶ κοινῇ μεθ’ ἡμῶν βουλεύσηται περὶ τῶν παρόντων, οὔτ’ ἦλθεν οὔθ’ ἥξειν ὑπέσχετο. καίτοι τί μὲν ἐγὼ ἄδικον ἢ ἀνεπιεικὲς ἢ φορτικὸν ἐποίησα μεταπεμψάμενος αὐτὸν ὡς φίλον καὶ σύμμαχον; τί δὲ ἐκεῖνος ὕβρεως καὶ ἀσελγείας, οὐκ ἐθελήσας ἐλθεῖν, ἐκλέλοιπεν; ἆρ’ οὐ δυοῖν ἀνάγκη θάτερον, ἤτοι ὑπωπτευκότα αὐτόν τι κακὸν πείσεσθαι ἢ ὑπερπεφρονηκότα ἡμᾶς τοῦτο πεποιηκέναι; οὐκοῦν εἴτε τι ὑποτετόπηκεν, σαφέστατα αὐτὸς ἑαυτὸν ἐξελέγχει ἐπιβουλεύοντα ἡμῖν· οὐδεὶς γὰρ ἡμῖν μηδὲν δεινὸν παθὼν ὕποπτός ἐστιν, οὐδ’ ἀπ’ ὀρθῆς καὶ ἀδόλου τῆς γνώμης γίγνεται, ἀλλ’ οἱ προπαρεσκευασμένοι τινὰς ἀδικῆσαι ἑτοίμην τὴν ὑποψίαν κατ’ αὐτῶν ἐκ τοῦ συνειδότος σφῶν ἔχουσιν· εἴτ’ αὖ μηδενὸς τοιούτου ὑπόντος ὑπερεόρακέ τε ἡμᾶς καὶ λόγοις ὑπερηφάνοις ὕβρικε, τί χρὴ τοῦτον, ἐπειδὰν ἔργου τινὸς ἐπιλάβηται, προσδοκῆσαι πράξειν; ὁ γὰρ ἐν οἷς μηδὲν κερδανεῖν ἔμελλε τοσαύτῃ ὑπεροψίᾳ κεχρημένος πῶς οὐ πόρρωθεν ἐξελήλεγκται μηδὲν δίκαιον μήτε φρονῶν μήτε πράσσων; οὐ τοίνυν ἀπέχρησεν αὐτῷ τοῦτο, ἀλλὰ καὶ ἐμὲ ἐλθεῖν πρὸς αὑτὸν ἐκέλευσεν, εἴπερ τι αὐτοῦ", "st": "38.42"}, {"sp": "N", "t": "δεοίμην. καὶ μή μοι μικρὰν τὴν προσθήκην ταύτην εἶναι νομίσητε· μεγάλη γάρ ἐστιν ἐπίδειξις τῆς διανοίας αὐτοῦ. τὸ μὲν γὰρ αὐτὸν μὴ ἐθελῆσαι πρὸς ἡμᾶς ἀφικέσθαι τάχ’ ἄν τις καὶ ὄκνῳ καὶ ἀρρωστίᾳ καὶ φόβῳ, ἀπολογούμενος ὑπὲρ αὐτοῦ, ἀνέθηκε· τὸ δὲ δὴ καὶ ἐμὲ μεταπέμψασθαι οὔτε σκῆψιν οὐδεμίαν ἐνδέχεται, καὶ προσεξελέγχει καὶ ἐκεῖνο αὐτὸν οὐ κατ’ ἄλλο τι πεποιηκότα ἢ ὅτι οὔθ’ ὑπακούειν ἐς οὐδὲν ἡμῖν καὶ προσέτι καὶ προσαντεπιτάττειν πάντα παρεσκεύασται. καίτοι καὶ αὐτὸ τοῦτο πόσης ὕβρεως καὶ πόσου προπηλακισμοῦ μεστόν ἐστιν; μεταπέμπεταί τινα ὁ ἀνθύπατος ὁ Ῥωμαίων, καὶ ἐκεῖνος οὐκ ἔρχεται· μεταπέμπεταί τις τὸν ἀνθύπατον τὸν Ῥωμαίων Ἀλλόβριξ ὤν. μὴ γὰρ ὅτι ἐμοῦ τοῦ Καίσαρος οὐκ ἐπείσθη, μηδ’ ὅτι ἐμὲ τὸν Καίσαρα ἐκάλεσε, σμικρόν τι τοῦτο καὶ φαῦλον εἶναι νομίσητε. οὔτε γὰρ ἐγὼ αὐτὸν μετεπεμψάμην, ἀλλ’ ὁ Ῥωμαῖος, ὁ ἀνθύπατος, αἱ ῥάβδοι, τὸ ἀξίωμα, τὰ στρατόπεδα, οὔτε ἐγὼ μετεπέμφθην ὑπ’ αὐτοῦ, ἀλλὰ ταῦτα πάντα. ἰδίᾳ μὲν γὰρ ἐμοὶ πρὸς αὐτὸν οὐδέν ἐστι συμβόλαιον· κοινῇ δὲ δὴ πάντες καὶ εἴπομέν τι καὶ ἐποιήσαμεν καὶ ἀντηκούσαμεν καὶ ἀντεπάθομεν.", "st": "38.43"}, {"sp": "N", "t": "Ὥσθ’ ὅσῳ τις ἂν αὐτὸν ἔν τε τοῖς φίλοις καὶ ἐν τοῖς συμμάχοις ἡμῶν ἀναγεγράφθαι φήσῃ, τοσούτῳ μᾶλλον ἀξιομίσητον ὄντα ἀποδείξει. διὰ τί; ὅτι οἷα μηδὲ τῶν ἐχθίστων τις ὁμολογούντων ἡμῖν εἶναι ἐτόλμησέ ποτε ποιῆσαι, ταῦτ’ ἐκεῖνος ἔν τε τοῖς τῆς φιλίας καὶ ἐν τοῖς τῆς συμμαχίας ὀνόμασιν ἐξείργασται, καθάπερ ἐπ’ αὐτὸ τοῦτο πεποιημένος αὐτάς, ἵν’ ἡμᾶς ἀδικεῖν ἀδεῶς ἔχῃ. ἀλλ’ οὔτε τότε ἐπὶ τῷ προπηλακίζεσθαι καὶ ἐπιβουλεύεσθαι ἐσπεισάμεθα αὐτῷ, οὔτε νῦν αὐτοὶ τὰς σπονδὰς λύσομεν· ἡμεῖς μὲν γὰρ ὡς πρὸς φίλον καὶ σύμμαχον ἔτ’ αὐτὸν ὄντα ἐπρεσβευσάμεθα, ὁ δ’ ὁρᾶτε ὅπως ἡμῖν κέχρηται· ὥσπερ οὖν. ἡνίκα εὐεργετεῖν τε ἡμᾶς ἐβούλετο κἀντ’ εὖ πάσχειν ἠξίου, δικαίως ἐκείνων ἐτύγχανεν, οὕτω καὶ νῦν, ἐπειδὴ τἀναντία αὐτῶν πάντα ποιεῖ, δικαιότατα ἂν ἐν ἐχθροῦ μέρει νομισθείη. καὶ μὴ θαυμάσητε εἰ αὐτὸς ἐγὼ πρότερόν ποτε καὶ ἐν τῇ βουλῇ καὶ ἐν τῷ δήμῳ χρηματίσας τινὰ ὑπὲρ αὐτοῦ, εἶτα ταυτὶ νυνὶ λέγω. ἐγὼ μὲν γὰρ καὶ τότε καὶ νῦν τὴν αὐτὴν γνώμην ἔχω καὶ οὐ μεταβάλλομαι. τίς δέ ἐστιν αὕτη; τοὺς μὲν ἀγαθοὺς καὶ πιστοὺς καὶ τιμᾶν καὶ ἀμείβεσθαι, τοὺς δὲ κακοὺς καὶ ἀπίστους καὶ ἀτιμάζειν καὶ ἀμύνεσθαι. ἐκεῖνος δέ ἐστιν ὁ μεταβαλλόμενος, ὁ μήτε καλῶς μήτε δεόντως τοῖς δοθεῖσιν αὐτῷ παρ’ ἡμῶν χρώμενος.", "st": "38.44"}, {"sp": "N", "t": "Ὥσθ’ ὅτι μὲν δικαιότατα ἂν αὐτῷ πολεμήσαιμεν, οὐδένα ἀμφισβητήσειν οἴομαι· ὅτι δὲ οὔτε ἄμαχος οὔτε δυσπολέμητός ἐστιν, ὁρᾶτε μὲν καὶ ἐκ τῶν ἄλλων τῶν ὁμοφύλων αὐτῷ, οὓς πολλάκις μὲν καὶ πρότερον, ῥᾷστα δὲ καὶ νῦν ἐνικήσαμεν, λογίζεσθε δὲ καὶ ἐξ ὧν περὶ αὐτοῦ ἐκείνου πυνθανόμεθα. οὔτε γὰρ ἄλλως δύναμίν τινα οἰκείαν συνεστηκυῖαν καὶ συγκεκροτημένην ἔχει· νῦν τε, ἅτε μηδὲν δεινὸν προσδοκῶν, καὶ παντελῶς ἀπαράσκευός ἐστιν. οὐ τοίνυν οὐδὲ ἐκ τῶν ὁμοχώρων ἄν τις αὐτῷ προθύμως, οὐδ’ εἰ πάνυ ἐπαγγέλλεται, βοηθήσειε· τίς μὲν γὰρ ἂν ἕλοιτο ἐκείνῳ συμμαχήσας πολεμῆσαι ἡμῖν, μηδὲν ὑφ’ ἡμῶν λελυπημένος; πῶς δ’ οὐκ ἂν μᾶλλον ἡμῖν πάντες ἢ ἐκείνῳ συναράμενοι τήν τε τυραννίδα αὐτοῦ ὅμορόν σφισιν οὖσαν καταλῦσαι καὶ τῆς χώρας μέρος τι παρ’ ἡμῶν προσλαβεῖν ἐθελήσειαν; εἰ δὲ δὴ καὶ συσταῖέν τινες, οὔτι γε καὶ κρείττους ἂν ἡμῶν γένοιντο. ἵνα γὰρ τἆλλα ἐάσω, τὸ πλῆθος ἡμῶν, τὴν ἡλικίαν, τὴν ἐμπειρίαν, τὰ ἔργα, ἐκεῖνό γε τίς οὐκ οἶδεν, ὅτι ἡμεῖς μὲν κατὰ πᾶν ὁμοίως τὸ σῶμα ὡπλίσμεθα, ἐκεῖνοι δὲ δὴ γυμνοὶ τὸ πλεῖστόν εἰσι, καὶ ἡμεῖς μὲν καὶ λογισμῷ καὶ τάξει χρώμεθα, ἐκεῖνοι δὲ δὴ θυμῷ πρὸς πάντα ἀσύντακτοι φέρονται; μὴ γάρ τοι μήτε τὴν ὁρμὴν αὐτῶν μήτε τὸ μέγεθος ἢ τῶν σωμάτων ἢ τῆς βοῆς φοβηθῆτε. φωνή τε γὰρ οὐδένα πώποτε ἀνθρώπων ἀπέκτεινε, καὶ τὰ σώματα αὐτῶν δρᾶν μὲν οὐδὲν πλέον, ἅτε τὰς αὐτὰς ἡμῖν χεῖρας ἔχοντα, πάσχειν δὲ πολὺ πλείω, ἅτε καὶ μεγάλα καὶ γυμνὰ ὄντα, δυνήσεται· ἥ τε ὁρμὴ ἄμετρος καὶ προπετὴς τὸ κατ’ ἀρχὰς οὖσα καὶ", "st": "38.45"}, {"sp": "N", "t": "ἐκκενοῦται ῥᾳδίως καὶ ἐπ’ ὀλίγον ἀνθεῖ. πεπειραμένοις δέ που ὧν λέγω καὶ νενικηκόσιν ὑμῖν τοὺς ὁμοίους αὐτοῖς ταυτὶ παραινῶ, ὥσθ’ ὑμᾶς μήτε τῷ λόγῳ δοκεῖν ὑπ’ ἐμοῦ παράγεσθαι, καὶ τῷ ἔργῳ ἐχυρωτάτην τὴν ἐλπίδα τῆς νίκης ἐκ τῶν προκατειργασμένων ποιεῖσθαι. καὶ μέντοι καὶ τῶν Γαλατῶν αὐτῶν τῶν ὁμοίων σφίσι συχνοὶ ἡμῖν συμμαχήσουσιν, ὥστ’ εἰ καί τι φοβερὸν τὰ ἔθνη ταῦτα εἶχε, τοῦτο καὶ ἡμῖν καὶ ἐκείνοις ὑπάρξει. Ταῦτ’ οὖν αὐτοί τε οὕτω λογίζεσθε καὶ τοὺς ἄλλους διδάσκετε· ὡς εἴ γε καὶ ὑμῶν τινες ἄλλως πως φρονοῦσιν, ἀλλ’ ἔγωγε καὶ ὣς πολεμήσω, οὐδὲ ἐγκαταλείψω ποτὲ τὴν τάξιν ἣν ἐτάχθην ὑπὸ τῆς πατρίδος. καί μοι τὸ δέκατον στρατόπεδον ἀρκέσει· καὶ γὰρ εὖ οἶδ’ ὅτι κἂν διὰ πυρὸς δέῃ καὶ γυμνοὶ χωρήσουσι προθύμως. οἱ δὲ δὴ ἄλλοι τὴν ταχίστην ἀπαγάγετε, μηδέ μοι μάτην ἐνταῦθα τρύχεσθε, τά τε κοινὰ εἰκῇ ἀναλίσκοντες καὶ τῶν ἀλλοτρίων πόνων μεταποιούμενοι, τήν τε λείαν τὴν ὑφ’ ἑτέρων κτωμένην σφετεριζόμενοι.”", "st": "38.46"}, {"sp": "N", "t": "ταῦτα τοῦ Καίσαρος εἰπόντος οὐ μόνον οὐδεὶς ἀντεῖπεν, εἰ καὶ τὰ μάλιστά τινες τἀναντία σφίσιν ἐγίγνωσκον, ἀλλὰ καὶ συνῄνεσαν πάντες, καὶ οὐχ ἥκιστα οἱ δι’ ὑποψίας αὐτῷ ὄντες, λογοποιεῖν ἃ ἤκουσαν. καὶ τούς γε στρατιώτας οὐ χαλεπῶς ἔπεισαν πειθαρχῆσαι, τοὺς μὲν ἐκ τοῦ προκεκρίσθαι προθυμουμένους, τοὺς δ’ ἄλλους δι’ ἐκείνους φιλοτιμουμένους. ἐξαίρετον δὲ δὴ τὸ δέκατον στράτευμα ἐποιήσατο, ὅτι εὔνοιάν πως ἀεὶ αὐτοῦ εἶχεν. οὕτω δὲ δὴ τὰ πολιτικὰ στρατόπεδα πρὸς τὴν τῶν καταλόγων τάξιν ὠνομάζετο· ὅθενπερ καὶ νῦν ὁμοίως τὰ νῦν ὄντα τὰς ἐπικλήσεις ἔχει. ὡρμημένων οὖν αὐτῶν ὁ Καῖσαρ οὐκέτι κατὰ χώραν ἔμεινε, μὴ καὶ χρονίσαντες ἀμβλύτεροι αὖθις γένωνται, ἀλλ’ εὐθὺς ἄρας ἐπὶ τὸν Ἀριόουιστον ἤλασε. καὶ οὕτω γε αὐτὸν τῷ αἰφνιδίῳ τῆς ἐφόδου κατέπληξεν ὥστε καὶ ἐς λόγους οἱ ὑπὲρ εἰρήνης ἐλθεῖν κατηνάγκασεν. οὐ μέντοι καὶ συνέβησαν· αὐτός τε γὰρ πάντα προστάξαι καὶ ἐκεῖνος οὐδὲν ὑπακοῦσαι ἠθέλησεν. ὅ τε οὖν πόλεμος συνερρώγει, καὶ μετέωροι οὐ μόνον αὐτοὶ ἑκάτεροι ἀλλὰ καὶ οἱ σύμμαχοι οἵ τε πολέμιοί σφων οἱ ἐκείνῃ πάντες ἦσαν, τήν τε μάχην αὐτῶν ὅτι τάχιστα ἔσεσθαι καὶ τοῖς ἅπαξ κρατήσασι καὶ τἆλλα δουλεύσειν νομίζοντες. προεῖχον δὲ οἱ μὲν βάρβαροι τῷ τε πλήθει καὶ τοῖς μεγέθεσιν, οἱ δὲ δὴ Ῥωμαῖοι τῇ τε ἐμπειρίᾳ καὶ ταῖς ὁπλίσεσι· καί πως καὶ πρὸς τὸν θυμὸν τῶν Κελτῶν, τήν τε ἄκριτον καὶ προπετῆ αὐτῶν ὁρμήν, ἀντίρροπον τὸ τοῦ Καίσαρος φρόνημα εὑρίσκετο, ὥστε ἰσοπαλεῖς ἐκ τούτων ὄντες καὶ τὰς ἐλπίδας τήν τε ἐπ’ αὐταῖς προθυμίαν ἰσοστασίας ἐποιοῦντο.", "st": "38.47"}, {"sp": "N", "t": "ἀντικαθημένων δὲ αὐτῶν ἀλλήλοις, αἱ γυναῖκες αἱ τῶν βαρβάρων ἀπηγόρευσάν σφισι θειάσασαι μηδεμίαν πρὸ τῆς νέας σελήνης μάχην συνάψαι. καὶ διὰ τοῦτο ὁ Ἀριόουιστος (πάνυ γὰρ αὐταῖς προσεῖχεν ὁπότε τοιοῦτό τι ποιήσειαν) οὐχ ἁπάσῃ εὐθὺς τῇ δυνάμει, καίτοι τῶν Ῥωμαίων προκαλουμένων σφᾶς, συνέμιξεν, ἀλλὰ τοὺς ἱππέας μετὰ τῶν συντεταγμένων σφίσι πεζῶν μόνους ἐκπέμπων ἰσχυρῶς αὐτοὺς ἐλύπει. κἀκ τούτου καταφρονήσας χωρίον τι ὑπὲρ τοῦ ταφρεύματός σφων καταλαβεῖν ἐπεχείρησε. καὶ κατέσχε μὲν αὐτό, ἀντικαταλαβόντων δὲ καὶ ἐκείνων ἕτερον, ἐς μὲν μάχην, καίπερ καὶ μέχρι τῆς μεσημβρίας τὸν στρατὸν ἔξω τοῦ Καίσαρος παρατάξαντος, οὐχ ὥρμησεν, ἐπαναχωρήσαντος δὲ αὐτοῦ πρὸς ἑσπέραν ἐπῆλθέ τε ἐξαπιναίως σφίσι καὶ ὀλίγου καὶ τὸ χαράκωμα αὐτῶν εἷλε. προχωρούντων οὖν οὕτως οἱ τῶν πραγμάτων σμικρόν τε ἔτι τῶν γυναικῶν ἐφρόντισε, καὶ τῇ ὑστεραίᾳ παραταξα μένων τῶν Ῥωμαίων, ὅπερ που καθ’ ἡμέραν ἐποιοῦντο, ἀντεπεξήγαγε.", "st": "38.48"}, {"sp": "N", "t": "καὶ αὐτοὺς ἐκεῖνοι προϊόντας ἐκ τῶν σκηνωμάτων ἰδόντες οὐχ ἡσύχασαν, ἀλλ’ ἐξᾴξαντες οὔτε συντάξασθαί σφισιν ἀκριβῶς ἐπέτρεψαν, καὶ τὴν ἀκόντισιν αὐτῶν, ἐφ’ ᾗ ἐς τὰ μάλιστα ἐθάρσουν, δρόμῳ μετὰ βοῆς προσπεσόντες ὑπετέμοντο, καὶ οὕτω γε ὁμόσε αὐτοῖς ἐχώρησαν ὥστε σφᾶς μήτε τοῖς κοντοῖς μήτε τοῖς ξίφεσι τοῖς μακροτέροις χρήσασθαι. ὠθίζοντό τε οὖν, καὶ τοῖς σώμασι τὸ πλεῖον ἢ τοῖς ὅπλοις ἐμάχοντο, ἀνατρέψαι τε τὸν προσκείμενον καὶ καταβαλεῖν τὸν ἀνθεστηκότα ἀγῶνα ποιούμενοι. καὶ πολλοὶ καὶ τῆς τῶν βραχυτέρων ξιφῶν χρήσεως στερηθέντες ταῖς τε χερσὶ καὶ τοῖς στόμασιν ἀντ’ ἐκείνων ἠγωνίζοντο, κατασπῶντες τοὺς ἀντιπάλους, δάκνοντες, σπαράττοντες, ἅτε καὶ τῷ μεγέθει τῶν σωμάτων πολὺ αὐτῶν ὑπερέχοντες. οὐ μέντοι καὶ μεγάλα τινὰ ἐκ τούτου σφᾶς ἔβλαψαν· συμπλεκόμενοι γὰρ αὐτοῖς οἱ Ῥωμαῖοι ἰσόρροποί πως τῇ τε ὁπλίσει καὶ τῇ τέχνῃ ἐγίγνοντο. καὶ τέλος ἐπὶ μακρότατον τοιουτοτρόπῳ μάχῃ χρησάμενοι ὀψέ ποτε ἐπεκράτησαν· τά τε γὰρ ξιφίδια καὶ σμικρότερα τῶν Γαλατικῶν ὄντα καὶ τὰς προσβολὰς χαλυβδικὰς ἔχοντα χρησιμώτατά σφισιν ἐγένετο, καὶ αὐτοὶ τῷ αὐτῷ πόνῳ ἐπὶ πλεῖον συσχεθέντες μᾶλλον τῶν βαρβάρων ἀντήρκεσαν, ἅτε οὐχ ὅμοιον ταῖς ὀξύτησι τῶν ἐφόδων τὸ διαρκές σφων ἐχόντων. διὰ μὲν οὖν ταῦτα ἡττήθησαν ἐκεῖνοι, οὐ μέντοι καὶ ἐτράποντο, οὐχ ὅτι οὐκ ἠθέλησαν ἀλλ’ ὅτι οὐκ ἠδυνήθησαν φυγεῖν ὑπ’ ἀπορίας τε ἅμα καὶ ἐκλύσεως. συστρεφόμενοι οὖν κατὰ τριακοσίους καὶ πλείους καὶ ἐλάττους, τάς τε ἀσπίδας ἁπανταχόθεν σφῶν προεβάλλοντο, καὶ ὀρθοὶ ἱστάμενοι ἀπρόσμικτοι μὲν ὑπὸ τῆς συγκλείσεως δυσκίνητοι δὲ ὑπὸ τῆς πυκνότητος ἐγίγνοντο, καὶ οὔτε ἔδρων οὐδὲν οὔτε ἔπασχον.", "st": "38.49"}, {"sp": "N", "t": "οἱ οὖν Ῥωμαῖοι, ἐπειδὴ μήτε ἐκεῖνοι ἀντεπῄεσάν σφισιν ἢ καὶ ἔφευγον, ἀλλ’ ἐν ταὐτῷ μένοντες ὥσπερ ἐν πύργοις εἱστήκεσαν, καὶ αὐτοὶ τά τε δοράτια κατὰ πρώτας εὐθὺς ἅτε μηδεμίαν χρῆσιν ἔχοντα ἀπετέθειντο, καὶ τοῖς ξίφεσιν οὐκ ἐδύναντο οὔτε συστάδην μάχεσθαι οὔτε τῶν κεφαλῶν αὐτῶν, ᾗπερ καὶ μόνον ἁλωτοὶ οἷά που γυμναῖς αὐταῖς μαχόμενοι ἦσαν, ἐφικνεῖσθαι, τάς τε ἀσπίδας ἀπέρριψαν, καὶ προσπίπτοντές σφισιν, οἱ μὲν ἐξ ἐπιδρομῆς οἱ δὲ καὶ ἐγγύθεν, ἐνήλλοντο τρόπον τινὰ καὶ ἔκοπτον αὐτούς. κἀκ τούτου πολλοὶ μὲν εὐθὺς ἅτε καὶ μιᾶς ἐπικοπῆς ὄντες ἔπιπτον, πολλοὶ δὲ καὶ πρὶν πεσεῖν ἀπέθνησκον· ὑπὸ γὰρ τῆς πυκνότητος τῆς συστάσεως καὶ τεθνηκότες ὀρθοὶ ἀνείχοντο. τοῦ μὲν οὖν πεζοῦ τὸ πλεῖστον οὕτω καὶ ἐκεῖ καὶ πρὸς ταῖς ἁμάξαις, ὅσον γε καὶ ἐξωσθὲν ἐς αὐτὰς ἐτύγχανε, σύν τε ταῖς γυναιξὶ καὶ σὺν τοῖς παισὶν αὐτῶν ἐφθάρησαν· ὁ δὲ Ἀριόουιστος μεθ’ ἱππέων … τήν τε χώραν παραχρῆμα ἐξέλιπε, καὶ πρὸς τὸν Ῥῆνον ὁρμήσας ἐπεδιώχθη μέν, οὐ κατελήφθη δέ. ἀλλ’ ὁ μὲν ἐπὶ πλοίου προεξέφυγε, τῶν δ’ ἄλλων τοὺς μὲν οἱ Ῥωμαῖοι ἐς τὸν ποταμὸν ἐσβαίνοντες ἀπέκτειναν, τοὺς δὲ καὶ αὐτὸς ἐκεῖνος ὑπολαβὼν ἀπήνεγκεν.", "st": "38.50"}, {"sp": "HDR", "t": "Βιβλίον ΛΘʹ", "st": "39"}, {"sp": "N", "t": "τάδε ἔνεστιν ἐν τῷ τριακοστῷ ἐνάτῳ τῶν Δίωνος Ῥωμαϊκῶν.<br>α. ὡς Καῖσαρ Βελγικοῖς ἐπολέμησεν.<br>β. ὡς Κικέρων κατῆλθεν.<br>γ. ὡς Πτολεμαῖος ἐκπεσὼν ἐξ Αἰγύπτου ἐς Ῥώμην ἀνῆλθεν.<br>δ. ὡς Κάτων τὰ ἐν Κύπρῳ κατεστήσατο.<br>ε. ὡς Πομπήιος καὶ Κράσσος ὕπατοι ᾑρέθησαν.<br>ζ. ὡς τὸ θέατρον τὸ Πομπηίου καθιερώθη.<br>η. ὡς Δέκιμος Βροῦτος Καίσαρος ὑποστράτηγος Οὐενετοὺς ναυμαχίᾳ ἐνίκησεν.<br>θ. ὡς Πούπλιος Κράσσος Καίσαρος ὑποστράτηγος Ἀκυϊτανοῖς ἐπολέμησεν.<br>ι. ὡς Καῖσαρ Κελτῶν τισι πολεμήσας τὸν Ῥῆνον διέβη· καὶ περὶ τοῦ Ῥήνου.<br>κ. ὡς Καῖσαρ ἐς Βρεττανίαν ἐπεραιώθη· καὶ περὶ τῆς νήσου.<br>λ. ὡς Πτολεμαῖος ὑπὸ Γαβινίου ἐς Αἴγυπτον κατήχθη, καὶ ὡς ὁ Γαβίνιος ἐπὶ τούτῳ ἐκρίθη.<br>χρόνου πλῆθος ἔτη τέτταρα ἐν οἷς ἄρχοντες οἱ ἀριθμούμενοι οἵδε ἐγένοντο<br>π. Κορνήλιος Π. υἱ. Λεντοῦλος Σπινθήρ<br>κ. Καικίλιος Κ. υἱ Μέτελλος Νέπως ὑπ.<br>Γν. Κορνήλιος Π. υἱ. Λεντοῦλος Μαρκελλῖνος<br>λ. Μάρκιος λ. υἱ. Φίλιππος ὑπ.<br>Γν. Πομπήιος Γν. υἱ. Μάγνος τὸ Β<br>μ. Λικίννιος Π. υἱ. Κράσσος τὸ Β ὑπ.<br>λ. Δομίτιος Γν. υἱ. Ἀηνόβαρβος<br>Ἀππ. Κλαύδιος Ἀππ. υἱ. Ποῦλχρος ὑπ.", "st": "39.0"}, {"sp": "N", "t": "οὕτω μὲν δὴ καὶ ἐκεῖνα διεπολεμήθη· μετὰ δὲ ταῦτα, τοῦ χειμῶνος ἐν ᾧ Κορνήλιός τε Σπινθὴρ καὶ ὁ Μέτελλος ὁ Νέπως ὑπατεύειν ἤρξαντο διελθόντος, τρίτος τις πόλεμος αὐτοῖς ἐγένετο. οἱ γὰρ Βελγικοὶ τῷ τε Ῥήνῳ πολλοῖς καὶ συμμίκτοις γένεσι προσοικοῦντες, καὶ ἐπὶ τὸν ὠκεανὸν τὸν κατὰ Βρεττανίαν καθήκοντες, ἐν μὲν τῷ πρὶν οἱ μὲν ἔνσπονδοι τοῖς Ῥωμαίοις ἦσαν οἱ δὲ ἐφρόντιζον αὐτῶν οὐδέν, τότε δὲ τὸν Καίσαρα εὖ φερόμενον ἰδόντες, καὶ δείσαντες μὴ καὶ ἐπὶ σφᾶς ὁρμήσῃ, συνεστράφησαν, καὶ κοινῷ πλὴν Ῥημῶν λόγῳ χρησάμενοι συνεβουλεύσαντό τε ἐπὶ τοῖς Ῥωμαίοις καὶ συνώμοσαν, Γάλβαν προστησάμενοι. Ταῦτ’ οὖν ὁ Καῖσαρ παρὰ τῶν Ῥημῶν μαθὼν ἐν φρουρᾷ τε αὐτοὺς ἐποιήσατο, κἀνταῦθα πρὸς τῷ Αὐξούννῳ ποταμῷ στρατοπεδευσάμενος ἤθροιζέ τε ἅμα τοὺς στρατιώτας καὶ ἐξήσκει. οὐδὲ ἐτόλμησε πρότερον τοῖς πολεμίοις, καίτοι τὴν χώραν σφῶν κατατρέχουσιν, ἐς χεῖρας ἐλθεῖν, πρὶν ὡς καὶ δεδιότος αὐτοῦ καταφρονήσαντες ἐπεχείρησαν τήν τε γέφυραν καταλαβεῖν καὶ τὴν σιτοπομπίαν, ἣν δι’ αὐτῆς παρὰ τῶν συμμάχων ἐποιεῖτο, ἀφελέσθαι. τοῦτο γὰρ ἐξ αὐτομόλων προγνοὺς ἐσόμενον, ἔπεμψεν ἐπ’ αὐτοὺς νυκτὸς", "st": "39.1"}, {"sp": "N", "t": "τούς τε ψιλοὺς καὶ τοὺς ἱππέας. καὶ οἱ μὲν προσπεσόντες τοῖς βαρβάροις ἀπροσδόκητοι πολλοὺς ἀπέκτειναν, ὥστε πάντας τῆς ἐπιούσης νυκτὸς ἐς τὴν οἰκείαν, ἄλλως τε καὶ ἐπειδὴ οἱ Αἴδουοι ἐσβεβληκότες ἐς αὐτὴν ἠγγέλλοντο, ἀπαναστῆναι· Καῖσαρ δὲ ᾔσθετο μὲν τὸ γιγνόμενον, οὐκ ἐτόλμησε δέ σφας εὐθύς, ἀγνοίᾳ τῶν χωρίων, ἐπιδιῶξαι. ἀλλ’ ἅμα ἕῳ τήν τε ἵππον λαβὼν καὶ τοὺς πεζοὺς ἐπακολουθεῖν κελεύσας κατέλαβεν αὐτούς, καὶ ὑποστάντας ἐς μάχην (ἐνομίζετο γὰρ σὺν μόνῃ τῇ ἵππῳ εἶναι) διέτριψε μέχρις οὗ καὶ ὁ πεζὸς ἦλθε, καὶ οὕτω παντὶ τῷ στρατῷ περισχὼν τούς τε πλείους κατέκοψε καὶ τοὺς περιλοίπους ὁμολογίᾳ παρεστήσατο. κἀκ τούτου καὶ τῶν δήμων τοὺς μὲν ἀμαχεὶ προσηγάγετο τοὺς δὲ πολέμῳ.", "st": "39.2"}, {"sp": "N", "t": "Νέρουιοι οὖν τῆς μὲν πεδιάδος (οὐ γὰρ ἦσαν ἀξιόμαχοι) ἑκόντες αὐτῷ ἐξέστησαν, ἐς δὲ δὴ τὰ ὄρη τὰ ὑλωδέστατα ἀνακομισθέντες, ἔπειτ’ ἐπειδὴ καὶ ἐκεῖθεν ἐπικατέδραμον ἀνέλπιστοι, καὶ καθ’ ὃ μὲν αὐτὸς ὁ Καῖσαρ ἦν ἐτράποντο καὶ ἔφυγον, τῷ δὲ δὴ πλείονι τοῦ στρατοῦ καθυπέρτεροί τε ἐγένοντο καὶ τὸ στρατόπεδον αὐτοβοεὶ εἷλον. αἰσθόμενος δὲ τοῦτ’ ἐκεῖνος (προεκεχωρήκει γὰρ ἐπί τι τοὺς τετραμμένους διώκων) ἀνέστρεψε, καὶ καταλαβὼν αὐτοὺς ἐν τῷ ἐρύματι ἁρπαγὴν ποιουμένους περιεστοιχίσατο καὶ κατεφόνευσε. πράξας δὲ ταῦτα, οὐδὲν ἔτι μέγα ἔργον τοὺς λοιποὺς Νερουίους χειρούμενος ἔσχε.", "st": "39.3"}, {"sp": "N", "t": "κἀν τούτῳ Ἀτουατικοί, πλησιόχωροί τε αὐτοῖς ὄντες καὶ τὸ γένος τό τε φρόνημα τὸ τῶν Κίμβρων ἔχοντες, ὥρμησαν μὲν ὡς καὶ βοηθήσοντές σφισιν, ἐπειδὴ δὲ ἔφθησαν προαλόντες, ἀνεχώρησαν, καὶ πάντα τἆλλα χωρία ἐκλιπόντες ἐς ἓν τεῖχος τὸ κράτιστον ἀνεσκευάσαντο. καὶ αὐτῷ τὸν Καίσαρα προσβαλόντα ἐπὶ πολλὰς ἡμέρας ἀπεκρούσαντο, μέχρις οὗ πρὸς μηχανῶν ποίησιν ἐτράπετο. τότε γάρ, τέως μὲν τήν τε ὕλην τέμνοντας καὶ τὰ μηχανήματα συμπηγνύντας τοὺς Ῥωμαίους ἑώρων, γέλωτα τῇ ἀπειρίᾳ τῶν γιγνομένων ἐποιοῦντο, ἐπεὶ δὲ ἐκεῖνά τε ἐξειργάσθη καὶ ὁπλῖταί σφισι πανταχόθεν ἅμα ἐπ’ αὐτῶν προσήγοντο, κατεπλάγησαν ἅτε μηπώποτε τοιοῦτό τι ἑορακότες, καὶ διεκηρυκεύσαντο, τά τε ἐπιτήδεια τοῖς στρατιώταις πέμψαντες καὶ ὅπλα τινὰ ἀπὸ τοῦ τείχους ῥίψαντες. ὡς μέντοι τά τε μηχανήματα τῶν ἀνδρῶν γυμνωθέντα αὖθις εἶδον καὶ ἐκείνους πρὸς θυμηδίαν οἷα ἐπὶ νίκῃ τετραμμένους ᾔσθοντο, μετέγνωσαν, καὶ ἀναθαρσήσαντες τῆς νυκτὸς ἐπέξοδον ὡς καὶ ἀνελπίστους σφᾶς κατακόψοντες ἐποιήσαντο. περιπεσόντες δὲ τοῖς προφύλαξιν (ὁ γὰρ Καῖσαρ ἀκριβῶς πάντα ἀεὶ διῴκει) ἐσφάλησαν. καὶ οὐδὲ τῶν λοιπῶν οὐδεὶς ἔτι συγγνώμης ἔτυχεν, ἀλλὰ πάντες ἐπράθησαν.", "st": "39.4"}, {"sp": "N", "t": "ἐπειδὴ δὲ οὗτοί τε κατεστράφατο, καὶ ἄλλοι οἱ μὲν ὑπ’ αὐτοῦ οἱ δὲ καὶ διὰ τῶν ὑποστρατήγων συχνοὶ ἐκεχείρωντο, ὅ τε χειμὼν ἐνέστη, ἀνεχώρησεν ἐς τὰ χειμάδια. μαθόντες δὲ ταῦθ’ οἱ οἴκοι Ῥωμαῖοι ἐθαύμασαν ὅτι ἔθνη τοσαῦτα, ὧν οὐδὲ τὰ ὀνόματα πρότερον ἠκρίβουν, ᾑρήκει, καὶ ἐψηφίσαντο πεντεκαίδεκα ἐπ’ αὐτοῖς ἡμέρας θῦσαι, ὅπερ οὔπω πρότερον ἐγεγόνει. κἀν τῷ αὐτῷ τούτῳ χρόνῳ Γάλβας ὁ Σέρουιος ὑποστρατηγῶν αὐτῷ, μέχρι μὲν ἥ τε ὡραία ἦν καὶ τὸ στράτευμα συνεστὸς εἶχεν, Οὐαράγρους παρά τε τῇ Λεμμάνῳ λίμνῃ καὶ πρὸς τοῖς Ἀλλόβριξι μέχρι τῶν Ἄλπεων οἰκοῦντας, τοὺς μὲν βίᾳ τοὺς δὲ καὶ ὁμολογίᾳ παρεστήσατο, ὥστε καὶ χειμάσαι κατὰ χώραν παρασκευάσασθαι. ἐπεὶ μέντοι οἱ πλείους τῶν στρατιωτῶν οἱ μὲν παρέμενοι οἷα μὴ πόρρω τῆς Ἰταλίας ὄντες, οἱ δὲ καὶ ἐφ’ ἑαυτῶν ἄλλοσε ἀπεχώρησαν, καὶ αὐτῷ ἀπροσδόκητοι κατὰ τοῦτο οἱ ἐπιχώριοι ἐπέθεντο, πρὸς ἀπόνοιαν ὑπ’ ἀπογνώσεως προήχθη, καὶ ἐκπηδήσας ἐκ τοῦ χειμαδίου ἄφνω τούς τε προσκειμένους οἱ τῷ παραδόξῳ τοῦ τολμήματος ἐξέπληξε, καὶ δι’ αὐτῶν πρὸς τὰ μετέωρα διέπεσε. γενόμενος δὲ ἐν τῷ ἀσφαλεῖ ἠμύνατο μὲν αὐτοὺς μετὰ τοῦτο καὶ ἐδουλώσατο, οὐ μὴν καὶ ἐχείμασεν αὐτόθι, ἀλλὰ καὶ ἐς τὴν τῶν Ἀλλοβρίγων μετέστη.", "st": "39.5"}, {"sp": "N", "t": "ταῦτα μὲν ἐν τῇ Γαλατίᾳ ἐγένετο, Πομπήιος δὲ ἐν τούτῳ τὴν κάθοδον τῷ Κικέρωνι ψηφισθῆναι διεπράξατο. ὃν γὰρ διὰ τοῦ Κλωδίου ἐξεληλάκει, τοῦτον ἐπ’ αὐτὸν ἐκεῖνον ἐπανήγαγεν· οὕτω που τὸ ἀνθρώπειον δι’ ὀλίγου τε ἔστιν ὅτε μεταβάλλεται, καὶ ἀφ’ ὧν ὠφελήσεσθαί τινες ἢ καὶ βλαβήσεσθαι νομίζουσι, τὰ ἐναντιώτατα ἀντιλαμβάνουσι. συνέπραττον δὲ ἀπὸ τῶν στρατηγῶν καὶ τῶν δημάρχων ἄλλοι τε καὶ Τίτος Ἄννιος Μίλων, οἵπερ που καὶ τὴν γνώμην ἐς τὸ πλῆθος ἐσήνεγκαν· ὁ γὰρ Σπινθὴρ ὁ ὕπατος τὸ μέν τι καὶ τῷ Πομπηίῳ χαριζόμενος, τὸ δὲ καὶ ἐξ ἰδίας ἔχθρας τὸν Κλώδιον ἀμυνόμενος, ὑφ’ ἧς καὶ τὴν μοιχείαν αὐτοῦ δικάζων κατεγνώκει, καὶ. … ἐκείνῳ δὲ ἄλλοι τε τῶν ἐν ταῖς ἀρχαῖς ὄντων ὑπῆρχον καὶ ὁ ἀδελφὸς Ἄππιος Κλαύδιος στρατηγῶν, ὅ τε Νέπως ὁ ὕπατος ἀπ’ οἰκείας τινὸς", "st": "39.6"}, {"sp": "N", "t": "ἔχθρας τὸν Κικέρωνα μισῶν. οὗτοί τε οὖν ἐπὶ πλέον ἢ πρίν, ἅτε καὶ ἡγεμόνας τοὺς ὑπάτους ἔχοντες, καὶ οἱ ἄλλοι οἱ ἐν τῇ πόλει διαστάντες πρὸς ἑκατέρους ἐθορύβουν. καὶ ἄλλα τε ἐκ τούτου οὐκ ἐν κόσμῳ πολλὰ ἐγίγνετο, καὶ ἐν αὐτῇ τῇ διαψηφίσει ὁ Κλώδιος γνοὺς τὸ πλῆθος πρὸς τοῦ Κικέρωνος ἐσόμενον, τοὺς μονομάχους οὓς ὁ ἀδελφὸς αὐτοῦ πρὸς ἀγῶνας ἐπιταφίους ἐπὶ τῷ Μάρκῳ τῷ συγγενεῖ προπαρεσκεύαστο λαβὼν ἐσεπήδησεν ἐς τὸν σύλλογον καὶ πολλοὺς μὲν ἔτρωσε πολλοὺς δὲ καὶ ἔκτεινεν. οὔτ’ οὖν ἡ γνώμη ἐκυρώθη, καὶ ἐκείνοις ὡς δορυφόροις συνὼν φοβερὸς καὶ ἐς τἆλλα πᾶσιν ἦν, ἀγορανομίαν τε ᾔτει ὡς καὶ τὴν δίκην τῆς βίας, ἂν ἀποδειχθῇ, διαφευξόμενος. ἐγράψατο γὰρ αὐτὸν ὁ Μίλων καὶ οὐκ ἐσήγαγε μέν (οὔτε γὰρ οἱ ταμίαι, δι’ ὧν τὴν ἀποκλήρωσιν τῶν δικαστῶν γενέσθαι ἐχρῆν, ᾕρηντο, καὶ ὁ Νέπως ἀπεῖπε τῷ στρατηγῷ μηδεμίαν πρὸ τῆς κληρώσεως αὐτῶν δίκην προσέσθαι· ἔδει δὲ ἄρα τοὺς ἀγορανόμους πρὸ τῶν ταμιῶν καταστῆναι, καὶ διὰ τοῦτο ὅτι μάλιστα", "st": "39.7"}, {"sp": "N", "t": "ἡ διατριβὴ ἐγένετο), μαχόμενος δὲ καὶ περὶ αὐτοῦ τούτου πολλὰ ἐτάραττε, καὶ τέλος μονομάχους τινὰς καὶ αὐτὸς καὶ ἄλλους τῶν τὰ αὐτά οἱ βουλομένων ἀθροίσας ἐς χεῖρας τῷ Κλωδίῳ συνεχῶς ᾔει, καὶ σφαγαὶ κατὰ πᾶσαν ὡς εἰπεῖν τὴν πόλιν ἐγίγνοντο. ὁ οὖν Νέπως φοβηθεὶς πρός τε τοῦ συνάρχοντος καὶ πρὸς τοῦ Πομπηίου τῶν τε ἄλλων τῶν πρώτων μετεβάλετο, καὶ οὕτως ἥ τε γερουσία κατελθεῖν τὸν Κικέρωνα τοῦ Σπινθῆρος ἐσηγησαμένου προεβούλευσε, καὶ ὁ δῆμος ἀμφοτέρων τῶν ὑπάτων ἐσενεγκόντων ἐψηφίσατο. ἀντέλεγε μὲν γὰρ πρὸς αὐτοὺς Κλώδιος, ἀλλ’ ἐκείνῳ τε ὁ Μίλων ἀντέκειτο ὥστε μηδὲν βίαιον δρᾶσαι, καὶ τῷ νόμῳ ἄλλοι τε καὶ ὁ Πομπήιος συνεῖπον ὥστε πολὺ κρείττους αὐτοὺς γενέσθαι.", "st": "39.8"}, {"sp": "N", "t": "κατῆλθέ τε οὖν ὁ Κικέρων καὶ χάριν τῇ τε βουλῇ καὶ τῷ δήμῳ, παρασχόντων αὐτῷ τῶν ὑπάτων καὶ τὸ συνέδριον καὶ τὴν ἐκκλησίαν, ἔγνω. τῷ τε Πομπηίῳ τὴν ἔχθραν τὴν ἐπὶ τῇ φυγῇ μεθεὶς συνηλλάγη, καὶ τήν γε εὐεργεσίαν παραχρῆμα ἀπέδωκε· λιμοῦ γὰρ ἐν τῇ πόλει ἰσχυροῦ γενομένου, καὶ τοῦ ὁμίλου παντὸς ἔς τε τὸ θέατρον (οἵῳ δὲ δὴ καὶ τότε ἔτι θεάτρῳ ἐς τὰς πανηγύρεις ἐχρῶντο) καὶ μετὰ τοῦτο καὶ ἐς τὸ Καπιτώλιον ἐπὶ τοὺς βουλευτὰς συνεδρεύοντας ἐσπηδήσαντος, καὶ τοτὲ μὲν ἐν χερσὶν αὐτοὺς ἀποσφάξειν τοτὲ δὲ καὶ καταπρήσειν αὐτοῖς τοῖς ναοῖς ἀπειλοῦντος, ἔπεισέ σφας ἐπιμελητὴν τοῦ σίτου τὸν Πομπήιον προχειρίσασθαι, καὶ διὰ τοῦτο καὶ ἀρχὴν αὐτῷ ἀνθυπάτου καὶ ἐν τῇ Ἰταλίᾳ καὶ ἔξω ἐπὶ πέντε ἔτη δοῦναι. καὶ ὁ μέν, ὥσπερ ἐπὶ τοῖς καταποντισταῖς πρότερον οὕτω καὶ τότε ἐπὶ τῷ σίτῳ πάσης αὖθις τῆς οἰκουμένης τῆς ὑπὸ τοῖς Ῥωμαίοις τότε οὔσης ἄρξειν ἔμελλε·", "st": "39.9"}, {"sp": "N", "t": "Καῖσαρ δὲ καὶ Κράσσος ἄλλως μὲν ἤχθοντο τῷ Κικέρωνι, σπουδὴν δ’ οὖν τινα αὐτοῦ ἔσχον, ἐπειδὴ πάντως καθήξοντα αὐτὸν ᾔσθοντο (καὶ γὰρ ὁ Καῖσαρ καὶ ἀπὼν εὔνοιάν τινα αὐτῷ ἐνεδείξατο), οὐ μέντοι καὶ χάριν οὐδεμίαν ἀντέλαβον. ἐκεῖνος γὰρ τοῦτό τε οὐκ ἀπὸ γνώμης σφᾶς πεποιηκότας εἰδώς, καὶ τῆς φυγῆς αἰτιωτάτους γεγονέναι νομίζων, ἐκ μὲν τοῦ προφανοῦς οὐ πάνυ πρὸς αὐτοὺς ἐθρασύνετο, ἅτε καὶ τῶν τῆς ἀκράτου παρρησίας ἐπικαρπιῶν νεωστὶ πεπειραμένος, βιβλίον μέντοι τι ἀπόρρητον συνέθηκε, καὶ ἐπέγραψεν αὐτῷ ὡς καὶ περὶ τῶν ἑαυτοῦ βουλευμάτων ἀπολογισμόν τινα ἔχοντι, πολλὰ δὲ δὴ καὶ δεινὰ ἐς αὐτὸ καὶ περὶ ἐκείνων καὶ περὶ ἄλλων τινῶν συνένησε, καὶ διὰ τοῦτο φοβηθεὶς μὴ καὶ ζῶντος αὐτοῦ ἐκφοιτήσῃ, κατεσημήνατό τε αὐτὸ καὶ παρέδωκε τῷ παιδί, προστάξας οἱ μήτ’ ἀναγνῶναι μήτε δημοσιεῦσαι τὰ γεγραμμένα πρὶν ἂν μεταλλάξῃ.", "st": "39.10"}, {"sp": "N", "t": "Κικέρων μὲν οὖν αὖθις ἀνεβλάστανε, καὶ τήν τε ἄλλην οὐσίαν καὶ τὸ ἔδαφος τῆς οἰκίας, καίτοι τῇ Ἐλευθερίᾳ ἀνειμένον, καὶ τοῦ Κλωδίου καὶ ἐπιθειάζοντος καὶ ἐς ἐνθυμίαν αὐτῷ προβάλλοντος, ἐκομίσατο. τὴν γὰρ ἐσφορὰν τοῦ φρατριατικοῦ νόμου, παρ’ ἣν ἐκ τῶν εὐπατριδῶν ἐς τὸ πλῆθος ἐπεποίητο, διαβάλλων ὡς οὐκ ἐν τοῖς ὡρισμένοις ἐκ τῶν πατρίων χρόνοις ἐκτεθέντος αὐτοῦ, τήν τε δημαρχίαν τοῦ Κλωδίου πᾶσαν, ἐν ᾗ καὶ τὰ κατὰ τὴν οἰκίαν ἐδέδοκτο, κατέλυε, λέγων οὐχ οἷόν τ’ εἶναι, τῆς μεταστάσεως αὐτοῦ τῆς ἐς τὸν ὅμιλον παρανόμως γεγενημένης, ὑγιές τι τῶν ἐν αὐτῇ πραχθέντων νομίζεσθαι, καὶ ἔπεισε διὰ τούτου τοὺς ποντίφικας τὸ ἔδαφός οἱ ὡς καὶ ὅσιον καὶ βέβηλον ὂν ἀποδοῦναι. καὶ οὕτω καὶ ἐκεῖνο καὶ χρήματα ἔς τε τὴν τῆς οἰκίας κατασκευήν, καὶ εἰ δή τι ἄλλο τῆς οὐσίας αὐτοῦ ἐλελύμαντο, ἔλαβε.", "st": "39.11"}, {"sp": "N", "t": "μετὰ δὲ δὴ τοῦτο Πτολεμαίου τοῦ βασιλέως ἕνεκα αὖθις ἐκινήθησαν. ἐπειδὴ γὰρ πολλά τισι τῶν Ῥωμαίων χρήματα, τὰ μὲν οἴκοθεν τὰ δὲ καὶ δανεισάμενος, ὅπως τήν τε ἀρχὴν βεβαιώσηται καὶ φίλος καὶ σύμμαχος ὀνομασθῇ, καταναλώκει, καὶ αὐτὰ παρὰ τῶν Αἰγυπτίων βιαίως ἠργυρολόγει, καὶ διά τε τοῦτο ἐχαλεπαίνετο καὶ ὅτι τὴν Κύπρον ἀπαιτῆσαι παρὰ τῶν Ῥωμαίων ἢ καὶ τὴν φιλίαν τὴν πρὸς αὐτοὺς ἀπειπεῖν κελευόντων αὐτῶν οὐκ ἠθέλησε, καὶ οὔτε πεῖσαί σφας ἡσυχάζειν οὔτ’ αὖ βιάσασθαι (ξενικὸν γὰρ οὐκ εἶχεν) ἠδυνήθη, διέδρα τε ἐκ τῆς Αἰγύπτου, καὶ ἐς τὴν Ῥώμην ἐλθὼν κατηγόρησέ τε αὐτῶν ὡς καὶ ἐκ τῆς βασιλείας αὐτὸν ἐκβεβληκότων, καὶ ἔτυχεν ὥστε ὑπὸ τοῦ Σπινθῆρος, ᾧ ἡ Κιλικία", "st": "39.12"}, {"sp": "N", "t": "ἐπετέτραπτο, καταχθῆναι. ἐν ᾧ δὲ ταῦτα ἐγένετο, οἱ Ἀλεξανδρεῖς τέως μὲν ἀγνοήσαντες ὅτι ἐς τὴν Ἰταλίαν ἀπηρκὼς ἦν, ἢ τεθνηκέναι αὐτὸν νομίσαντες, Βερενίκην τὴν θυγατέρα αὐτοῦ ἐς τὴν βασιλείαν ἀντικατέστησαν, ἔπειτα δὲ τἀληθὲς μαθόντες ἄνδρας ἑκατὸν ἐς τὴν Ῥώμην ἔπεμψαν πρός τε τὰ ἐγκλήματα αὐτοῦ ἀπολογησομένους καὶ ἀντικατηγορήσοντας ὅσα ἠδίκηντο. προμαθὼν οὖν ταῦτ’ ἐκεῖνος (ἔτι δὲ ἐν τῇ Ῥώμῃ ἦν) ἐνήδρευσε τοὺς πρέσβεις, πρὶν ἐλθεῖν, ἄλλους ἄλλῃ διαπέμψας, καὶ τοὺς μὲν πλείους αὐτῶν κατὰ τὴν ὁδὸν ἔφθειρε, τῶν δὲ δὴ λοιπῶν τοὺς μὲν ἐν τῷ ἄστει αὐτῷ ἀπέκτεινε, τοὺς δὲ καὶ καταφοβήσας ἐκ τούτων ἢ χρήμασι διαφθείρας ἔπεισε μήτε ταῖς ἀρχαῖς ὑπὲρ ὧν ἐστάλατο ἐντυχεῖν μήθ’ ὅλως μνείαν τινὰ περὶ", "st": "39.13"}, {"sp": "N", "t": "τῶν ἀπολωλότων ποιήσασθαι. καίτοι τὸ πρᾶγμα οὕτω περιβόητον ἐγένετο ὥστε καὶ τὴν βουλὴν ἀγανακτῆσαι δεινῶς, ἐνάγοντός σφας ὅτι μάλιστα Φαουωνίου τοῦ Μάρκου καθ’ ἑκάτερον, ὅτι τε πολλοὶ παρὰ τῶν συμμάχων πρέσβεις πεμφθέντες βιαίως ἀπωλώλεσαν, καὶ ὅτι συχνοὶ καὶ τότε τῶν Ῥωμαίων ἐδεδωροδοκήκεσαν. καὶ οἱ μὲν τὸν Δίωνα τὸν τῆς πρεσβείας αὐτοκράτορα (περιῆν γάρ) μετεπέμψαντο ὡς καὶ τὴν ἀλήθειαν παρ’ αὐτοῦ μαθησόμενοι· οὕτω δὲ ἄρα καὶ τότε ἔθ’ ὁ Πτολεμαῖος τοῖς χρήμασι κατεκράτει ὥστε μήτε τὸν Δίωνα ἐς τὸ συνέδριον ἐσελθεῖν μήτε μνήμην τινὰ τοῦ φόνου τῶν τεθνηκότων, ἕως γε καὶ αὐτὸς παρῆν, γενέσθαι. καὶ μέντοι τοῦ Δίωνος μετὰ ταῦτα δολοφονηθέντος οὐδεμίαν οὐδ’ ἐπ’ ἐκείνῳ δίκην ἔδωκε· τά τε γὰρ ἄλλα καὶ ὁ Πομπήιος τῇ τε οἰκίᾳ αὐτὸν ὑπεδέδεκτο καὶ ἰσχυρῶς οἱ συνῄρετο. τῶν γε μὴν ἄλλων τῶν αὐτόθεν ἐνεκλήθησαν μὲν ἐν ὑστέρῳ συχνοί, ἑάλωσαν δὲ ὀλίγοι· τό τε γὰρ δεδωροδοκηκὸς πολὺ ἦν, καὶ ἀλλήλοις διὰ τὸ ἴδιον ἕκαστος δέος συνεμάχουν.", "st": "39.14"}, {"sp": "N", "t": "οἱ μὲν οὖν ἄνθρωποι τοιαῦτα ὑπὸ τῶν χρημάτων ἐποίουν, τὸ δὲ δὴ θεῖον κεραυνῷ κατ’ ἀρχὰς εὐθὺς τοῦ ἐχομένου ἔτους τὸ ἄγαλμα τοῦ Διὸς τοῦ ἐν τῷ Ἀλβανῷ ἱδρυμένου βαλὸν τὴν κάθοδον τοῦ Πτολεμαίου χρόνον τινὰ ἐπέσχε. τοῖς γὰρ Σιβυλλείοις ἔπεσιν ἐντυχόντες εὗρον ἐν αὐτοῖς ἐγγεγραμμένον αὐτὸ τοῦτο “ἂν ὁ τῆς Αἰγύπτου βασιλεὺς βοηθείας τινὸς δεόμενος ἔλθῃ, τὴν μὲν φιλίαν οἱ μὴ ἀπαρνήσασθαι, μὴ μέντοι καὶ πλήθει τινὶ ἐπικουρήσητε· εἰ δὲ μή, καὶ πόνους καὶ κινδύνους ἕξετε.” κἀκ τούτου τὴν συντυχίαν τῶν ἐπῶν πρὸς τὰ τότε γενόμενα θαυμάσαντες ἀπεψηφίσαντο πάντα τὰ περὶ αὐτοῦ ἐγνωσμένα, Γαΐῳ Κάτωνι πεισθέντες δημάρχῳ. ταῦτα δὲ ἐχρήσθη μὲν οὕτως, ἐδημοσιεύθη δέ (οὐ γὰρ ἐξῆν οὐδὲν τῶν Σιβυλλείων, εἰ μὴ ἡ βουλὴ ψηφίσαιτο, ἐς τὸ πλῆθος ἐξαγγέλλεσθαι) διὰ τοῦ Κάτωνος. ἐπειδὴ γὰρ τάχιστα ὁ νοῦς τῶν ἐπῶν διεθρυλήθη, ὥσπερ εἴωθε γίγνεσθαι, ἔδεισε μὴ συγκρυφθείη, καὶ ἔς τε τὸν ὅμιλον τοὺς ἱερέας ἐσήγαγε, κἀνταῦθα, πρὶν ὁτιοῦν τὴν γερουσίαν ἐπ’ αὐτοῖς χρηματίσαι, ἐξεβιάσατό σφας ἐκλαλῆσαι τὸ λόγιον· ὅσῳ γάρ τοι μᾶλλον οὐκ ἐδόκει σφίσιν", "st": "39.15"}, {"sp": "N", "t": "ἐξεῖναι τοῦτο,...τὸ πλῆθος ἔσχε. καὶ ἐκεῖνο μὲν ἔσχεν οὕτως, καὶ ἐς τὴν τῶν Λατίνων γλῶσσαν μεταγραφὲν ἀνεκηρύχθη· γνώμας δὲ αὐτῶν μετὰ τοῦτο ποιουμένων, καὶ τῶν μὲν ἄνευ στρατοῦ τῷ Σπινθῆρι τὴν τοῦ Πτολεμαίου κάθοδον προσταττόντων, τῶν δὲ δὴ καὶ τὸν Πομπήιον μετὰ ῥαβδούχων δύο καταγαγεῖν αὐτὸν κελευόντων (ὅ τε γὰρ Πτολεμαῖος μαθὼν τὸ χρησθὲν ἠξίωσε τούτου τυχεῖν, καὶ τὰ γράμματα αὐτοῦ Αὖλος Πλαύτιος ἐς τὸ κοινὸν δημαρχῶν ἀνέγνω), δείσαντες οἱ βουλευταὶ μὴ μείζων ἔθ’ ὁ Πομπήιος καὶ ἀπ’ ἐκείνου γένηται, ἀντέπραξαν αὐτῷ τῇ τοῦ σίτου προφάσει χρησάμενοι. ταῦτα μὲν ἐπί τε Λουκίου Φιλίππου καὶ ἐπὶ Γναίου Μαρκελλίνου ὑπάτων ἐγένετο· καὶ αὐτὰ ὁ Πτολεμαῖος μαθὼν τήν τε κάθοδον ἀπέγνω, καὶ ἐς Ἔφεσον ἐλθὼν παρὰ τῇ θεῷ διῃτᾶτο.", "st": "39.16"}, {"sp": "N", "t": "τῷ δὲ δὴ προτέρῳ ἔτει καὶ τοιόνδε τι, ἴδιον μέν, φέρον δέ πως ἐς τὴν συγγραφήν, ἐπράχθη. τοῦ γὰρ νόμου διαρρήδην ἀπαγορεύοντος μηδένας δύο ἅμα ἐκ τῆς αὐτῆς συγγενείας τὴν αὐτὴν ἱερατείαν ἔχειν, ὁ Σπινθὴρ ὁ ὕπατος ἐπιθυμήσας Κορνήλιον Σπινθῆρα τὸν υἱὸν ἐς τοὺς οἰωνιστὰς ἐσαγαγεῖν, ἔπειτ’ ἐπειδὴ ὁ Φαῦστος ὁ τοῦ Σύλλου παῖς ἐκ τοῦ τῶν Κορνηλίων φύλου ὢν προενεγέγραπτο, ἐξεποίησεν αὐτὸν ἐς τὸ Μαλλίου Τορκουάτου γένος, καὶ οὕτως ὁ νόμος ἐν τοῖς ἑαυτοῦ ῥήμασι μείνας ἔργῳ κατελύθη.", "st": "39.17"}, {"sp": "N", "t": "μετὰ δὲ δὴ τοῦτο ὁ Κλώδιος ἐπειδὴ τάχιστα ἐς τὴν ἀγορανομίαν ἐπί τε τοῦ Φιλίππου καὶ ἐπὶ τοῦ Μαρκελλίνου παρεληλύθει (πρὸς γὰρ τὴν ἀπόδρασιν τῆς δίκης παρακελευστὸς ᾑρέθη), γραφὴν κατὰ τοῦ Μίλωνος τῆς τῶν μονομάχων παρασκευῆς ἀπήνεγκε· ἃ γὰρ αὐτὸς ἔπραττε καὶ ἐφ’ οἷς ἐκρίνετο, ταῦτ’ ἐκείνῳ ἀντενεκάλει. ἐποίει δὲ τοῦτο οὐχ ὅτι τὸν Μίλωνα προσεδόκα αἱρήσειν ἅτε καὶ συναγωνιστὰς ἰσχυροὺς ἄλλους τε καὶ τὸν Κικέρωνα τόν τε Πομπήιον ἔχοντα, ἀλλ’ ἵνα ἐπὶ τῇ προφάσει ταύτῃ τῷ τε Μίλωνι προσπολεμοίη", "st": "39.18"}, {"sp": "N", "t": "καὶ ἐκείνους ὑβρίζοι. πρὸς γοῦν τοῖς ἄλλοις τοιόνδε τι ἐμεμηχάνητο· παρασκευάσας τοὺς ἑταίρους ἵν’, ὁπότε πύθοιτο αὐτῶν ἐν τοῖς συλλόγοις “τίς ὁ ποιῶν ἢ καὶ λέγων τοιόνδε τι ἦν, ” συνεκβοῷεν ὅτι Πομπήιος, ἐπηρώτα πολλάκις ἐξαίφνης πάνθ’ ὅσα ἐπαίτια περὶ αὐτὸν ἢ κατὰ τὸ σῶμα ἢ κατ’ ἄλλο τι ἦν, ἰδίᾳ καὶ καθ’ ἕκαστον, ὡς οὐ περὶ ἐκείνου δὴ λέγων· κἀκ τούτου τῶν μὲν ἐξαρχόντων τῶν δὲ συνεπηχούντων σφίσιν, οἷα φιλεῖ ἐν τοῖς τοιούτοις γίγνεσθαι, καὶ λεγόντων ὅτι Πομπήιος, χλευασία πολλὴ συνέβαινεν, ὥστε ἐκεῖνον μήτε τὴν ἡσυχίαν ἄγειν καρτεροῦντα μήθ’ ὅμοιόν τι ποιεῖν αὐτῷ ὑπομένοντα περιοργῆ τε γίγνεσθαι καὶ ἐν ἀμηχανίᾳ καθίστασθαι, καὶ λόγῳ μὲν τὸν Μίλωνα κατακρίνεσθαι, ἔργῳ δὲ αὐτὸν μηδ’ ἀπολογούμενον ἁλίσκεσθαι. ὁ γὰρ Κλώδιος, ὅπως ἐπὶ πλεῖον ἀποροίη, οὐκ εἴα τὸν φρατριατικὸν νόμον ἐσενεχθῆναι· πρὶν γὰρ ἐκεῖνον τεθῆναι οὔτ’ ἄλλο τι τῶν σπουδαίων ἐν τῷ κοινῷ πραχθῆναι οὔτε δίκην οὐδεμίαν ἐσαχθῆναι ἐξῆν.", "st": "39.19"}, {"sp": "N", "t": "τέως μὲν οὖν ὁ Μίλων τῶν λοιδοριῶν καὶ τῶν σφαγῶν πρόσχημα αὐτοῖς ἦν· τεράτων τέ τινων ἐν τούτῳ γενομένων (ἔν τε γὰρ τῷ Ἀλβανῷ νεὼς Ἥρας βραχὺς ἐπὶ τραπέζης τινὸς πρὸς ἀνατολῶν ἱδρυμένος πρὸς τὴν ἄρκτον μετεστράφη, καὶ λαμπὰς ἀπὸ τῆς μεσημβρίας ὁρμηθεῖσα πρὸς βορέαν διῇξε, λύκος τε ἐς τὴν πόλιν ἐσῆλθε, καὶ σεισμὸς ἐγένετο, τῶν τε πολιτῶν τινες κεραυνοῖς ἐφθάρησαν, καὶ θόρυβος ἐν τῷ Λατίνῳ ὑπὸ γῆς ἐξηκούσθη· καὶ αὐτὰ οἱ μάντεις ἀκέσασθαι ἐθελήσαντες ὀργίζεσθαί σφισι δαιμόνιόν τι ὡς καὶ ἱερῶν τινων ἢ χωρίων οὐχ ὁσίων ἐποικουμένων ἔφασαν) ἐνταῦθα ὁ Κλώδιος τὸν Κικέρωνα μεταλαβὼν τῷ τε λόγῳ πολὺς ἐνέκειτο, ὅτι τὸ ἔδαφος τῆς οἰκίας ἱερωμένον τῇ Ἐλευθερίᾳ κατῳκοδόμησε, καὶ ἐπῆλθέ ποτε ἐπ’ αὐτὸ ὡς καὶ ἐκ θεμελίων αὖθις αὐτὴν ἀναιρήσων. καὶ οὐκ ἐποίησε μὲν", "st": "39.20"}, {"sp": "N", "t": "τοῦτο, ὁ γὰρ Μίλων ἐκώλυσεν· ὁ δ’ οὖν Κικέρων ὡς καὶ παθὼν αὐτὸ ὀργήν τε εἶχε καὶ κατηγορίας ἐποιεῖτο, καὶ τέλος τόν τε Μίλωνα καὶ δημάρχους τινὰς παραλαβὼν ἀνῆλθέ τε ἐς τὸ Καπιτώλιον καὶ τὰς στήλας τὰς ἐπὶ τῇ ἑαυτοῦ φυγῃ ὑπὸ τοῦ Κλωδίου σταθείσας καθεῖλε. καὶ τότε μὲν αὐτὰς ἐκείνου σὺν Γαΐῳ τῷ ἀδελφῷ στρατηγοῦντι ἐπελθόντος ἀφῃρέθη, μετὰ δὲ τοῦτο φυλάξας ἐκδημοῦντα τὸν Κλώδιον ἀνέβη τε αὖθις ἐς τὸ Καπιτώλιον, καὶ λαβὼν αὐτὰς οἴκαδε ἀπεκόμισε. γενομένου δὲ τούτου οὐδὲν ἔτ’ ἀπώμοτον οὐδετέρῳ αὐτῶν ἦν, ἀλλὰ ἐλοιδόρουν ἀλλήλους καὶ διέβαλλον ἄλλα τε ὅσα ἐδύναντο, μηδενὸς τῶν αἰσχίστων ἀπεχόμενοι, καὶ ὁ μὲν τήν τε δημαρχίαν τὴν τοῦ Κλωδίου ὡς καὶ παρὰ τοὺς νόμους γενομένην καὶ τὰ πραχθέντα ἐν αὐτῇ ὑπ’ αὐτοῦ ὡς καὶ ἄκυρα ὄντα, ὁ δὲ τήν τε φυγὴν τὴν τοῦ Κικέρωνος ὡς καὶ δικαίως ἐγνωσμένην καὶ τὴν κάθοδον αὐτοῦ ὡς καὶ παρανόμως ἐψηφισμένην.", "st": "39.21"}, {"sp": "N", "t": "μαχομένων δὲ αὐτῶν, καὶ τοῦ Κλωδίου πολὺ τῇ στάσει ἐλαττουμένου, ὁ Κάτων ὁ Μᾶρκος ἐπελθὼν ἀνίσωσεν αὐτούς· τῷ τε γὰρ Κικέρωνι ἀχθόμενος, καὶ φοβηθεὶς ἅμα μὴ καὶ ὅσα αὐτὸς ἐν τῇ Κύπρῳ ἐπεποιήκει καταλυθείη, ὅτι πρὸς τοῦ Κλωδίου δημαρχοῦντος ἐπέπεμπτο, προθύμως αὐτῷ συνήρατο. μέγα γὰρ ἐπ’ αὐτοῖς ἐφρόνει, καὶ περὶ παντὸς τὸ βεβαιωθῆναι αὐτὰ ἐποιεῖτο. ὁ μὲν γὰρ Πτολεμαῖος ὁ τὴν νῆσον τότε κατέχων, ἐπειδὴ τά τε ἐψηφισμένα ᾔσθετο καὶ μήτ’ ἀντᾶραι τοῖς Ῥωμαίοις ἐτόλμησε μήτ’ αὖ στερηθεὶς τῆς ἀρχῆς ζῆν ὑπέμεινε, φάρμακον πιὼν ἀπέθανε, καὶ οἱ Κύπριοι τὸν Κάτωνα οὐκ ἀκουσίως, ἅτε καὶ φίλοι καὶ σύμμαχοι τῶν Ῥωμαίων ἀντὶ δούλων ἔσεσθαι προσδοκήσαντες, ἐσεδέξαντο· ὁ δὲ Κάτων ἐπὶ μὲν τούτοις οὐδὲν εἶχε σεμνύνεσθαι, ὅτι δὲ δὴ τά τε ἄλλα ἄριστα διῴκησε, καὶ δούλους καὶ χρήματα πολλὰ ἐκ τῶν βασιλικῶν ἀθροίσας οὐδὲν ᾐτιάθη ἀλλὰ ἀνεπικλήτως πάντα ἀπέδειξεν, ἀνδραγαθίας οὐδὲν ἧττον ἢ εἰ πολέμῳ τινὶ ἐνενικήκει μετεποιεῖτο· ὑπὸ γὰρ τοῦ πολλοὺς δωροδοκεῖν σπανιώτερον τὸ τῶν χρημάτων καταφρονεῖν τινα τοῦ τῶν πολεμίων κρατεῖν ἐνόμιζε.", "st": "39.22"}, {"sp": "N", "t": "τότε οὖν ὁ Κάτων ἐν δόξῃ τινὶ ἐπινικίων διὰ ταῦτ’ αἰσίων ἐγένετο, καὶ οἱ ὕπατοι γνώμην ἐν τῷ συνεδρίῳ ἐποιήσαντο στρατηγίαν αὐτῷ δοθῆναι καίπερ μηδέπω ἐκ τῶν νόμων προσήκουσαν. καὶ οὐκ ἀπεδείχθη μέν (αὐτὸς γὰρ ἀντεῖπε), τὴν δὲ δὴ εὔκλειαν καὶ ἐκ τούτου μείζονα ἔσχε. Κλώδιος δὲ ἐπεχείρησε μὲν τοὺς οἰκέτας τοὺς ἐκ τῆς Κύπρου ἀχθέντας Κλωδίους, ὅτι αὐτὸς τὸν Κάτωνα ἐκεῖσε ἐπεπόμφει, ὀνομόσαι, οὐκ ἠδυνήθη δὲ ἐναντιωθέντος αὐτοῦ. καὶ οἱ μὲν Κύπριοι ἐπεκλήθησαν, καίτοι τινῶν Πορκίους σφᾶς προσειπεῖν ἐθελησάντων (ὁ γὰρ Κάτων καὶ τοῦτ’ ἐκώλυσεν)· ὀργῇ δ’ οὖν ὁ Κλώδιος τὴν ἐναντίωσιν αὐτοῦ φέρων, τά τε διοικηθέντα ὑπ’ αὐτοῦ διέβαλλε καὶ τοὺς λογισμοὺς τῶν πεπραγμένων ἀπῄτει, οὐχ ὅτι καὶ διελέγξαι τι αὐτὸν ἀδικοῦντα ἐδύνατο, ἀλλ’ ὅτι ὑπὸ ναυαγίας τὰ γράμματα σχεδόν τι πάντα διέφθαρτο, καὶ ἐδόκει κατὰ τοῦτό τι ἰσχύσειν. ἐβοήθει δὲ καὶ τότε τῷ Κλωδίῳ ὁ Καῖσαρ καίτοι μὴ παρών, καὶ τάς γε κατηγορίας αὐτῷ τὰς κατὰ τοῦ Κάτωνος ἐπιστολιμαίους, ὥς γέ τινές φασιν, ἔπεμπεν. ἐπεφέρετο δὲ τῷ Κάτωνι ἄλλα τε καὶ ὅτι τὴν στρατηγίαν οἱ αὐτὸς τοὺς ὑπάτους πείσας, ὥς γε ἔλεγον, ἐσηγήσασθαι, προσεποιήσατο ἐθελοντής, ἵνα καὶ μὴ ἄκων ἀποτετυχηκέναι αὐτῆς δόξῃ, παρεῖσθαι.", "st": "39.23"}, {"sp": "N", "t": "οὗτοί τε οὖν ἐμάχοντο, καὶ ὁ Πομπήιος ἔσχε μὲν καὶ ἐν τῇ τοῦ σίτου διαδόσει τριβήν τινα· πολλῶν γὰρ πρὸς τὰς ἀπ’ αὐτοῦ ἐλπίδας ἐλευθερωθέντων, ἀπογραφήν σφων, ὅπως ἔν τε κόσμῳ καὶ ἐν τάξει τινὶ σιτοδοτηθῶσιν, ἠθέλησε ποιήσασθαι· οὐ μὴν ἀλλὰ τοῦτο μὲν τῇ τε ἑαυτοῦ σοφίᾳ καὶ ἐκ τοῦ πλήθους τοῦ σίτου ῥᾷόν πως διῴκησε, τὴν δὲ δὴ ὑπατείαν αἰτῶν πράγματα ἔσχε καὶ αἰτίαν ἀπ’ αὐτοῦ ἔλαβεν. ἐλύπει μὲν γὰρ αὐτὸν καὶ τὰ ὑπὸ τοῦ Κλωδίου γιγνόμενα, καὶ μάλισθ’ ὅτι καὶ ὑπὸ τῶν ἄλλων ὑπερεωρᾶτο ὧν διέφερε, διά τε τὸ ἀξίωμα καὶ διὰ τὰς ἐλπίδας ἀφ’ ὧν καὶ ἰδιωτεύων ὑπὲρ πάντας αὐτοὺς τιμηθήσεσθαι προσεδόκησεν ὑβριζόμενος. ἀλλὰ τούτων μὲν ἔσθ’ ὅτε καὶ κατεφρόνει· παραχρῆμα μὲν γὰρ κακῶς ἀκούων ἐδυσχέραινεν, διαλιπὼν δὲ καὶ ἐς ἀναλογισμὸν τῆς τε ἑαυτοῦ ἀρετῆς καὶ τῆς τῶν ἐναντίων κακίας ἀφικνούμενος", "st": "39.24"}, {"sp": "N", "t": "οὐκέτ’ αὐτῶν προετίμα· ὁ δὲ δὴ Καῖσαρ αὐξανόμενος, καὶ ὁ δῆμος τά τε κατειργασμένα αὐτῷ θαυμάζων ὥστε καὶ ἐκ ἀποστεῖλαι, καὶ πρὸς τὰς ἀπ’ αὐτοῦ ἐλπίδας ἐπαιρόμενος ὥστε καὶ χρήματά οἱ πολλὰ ψηφίσασθαι, δεινῶς αὐτὸν ἠνία. ἐπεχείρησε μὲν γὰρ τοὺς ὑπάτους ἀναπεῖσαι μήτε τὰς ἐπιστολὰς αὐτοῦ εὐθὺς ἀναγιγνώσκειν, ἀλλὰ καὶ ἐπὶ πλεῖστον, μέχρις ἂν αὐτόματος ἡ δόξα τῶν πραττομένων ἐκνικήσῃ, συγκρύπτειν, καὶ διάδοχόν τινα αὐτῷ καὶ πρὸ τοῦ καθήκοντος καιροῦ πέμψαι. τοσαύτῃ γὰρ φιλοτιμίᾳ ἐχρῆτο ὥσθ’ ὅσα αὐτὸς τῷ Καίσαρι συνέπραξε καὶ βασκαίνειν καὶ καταλύειν, καὶ ἐκείνῳ τε ἄλλως τε μεγάλως ἐπαινουμένῳ καὶ τὰ ἑαυτοῦ συσκιάζοντι ἄχθεσθαι, καὶ τῷ δήμῳ ἐγκαλεῖν ὅτι αὐτόν τε ἐν ὀλιγωρίᾳ ἐποιεῖτο καὶ τὸν Καίσαρα ὑπερεσπούδαζε. τά τε γὰρ ἄλλα καὶ ἠγανάκτει ὁρῶν αὐτοὺς τῶν τε προποιηθέντων τινὶ ἐπὶ τοσοῦτον μνημονεύοντας ἐφ’ ὅσον μηδὲν ἄλλο ἐπιγένοιτο, καὶ πρὸς τὸ ἀεὶ καθιστάμενον, κἂν ἔλαττον τοῦ προτέρου ᾖ, προχειρότατα τῷ τε τοῦ συνήθους κόρῳ καὶ τῇ τοῦ ξένου ἡδονῇ φερομένους, καὶ τὸ μὲν προευδοκιμοῦν πᾶν καταλύοντας ὑπὸ τοῦ φθόνου, τὸ δ’ ἄρτι προφαινόμενον συνεπαύξοντας", "st": "39.25"}, {"sp": "N", "t": "ὑπὸ τῶν ἐλπίδων. δι’ οὖν ταῦτα δυσχεραίνων, καὶ μήτε τι διὰ τῶν ὑπάτων διαπράξασθαι δυνηθεὶς καὶ τὸν Καίσαρα μείζω τῆς πρὸς ἑαυτὸν πίστεως γιγνόμενον ὁρῶν, οὐκ ἐν ἐλαφρῷ τὸ πρᾶγμα ἐποιήσατο. καὶ γὰρ ἐνόμιζε δύο τε εἶναι τὰ τὰς φιλίας τινῶν συγχέοντα, τό τε δέος καὶ τὸν φθόνον, καὶ ταῦτα ἀπ’ ἀντιπάλου καὶ τῆς δόξης καὶ τῆς ἰσχύος μόνως μὴ συμβαίνειν· ἕως μὲν γὰρ ἂν ἰσομοιρῶσί τινες αὐτῶν, καὶ ἐκείνας ἐρρῶσθαι, ἐπειδὰν δ’ ὑπεράρωσί τι οἱ ἕτεροι, ἐνταῦθα τό τε ἐλαττούμενον φθονῆσαν μισεῖν τὸν κρείττονα καὶ τὸ κρατοῦν καταφρονῆσαν ἐξυβρίζειν ἐς τὸν χείρονα, καὶ οὕτως ἀπ’ ἀμφοτέρων τὸν μὲν τῇ ἐλαττώσει ἀγανακτοῦντα τὸν δὲ τῇ πλεονεξίᾳ ἐπαιρόμενον, πρός τε διαφορὰς καὶ πρὸς πολέμους ἐκ τῆς πρὶν φιλίας ἀφικνεῖσθαι. τοιούτοις οὖν δή τισι λογισμοῖς ὁ Πομπήιος ἐπὶ τὸν Καίσαρα ὡπλίζετο. καὶ ἐδόκει γὰρ οὐκ ἂν ῥᾳδίως μόνος αὐτὸν καταλῦσαι, τὸν Κράσσον, ὡς καὶ μετ’ αὐτοῦ τοῦτο ποιήσων, ἔτι καὶ μᾶλλον ἀνηρτήσατο.", "st": "39.26"}, {"sp": "N", "t": "συμφρονήσαντες οὖν ἄλλως μὲν οὐδὲν ἰδιωτεύοντες πράξειν ἤλπισαν, ἂν δ’ ὑπατεύσωσι κἀκ τούτου καὶ αὐτοὶ τὰ πράγματα τῇ ἐκείνου ζηλώσει διαλάβωσι, καὶ ἀντίρροποί οἱ ἔσεσθαι καὶ ταχὺ αὐτοῦ, ἅτε καὶ δύο ἑνός, περιγενήσεσθαι προσεδόκησαν. καὶ οὕτω πᾶσαν τὴν προσποίησιν ἀφ’ ἧς, εἰ καί τις τῶν ἑταίρων σφῶν ἐπὶ τὴν ἀρχὴν αὐτοὺς προῆγεν, ἀπηρνοῦντο μηκέτι βούλεσθαι ὑπατεῦσαι, ἀποθέμενοι, ἄντικρυς αὐτῆς, καίπερ ἑτέροις τισὶ πρότερον συναγωνιζόμενοι, μετεποιήσαντο. ἐπειδή τε ἔξω τῶν χρόνων τῶν ἐν τοῖς νόμοις διειρημένων ἐπήγγειλαν αὐτήν, καὶ δῆλοι ἦσαν ἄλλοι τε καὶ αὐτοὶ οἱ ὕπατοι (καὶ γάρ τι καὶ ῥώμης ὁ Μαρκελλῖνος εἶχεν) οὐκ ἐπιτρέψοντές σφισιν ἀποδειχθῆναι, διεπράσσοντο τὰς ἀρχαιρεσίας ἐν τῷ ἐνιαυτῷ ἐκείνῳ μὴ γενέσθαι, ἄλλους τε καὶ τὸν Κάτωνα τὸν Γάιον ἐνιέντες, ἵνα μεσοβασιλέως αἱρεθέντος καὶ αἰτήσωσι κατὰ τοὺς νόμους τὴν ἀρχὴν καὶ λάβωσι.", "st": "39.27"}, {"sp": "N", "t": "καὶ ἐγίγνετο γὰρ τοῦτο λόγῳ μὲν ὑπὸ τῶν παρεσκευασμένων ἄλλοτε κατ’ ἄλλην πρόφασιν, ἔργῳ δὲ ὑπ’ αὐτῶν ἐκείνων (τοῖς γοῦν ἐναντιουμένοις σφίσι φανερῶς ἤχθοντο), δεινῶς ἡ γερουσία ἠγανάκτησεν, ὥστε ποτὲ μεταξὺ μαχομένων αὐτῶν ἐξαναστῆναι. καὶ τότε μὲν οὕτω διελύθησαν, αὖθις δὲ ἐπειδὴ τὰ αὐτὰ ἐγίγνετο, τὰς στολὰς καθάπερ ἐν συμφορᾷ τινι μετεκδῦναι ἐψηφίσαντο, καίτοι τοῦ Κάτωνος ἔκ τε τοῦ συνεδρίου, ἐπειδήπερ ἀντιλέγων οὐδὲν ἤνυσεν, ἐκπηδήσαντος. … ὅπως μηδὲν τελεσθείη· εἰ γάρ τις τῶν μὴ βουλευόντων ἔνδον ἦν, οὐδεμία ψῆφος αὐτοῖς ἐδίδοτο. ἐκείνους τε γὰρ προαπαντήσαντες ἕτεροι δήμαρχοι ἐκώλυσαν ἐσελθεῖν, καὶ οὕτω τοῦτό τε τὸ δόγμα ἐκυρώθη, καὶ ἐχρηματίζετο ὅπως καὶ ἐς τὴν πανήγυριν τὴν τότε οὖσαν οἱ βουλευταὶ μὴ θεωρήσωσιν. ἐπεὶ δὲ καὶ πρὸς ἐκεῖνο ὁ Κάτων ἀνθίστατο, ἐξεπήδησαν ἀθρόοι, καὶ τὰ ἐσθήματα ἀλλαξάμενοι ἐπανῆλθον ὡς καὶ διὰ τοῦτ’ αὐτὸν καταπλήξοντες. καὶ ἐπειδὴ μηδ’ ὣς ἐμετρίαζεν, προῆλθον ἐς τὴν ἀγορὰν ἅμα πάντες, καὶ συνδραμόντος ἐπὶ τούτῳ τοῦ πλήθους ἐς πᾶν κατηφείας αὐτοὺς κατέστησαν, δημηγορῶν μὲν ὁ Μαρκελλῖνος καὶ τὰ παρόντα σφίσιν ὀδυρόμενος, ἐπιδακρύοντες δὲ οἱ ἄλλοι καὶ ἐπιστένοντες, ὥστε μηδένα μηδὲν ἀντιφθέγξασθαι. καὶ οἱ μὲν τοῦτο πράξαντες ἐς τὸ βουλευτήριον εὐθὺς ἐσῆλθον, γνώμην ἔχοντες ἐς τοὺς ὑπαιτίους τὴν ὀργὴν", "st": "39.28"}, {"sp": "N", "t": "ἀφεῖναι· Κλώδιος δὲ ἐν τούτῳ μεταπηδήσας αὖθις πρὸς τὸν Πομπήιον, καὶ τὰ ἐκείνου πάλιν ἀνθελόμενος ἐλπίδι τοῦ, εἴ τί οἱ τῶν τότε πραττομένων συγκατεργάσαιτο, πάνυ αὐτὸν ἰδιώσεσθαι, παρῆλθέ τε ἐς τὸν ὅμιλον ἐν τῇ καθηκούσῃ στολῇ, μηδὲν αὐτῆς πρὸς τὸ δόγμα μεταλλάξας, καὶ κατά τε τοῦ Μαρκελλίνου καὶ κατὰ τῶν ἄλλων ἐδημηγόρει. πολλῆς οὖν καὶ ἐπὶ τούτῳ ἀγανακτήσεως ὑπὸ τῶν βουλευτῶν γενομένης τὸ μὲν πλῆθος μεταξὺ λέγων ἐγκατέλιπε, πρὸς δὲ δὴ τὸ συνέδριον ᾅξας ὀλίγου διεφθάρη· τῆς γὰρ γερουσίας ἀπαντησάσης αὐτῷ εἴσω τε ἐσελθεῖν ἐκωλύθη, κἀν τούτῳ ὑπὸ ἱππέων περιστοιχισθεὶς διεσπάσθη ἄν, εἰ μὴ ἀνακραγόντος αὐτοῦ καὶ τὸν ὅμιλον ἐπιβοησαμένου προσέδραμον πολλοὶ πῦρ φέροντες, ὡς καὶ μετὰ τοῦ βουλευτηρίου σφᾶς καταπρήσοντες εἴ τι αὐτὸν ἐξεργάσαιντο. καὶ ὁ μὲν παρὰ τοσοῦτον ἐλθὼν ἀπολέσθαι", "st": "39.29"}, {"sp": "N", "t": "οὕτως ἐσώθη· Πομπήιος δὲ οὐδὲν τούτοις ἐκπλαγεὶς ἔς τε τὸ συνέδριόν ποτε ἐσεπήδησεν, ὑπεναντιούμενος αὐτῷ ψηφιεῖσθαι μέλλοντι, καὶ ἐκεῖνό τε κυρωθῆναι ἐκώλυσε, καὶ τοῦ Μαρκελλίνου μετὰ τοῦτο πυθομένου δημοσίᾳ αὐτοῦ εἰ ὄντως ἐπιθυμεῖ ὑπατεῦσαι, ἐλπίδι τοῦ κατοκνήσειν αὐτὸν σπουδαρχεῖν ὁμολογῆσαι, τῶν μὲν δικαίων ἀνδρῶν ἕνεκα οὐδὲν τῆς ἀρχῆς δεῖσθαι ἔφη, διὰ δὲ δὴ τοὺς ταραχώδεις καὶ σφόδρα αὐτῆς ἀντιποιεῖσθαι. ὡς οὖν τούτῳ φανερῶς ἐνέκειτο, καὶ ὁ Κράσσος ἐρωτηθεὶς καὶ αὐτὸς τὰ αὐτὰ οὐχ ὡμολόγησε μέν, οὐ μὴν οὐδ’ ἀπηρνήσατο, ἀλλ’ ὥσπερ εἰώθει διὰ μέσου ἐχώρησεν, εἰπὼν ὅτι πάνθ’ ὅσα τῷ κοινῷ συμφέροι πράξοι, κατέδεισαν ὅ τε Μαρκελλῖνος καὶ ἄλλοι πολλοὶ τήν τε παρασκευὴν αὐτῶν καὶ τὴν ἀντίταξιν, καὶ οὐδὲ ἀπήντων ἔτι ἐς τὸ βουλευτήριον. μὴ συλλεγομένου δὲ τοῦ καθήκοντος ἐκ τῶν νομίμων ἀριθμοῦ πρὸς τὸ ψηφισθῆναί τι περὶ τῶν ἀρχαιρεσιῶν, οὐδὲ χρηματισθῆναί τι ἀρχὴν περὶ αὐτῶν ἠδυνήθη, ἀλλὰ ὁ ἐνιαυτὸς οὕτω διέβη. οὐ μέντοι οὔτε τὴν ἐσθῆτα μετημπίσχοντο οὔτε ἐς τὰς πανηγύρεις ἐφοίτων, οὐκ ἐν τῷ Καπιτωλίῳ τῇ τοῦ Διὸς ἑορτῇ εἱστιάθησαν, οὐκ ἐπὶ τὰς ἀνοχὰς τὰς Λατίνας, δεύτερον τότε ὑπό τινος οὐκ ὀρθῶς πραχθέντος ποιουμένας, ἐς τὸ Ἀλβανὸν ἀφίκοντο, ἀλλ’ ὥσπερ δεδουλωμένοι, καὶ μήτ’ ἀρχὰς ἑλέσθαι μήτ’ ἄλλο τι πολιτικὸν πρᾶξαι ἐξουσίαν ἔχοντες, τὸ λοιπὸν τοῦ ἔτους διήγαγον.", "st": "39.30"}, {"sp": "N", "t": "καὶ μετὰ τοῦτο ὅ τε Πομπήιος καὶ ὁ Κράσσος ὕπατοι ἐκ μεσοβασιλείας ἀπεδείχθησαν, οὔτ’ ἄλλου τινὸς τῶν προεπηγγελκότων ἀπαντήσαντος, καὶ Λουκίου Δομιτίου, ὃς μέχρι τῆς τελευταίας ἡμέρας ἐσπουδάρχησεν, ὁρμήσαντος μὲν πρὸς τὴν ἐκκλησίαν οἴκοθεν ὑπὸ νύκτα, ἐπεὶ δ’ ὁ παῖς ὁ τὸν λύχνον οἱ προφέρων ἐσφάγη, δείσαντος καὶ μηκέτι περαιτέρω προχωρήσαντος. οὔτ’ οὖν ἀντιστάντος τινὸς τὴν ἀρχήν, καὶ προσέτι τοῦ Πουπλίου Κράσσου, ὃς υἱός τε τοῦ Μάρκου ἦν καὶ τότε τῷ Καίσαρι ὑπεστρατήγει, στρατιώτας ἐπ’ αὐτὸ τοῦτο ἐς τὴν Ῥώμην ἀγαγόντος, οὐ χαλεπῶς ᾑρέθησαν.", "st": "39.31"}, {"sp": "N", "t": "παραλαβόντες δ’ οὕτω τὴν ἡγεμονίαν τὰς λοιπὰς ἀρχὰς τοῖς ἐπιτηδείως σφίσιν ἔχουσι δοθῆναι ἐποίησαν, τὸν Κάτωνα τὸν Μᾶρκον κωλύσαντες στρατηγὸν ἀποδειχθῆναι· ὑπώπτευόν τε γὰρ αὐτὸν οὐκ ἀνέξεσθαι τὰ γιγνόμενα, καὶ οὐκ ἠθέλησαν ἰσχὺν αὐτῷ ἔννομον πρὸς τὰς ἀντιλογίας προσθεῖναι. καὶ ἡ μὲν τῶν στρατηγῶν κατάστασις (ὁ γὰρ Κάτων οὐδὲν βίαιον πρᾶξαι ἠξίωσεν) εἰρηναία ἐγένετο, περὶ δὲ τοὺς ἀγορανόμους τοὺς κουρουλίους σφαγαὶ συνέβησαν, ὥστε καὶ τὸν Πομπήιον πολλοῦ αἵματος ἀναπλησθῆναι. οὐ μὴν ἀλλ’ ἐκείνους μέν, τούς τε ἄλλους τοὺς ὑπὸ τοῦ δήμου αἱρουμένους, πρὸς τρόπου σφίσιν (αὐτοὶ γὰρ τὰς ἀρχαιρεσίας ἐποίουν) ἀπέδειξαν, τούς τε ἀγορανόμους τοὺς ἑτέρους καὶ τῶν δημάρχων τοὺς πλείους προσηταιρίσαντο· δύο δὲ δήμαρχοι, γάιός τε Ἀτέιος Καπίτων καὶ Πούπλιος Ἀκύλιος Γάλλος, οὐχ ὡμολόγησαν αὐτοῖς.", "st": "39.32"}, {"sp": "N", "t": "ὡς οὖν αἱ ἀρχαὶ κατέστησαν, εἴχοντο ὧν ἐφιεντο. καὶ αὐτοὶ μὲν οὐδένα οὔτε ἐν τῇ βουλῇ οὔτε ἐν τῷ δήμῳ λόγον ὑπὲρ αὐτῶν ἐποιήσαντο, ἀλλὰ καὶ πάνυ ἐπλάττοντο μηδενός σφων προσδεῖσθαι· Γάιος δὲ δὴ Τρεβώνιος δημαρχῶν ἔγραψε τῷ μὲν τήν τε Συρίαν καὶ τὰ πλησιόχωρα αὐτῆς, τῷ δὲ τὰς Ἰβηρίας (καὶ γάρ τι καὶ ἔναγχος ἐκεκίνηντο ) ἄρχειν ἐπὶ πέντε ἔτη δοθῆναι, στρατιώταις τε ὅσοις ἂν ἐθελήσωσι καὶ τῶν πολιτῶν καὶ τῶν συμμάχων χρωμένοις, καὶ πόλεμον καὶ εἰρήνην πρὸς οὓς ἂν βουληθῶσι ποιουμένοις. χαλεπῶς οὖν ἐπὶ τούτῳ πολλῶν, καὶ μάλιστα τῶν τοῦ Καίσαρος φίλων, ἐχόντων, ὅτι ἤμελλον ἐκεῖνοι, τυχόντες ὧν διῳκοῦντο, τὸν Καίσαρα μηκέτ’ ἐπὶ πολὺ τὴν ἀρχὴν ἕξοντα καθείρξειν, καὶ παρασκευαζομένων διὰ τοῦτο ἀντειπεῖν τινων τοῖς γεγραμμένοις, φοβηθέντες οἱ ὕπατοι μὴ διαμάρτωσιν ὧν ἔπραττον, προσεποιήσαντο αὐτοὺς ὥστε τὴν ἡγεμονίαν καὶ ἐκείνῳ τρία ἔτη πλείω, ὥς γε τἀληθὲς εὑρίσκεται, μηκῦναι. οὐ μέντοι καὶ ἐς τὸν δῆμόν τι ὑπὲρ αὐτοῦ πρότερον ἐσήνεγκαν πρὶν τὰ σφέτερα βεβαιώσασθαι. οἵ τε γὰρ τοῦ Καίσαρος ἐπιτήδειοι προκαταληφθέντες οὕτως ἡσύχασαν, καὶ τῶν ἄλλων τὸ μὲν πολὺ δουλωθὲν ὑπὸ τοῦ φόβου ἡσυχίαν ἤγαγον, ἀγαπῶντες εἰ καὶ", "st": "39.33"}, {"sp": "N", "t": "ὣς περισωθεῖεν, ὁ δὲ δὴ Κάτων καὶ ὁ Φαουώνιος ἠναντιοῦντο μὲν πᾶσι τοῖς πρασσομένοις ὑπ’ αὐτῶν, συνεργοὺς ἄλλους τέ τινας καὶ τοὺς δύο δημάρχους ἔχοντες, ἅτε δὲ ὀλίγοι πρὸς πολλοὺς ἀγωνιζόμενοι μάτην ἐπαρρησιάζοντο. καὶ ὁ μὲν Φαουώνιος μίαν ὥραν μόνην παρὰ τοῦ Τρεβωνίου πρὸς τὴν ἀντιλογίαν λαβών, κατέτριψεν αὐτὴν ὑπὲρ αὐτῆς τῆς τοῦ καιροῦ στενοχωρίας εἰκῇ βοῶν· ὁ δὲ δὴ Κάτων ἔτυχε μὲν ἐν δύο ὥραις δημηγορῆσαι, τραπόμενος δὲ πρὸς κατηγορίαν τῶν τε ἐν χερσὶ καὶ τῆς ὅλης καταστάσεως, ὥσπερ εἰώθει, κατανάλωσε τὸν καιρὸν πρὶν καὶ ὁτιοῦν τῶν προκειμένων εἰπεῖν, οὐχ ὅτι οὐκ ἐνεδέχετό τι καὶ περὶ ἐκείνων λεχθῆναι, ἀλλ’ ἵν’ ἔτι τι δημηγορῆσαι δοκῶν ἔχειν ὑπό τε τοῦ Τρεβωνίου σιγασθῇ καὶ αὐτῷ καὶ τοῦτ’ αὐτὸ ἐγκαλῇ, ἐπεὶ εὖ γε ἠπίστατο ὅτι οὐδ’ εἰ πάσῃ τῇ ἡμέρᾳ ἐκέχρητο, πεῖσαί τι ὧν ἐβούλετο ψηφίσασθαί σφας ἐδύνατο. οὐκοῦν οὔτε παραχρῆμα σιωπῆσαι κελευσθεὶς ἐπαύσατο, ἀλλὰ καὶ ἐξωσθεὶς καὶ ἑλκυσθεὶς ἐκ τοῦ συλλόγου ἐπανῆλθε, καὶ τὸ τελευταῖον καὶ ἐς τὸ οἴκημα ἐσαχθῆναι προσταχθεὶς οὐκ ἐμετρίασεν.", "st": "39.34"}, {"sp": "N", "t": "καὶ ἐκείνη μὲν ἡ ἡμέρα οὕτω κατετρίβη ὥστε μηδ’ εἰπεῖν ἀρχὴν μηδὲν τοὺς δημάρχους δυνηθῆναι· ἐν γάρ τοι ταῖς συνόδοις ταῖς τοῦ δήμου, ἐν αἷς γε καὶ ἐβουλεύοντο, πάσαις τοῖς ἰδιώταις πρὸ τῶν τὰς ἀρχὰς ἐχόντων ὁ λόγος ἐδίδοτο, τοῦ μηδένα αὐτῶν, ὡς ἔοικε, τῇ τοῦ κρείττονος γνώμῃ προκαταλαμβανόμενον ὑποστέλλεσθαί τι ὧν φρονοίη, ἀλλ’ ἐπὶ πάσης παρρησίας τὰ δοκοῦντα αὐτῷ λέγειν. φοβηθεὶς οὖν ὁ Γάλλος μή τις αὐτὸν ἐκ τῆς ἀγορᾶς τῇ ὑστεραίᾳ ἐξείρξῃ ἢ καὶ δεινότερόν τι ἐργάσηται, ἔς τε τὸ συνέδριον ἀφ’ ἑσπέρας ἐσῆλθε καὶ ἐν αὐτῷ ἐνυκτέρευσε, τῆς τε ἀσφαλείας ἕνεκα τῆς παρὰ τοῦ χωρίου, καὶ ὅπως ἐκεῖθεν ἅμα ἕῳ πρὸς τὸ πλῆθος ἐξέλθῃ. καὶ τοῦτον μὲν ὁ Τρεβώνιος μάτην ἐνταῦθα καὶ τὴν νύκτα καὶ τῆς ἡμέρας τὸ πλεῖον ἐνδιατρῖψαι ἐποίησε, πάσας τὰς θύρας τοῦ βουλευτηρίου κλείσας· τὸν δὲ Ἀτέιον τόν τε Κάτωνα καὶ τὸν Φαουώνιον καὶ τοὺς ἄλλους τοὺς μετ’ αὐτῶν ὄντας ἕτεροι, προκαταλαβόντες τῆς νυκτὸς τὸ τοῦ συλλόγου χωρίον, ἐξεῖργον. καὶ ἐπειδὴ ὁ μὲν Φαουώνιος καὶ ὁ Νίννιος διαλαθόντες πως ἔνδον ἐγένοντο, ὁ δὲ δὴ Κάτων καὶ ὁ Ἀτέιος ἐπαναβάντες τισὶ τῶν περιεστηκότων καὶ μετεωρισθέντες ὑπ’ αὐτῶν διοσημίαν, ὡς καὶ διαλύσοντές σφας, ἐπεφήμιζον, τούτους μὲν ἑκατέρους οἱ ὑπηρέται τῶν δημάρχων ἐξήλασαν, τοὺς δ’ ἄλλους τοὺς σὺν αὐτοῖς ὄντας κατετραυμάτισαν, καί τινας καὶ ἀπέκτειναν.", "st": "39.35"}, {"sp": "N", "t": "κυρωθέντος δὲ οὕτω τοῦ νόμου, καὶ τοῦ πλήθους ἀπαλλαττομένου ἤδη ἐκ τοῦ συλλόγου, παραλαβὼν ὁ Ατέιος τὸν Γάλλον αἵματος ἀνάπλεων (ἐκβιαζόμενος γὰρ ἐκ τοῦ συνεδρίου ἐπλήγη) παρήγαγέ τε ἐς τοὺς ἔτι παρόντας, καὶ ἐπιδείξας αὐτόν, καὶ ἐπειπὼν ὅσα εἰκὸς ἦν, δεινῶς σφας ἐξετάραξεν. αἰσθόμενοι οὖν τοῦθ’ οἱ ὕπατοι ἦλθόν τε διὰ ταχέων (ἐγγύθεν γάρ ποθεν τοῖς πραττομένοις ἐφήδρευον) καὶ καταφοβήσαντες αὐτούς, ἅτε καὶ χεῖρα οὐκ ὀλίγην ἔχοντες, εὐθύς τε ἐκκλησίαν συνήγαγον καὶ τὰ κατὰ τὸν Καίσαρα ἐπεψήφισαν, ἀντειπεῖν μὲν καὶ πρὸς ἐκεῖνα τῶν αὐτῶν πειραθέντων, οὐ μέντοι καὶ δυνηθέντων τι πρᾶξαι.", "st": "39.36"}, {"sp": "N", "t": "ταῦτά τε οὖν κυρωθῆναι ἐποίησαν, καὶ μετὰ τοῦτο πικρότερα ἐπιτίμια τοῖς δεκάζουσί τινας ἐπέταξαν, ὥσπερ τι αὐτοὶ ἔλαττον, ὅτι οὐ χρήμασιν ἀλλὰ βίᾳ τὴν ἀρχὴν εἰλήφεσαν, ἁμαρτόντες. ἐπεχείρησαν μὲν γὰρ καὶ τὰ ἀναλώματα τὰ κατὰ τὴν δίαιταν ἐπὶ μακρότατον προηγμένα συστεῖλαι, καίπερ ἐς πᾶν αὐτοὶ καὶ τρυφῆς καὶ ἁβρότητος προκεχωρηκότες, ἐκωλύθησαν δὲ ὑπὸ αὐτοῦ τούτου διανομοθετῆσαι. ὁ γὰρ Ὁρτήσιος φιλαναλωτὴς ἐν τοῖς μάλιστα ὢν ἔπεισεν αὐτούς, τό τε μέγεθος τῆς πόλεως ἐπεξιών, καὶ αὐτοὺς ἐπί τε τῇ οἴκοι πολυτελείᾳ καὶ ἐπὶ τῇ ἐς τοὺς ἄλλους μεγαλοφροσύνῃ ἐπαινῶν, καταβαλεῖν τὴν γνώμην, ἅτε καὶ συναγωνιστῇ τῶν λόγων τῷ βίῳ σφῶν χρώμενος. τήν τε γὰρ ἐναντίωσιν αἰδεσθέντες, καὶ προσέτι καὶ κατοκνήσαντες φθόνῳ τινὶ τοὺς ἄλλους, ὧν αὐτοὶ ἐποίουν, δοκεῖν ἀπείργειν, ἑκόντες ἀφῆκαν τὴν ἐσήγησιν.", "st": "39.37"}, {"sp": "N", "t": "κἀν ταῖς αὐταῖς ἡμέραις ὁ Πομπήιος τὸ θέατρον, ᾧ καὶ νῦν λαμπρυνόμεθα, καθιέρωσε, καὶ ἔν τε ἐκείνῳ θέαν καὶ μουσικῆς καὶ ἀγῶνος γυμνικοῦ κἀν τῷ ἱπποδρόμῳ καὶ ἵππων ἅμιλλαν καὶ θηρίων πολλῶν καὶ παντοδαπῶν σφαγὰς ἐποίησεν. λέοντές τε γὰρ πεντακόσιοι ἐν πέντε ἡμέραις ἀναλώθησαν, καὶ ἐλέφαντες ὀκτωκαίδεκα πρὸς ὁπλίτας ἐμαχέσαντο. καὶ αὐτῶν οἱ μὲν παραχρῆμα ἀπέθανον, οἱ δὲ οὐ πολλῷ ὕστερον. ἠλεήθησαν γάρ τινες ὑπὸ τοῦ δήμου παρὰ τὴν τοῦ Πομπηίου γνώμην, ἐπειδὴ τραυματισθέντες τῆς μάχης ἐπαύσαντο, καὶ περιιόντες τάς τε προβοσκίδας ἐς τὸν οὐρανὸν ἀνέτεινον καὶ ὠλοφύροντο οὕτως ὥστε καὶ λόγον παρασχεῖν ὅτι οὐκ ἄλλως ἐκ συντυχίας αὐτὸ ἐποίησαν, ἀλλὰ τούς τε ὅρκους οἷς πιστεύσαντες ἐκ τῆς Λιβύης ἐπεπεραίωντο ἐπιβοώμενοι καὶ τὸ δαιμόνιον πρὸς τιμωρίαν σφῶν ἐπικαλούμενοι. λέγεται γὰρ ὅτι οὐ πρότερον τῶν νεῶν ἐπέβησαν πρὶν πίστιν παρὰ τῶν ἀγόντων σφᾶς ἔνορκον λαβεῖν, ἦ μὴν μηδὲν κακὸν πείσεσθαι. καὶ τοῦτο μὲν εἴτ’ ὄντως οὕτως εἴτε καὶ ἄλλως πως ἔχει, οὐκ οἶδα· ἤδη γάρ τινες καὶ ἐκεῖνο εἶπον, ὅτι πρὸς τῷ τῆς φωνῆς τῆς πατριώτιδος αὐτοὺς ἐπαΐειν καὶ τῶν ἐν τῷ οὐρανῷ γιγνομένων συνιᾶσιν, ὥστε καὶ ἐν ταῖς νουμηνίαις, πρὶν ἐς ὄψιν τοῖς ἀνθρώποις τὴν σελήνην ἐλθεῖν, πρός τε ὕδωρ ἀείνων ἀφικνεῖσθαι κἀνταῦθα καθαρμόν τινά σφων ποιεῖσθαι. ἤκουσα μὲν δὴ ταῦτα, ἤκουσα δὲ καὶ ἐκεῖνο, ὅτι τὸ θέατρον τοῦτο οὐχ ὁ Πομπήιος ἐποίησεν, ἀλλὰ καὶ Δημήτριός τις ἀπελεύθερος αὐτοῦ, ἐκ τῶν χρημάτων ὧν συστρατευόμενός οἱ ἐπεπόριστο. ὅθενπερ καὶ τὴν ἐπωνυμίαν τοῦ ἔργου δικαιότατα αὐτῷ ἀνέθηκεν, ἵνα μὴ μάτην κακῶς ἀκούῃ ὅτι ἐξελεύθερος αὐτοῦ ἠργυρολόγησεν ὥστε καὶ ἐς τηλικοῦτον ἀνάλωμα ἐξικέσθαι.", "st": "39.38"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἐν μὲν τούτοις οὐ σμικρὰ τῷ δήμῳ ὁ Πομπήιος ἐχαρίσατο, τοὺς δὲ δὴ καταλόγους μετὰ τοῦ Κράσσου πρὸς τὰ ἐψηφισμένα σφίσι ποιούμενος πλεῖστον αὐτοὺς ἐλύπησε. καὶ τότε δὴ οἱ πολλοὶ μετεμέλοντο καὶ τόν τε Κάτωνα καὶ τοὺς ἄλλους ἐπῄνουν, ὥστε καὶ ἐκείνους διά τε τοῦτο, καὶ ὅτι δίκη τις λόγῳ μὲν τοῖς ὑποστρατήγοις σφῶν, ἔργῳ δὲ αὐτοῖς πρὸς τὰ γιγνόμενα παρὰ δημάρχων τινῶν ἐπήχθη, βίαιον μὲν μηδὲν τολμῆσαι, τὴν δὲ ἐσθῆτα ὡς ἐπὶ συμφορᾷ μετὰ τῶν ἐκ τῆς βουλῆς στασιωτῶν ἀλλάξασθαι. καὶ ταύτην μὲν εὐθὺς μεταγνόντες καὶ μηδὲ προφάσεώς τινος ἐπιλαβόμενοι μετεσκευάσαντο· τῶν δὲ δημάρχων τούς τε καταλόγους διαλῦσαι καὶ τὰς στρατείας αὐτῶν ἀναψηφίσαι ἐπιχειρούντων ὁ μὲν Πομπήιος οὐκ ἠγανάκτει (τούς τε γὰρ ὑπάρχους παραχρῆμα ἐξεπεπόμφει, καὶ αὐτὸς κατὰ χώραν, ὡς καὶ κωλυόμενος ἐξελθεῖν, ἄλλως διὰ τὴν ἐπιμέλειαν τοῦ σίτου παρεῖναι ὀφείλων, ἡδέως ἔμενεν, ἵνα τάς τ’ Ἰβηρίας ἅμα δι’ ἐκείνων κατάσχῃ καὶ τὰ ἐν τῇ Ῥώμῃ τῇ τε ἄλλῃ Ἰταλίᾳ δι’ ἑαυτοῦ ποιήσηται), ὁ δὲ δὴ Κράσσος, ἐπειδὴ μηδέτερον αὐτῷ τούτων ὑπῆρχεν, ἐπὶ τὴν ἐκ τῶν ὅπλων ἰσχὺν ἐτράπετο. οἱ οὖν δήμαρχοι ἰδόντες ὅτι ἡ παρρησία αὐτῶν ἄοπλος οὖσα ἀσθενὴς πρὸς τὸ κωλῦσαί τι πραχθῆναι ἦν, ἄλλως μὲν ἐσιώπων, ἐπεφήμιζον δὲ αὐτῷ πολλὰ καὶ ἄτοπα, ὥσπερ οὐ καὶ τῷ δημοσίῳ δι’ ἐκείνου καταρώμενοι, καὶ τοῦτο μὲν ἐν τῷ Καπιτωλίῳ τὰς εὐχὰς αὐτοῦ τὰς νομιζομένας ἐπὶ τῇ στρατείᾳ ποιουμένου καὶ διοσημίας τινὰς καὶ τέρατα διεθρόουν, τοῦτο δὲ ἐξορμωμένῳ οἱ πολλὰ καὶ δεινὰ ἐπηράσαντο. ἐπεχείρησε μὲν γὰρ ὁ Ἀτέιος καὶ ἐς τὸ δεσμωτήριον αὐτὸν ἐμβαλεῖν· ἀντιστάντων δὲ ἑτέρων δημάρχων μάχη τε αὐτῶν καὶ διατριβὴ ἐγένετο, κἀν τούτῳ ὁ Κράσσος ἔξω τοῦ πωμηρίου ἐξῆλθε. καὶ ὁ μέν, εἴτε ἐκ συντυχίας εἴτε καὶ ἐκ τῶν", "st": "39.39"}, {"sp": "N", "t": "ἀρῶν αὐτῶν, οὐκ ἐς μακρὰν ἐσφάλη, ὁ δὲ δὴ Καῖσαρ ἐν τῇ τοῦ Μαρκελλίνου τῇ τε Φιλίππου ὑπατείᾳ ἐπὶ Οὐενέτους ἐστράτευσεν. οἰκοῦσι δὲ πρὸς τῷ ὠκεανῷ, καὶ στρατιώτας τινὰς Ῥωμαίους πεμφθέντας ἐπὶ σῖτον συνέλαβον, καὶ μετὰ τοῦτο τοὺς πρέσβεις τοὺς ὑπὲρ ἐκείνων ἐλθόντας κατέσχον, ὅπως ἀντ’ αὐτῶν τοὺς ὁμήρους σφῶν ἀπολάβωσιν. ὁ οὖν Καῖσαρ τούτους μὲν οὐκ ἀπέδωκε, διαπέμψας δὲ ἄλλους ἄλλῃ, τοὺς μὲν τὰ τῶν συναφεστηκότων αὐτοῖς πορθεῖν, ἵνα μὴ συμβοηθήσωσιν ἀλλήλοις, τοὺς δὲ καὶ τὰ τῶν ἐνσπόνδων, μὴ καὶ αὐτοί τι παρακινήσωσι, φρουρεῖν, αὐτὸς ἐπὶ τοὺς Οὐενέτους ἤλασε, καὶ πλοῖα ἐν τῇ μεσογείᾳ, ἃ ἤκουεν ἐπιτήδεια πρὸς τὴν τοῦ ὠκεανοῦ παλίρροιαν εἶναι, κατασκευάσας διά τε τοῦ Λίγρου ποταμοῦ κατεκόμισε, καὶ πᾶσαν ὀλίγου τὴν ὡραίαν μάτην ἀνάλωσεν. αἵ τε γὰρ πόλεις ἐπ’ ἐρυμνῶν χωρίων ἱδρυμέναι ἀπρόσιτοι ἦσαν, καὶ ὁ ὠκεανὸς πάσας ὡς εἰπεῖν αὐτὰς περικλύζων ἄπορον μὲν τῷ πεζῷ ἄπορον δὲ καὶ τῷ ναυτικῷ τὴν προσβολήν, καὶ πλημμύρων καὶ ἀναρρέων, ἔν τε τῇ ἀμπώτιδι καὶ ἐν τῇ ῥαχίᾳ ἐποίει, ὥστε ἐν παντὶ τὸν Καίσαρα γενέσθαι, μέχρις οὗ Δέκιμος Βροῦτος ταχείαις οἱ ναυσὶν ἐκ τῆς ἔνδοθε θαλάσσης ἦλθεν. αὐτὸς μὲν γὰρ ὡς οὐδὲ ἐκείναις τι πράξων γνώμην εἶχεν, οἱ δὲ δὴ βάρβαροι καταφρονήσαντες τῆς τε σμικρότητος καὶ τῆς ἀσθενείας", "st": "39.40"}, {"sp": "N", "t": "τῶν σκαφῶν ἡττήθησαν. ταῦτα μὲν γὰρ πρὸς τὸ κουφότερον ὑπὲρ τοῦ ταχυναυτεῖν ἐς τὸν τῆς παρ’ ἡμῖν ναυτιλίας τρόπον ἐσκεύαστο, τὰ δὲ δὴ τῶν βαρβάρων, ἅτε ἐν τῇ συνεχείᾳ τῆς τοῦ ὠκεανοῦ παλιρροίας ἐπί τε τοῦ ξηροῦ πολλάκις ἵστασθαι καὶ πρὸς τὴν ἄνω τε καὶ κάτω αὐτοῦ διαρροὴν ἀντικαρτερεῖν ὀφείλοντα, πλεῖστόν σφων καὶ τῷ μεγέθει καὶ τῇ παχύτητι προεῖχεν. δι’ οὖν ταῦθ’ οἱ βάρβαροι, οἷα μήπω πρότερον τοιούτου ναυτικοῦ πεπειραμένοι, πρός τε τὴν ὄψιν τῶν νεῶν καὶ τὸ ἔργον αὐτῶν ἐν οὐδενὶ λόγῳ ἐποιήσαντο, καὶ εὐθὺς ναυλοχούσαις σφίσιν ἐπανήχθησαν ὡς καὶ δι’ ἐλαχίστου τοῖς κοντοῖς αὐτὰς καταποντώσοντες. ἐφέροντο δὲ ἀνέμῳ καὶ πολλῷ καὶ σφοδρῷ· καὶ γὰρ ἱστία δερμάτινα εἶχον, ὥστε πᾶσαν τὴν", "st": "39.41"}, {"sp": "N", "t": "τοῦ πνεύματος ἰσχὺν ἀπλήστως ἐσδέχεσθαι. ὁ οὖν Βροῦτος, τέως μὲν ἐκεῖνο ἐπέσπερχεν, οὐδ’ ἀνταναχθῆναι αὐτοῖς διά τε τὸ πλῆθος καὶ διὰ τὸ μέγεθος τῶν νεῶν τήν τε ἐκ τοῦ πνεύματος φορὰν καὶ τὴν ἐπιβολήν σφων ἐτόλμησεν, ἀλλὰ παρεσκευάζετο ὡς καὶ πρὸς τῇ γῇ τὰς προσβολὰς αὐτῶν ἀμυνούμενος καὶ τὰ σκάφη παντελῶς ἐκλείψων. ἐπεὶ δ’ ὅ τε ἄνεμος ἐξαπιναίως ἔπεσε καὶ τὸ κῦμα ἐστορέσθη, τά τε πλοῖα οὐκέθ’ ὁμοίως ὑπὸ τῶν κωπῶν ἐκινεῖτο, ἀλλ’ ἅτε καὶ καταβαρῆ ὄντα κατὰ χώραν τρόπον τινὰ εἱστήκει, τότε δὴ θαρσήσας ἀντανήχθη, καὶ προσπεσὼν αὐτοῖς πολλά σφας καὶ δεινὰ ἀδεῶς καὶ περιπλέων καὶ διεκπλέων, καὶ τοτὲ μὲν ἐμβάλλων τινὶ τοτὲ δὲ ἀνακρουόμενος, ὅπῃ τε καὶ ἐφ’ ὅσον ἤθελεν, εἰργάσατο, πολλαῖς τε πρὸς μίαν καὶ ἑτέρωθι ἴσαις πρὸς ἴσας, ἔστι δ’ ᾗ καὶ ἐλάσσοσι πρὸς πλείονας ἀσφαλῶς προσφερόμενος. ὅπου μὲν γὰρ κρείοττων αὐτῶν ἐν τῇ … προσηρτᾶτό σφισι, καὶ τὰς μὲν κατέδυεν ἀναρρηγνύς, ἐς δὲ τὰς πολλαχόθεν μετεκβαίνων ἔς τε χεῖρας τοῖς ἐπιβάταις ᾔει καὶ πολλοὺς ἐφόνευεν· εἰ δὲ καὶ καθ’ ὁτιοῦν ἐλαττοῖτο, ῥᾷστα ἀνεχώρει, ὥστε ἐπ’ αὐτῷ τὴν πλεονεξίαν", "st": "39.42"}, {"sp": "N", "t": "ἀεὶ εἶναι. οἱ γὰρ βάρβαροι μήτε τοξείᾳ χρώμενοι, μήτε λίθους, ὡς οὐδὲν αὐτῶν δεησόμενοι, προπαρασκευάσαντες, εἰ μέν τίς σφισιν ὁμόσε ἐχώρησε, τρόπον τινὰ ἀπεμάχοντο, τοὺς δ’ ὀλίγον σφῶν ἀφεστηκότας οὐκ εἶχον ὅ τι ποιήσωσιν. αὐτοί τε οὖν ἐτιτρώσκοντο καὶ ἀπέθνησκον καὶ οἱ μηδὲ ἀμύνασθαί τινα δυνάμενοι, καὶ τὰ σκάφη τὰ μὲν ἀνερρήγνυτο ἐμβαλλόμενα τὰ δὲ κατεπίμπρατο ὑφαπτόμενα· ἄλλα ἀναδούμενα ὥσπερ κενὰ ἀνδρῶν εἵλκετο. ὁρῶντες δὲ ταῦθ’ οἱ λοιποὶ ἐπιβάται οἱ μὲν ἀπεκτίννυσάν σφας, μὴ καὶ ζῶντες ἁλῶσιν, οἱ δὲ ἐς τὴν θάλασσαν ἐξεπήδων, ὡς καὶ δι’ ἐκείνης ἤτοι τῶν πολεμίων νεῶν ἐπιβησόμενοι ἢ πάντως γε οὐχ ὑπὸ τῶν Ῥωμαίων ἀπολούμενοι. προθυμίᾳ μὲν γὰρ καὶ τόλμῃ οὐδὲν αὐτῶν διέφερον, τῷ δὲ δὴ σταδίῳ τῶν σκαφῶν προδιδόμενοι δεινῶς ἤσχαλλον. ὅπως γὰρ δὴ μηδ’ αὖθίς ποτε πνεῦμα τι ταῖς ναυσὶν ἐπιγενόμενον κινήσειεν αὐτάς, δορυδρέπανα πόρρωθέν σφισιν οἱ Ῥωμαῖοι ἐπέφερον, καὶ τά τε σχοινία αὐτῶν διέτεμνον καὶ τὰ ἱστία διέσχιζον. πεζομαχεῖν δὲ τρόπον τινὰ ἐν πλοίοις πρὸς ναυμαχοῦντας ἀναγκαζόμενοι πάμπολλοι μὲν αὐτοῦ ταύτῃ ἐφθάρησαν, πάντες δὲ οἱ περιλιπεῖς ἑάλωσαν· καὶ αὐτῶν τοὺς λογιμωτάτους ὁ Καῖσαρ ἀποσφάξας τοὺς ἄλλους ἐπώλησε.", "st": "39.43"}, {"sp": "N", "t": "καὶ μετὰ τοῦτο ἐπί τε Μωρίνους καὶ ἐπὶ Μεναπίους ὁμόρους σφίσιν ὄντας ἐστράτευσε, προσκαταπλήξειν τε αὐτοὺς ἐκ τῶν προκατειργασμένων καὶ ῥᾳδίως αἱρήσειν ἐλπίσας. οὐ μέντοι καὶ ἐχειρώσατό τινας· οὔτε γὰρ πόλεις ἔχοντες ἀλλ’ ἐν καλύβαις διαιτώμενοι, καὶ τὰ τιμιώτατα ἐς τὰ λασιώτατα τῶν ὀρῶν ἀνασκευασάμενοι, πολὺ πλείω τοὺς προσμίξαντάς σφισι τῶν Ῥωμαίων ἐκάκωσαν ἢ αὐτοὶ ἔπαθον. ἐπεχείρησε μὲν γὰρ ὁ Καῖσαρ καὶ ἐς αὐτὰ τὰ ὄρη τὴν ὕλην τέμνων προχωρῆσαι, ἀπειπὼν δὲ διά τε τὸ μέγεθος αὐτῶν καὶ διὰ τὸ πρὸς χειμῶνα εἶναι ἀπανέστη.", "st": "39.44"}, {"sp": "N", "t": "ἔτι δ’ αὐτοῦ ἐν τῇ Οὐενετίᾳ ὄντος Κύιντος Τιτούριος Σαβῖνος ὑποστράτηγός τε ἐστάλη ἐπὶ Οὐενέλλους, ὧν ἡγεῖτο Οὐιριδοῦιξ, καὶ τὰ μὲν πρῶτα καὶ πάνυ τὸ πλῆθος αὐτῶν κατεπλάγη, ὥστ’ ἀγαπᾶν ἂν τό γε ἔρυμα διασώσηται, ἔπειτα δὲ αἰσθόμενός σφας θρασύτερον μὲν ἀπὸ τούτου διακειμένους, οὐ μὴν καὶ τῷ ἔργῳ δεινοὺς ὄντας, οἷά που οἱ πολλοὶ τῶν βαρβάρων ἐν ταῖς ἀπειλαῖς πᾶν τὸ φοβερὸν διὰ κενῆς ἐπικομποῦσιν, ἀνεθάρσησε. καὶ ἐκ μὲν τοῦ προφανοῦς οὐδ’ οὕτως ἐτόλμησέ σφισι συνενεχθῆναι (τῷ γὰρ πλήθει πολὺ κατείργετο), πρὸς δὲ δὴ τὸ τάφρευμα τὸ ἑαυτοῦ μετεώρου τοῦ χωρίου ὄντος ὑπηγάγετο αὐτοὺς ἀπερισκέπτως προσβαλεῖν· τῶν γὰρ συμμάχων τινὰ ὁμοφωνοῦντά σφισιν ὑπὸ τὴν ἐσπέραν ὡς αὐτόμολον πέμψας, ἔπεισεν αὐτοὺς ὅτι ὅ τε Καῖσαρ ἐπταικὼς εἴη … καὶ οὕτω πιστεύσαντες ἀπερισκέπτως ἐκεῖνοι (πάνυ γάρ τι διακορεῖς καὶ τῆς τροφῆς καὶ τοῦ ποτοῦ ἦσαν) εὐθὺς ἐπὶ τοὺς Ῥωμαίους, μὴ καὶ φθάσωσί σφας φυγόντες, ὥρμησαν, καὶ ἔδει γὰρ μηδὲ πυρφόρον τῷ λόγῳ αὐτῶν σωθῆναι, φρύγανα καὶ ξύλα τὰ μὲν ἀράμενοι τὰ δὲ ἐφελκόμενοι ὡς καὶ καταπρήσοντες αὐτούς, πρός τε τὸ ὄρθιον προσέβαλον καὶ σπουδῇ προσανέβαινον, μηδενός σφισιν ἐναντιουμένου· ὁ γὰρ Σαβῖνος οὐκ ἐκινήθη πρὶν ἐντὸς τῆς ἐπικρατείας αὐτοῦ τοὺς πλείους αὐτῶν γενέσθαι. τότε δὲ ἐπικατέδραμέ σφισιν ἁπανταχόθεν ἅμα ἀπροσδόκητος, καὶ τοὺς πρώτους ἐκπλήξας κατήραξε κατὰ τοῦ πρανοῦς ἅπαντας, κἀνταῦθα αὐτοὺς ἐν τῇ ἀναστροφῇ περί τε ἀλλήλοις καὶ περὶ τοῖς ξύλοις σφαλλομένους κατέκοψεν οὕτως ὥστε μηδένα αὐτῶν μηδὲ τῶν ἄλλων ἔτ’ ἀντᾶραι. ἄπληστοι γὰρ ἀλογίστως οἱ Γαλάται ἐς πάνθ’ ὁμοίως ὄντες οὔτε τὸ θαρσοῦν σφων οὔτε τὸ δεδιὸς μετριάζουσιν, ἀλλὰ ἔκ τε τούτου πρὸς δειλίαν ἀνέλπιστον καὶ ἐξ ἐκείνου πρὸς θάρσος προπετὲς ἐκπίπτουσιν.", "st": "39.45"}, {"sp": "N", "t": "ὑπὸ δὲ δὴ τὰς αὐτὰς ἡμέρας καὶ ὁ Κράσσος ὁ Πούπλιος, τοῦ Κράσσου τοῦ Μάρκου παῖς, τὴν Ἀκυϊτανίαν ὀλίγου πᾶσαν κατεστρέψατο· Γαλάται γὰρ καὶ αὐτοὶ ὄντες τῇ τε Κελτικῇ προσοικοῦσι καὶ παρ’ αὐτὸ τὸ Πυρηναῖον ἐς τὸν ὠκεανὸν καθήκουσιν. ἐπ’ οὖν τούτους ὁ Κράσσος στρατεύσας Σωτιάτας τε μάχῃ ἐκράτησε καὶ πολιορκίᾳ εἷλεν, ὀλίγους μὲν ἐν ὁμολογίᾳ τινὶ ἐξ ἀπάτης ἀποβαλών, ἰσχυρῶς δέ σφας καὶ περὶ αὐτοῦ τούτου ἀμυνάμενος· καὶ ἑτέρους τινὰς ἰδὼν ἠθροισμένους τε καὶ στρατιώτας ἐκ τῆς Ἰβηρίας Σερτωριείους ἔχοντας, καὶ μετ’ αὐτῶν στρατηγικώτερον ἢ προπετέστερον τῷ πολέμῳ χρωμένους, ὡς καὶ τῇ ἀπορίᾳ τῶν τροφῶν δι’ ὀλίγου σφῶν ἐκ τῆς γῆς ἐκχωρησόντων, προσεποιήσατό τε αὐτοὺς δεδιέναι, καὶ καταφρονηθεὶς οὐχ ὑπηγάγετο μὲν οὐδ’ ὣς ἐς χεῖράς οἱ ἐλθεῖν, ἀδεῶς δ’ ἐς ὕστερον ἔχουσί σφισι προσέβαλεν ἐξαίφνης ἀνέλπιστος. καὶ ταύτῃ μὲν ᾗ προσέμιξεν οὐδὲν εἰργάσατο (ἐπεκδραμόντες γὰρ οἱ βάρβαροι ἰσχυρῶς ἠμύνοντο), ἐνταῦθα δὲ δὴ τῆς δυνάμεως αὐτοῖς οὔσης περιέπεμψέ τινας ἐς τὰ ἐπὶ θάτερα τοῦ στρατοπέδου σφῶν, καὶ τοῦτό τε ἔρημον ἀνδρῶν κατέσχεν, καὶ τοῖς μαχομένοις δι’ αὐτοῦ κατὰ νώτου ἐπεγένετο. καὶ οὕτως ἐκεῖνοί τε πάντες ἐφθάρησαν, καὶ οἱ λοιποὶ πλὴν ὀλίγων ἀκονιτὶ ὡμολόγησαν.", "st": "39.46"}, {"sp": "N", "t": "ταῦτα μὲν ἐν τῷ θέρει ἐπράχθη, χειμαζόντων δὲ τῶν Ῥωμαίων ἐν τῇ φιλίᾳ Τέγκτηροί τε καὶ Οὐσιπέται, Κελτικὰ γένη, τὸ μέν τι καὶ πρὸς Σουήβων ἐκβιασθέντες τὸ δὲ καὶ πρὸς τῶν Γαλατῶν ἐπικληθέντες, τόν τε Ῥῆνον διέβησαν καὶ ἐς τὴν τῶν Τρηουήρων ἐνέβαλον. κἀνταῦθα τὸν Καίσαρα εὑρόντες καὶ φοβηθέντες ἔπεμψαν πρὸς αὐτὸν σπονδάς τε ποιούμενοι καὶ χώραν αἰτοῦντες, ἢ σφίσι γε ἐπιτραπῆναί τινα ἀξιοῦντες λαβεῖν. ὡς δ’ οὐδενὸς ἔτυχον, τὸ μὲν πρῶτον ἐθελονταὶ οἴκαδε ἐπανήξειν ὑπέσχοντο καὶ διοκωχὴν ᾐτήσαντο· ἔπειτα δὲ ἱππέας αὐτοῦ ὀλίγους προσιόντας ἰδόντες οἱ ἐν τῇ ἡλικίᾳ σφῶν ὄντες κατεφρόνησάν τε αὐτῶν καὶ μετέγνωσαν, κἀκ τούτου ἐπισχόντες τῆς πορείας ἐκείνους τε μὴ προσδεχομένους ἐκακωσαν, καὶ ἐπαρθέντες ἐπὶ", "st": "39.47"}, {"sp": "N", "t": "τούτῳ εἴχοντο τοῦ πολέμου. καὶ αὐτῶν οἱ πρεσβύτεροι καταγνόντες πρός τε τὸν Καίσαρα καὶ παρὰ τὴν γνώμην σφῶν ἦλθον, καὶ ἐδέοντο αὐτοῦ συγγνῶναί σφισι, τὴν αἰτίαν ἐς ὀλίγους τρέποντες. ὁ δὲ τούτους μὲν ὡς καὶ ἀπόκρισίν τινα αὐτοῖς οὐκ ἐς μακρὰν δώσων κατέσχεν, ὁρμήσας δὲ ἐπὶ τοὺς ἄλλους ἐν ταῖς σκηναῖς ὄντας ἐπέστη τέ σφισι μεσημβριάζουσι καὶ μηδὲν πολέμιον, ἅτε ἐκείνων παρ’ αὐτῷ ὄντων, ὑποτοπουμένοις, καὶ ἐσπηδήσας ἐς αὐτὰς παμπληθεῖς τῶν πεζῶν, οὐδὲ τὰ ὅπλα ἀνελέσθαι φθάσαντας, ἀλλὰ καὶ περὶ ταῖς ἁμάξαις ὑπό τε τῶν γυναικῶν καὶ ὑπὸ τῶν παίδων ἀναμὶξ ὄντων ταραττομένους, κατεφόνευσε. τούς τε ἱππέας ἀπόντας τότε, καὶ παραχρῆμα, ὡς ἐπύθοντο τὸ γεγονός, πρός τε τὰ οἰκεῖα ἤθη ὁρμήσαντας καὶ πρὸς Συγάμβρους ἀποχωρήσαντας, πέμψας ἐξῄτησεν, οὐχ ὅτι καὶ ἐκδοθήσεσθαί σφας προσεδόκησεν (οὐ γάρ που οὕτως οἱ πέραν τοῦ Ῥήνου τοὺς Ῥωμαίους ἐφοβοῦντο ὥστε καὶ τὰ τοιαῦτα αὐτῶν ἀκούειν), ἀλλ’ ὅπως ἐπὶ τῇ προφάσει ταύτῃ καὶ ἐκεῖνον διαβαίη. αὐτός τε γὰρ ὃ μηδείς πω πρότερον τῶν ὁμοίων οἱ ἐπεποιήκει, δεινῶς πρᾶξαι ἐγλίχετο, καὶ τοὺς Κελτοὺς πόρρωθεν ἐκ τῆς Γαλατίας ἀνείρξειν, ἅτε καὶ ἐς τὴν οἰκείαν αὐτῶν ἐσβαλών, προσεδόκησεν. ὡς οὖν οὔτε οἱ ἱππῆς ἐξεδίδοντο, καὶ οἱ Οὔβιοι ὅμοροί τε τοῖς Συγάμβροις οἰκοῦντες καὶ διάφοροι αὐτοῖς ὄντες ἐπεκαλέσαντο αὐτόν, διέβη μὲν τὸν ποταμὸν γεφυρώσας, εὑρὼν δὲ τούς τε Συγάμβρους ἐς τὰ ἐρυμνὰ ἀνακεκομισμένους καὶ τοὺς Σουήβους συστρεφομένους ὡς καὶ βοηθήσοντάς σφισιν ἀνεχώρησεν ἐντὸς ἡμερῶν εἴκοσιν.", "st": "39.48"}, {"sp": "N", "t": "ὁ δὲ δὴ Ῥῆνος ἀναδίδωσι μὲν ἐκ τῶν Ἄλπεων τῶν Κελτικῶν, ὀλίγον ἔξω τῆς Ῥαιτίας, προχωρῶν δὲ ἐπὶ δυσμῶν ἐν ἀριστερᾷ μὲν τήν τε Γαλατίαν καὶ τοὺς ἐποικοῦντας αὐτήν, ἐν δεξιᾷ δὲ τοὺς Κελτοὺς ἀποτέμνεται, καὶ τελευτῶν ἐς τὸν ὠκεανὸν ἐμβάλλει. οὗτος γὰρ ὁ ὅρος, ἀφ’ οὗ γε καὶ ἐς τὸ διάφορον τῶν ἐπικλήσεων ἀφίκοντο, δεῦρο ἀεὶ νομίζεται, ἐπεὶ τὸ γε πάνυ ἀρχαῖον Κελτοὶ ἑκάτεροι οἱ ἐπ’ ἀμφότερα τοῦ ποταμοῦ οἰκοῦντες ὠνομάζοντο.", "st": "39.49"}, {"sp": "N", "t": "ὁ οὖν Καῖσαρ τόν τε Ῥῆνον πρῶτος τότε Ῥωμαίων διέβη, καὶ ἐς Βρεττανίαν μετὰ ταῦτα, τοῦ τε Πομπηίου καὶ τοῦ Κράσσου ὑπατευόντων, ἐπεραιώθη. ἡ δὲ δὴ χώρα αὕτη ἀπέχει μὲν τῆς ἠπείρου τῆς Βελγικῆς κατὰ Μωρίνους σταδίους πεντήκοντα καὶ τετρακοσίους τὸ συντομώτατον, παρήκει δὲ παρά τε τὴν λοιπὴν Γαλατίαν καὶ παρὰ τὴν Ἰβηρίαν ὀλίγου πᾶσαν, ἐς τὸ πέλαγος ἀνατείνουσα. καὶ τοῖς μὲν πάνυ πρώτοις καὶ Ἑλλήνων καὶ Ῥωμαίων οὐδ’ ὅτι ἔστιν ἐγιγνώσκετο, τοῖς δὲ ἔπειτα ἐς ἀμφισβήτησιν εἴτε ἤπειρος εἴτε καὶ νῆσος εἴη ἀφίκετο· καὶ πολλοῖς ἐφ’ ἑκάτερον, εἰδόσι μὲν οὐδὲν ἅτε μήτ’ αὐτόπταις μήτ’ αὐτηκόοις τῶν ἐπιχωρίων γενομένοις, τεκμαιρομένοις δὲ ὡς ἕκαστοι σχολῆς ἢ καὶ φιλολογίας εἶχον, συγγέγραπται. προϊόντος δὲ δὴ τοῦ χρόνου πρότερόν τε ἐπ’ Ἀγρικόλου ἀντιστρατήγου καὶ νῦν ἐπὶ Σεουήρου αὐτοκράτορος νῆσος οὖσα σαφῶς ἐλήλεγκται.", "st": "39.50"}, {"sp": "N", "t": "ἐς ταύτην οὖν τότε ὁ Καῖσαρ, ἐπειδὴ τά τε ἄλλα τὰ τῶν Γαλατῶν ἡσύχαζε καὶ τοὺς Μωρίνους προσεποιήσατο, ἐπεθύμησε διαβῆναι. καὶ τὸν μὲν διάπλουν καθ’ ὃ μάλιστα ἐχρῆν μετὰ τῶν πεζῶν ἐποιήσατο, οὐ μέντοι καὶ ᾗ ἔδει προσέσχεν· οἱ γὰρ Βρεττανοὶ τὸν ἐπίπλουν αὐτοῦ προπυθόμενοι τὰς κατάρσεις ἁπάσας τὰς πρὸς τῆς ἠπείρου οὔσας προκατέλαβον. ἄκραν οὖν τινα προέχουσαν περιπλεύσας ἑτέρωσε παρεκομίσθη· κἀνταῦθα τοὺς προσμίξαντάς οἱ ἐς τὰ τενάγη ἀποβαίνοντι νικήσας, ἔφθη τῆς γῆς κρατήσας πρὶν τὴν πλείω συμβοήθειαν ἐλθεῖν, καὶ μετὰ ταῦτα καὶ ἐκείνους προσβαλόντας ἀπεώσατο. καὶ ἔπιπτον μὲν οὐ πολλοὶ τῶν βαρβάρων (ἁρματηλάται τε γὰρ ὄντες καὶ ἱππῆς ῥᾳδίως τοὺς Ῥωμαίους, μηδέπω τοῦ ἱππικοῦ αὐτοῖς παρόντος, διέφυγον), ἐκπλαγέντες δὲ πρός τε τὰ ἐκ τῆς ἠπείρου περὶ αὐτῶν ἀγγελλόμενα, καὶ ὅτι περαιωθῆναί τε ὅλως ἐτόλμησαν καὶ ἐπιβῆναι τῆς χώρας ἠδυνήθησαν, πέμπουσι πρὸς τὸν Καίσαρα τῶν Μωρίνων τινάς, φίλων σφίσιν ὄντων, ἐπικηρυκευόμενοι. καὶ τότε μὲν", "st": "39.51"}, {"sp": "N", "t": "ὁμήρους αἰτήσαντι αὐτῷ δοῦναι ἠθέλησαν, πονησάντων δὲ ἐν τούτῳ τῶν Ῥωμαίων ὑπὸ χειμῶνος καὶ τῷ παρόντι ναυτικῷ καὶ τῷ ἀφικνουμένῳ καὶ μετέγνωσαν, καὶ ἐκ μὲν τοῦ προφανοῦς οὐκ ἐπέθεντο αὐτοῖς (τὸ γὰρ στρατόπεδον ἰσχυρῶς ἐφυλάσσετο), δεξάμενοι δέ τινας ὡς καὶ ἐς φιλίαν τὴν χώραν σφῶν πρὸς κομιδὴν τῶν ἐπιτηδείων πεμφθέντας, αὐτούς τε πλὴν ὀλίγων ἔφθειραν (ὁ γὰρ Καῖσαρ διὰ ταχέων τοῖς λοιποῖς ἐπήμυνε) καὶ μετὰ τοῦτο καὶ πρὸς αὐτὸ τὸ ἔρυμα αὐτῶν προσέβαλον. καὶ ἔπραξαν μὲν οὐδέν, ἀλλὰ καὶ κακῶς ἀπήλλαξαν· οὐ μέντοι καὶ ἐς ὁμολογίαν ἦλθον πρὶν πολλάκις σφαλῆναι. καὶ γὰρ ὁ Καῖσαρ ἄλλως μὲν οὐκ εἶχε γνώμην σπείσασθαι σφίσιν· ἐπεὶ δὲ ὅ τε χειμὼν προσῄει, καὶ οὐχ ἱκανὴν τὴν παροῦσαν δύναμιν περιεβέβλητο ὥστε καὶ ἐν αὐτῷ πολεμῆσαι, ἥ τε κομιζομένη ἔσφαλτο, καὶ οἱ Γαλάται πρὸς τὴν ἀπουσίαν αὐτοῦ ἐνεωτέρισαν, καὶ ἄκων αὐτοῖς συνηλλάγη, ὁμήρους καὶ τότε πλείους αἰτήσας μέν, λαβὼν δὲ ὀλίγους.", "st": "39.52"}, {"sp": "N", "t": "καὶ ὁ μὲν ἐς τὴν ἤπειρον ἀναπλεύσας τὰ ταραχθέντα καθίστατο, μηδὲν ἐκ τῆς Βρεττανίας μήτε ἑαυτῷ μήτε τῇ πόλει προσκτησάμενος πλὴν τοῦ ἐστρατευκέναι ἐπ’ αὐτοὺς δόξαι. τούτῳ γὰρ καὶ αὐτὸς ἰσχυρῶς ἐσεμνύνετο καὶ οἱ οἴκοι Ῥωμαῖοι θαυμαστῶς ἐμεγαλύνοντο· ἐμφανῆ τε γὰρ τὰ πρὶν ἄγνωστα καὶ ἐπιβατὰ τὰ πρόσθεν ἀνήκουστα ὁρῶντές σφισι γεγονότα, τήν τε μέλλουσαν ἐξ αὐτῶν ἐλπίδα ὡς καὶ παροῦσαν ἔργῳ ἐλάμβανον, καὶ πάνθ’ ὅσα καταπράξειν προσεδέχοντο ὡς καὶ ἔχοντες ἤδη ἠγάλλοντο. καὶ οἱ μὲν διὰ ταῦτα ἱερομηνίας ἐπὶ εἴκοσιν", "st": "39.53"}, {"sp": "N", "t": "ἡμέρας ἀγαγεῖν ἐψηφίσαντο· ἐν ᾧ δὲ ἐκεῖνα ἐγίγνετο, καὶ ἡ Ἰβηρία ἐκινήθη, διὸ καὶ τῷ Πομπηίῳ προσετάχθη. ἐπαναστάντες γάρ τινες καὶ Οὐακκαίους προστησάμενοι μάχῃ μὲν ὑπὸ τοῦ Νέπωτος τοῦ Μετέλλου, ἀπαράσκευοι ἔτ’ ὄντες, ἡττήθησαν, πολιορκοῦντι δ’ αὐτῷ Κλουνίαν ἐπελθόντες ἀμείνους ἐγένοντο, καὶ ἐκείνην μὲν περιεποιήσαντο, ἑτέρωθι δὲ ἐσφάλησαν, οὐ μὴν ὥστε καὶ δι’ ὀλίγου δουλωθῆναι. τῷ γὰρ πλήθει πολὺ τῶν ἐναντίων περιῆσαν, ὥστε τὸν Νέπωτα ἀγαπᾶν ἂν τὴν ἡσυχίαν ἀκινδύνως ἄγῃ.", "st": "39.54"}, {"sp": "N", "t": "κατὰ δὲ δὴ τὸν αὐτὸν τοῦτον χρόνον καὶ ὁ Πτολεμαῖος, καίτοι τῶν Ῥωμαίων τήν τε ἐπικουρίαν ἀπεψηφισμένων καὶ πρὸς τὰς δωροδοκίας τὰς ὑπ’ αὐτοῦ γενομένας δεινῶς ἔτι καὶ τότε διακειμένων, κατήχθη καὶ τὴν βασιλείαν ἐκομίσατο. ἔπραξαν δὲ τοῦτο ὅ τε Πομπήιος καὶ ὁ Γαβίνιος· τοσοῦτον γὰρ αἵ τε δυναστεῖαι καὶ αἱ τῶν χρημάτων περιουσίαι καὶ παρὰ τὰ ψηφίσματα τά τε τοῦ δήμου καὶ τὰ τῆς βουλῆς ἴσχυσαν, ὥστε ἐπιστείλας μὲν ὁ Πομπήιος τῷ Γαβινίῳ τῆς Συρίας τότε ἄρχοντι, στρατεύσας δὲ ἐκεῖνος, ὁ μὲν τῇ χάριτι ὁ δὲ τῇ δωροληψίᾳ καὶ ἄκοντος αὐτὸν τοῦ κοινοῦ κατήγαγον, μηδὲν μήτε ἐκείνου μήτε τῶν τῆς Σιβύλλης χρησμῶν φροντίσαντες. καὶ ἐκρίθη μὲν ὕστερον ἐπὶ τούτῳ ὁ Γαβίνιος, οὐχ ἐάλω δὲ διά τε τὸν Πομπήιον καὶ διὰ τὰ χρήματα· οὕτω γάρ που τὰ πράγματα τοῖς τότε Ῥωμαίοις συνεκέχυτο ὥστε ἀπὸ πολλῶν ὧν ἐδωροδόκησε σμικρὰ ἄττα τῶν τε ἀρχόντων τινὲς καὶ τῶν δικαστῶν παρ’ αὐτοῦ λαβόντες οὔτε τοῦ προσήκοντός τι προετίμησαν, καὶ προσέτι καὶ τοὺς ἄλλους κακουργεῖν ὑπὲρ χρημάτων ἐξεδίδαξαν ὡς καὶ τὴν τιμωρίαν ῥᾳδίως ἐξωνεῖσθαι δυναμένους. τότε μὲν οὖν διὰ ταῦτα ἀφείθη, αὖθις δὲ ἐπί τε ἑτέροις τισί, καὶ ὅτι πλέον ἢ μυρίας ἐκ τῆς ἀρχῆς μυριάδας ἥρπασε, κριθεὶς ἑάλω. καὶ ἐκείνῳ τε τοῦτο παραδοξότατον συνέβη (τῆς τε γὰρ προτέρας δίκης διὰ τὰ χρήματα ἀπελύθη, καὶ ἐπὶ τούτοις δι’ ἐκείνην ὅτι μάλιστα κατεδικάσθη ) καὶ τῷ Πομπηίῳ, ὅτι τὸ μὲν πρότερον, καίτοι πόρρω που ὤν, ἐρρύσατο τὸν Γαβίνιον διὰ τῶν ἑταίρων, τότε δὲ ἔν τε τῷ προαστείῳ ὢν καὶ τρόπον τινὰ καὶ ἐν τῷ δικαστηρίῳ αὐτῷ παρὼν οὐδὲν ἤνυσεν.", "st": "39.55"}, {"sp": "N", "t": "ἔσχε δὲ ὧδε. ὁ Γαβίνιος πολλὰ μὲν καὶ τὴν Συρίαν ἐκάκωσεν, ὥστε καὶ τῶν λῃστικῶν, ἃ καὶ τότε ἤκμαζε, πολὺ πλείω σφίσι λυμήνασθαι, πάντα δὲ δὴ τὰ αὐτόθεν λήμματα ἐλάχιστα εἶναι νομίσας τὸ μὲν πρῶτον ἐνόει καὶ παρεσκευάζετο ὡς καὶ ἐπὶ τοὺς Πάρθους τόν τε πλοῦτον αὐτῶν στρατεύσων. τοῦ γὰρ Φραάτου ὑπὸ τῶν παίδων δολοφονηθέντος Ὀρώδης τήν τε βασιλείαν αὐτοῦ διεδέξατο, καὶ Μιθριδάτην τὸν ἀδελφὸν ἐκ τῆς Μηδίας, ἧς ἦρχεν, ἐξέβαλε. καὶ ὃς καταφυγὼν πρὸς τὸν Γαβίνιον ἀνέπεισεν αὐτὸν συμπρᾶξαί οἱ τὴν κάθοδον. ἐπεὶ μέντοι ὁ Πτολεμαῖος μετὰ τῶν τοῦ Πομπηίου γραμμάτων ἦλθε, καὶ πολλὰ μὲν αὐτῷ πολλὰ δὲ καὶ τῷ στρατῷ χρήματα τὰ μὲν ἤδη παρέξειν, τὰ δ’ ἂν καταχθῇ δώσειν ὑπέσχετο, τά τε τῶν Πάρθων εἴασε καὶ ἐπὶ τὴν Αἴγυπτον ἠπείχθη, καίπερ ἀπαγορεύοντος μὲν τοῦ νόμου μήτε ἐς τὴν ὑπερορίαν τοὺς ἄρχοντάς τινων ἀποδημεῖν μήτε πολέμους ἀφ’ ἑαυτῶν ἀναιρεῖσθαι, ἀπειρηκότος δὲ καὶ τοῦ δήμου τῆς τε Σιβύλλης μὴ καταχθῆναι τὸν ἄνδρα. ἀλλ’ ὅσῳ γὰρ ἐκεκώλυτο ταῦτα, τόσῳ πλείονος αὐτὰ ἀπημπόλησε. καταλιπὼν οὖν ἐν τῇ Συρίᾳ Σισένναν τε τὸν υἱὸν κομιδῇ νέον ὄντα καὶ στρατιώτας μετ’ αὐτοῦ πάνυ ὀλίγους, τὴν μὲν ἀρχὴν ἐφ’ ἧς ἐτέτακτο τοῖς λῃσταῖς ἔτι καὶ μᾶλλον ἐξέδωκεν, αὐτὸς δὲ ἐς τὴν Παλαιστίνην ἐλθὼν τόν τε Ἀριστόβουλον (διαδρὰς γὰρ ἐκ τῆς Ῥώμης ὑπετάραττέ τι) συνέλαβε καὶ τῷ Πομπηίῳ ἔπεμψε, καὶ φόρον τοῖς Ἰουδαίοις ἐπέταξε, καὶ μετὰ τοῦτο καὶ ἐς τὴν Αἴγυπτον ἐνέβαλε.", "st": "39.56"}, {"sp": "N", "t": "ἦρχε δὲ τότε τῶν Αἰγυπτίων ἡ Βερενίκη, καὶ ἐπιεικὲς μὲν οὐδὲν πρὸς τὸν. … καίτοι φοβουμένη τοὺς Ῥωμαίους, ἔπραξε, Σέλευκον δέ τινα, ὡς καὶ ἐκ τοῦ βασιλείου γένους τοῦ ποτε ἐν τῇ Συρίᾳ ἀνθήσαντος ὄντα, μεταπέμψασα ἄνδρα τε ἐπεγράψατο καὶ κοινωνὸν τῆς τε βασιλείας καὶ τοῦ πολέμου ἐποιήσατο. ὡς δὲ ἐκεῖνος ἐν οὐδενὸς μοίρᾳ ὢν ἑωρᾶτο, τοῦτον μὲν ἀπέκτεινεν, Ἀρχέλαον δὲ τὸν τοῦ Ἀρχελάου τοῦ πρὸς τὸν Σύλλαν αὐτομολήσαντος, δραστήριόν τε ὄντα καὶ ἐν τῇ Συρίᾳ τὴν δίαιταν ἔχοντα, ἐπὶ τοῖς αὐτοῖς ἐπηγάγετο. ὁ γὰρ Γαβίνιος ἐδύνατο μὲν ἀρχόμενον τὸ δεινὸν παῦσαι (τὸν γὰρ Ἀρχέλαον προϋποτοπήσας συνέλαβε, καὶ ἔμελλεν ἐκ τούτου μηδὲν ἔτ’ ἔργον ἕξειν), φοβηθεὶς δὲ μὴ καὶ ἐλάττω διὰ τοῦτο παρὰ τοῦ Πτολεμαίου τῶν ὡμολογημένων οἱ χρημάτων, ὡς οὐδὲν ἀξιόλογον πεποιηκώς, λάβοι, καὶ ἐλπίσας ἔτι καὶ πλείω πρός τε τὴν δεινότητα καὶ πρὸς τὴν δόξαν τὴν τοῦ Ἀρχελάου χρηματιεῖσθαι, καὶ προσέτι καὶ ἄλλα παρ’ αὐτοῦ ἐκείνου συχνὰ λαβών, ἐθελοντὴς αὐτὸν ὡς καὶ διαδράντα", "st": "39.57"}, {"sp": "N", "t": "ἀφῆκε. καὶ οὕτως ἐς μὲν τὸ Πηλούσιον ἀφίκετο μηδενὸς ἐναντιουμένου, προϊὼν δὲ ἐντεῦθεν δίχα διῃρημένῳ τῷ στρατῷ τοὺς Αἰγυπτίους ἀπαντήσαντάς οἱ τῇ αὐτῇ ἡμέρᾳ ἐνίκησε, καὶ μετὰ τοῦτ’ αὖθις ἔν τε τῷ ποταμῷ ναυσὶ κἀν τῇ γῇ ἐκράτησεν· οἱ γὰρ Ἀλεξανδρεῖς θρασύνασθαι μὲν πρὸς πάντα ἱκανώτατοι καὶ ἐκλαλῆσαι πᾶν ὅ τι ποτ’ ἂν ἐπέλθῃ σφίσι προπετέστατοι πεφύκασι, πρὸς δὲ δὴ πόλεμον τά τε δεινὰ αὐτοῦ φλαυρότατοί εἰσι, καίπερ ἐν ταῖς στάσεσι, πλείσταις δὴ καὶ μεγίσταις παρ’ αὐτοῖς γιγνομέναις, διὰ φόνων τε ἀεὶ χωροῦντες καὶ τὸ ζῆν παρ’ οὐδὲν πρὸς τὴν αὐτίκα φιλονεικίαν τιθέμενοι, ἀλλὰ καὶ ὥσπερ τι τῶν ἀρίστων ἢ ἀναγκαιοτάτων τὸν ἐν αὐταῖς ὄλεθρον διώκοντες. νικήσας οὖν αὐτοὺς ὁ Γαβίνιος, καὶ ἄλλους τε πολλοὺς καὶ τὸν Ἀρχέλαον φονεύσας, ἐγκρατής τε τῆς Αἰγύπτου πάσης παραχρῆμα ἐγένετο καὶ τῷ Πτολεμαίῳ αὐτὴν παρέδωκε. καὶ ὁ μὲν τήν τε θυγατέρα καὶ τῶν ἄλλων τοὺς πρώτους καὶ πλουσιωτάτους, ἅτε καὶ χρημάτων", "st": "39.58"}, {"sp": "N", "t": "πολλῶν δεόμενος, ἀπέκτεινε· Γαβίνιος δὲ ἐκεῖνον μὲν οὕτω κατήγαγεν, οὐ μέντοι καὶ οἴκαδε περὶ τῶν πραχθέντων ἐπέστειλεν, ἵνα μὴ καὶ αὐτάγγελός σφισιν ὧν παρηνομήκει γένηται. ἀλλ’ οὐ γὰρ οἷόν τε ἦν τηλικοῦτο πρᾶγμα κρυφθῆναι, εὐθύς τε αὐτὸ ὁ δῆμος ἐπύθετο, καὶ ἐπειδὴ καὶ οἱ Σύροι πολλὰ τοῦ Γαβινίου, ἄλλως τε καὶ ἐν τῇ ἀπουσίᾳ αὐτοῦ δεινῶς ὑπὸ τῶν λῃστῶν κακωθέντες, κατεβόησαν, οἵ τε τελῶναι μὴ δυνηθέντες τὰ τέλη δι’ αὐτοὺς ἐσπρᾶξαι συχνὰ ἐπωφείλησαν, ὠργίζοντο καὶ γνώμας τε ἐποιοῦντο καὶ ἑτοίμως εἶχον καταψηφίσασθαι αὐτοῦ. καὶ γὰρ ὁ Κικέρων τά τε ἄλλα ἰσχυρῶς ἐνῆγε, καὶ συνεβούλευέ σφισι τὰ Σιβύλλεια ἔπη αὖθις ἀναγνῶναι, προσδοκῶν ἐγγεγράφθαι τινὰ ἐν αὐτοῖς τιμωρίαν ἄν τι παραβαθῇ.", "st": "39.59"}, {"sp": "N", "t": "ὁ οὖν Πομπήιος ὅ τε Κράσσος ὑπάτευόν τε ἔτι, καὶ ὁ μὲν ἑαυτῷ βοηθῶν, ὁ δὲ τήν τε ἐκείνου χάριν καὶ ἅμα καὶ χρήματα παρὰ τοῦ Γαβινίου πεμφθέντα οἱ λαβών, ἔκ τε τοῦ προφανοῦς ὑπὲρ αὐτοῦ διεδικαίουν, καὶ ἄλλα τε καὶ φυγάδα τὸν Κικέρωνα ἀποκαλοῦντες οὐδὲν ἐπεψήφισαν. ὡς μέντοι ἐκεῖνοί τε ἐκ τῆς ἀρχῆς ἀπηλλάγησαν καὶ αὐτοὺς ὅ τε Δομίτιος ὁ Λούκιος καὶ Ἄππιος Κλαύδιος διεδέξαντο, γνῶμαι αὖθις πολλαὶ ἐλέχθησαν, καὶ κατὰ τοῦ Γαβινίου αἱ πλείους ἐγένοντο· ὅ τε γὰρ Δομίτιος ἐχθρὸς τῷ Πομπηίῳ διά τε τὸ σπουδαρχῆσαι καὶ διὰ τὸ παρὰ γνώμην αὐτοῦ ἀποδειχθῆναι ὤν, καὶ ὁ Κλαύδιος, καίπερ προσήκων οἱ, ὅμως τοῖς τε πολλοῖς χαρίσασθαί τι ὑπὸ δημαγωγίας ἐθελήσας, καὶ παρὰ τοῦ Γαβινίου δωροδοκήσειν, ἄν γέ τι συνταράξῃ, προσδοκήσας, πάντα ἐπ’ αὐτῷ ἔπραξαν. καὶ αὐτὸν καὶ ἐκεῖνο δεινῶς ἐπίεσεν, ὅτι προπεμφθέντα τινὰ ὑπὸ τοῦ Κράσσου ὑποστράτηγον ἐπὶ τῇ τῆς ἀρχῆς αὐτοῦ διαδοχῇ οὐκ ἐδέξατο, ἀλλ’ ὥσπερ ἀθάνατον τὴν ἡγεμονίαν εἰληφὼς κατεῖχεν αὐτήν. ἔδοξεν οὖν σφισι τὰ τῆς Σιβύλλης ἔπη ἀναγνωσθῆναι, καίπερ ἀντειπόντος τοῦ Πομπηίου.", "st": "39.60"}, {"sp": "N", "t": "κἀν τούτῳ ὁ Τίβερις, εἴτ’ οὖν ὄμβρων ἄνω που ὑπὲρ τὴν πόλιν ἐξαισίων γενομένων, εἴτε καὶ σφοδροῦ πνεύματος ἐκ τῆς θαλάσσης τὴν ἐκροὴν αὐτοῦ ἀνακόψαντος, εἴτε καὶ μᾶλλον, ὡς ὑπωπτεύετο, ἐκ παρασκευῆς δαιμονίου τινός, τοσοῦτος ἐξαπιναίως ἐρρύη ὥστ’ ἐν πᾶσι μὲν τοῖς πεδίοις τοῖς ἐν τῷ ἄστει οὖσι πελαγίσαι, πολλὰ δὲ καὶ τῶν μετεωροτέρων καταλαβεῖν. αἵ τε οὖν οἰκίαι (ἐκ πλίνθων γὰρ συνῳκοδομημέναι ἦσαν) διάβροχοί τε ἐγένοντο καὶ κατερράγησαν, καὶ τὰ ὑποζύγια πάντα ὑποβρύχια ἐφθάρη. τῶν τε ἀνθρώπων ὅσοι μὴ ἔφθησαν πρὸς τὰ πάνυ ὑψηλὰ ἀναφυγόντες, οἱ μὲν ἐν ταῖς τέγαις οἱ δὲ καὶ ἐν ὁδοῖς ἐγκαταληφθέντες ἐξώλοντο. καὶ γὰρ αἱ λοιπαὶ οἰκίαι, ἅτε ἐπὶ πολλὰς ἡμέρας τοῦ δεινοῦ συμβάντος, σαθραί τε ἐγένοντο καὶ πολλοῖς τοῖς μὲν εὐθὺς τοῖς δὲ μετὰ τοῦτ’ ἐλυμήναντο. οἱ οὖν Ῥωμαῖοι ἐπί τ’ ἐκείνοις τοῖς παθήμασι λυπούμενοι, καὶ ἕτερα χαλεπώτερα ὡς καὶ διὰ τὴν τοῦ Πτολεμαίου κάθοδον ὀργήν σφισι τοῦ δαιμονίου πεποιημένου προσδεχόμενοι, ἠπείγοντο καὶ ἀπόντα τὸν Γαβίνιον, ὡς καὶ ἧττόν τι, ἂν φθάσωσιν αὐτὸν ἀπολέσαντες, κακωθησόμενοι, θανατῶσαι. καὶ οὕτω γε ἐντόνως ἔσχον ὥστε, καίτοι μηδενὸς τοιούτου ἐν τοῖς Σιβυλλείοις χρησμοῖς εὑρεθέντος, ὅμως τὴν γερουσίαν πικρότατα καὶ τραχύτατα τούς τε ἄρχοντας καὶ τὸν δῆμον αὐτῷ χρήσασθαι προβουλεῦσαι.", "st": "39.61"}, {"sp": "N", "t": "ἐν ᾧ δὲ ταῦτ’ ἐγίγνετο, χρήματα ὑπὸ τοῦ Γαβινίου προπεμφθέντα οὐχ ὅπως ἀπόντα ἀλλ’ οὐδὲ ἐπανελθόντα δεινόν τι παθεῖν αὐτὸν ἐπί γε ἐκείνοις ἐποίησε. καίτοι οὕτω καὶ αὐτὸς αἰσχρῶς καὶ κακῶς ὑπὸ τοῦ συνειδότος διετέθη ὥστε καὶ χρόνιος ἐς τὴν Ἰταλίαν ἀφικέσθαι καὶ νυκτὸς ἐς τὴν πόλιν ἐσκομισθῆναι, ἔξω τε τῆς οἰκίας συχναῖς πάνυ ἡμέραις μὴ τολμῆσαι φανῆναι. τὰ μὲν οὖν ἐγκλήματα πολλὰ ἦν, καὶ κατηγόρους οὐκ ὀλίγους εἶχε. πρῶτον δ’ οὖν περὶ τῆς τοῦ Πτολεμαίου καθόδου, ἅτε καὶ μεγίστου, ἐδικάσθη. καὶ ὅ γε δῆμος σύμπας ὡς εἰπεῖν πρός τε τὸ δικαστήριον συνερρύη καὶ διασπάσασθαι πολλάκις αὐτὸν ἠθέλησεν, ἄλλως τε καὶ ὅτι οὔθ’ ὁ Πομπήιος παρῆν καὶ ὁ Κικέρων δεινότατα αὐτοῦ κατηγόρησεν. οὕτω δὲ αὐτῶν διακειμένων ὅμως ἀφείθη· αὐτός τε γάρ, ἅτε ἐπὶ τηλικούτοις κρινόμενος, παμπληθῆ χρήματα ἀνάλωσε, καὶ οἱ τοῦ Πομπηίου τοῦ τε Καίσαρος ἑταῖροι προθυμότατα αὐτῷ συνήραντο, λέγοντες ἄλλον τέ τινα καιρὸν καὶ ἄλλον βασιλέα πρὸς τῆς Σιβύλλης εἰρῆσθαι, καὶ τὸ μέγιστον ὅτι μηδεμία τῶν πραχθέντων τιμωρία ἐν τοῖς ἔπεσιν αὐτῆς ἐνεγέγραπτο.", "st": "39.62"}, {"sp": "N", "t": "ὁ δ’ οὖν δῆμος ὀλίγου μὲν καὶ τοὺς δικαστὰς ἀπέκτεινε, διαφυγόντων δὲ αὐτῶν ἐπετήρει τὰ λοιπὰ αὐτοῦ ἐγκλήματα, καὶ ἐποίησεν ἐπ’ ἐκείνοις γοῦν αὐτὸν ἁλῶναι. οἱ γὰρ λαχόντες περὶ αὐτῶν κρῖναι, τό τε πλῆθος ἅμα φοβηθέντες καὶ μηδὲν μέγα παρὰ τοῦ Γαβινίου εὑρόμενοι (ὡς γὰρ ἐπί τε βραχυτέροις εὐθυνόμενος καὶ προσδοκῶν καὶ τότε κρατήσειν οὐ πολλὰ ἐδαπάνησε) κατεψηφίσαντο αὐτοῦ, καίτοι τοῦ τε Πομπηίου πλησίον ὄντος καὶ τοῦ Κικέρωνος συναγορεύοντος αὐτῷ. ὁ γὰρ Πομπήιος κατὰ τὴν τοῦ σίτου πρόνοιαν, ἐπειδὴ πολὺς ὑπὸ τοῦ ποταμοῦ διέφθαρτο, ἐκδημήσας ὥρμησε μὲν ὡς καὶ ἐς τὸ πρότερον δικαστήριον ἀπαντήσων (ἐν γὰρ τῇ Ἰταλίᾳ ἦν), ὑστερήσας δὲ αὐτοῦ οὐκ ἀπεχώρησεν ἐκ τοῦ προαστείου πρὶν καὶ ἐκεῖνο τελεσθῆναι. καὶ μέντοι καὶ τοῦ δήμου ἔξω τοῦ πωμηρίου (τὴν γὰρ ἀρχὴν ἤδη τὴν τοῦ ἀνθυπάτου ἔχων οὐκ ἠδυνήθη ἐς τὴν πόλιν ἐσελθεῖν) ἀθροισθέντος πολλὰ ὑπὲρ τοῦ Γαβινίου ἐδημηγόρησε, καὶ γράμματά τέ τινα παρὰ τοῦ Καίσαρος πρὸς ἑαυτὸν ὑπὲρ αὐτοῦ πεμφθέντα ἀνέγνω, καὶ τοὺς δικαστὰς ἱκέτευσε, τόν τε Κικέρωνα οὐχ ὅπως κατηγορῆσαι ἔτ’ αὐτοῦ ἐκώλυσεν, ἀλλὰ καὶ ὑπερδικῆσαι ἔπεισεν, ὥστε καὶ ἐκ τούτου τὸ τοῦ αὐτομόλου ἔγκλημα καὶ ὄνομα ἐπὶ πλεῖόν οἱ αὐξηθῆναι. οὐ μέντοι καὶ ὠφέλησέ τι τὸν Γαβίνιον, ἀλλὰ τότε μὲν ἔφυγεν ἁλούς, ὥσπερ εἶπον, ὕστερον δ’ ὑπὸ τοῦ Καίσαρος κατήχθη.", "st": "39.63"}, {"sp": "N", "t": "ἐν δὲ τῷ αὐτῷ τούτῳ χρόνῳ καὶ ἡ τοῦ Πομπηίου γυνὴ θυγάτριόν τι τεκοῦσα ἀπέθανε· καὶ αὐτήν, εἴτε διαπραξαμένων τῶν τε ἐκείνου καὶ τῶν τοῦ Καίσαρος φίλων, ἢ καὶ ἄλλως πως χαρίσασθαί τινες αὐτοῖς ἐθελήσαντες συνήρπασαν, ἐπειδὴ τάχιστα τῶν ἐν τῇ ἀγορᾷ ἐπαίνων ἔτυχε, καὶ ἐν τῷ Ἀρείῳ πεδίῳ ἔθαψαν, καίτοι τοῦ Δομιτίου ἀνθισταμένου καὶ λέγοντος ἄλλα τε καὶ ὅτι οὐχ ὁσίως ἐν τῷ ἱερῷ τόπῳ ἄνευ τινὸς ψηφίσματος θάπτοιτο.", "st": "39.64"}, {"sp": "N", "t": "κἀν τούτῳ καὶ ὁ Πομπτῖνος ὁ Γάιος τὰ ἐπινίκια τὰ τῶν Γαλατῶν ἔπεμψεν· ἐς γὰρ ἐκεῖνο τοῦ χρόνου, μηδενός οἱ διδόντος αὐτά, ἔξω τοῦ πωμηρίου διέμεινε. καὶ τότε δ’ ἂν αὐτῶν ἥμαρτεν, εἰ μὴ ὁ Γάλβας ὁ Σέρουιος συστρατευσάμενος αὐτῷ, κρύφα καὶ ὑπὸ τὴν ἕω στρατηγῶν τὴν ψῆφόν τισι (καίπερ οὐκ ἐξὸν ἐκ τῶν νόμων πρὶν πρώτην ὥραν γενέσθαι ἐν τῷ δήμῳ τι χρηματισθῆναι) ἔδωκε. καὶ διὰ τοῦτο τῶν δημάρχων τινὲς ἀπολειφθέντες τῆς ἐκκλησίας ἐν γοῦν τῇ πομπῇ πράγματα αὐτῷ παρέσχον, ὥστε καὶ σφαγὰς συμβῆναι.", "st": "39.65"}, {"sp": "HDR", "t": "Βιβλίον Μʹ", "st": "40"}, {"sp": "N", "t": "τάδε ἔνεστιν ἐν τῷ τετταρακοστῷ τῶν Δίωνος Ῥωμαϊκῶν<br>α. ὡς Καῖσαρ τὸ δεύτερον ἐς Βρεττανίαν διέπλευσεν.<br>β. ὡς Καῖσαρ ὑποστρέψας ἀπὸ Βρεττανίας τοῖς Γαλάταις αὖθις ἐπολέμησεν.<br>γ. ὡς Κράσσος Πάρθοις πολεμεῖν ἤρξατο.<br>δ. περὶ Πάρθων.<br>ε. ὡς Κράσσος ἡττηθεὶς ὑπ’ αὐτῶν ἀπώλετο.<br>ζ. ὡς Καῖσαρ τὴν Γαλατίαν τὴν ὑπὲρ τὰς Ἄλπεις πᾶσαν κατεστρέψατο.<br>η. ὡς Μίλων Κλώδιον ἀποκτείνας κατεδικάσθη.<br>θ. ὡς Καῖσαρ καὶ Πομπήιος στασιάζειν ἤρξαντο.<br>χρόνου πλῆθος τὰ λοιπὰ τῆς Δομιτίου καὶ Ἀππίου Κλαυδίου ὑπατείας καὶ ἄλλα ἔτη τέτταρα, ἐν οἷς ἄρχοντες οἱ ἀριθμούμενοι οἵδε ἐγένοντο<br>Γν. Δομίτιος Μ. υἱ. Καλουῖνος<br>μ. Οὐαλέριος … Μεσσάλας ὑπ.<br>Γν. Πομπήιος Γν. υἱ. Μάγνος τὸ γ<br>κ. Καικίλιος Μέτελλος Σκιπίων Νασικοῦ υἱ. ὑπ.<br>Σέρουιος Σουλπίκιος Κ. υἱ. Ῥοῦφος<br>μ. Κλαύδιος Μ. υἱ. Μάρκελλος ὑπ.<br>λ. Αἰμίλιος μ. υἱ. Παῦλος<br>γ. Κλαύδιος Γ. υἱ. Μάρκελλος ὑπ.", "st": "40.0"}, {"sp": "N", "t": "ἐν μὲν δὴ τῇ Ῥώμῃ ταῦτα, τότε ἑπτακόσια ἔτη ἀγούσῃ, ἐγένετο· ἐν δὲ δὴ τῇ Γαλατίᾳ ὁ Καῖσαρ ἐπὶ τῶν αὐτῶν ἐκείνων τοῦ Δομιτίου τοῦ Λουκίου καὶ τοῦ Κλαυδίου τοῦ Ἀππίου ὑπάτων τά τε ἄλλα καὶ ναῦς ἐν μέσῳ τῶν τε σφετέρων τῶν ταχειῶν καὶ τῶν αὐτόθεν τῶν φορτίδων, ὅπως ὡς μάλιστα καὶ κουφίζωσι καὶ πρὸς τὸ κῦμα ἀντέχωσιν, ἐπί τε τοῦ ξηροῦ ἱστάμεναι μὴ λυμαίνωνται, παρεσκευάσατο. καὶ ἐπειδὴ πλόιμα ἐγένετο, ἐς τὴν Βρεττανίαν αὖθις ἐπεραιώθη, πρόφασιν μὲν ὅτι μὴ πάντας τοὺς ὁμήρους οὓς ὑπέσχοντό οἱ ἐπεπόμφεσαν, νομίζοντες αὐτόν, ὅτι διὰ κενῆς τότε ἀνεχώρησε, μηκέτ’ αὖθίς σφων πειράσειν, ποιησάμενος, ἔργῳ δὲ δεινῶς τῆς νήσου ἐφιέμενος, ὥστε εἰ μὴ καὶ τοῦτο ἦν, πάντως ἂν ἄλλην τινὰ σκῆψιν εὑρεῖν. κατῆρέ τε οὖν ἔνθα καὶ πρότερον, μηδενὸς ὑπό τε τοῦ πλήθους τῶν νεῶν καὶ ὑπὸ τοῦ πολλαχόσε ἅμα αὐτὰς κατασχεῖν τολμήσαντος ἀντιστῆναι, καὶ τὸ ναύσταθμον", "st": "40.1"}, {"sp": "N", "t": "εὐθὺς ἐκρατύνατο. οἱ οὖν βάρβαροι τὸν μὲν πρόσπλουν αὐτοῦ οὐκ ἠδυνήθησαν διὰ ταῦτα κωλῦσαι, δείσαντες δὲ μᾶλλον ἢ πρότερον, ἅτε καὶ στρατῷ πλείονι αὐτοῦ ἐλθόντος, ἐς τὸ λασιώτατον καὶ ἐς τὸ λοχμωδέστατον τῶν ἐγγὺς χωρίων πάντα τὰ τιμιώτατα συνεφόρησαν, καὶ αὐτὰ ἐν ἀσφαλεῖ ποιησάμενοι (τά τε γὰρ πέριξ ξύλα ἔκοψαν, καὶ ἕτερα ἐπ’ αὐτοῖς στοιχηδὸν ἐπισυνένησαν, ὥστε ἐν χαρακώματι τρόπον τινὰ εἶναι) ἔπειτα τοὺς προνομεύοντας τῶν Ῥωμαίων ἐλύπουν. καὶ δὴ καὶ μάχῃ τινὶ ἐν τῷ ψιλῷ ἡττηθέντες ὑπήγαγόν σφας ἐκεῖσε κατὰ τὴν δίωξιν, καὶ συχνοὺς ἀνταπέκτειναν. καὶ μετὰ τοῦτο χειμῶνος αὖθις τὰς ναῦς αὐτῶν λυμηναμένου συμμάχους τε προσμετεπέμψαντο καὶ ἐπ’ αὐτὸ τὸ νεώριόν σφων ὥρμησαν, Κασουελλανὸν τὸν τὰ πρῶτα τῶν ἐν τῇ νήσῳ δυναστῶν φερόμενον προστησάμενοι. καὶ αὐτοῖς ἀπαντήσαντες οἱ Ῥωμαῖοι τὸ μὲν πρῶτον ἐταράχθησαν τῇ τῶν ἁρμάτων σφῶν προσμίξει, ἔπειτα δὲ διιστάμενοι, καὶ ἐκεῖνά τε παρεξιέντες καὶ τοὺς παραθέοντας ἐς τὰ πλάγια βάλλοντες,", "st": "40.2"}, {"sp": "N", "t": "ἀνίσωσαν τὴν μάχην. καὶ τότε μὲν κατὰ χώραν ἀμφότεροι ἔμειναν· αὖθις δὲ οἱ βάρβαροι τοῦ μὲν πεζοῦ κρείττους γενόμενοι, ὑπὸ δὲ τῆς ἵππου κακωθέντες, πρός τε τὸν Ταμέσαν ἀνεχώρησαν, καὶ τὸν πόρον αὐτοῦ σταυροῖς, τοῖς μὲν ἐμφανέσι τοῖς δὲ καὶ ὑφύδροις, διαλαβόντες ηὐλίσαντο. ἐπειδὴ δὲ ἐκείνους τε ὁ Καῖσαρ τό τε σταύρωμα προσβολῇ βιαίᾳ ἐκλιπεῖν ἠνάγκασε καὶ μετὰ τοῦτο καὶ ἐκ τοῦ ἐρύματος προσεδρείᾳ ἐξήλασε, καὶ τοὺς προσβάλλοντάς σφων τῷ ναυστάθμῳ ἕτεροι ἀπεώσαντο, κατέδεισαν καὶ κατελύσαντο ὁμήρους τε δόντες καὶ φόρον ἐτήσιον ταξάμενοι.", "st": "40.3"}, {"sp": "N", "t": "καὶ οὕτως ὁ Καῖσαρ ἀπῆρε παντάπασιν ἐκ τῆς νήσου, καὶ οὐδὲν ἐγκατέλιπε στράτευμα ἐν αὐτῇ· ἐκεῖνό τε γὰρ κινδυνεύσειν ἐν ἀλλοτρίᾳ πῃ χειμάζον, καὶ αὐτὸς οὐκ ἂν ἐν καλῷ ἐπὶ πλεῖον ἀπὸ τῆς Γαλατίας ἀποδημῆσαι νομίζων, ἠγάπησε τοῖς παροῦσι, μὴ καὶ μειζόνων ὀριγνώμενος καὶ περὶ ἐκείνοις σφαλῇ. καὶ ἔδοξε καὶ τοῦτο ὀρθῶς πεποιηκέναι, ὥσπερ που καὶ τῷ ἔργῳ διεδείχθη· ἐπεὶ γὰρ ἐς τὴν Ἰταλίαν ὥρμησεν ὡς καὶ ἐκεῖ παραχειμάσων, οἱ Γαλάται, καίτοι φρουροὺς ὡς ἕκαστοι πολλοὺς ἔχοντες, ὅμως ἐνεόχμωσαν, καί τινες αὐτῶν καὶ φανερῶς ἐπανέστησαν. ὅπερ εἰ ἐν τῇ Βρεττανίᾳ καταμείναντος αὐτοῦ παρὰ τὸν χειμῶνα ἐγεγόνει, πάντα ἂν τὰ τῇδε ἐτετάρακτο.", "st": "40.4"}, {"sp": "N", "t": "ἦρξαν δὲ τοῦ πολέμου τούτου Ἐβουρωνοί, ἡγουμένου σφίσιν Ἀμβιόριγος. καὶ ἔλεγον μὲν τῇ παρουσίᾳ τῶν Ῥωμαίων, ὧν ὅ τε Σαβῖνος καὶ Λούκιος Κόττας ὑποστράτηγοι ἦρχον, ἀχθόμενοι κεκινῆσθαι· τὸ δ’ ἀληθὲς ἐκείνων τε κατεφρόνησαν ὡς οὐχ ἱκανῶν ἀμῦναι σφᾶς ἐσομένων, καὶ τὸν Καίσαρα οὐκ ἤλπισαν διὰ ταχέων σφίσιν ἐπιστρατεύσειν. ἐπῆλθόν τε οὖν αὐτοῖς μὴ προσδεχομένοις ὡς καὶ αὐτοβοεὶ τὸ στρατόπεδον αἱρήσοντες, καὶ ἐπειδὴ διήμαρτον αὐτοῦ, πρὸς ἀπάτην ἐτράποντο. τῶν γὰρ χωρίων τὰ ἐπιτηδειότατα ὁ Ἀμβιόριξ προλοχίσας ἦλθεν ἐξ ἐπικηρυκείας πρὸς τοὺς Ῥωμαίους ὡς οὐχ ἑκὼν δὴ πολεμήσας, καὶ αὐτὸς μὲν μεταγιγνώσκειν ἔφη, τοὺς δ’ ἄλλους φυλάττεσθαί σφισι παρῄνεσεν· οὔτε γὰρ αὐτῷ πειθαρχεῖν αὐτοὺς καὶ ἐκείνοις μέλλειν τῆς νυκτὸς ἐπιθήσεσθαι. κἀκ τούτου καὶ γνώμην αὐτοῖς ἔδωκε τὴν μὲν Ἐβουρωνίαν, ὡς καὶ κινδυνεύσουσιν ἂν καταμείνωσι, καταλιπεῖν, πρὸς δὲ συστρατιώτας τινὰς πέλας που χειμάζοντας ὡς", "st": "40.5"}, {"sp": "N", "t": "τάχιστα μεταστῆναι. ἀκούσαντες δὲ ταῦτα οἱ Ῥωμαῖοι ἐπείσθησαν, ἄλλως τε καὶ ὅτι εὐηργέτητο πολλὰ ὑπὸ τοῦ Καίσαρος καὶ χάριν αὐτῷ ταύτην ἀντιδιδόναι ἐδόκει. συσκευασάμενοί τε σπουδῇ εὐθὺς ἀφ’ ἑσπέρας ἀφώρμησαν, καὶ ἐμπεσόντες ἐς τὰ λελοχισμένα δεινῶς ἐσφάλησαν· ὅ τε γὰρ Κόττας παραχρῆμα μετὰ πολλῶν ἀπώλετο, καὶ τὸν Σαβῖνον ὁ Ἀμβιόριξ μετεπέμψατο μὲν ὡς καὶ σώσων (οὔτε γὰρ τοῖς γιγνομένοις παρῆν, καὶ πιστὸς αὐτῷ καὶ τότε ἔτ’ ἐδόκει εἶναι), συλλαβὼν δὲ δή, καὶ ἀποδύσας καὶ τὰ ὅπλα καὶ τὴν ἐσθῆτα, κατηκόντισεν, ἐπιλέγων ἄλλα τε καὶ ὅτι τοιοίδε μέντοι ὄντες πῶς τηλικούτων ἡμῶν ὄντων ἄρχειν ἐθέλετε; οὗτοι μὲν δὴ ταῦτ’ ἔπαθον· οἱ δὲ λοιποὶ διέπεσον μὲν ἐς τὸ τάφρευμα ὅθεν ἀπανειστήκεσαν, ἐπεὶ δὲ οἵ τε βάρβαροι καὶ ἐκεῖ προσέμιξαν καὶ οὔτ’ ἀμύνασθαι αὐτοὺς οὔτε διαφυγεῖν ἠδυνήθησαν, ἀλλήλους ἀπέκτειναν.", "st": "40.6"}, {"sp": "N", "t": "γενομένου δὲ τούτου ἄλλοι τέ τινες τῶν πλησιοχώρων ἀπέστησαν καὶ Νέρουιοι, καίτοι Κυίντου Κικέρωνος παρ’ αὐτοῖς χειμάζοντος· ἀδελφὸς δὲ τοῦ Κικέρωνος τοῦ Μάρκου ἦν, ὑποστρατηγῶν τῷ Καίσαρι. καὶ αὐτοὺς ὁ Ἀμβιόριξ προσλαβὼν συνέβαλε τῷ Κικέρωνι· καὶ ἀγχώμαλα ἀγωνισάμενος, καί τινας καὶ ζῶντας ἑλών, ἀπατῆσαι μέν πῃ καὶ ἐκεῖνον ἐπεχείρησε, μὴ δυνηθεὶς δὲ ἔς τε πολιορκίαν αὐτὸν κατέστησε, καὶ διὰ ταχέων ὑπό τε τῆς πολυχειρίας καὶ ὑπὸ τῆς ἐμπειρίας, ἣν ἐκ τῆς συστρατείας ἣν μετὰ τῶν Ῥωμαίων ἐπεποίητο ἐκέκτητο, καί τινα καὶ παρὰ τῶν αἰχμαλώτων ἑκάστων μαθών, καὶ ἀπεσταύρωσε καὶ ἀπετάφρευσεν. ἐγίγνοντο μὲν γὰρ καὶ μάχαι, οἷα ἐν τῷ τοιούτῳ εἰκὸς ἦν, συχναί, καὶ ἀπώλλυντο πολὺ πλείους τῶν βαρβάρων ἅτε καὶ πλείους ὄντες· οὐ μὴν ἀλλὰ αὐτοὶ μὲν ὑπὸ τῆς περιουσίας τοῦ στρατοῦ οὐδὲ ἐν αἰσθήσει τοῦ φθειρομένου σφῶν ἦσαν, οἱ δὲ δὴ Ῥωμαῖοι μήτε ἄλλως πολλοὶ ὄντες καὶ ἐλάττους ἀεὶ γιγνόμενοι ῥᾳδίως περιεστοιχίσθησαν.", "st": "40.7"}, {"sp": "N", "t": "κινδυνευόντων οὖν αὐτῶν ἁλῶναι (οὔτε γὰρ τὰ τραύματα θεραπεύειν ἀπορίᾳ τῶν ἐπιτηδείων ἐδύναντο, οὔτε τὴν τροφὴν ἀφθόνως, ἅτε ἐν ἀδοκήτῳ πολιορκίᾳ, εἶχον· οὐδ’ ἐπήμυνέ τις αὐτοῖς, καίτοι πολλῶν οὐκ ἄπωθεν χειμαζόντων· οἱ γὰρ βάρβαροι τὰς ὁδοὺς ἀκριβῶς φυλάσσοντες πάντας τοὺς ἐκπεμπομένους σφῶν συνελάμβανον κἀν τοῖς ὀφθαλμοῖς αὐτῶν ἐφόνευον) Νέρουιός τις εὐνοϊκῶς σφισιν ἐξ εὐεργεσίας ἔχων, καὶ τότε σὺν τῷ Κικέρωνι πολιορκούμενος, δοῦλόν τινα ἑαυτοῦ διάγγελον αὐτῷ παρέσχεν· ἔκ τε γὰρ τῆς σκευῆς καὶ ἐκ τῆς φωνῆς τῆς ἐπιχωρίας ἠδυνήθη λαθεῖν συγγενόμενος τοῖς πολεμίοις ὡς καὶ ἐξ αὐτῶν ὢν καὶ μετὰ τοῦτο ἀποχωρήσας.", "st": "40.8"}, {"sp": "N", "t": "μαθὼν οὖν ὁ Καῖσαρ τὸ γιγνόμενον (οὐδέπω δὲ ἐς τὴν Ἰταλίαν ἀπεληλύθει, ἀλλ’ ἔτ’ ἐν ὁδῷ ἦν) ἀνέστρεψε, καὶ τοὺς ἐν τοῖς χειμαδίοις, δι’ ὧν διῄει, στρατιώτας παραλαμβάνων ἠπείγετο. κἀν τούτῳ φοβηθεὶς μὴ καὶ φθάσῃ ὁ Κικέρων ἀπογνώσει τῆς βοηθείας δεινόν τι παθὼν ἢ καὶ συνθέμενος, προέπεμψεν ἱππέα. τῷ μὲν γὰρ οἰκέτῃ τῷ τοῦ Νερουίου, καίτοι πεῖραν ἔργῳ τῆς εὐνοίας αὐτοῦ λαβών, οὐκ ἐπίστευσε, μὴ καὶ τοὺς πατριώτας ἐλεήσας μέγα τι κακόν σφας ἐξεργάσηται· ἐκ δὲ δὴ τῶν συμμάχων ἱππέα τήν τε διάλεκτον αὐτῶν εἰδότα καὶ τῇ στολῇ τῇ ἐκείνων σκευασθέντα ἔπεμψε. καὶ ὅπως γε μηδ’ αὐτός τι μήτ’ οὖν ἐθελοντὴς μήτ’ ἄκων ἐξείπῃ, οὔτε τι αὐτῷ ἐξελάλησε, καὶ τῷ Κικέρωνι πάνθ’ ὅσα ἠβουλήθη ἑλληνιστὶ ἐπέστειλεν, ἵνα ἂν καὶ τὰ γράμματα ἁλῷ, ἀλλ’ ἀσύνετά γε καὶ τότε τοῖς βαρβάροις ὄντα μηδέν σφας ἐκδιδάξῃ. εἰώθει δὲ καὶ ἄλλως, ὁπότε τι δι’ ἀπορρήτων τινὶ ἐπέστελλε, τὸ τέταρτον ἀεὶ στοιχεῖον ἀντὶ τοῦ καθήκοντος ἀντεγγράφειν, ὅπως ἂν ἄγνωστα τοῖς πολλοῖς ᾖ τὰ γραφόμενα. ὁ δ’ οὖν ἱππεὺς ἦλθε μὲν πρὸς τὸ τῶν Ῥωμαίων στρατόπεδον, μὴ δυνηθεὶς δ’ ἐγγύθεν αὐτῷ προσμῖξαι συνέδησε τὰ γράμματα ἀκοντίῳ, καὶ ὡς ἱεὶς αὐτὸ ἐς τοὺς πολεμίους πρὸς πύργον ἐξεπίτηδες προσέπηξε. καὶ ὁ μὲν Κικέρων οὕτω τὴν πρόσοδον τοῦ Καίσαρος μαθὼν ἀνεθάρσησε καὶ προθυμότερον", "st": "40.9"}, {"sp": "N", "t": "διεκαρτέρησεν· οἱ δὲ δὴ βάρβαροι ἐπὶ πολὺ μὲν τὴν ἐπικουρίαν αὐτοῦ ἠγνόησαν (νυκτοπορῶν γὰρ ἔπειτα τὰς ἡμέρας ἐν ἀφανεστάτοις χωρίοις ηὐλίζετο, ὅπως ἀπροσδοκήτοις ὅτι μάλιστα αὐτοῖς προσμίξῃ), ὀψὲ δέ ποτε ἐκ τῆς τῶν πολιορκουμένων περιχαρείας ὑποτοπήσαντες αὐτὴν προσκόπους ἔπεμψαν, καὶ μαθόντες παρ’ αὐτῶν πλησιάζοντα ἤδη τὸν Καίσαρα ὥρμησαν ἐπ’ αὐτὸν ὡς καὶ ἀνελπίστῳ οἱ προσπεσούμενοι. προμαθὼν οὖν τοῦτ’ ἐκεῖνος τήν τε νύκτα κατὰ χώραν ἔμεινε, καὶ ὑπὸ τὴν ἕω χωρίον τι ἐρυμνὸν προκαταλαβὼν ἐνταῦθα ὡς ἐν βραχυτάτῳ ἐστρατοπεδεύσατο τοῦ καὶ μετ’ ὀλίγων εἶναι δοκεῖν καὶ ἐκ τῆς πορείας πεπονῆσθαι τήν τε ἔφοδόν σφων δεδιέναι, κἀκ τούτου καὶ ἐς αὐτὸ τὸ μετέωρον αὐτοὺς ὑπαγαγέσθαι. καὶ ἔσχεν οὕτως· καταφρονήσαντες γὰρ αὐτοῦ διὰ ταῦτα πρός τε τὸ ὄρθιον προσέβαλον καὶ μεγάλως ἔπταισαν, ὥστε μηκέτ’ ἀντιπολεμῆσαι.", "st": "40.10"}, {"sp": "N", "t": "οὕτω μὲν οὖν τότε καὶ ἐκεῖνοι καὶ οἱ ἄλλοι πάντες ἐχειρώθησαν, οὐ μέντοι καὶ δι’ εὐνοίας τοῖς Ῥωμαίοις ἦσαν. οἱ γοῦν Τρήουηροι φοβηθέντες, ἐπειδήπερ τοὺς παρ’ ἑκάστοις πρώτους ὁ Καῖσαρ μεταπέμπων ἐκόλαζε, μὴ καὶ αὐτοὶ δίκην δῶσιν, ἐξεπολεμώθησαν αὖθις αὐτοῖς, Ἰνδουτιομάρου σφᾶς ἀναπείσαντος, καὶ συναποστήσαντες καὶ ἄλλους τινὰς τῶν τὰ αὐτὰ δεδιότων ἐπεστράτευσαν ἐπὶ τὸν Λαβιῆνον τὸν Τίτον ἐν Ῥημοῖς ὄντα, καὶ ἐπεξελθόντων σφίσι παρὰ δόξαν τῶν Ῥωμαίων ἐφθάρησαν. ταῦτα μὲν ἐν τῇ Γαλατίᾳ ἐγένετο, καὶ ἐν αὐτῇ καὶ ὁ Καῖσαρ ἐχείμασεν ὡς καὶ ἀκριβῶς σφας", "st": "40.11"}, {"sp": "N", "t": "καταστήσασθαι δυνησόμενος. ὁ δὲ δὴ Κράσσος ἐπιθυμήσας τι καὶ αὐτὸς δόξης τε ἅμα καὶ κέρδους ἐχόμενον πρᾶξαι, ἔπειτ’ ἐπειδὴ μηδὲν ἐν τῇ Συρίᾳ τοιοῦτό τι εἶδεν ὄν (αὐτοί τε γὰρ ἡσύχαζον, καὶ οἱ πρόσθε προσπολεμήσαντές σφισιν οὐδὲν ὑπ’ ἀδυνασίας παρεκίνουν), ἐπὶ τοὺς Πάρθους ἐπεστράτευσε, μήτε ἔγκλημά τι αὐτοῖς ἐπιφέρων μήτε τοῦ πολέμου οἱ ἐψηφισμένου· αὐτούς τε γὰρ παμπλουσίους ἤκουεν ὄντας, καὶ τὸν Ὀρώδην εὐάλωτον ἅτε καὶ νεοκατάστατον εἶναι προσεδόκησε. τόν τε οὖν Εὐφράτην ἐπεραιώθη, καὶ προῆλθεν ἐπὶ πολὺ τῆς Μεσοποταμίας, φέρων τε αὐτὴν καὶ πορθῶν· τῆς γὰρ διαβάσεως αὐτοῦ ἀδοκήτου τοῖς βαρβάροις γενομένης οὐδεμία ἀκριβὴς φυλακὴ αὐτῆς καθειστήκει, ὥστε ταχὺ μὲν ὁ Σιλάκης ὁ τότε τῆς χώρας ἐκείνης σατραπεύων ἡττήθη τε περὶ Ἰχνίας, τεῖχός τι οὕτω καλούμενον, ἱππεῦσιν ὀλίγοις μαχεσάμενος, καὶ τρωθεὶς ἀπεχώρησεν αὐτάγγελος τῷ βασιλεῖ τῆς ἐπιστρατείας αὐτοῦ", "st": "40.12"}, {"sp": "N", "t": "γενησόμενος, ταχὺ δὲ καὶ ὁ Κράσσος τά τε φρούρια καὶ τὰς πόλεις τὰς Ἑλληνίδας μάλιστα, τάς τε ἄλλας καὶ τὸ Νικηφόριον ὠνομασμένον, προσεποιήσατο· τῶν γὰρ Μακεδόνων καὶ τῶν ἄλλων τῶν συστρατευσάντων σφίσιν Ἑλλήνων ἄποικοι πολλοί, … βίᾳ ἀχθόμενοι καὶ ἐς τοὺς Ῥωμαίους ὡς καὶ φιλέλληνας πολλὰ ἐλπίζοντες, οὐκ ἀκουσίως μεθίσταντο· πλήν τε ὅτι οἱ Ζηνοδοτίου οἰκήτορες μετέπεμψάν τινας αὐτῶν ὡς καὶ μεταστησόμενοι, ἐπειδὴ δὲ ἔνδον ἐγένοντο, ἀπέλαβόν τε αὐτοὺς καὶ διέφθειραν καὶ διὰ τοῦτο καὶ ἀνέστησαν, οὐδὲν ἄλλο δεινὸν οὔτε ἔπραξε τότε Κράσσος οὔτε ἔπαθε. πάντως δὲ κἂν τὰ λοιπὰ χωρία τὰ ἐντὸς τοῦ Τίγριδος ὄντα ἐκεχείρωτο, εἰ τῇ τε ἑαυτοῦ ὁρμῇ καὶ τῇ τῶν βαρβάρων ἐκπλήξει πρὸς πάντα ὁμοίως ἐκέχρητο, καὶ προσέτι καὶ κατὰ χώραν χειμάσας ἐν φρουρᾷ αὐτὰ ἀκριβεῖ ἐπεποίητο. νῦν δὲ ἑλὼν ὅσα ἐξ ἐπιδρομῆς ἠδυνήθη λαβεῖν, οὔτε τι τῶν λοιπῶν οὔτ’ αὐτῶν ἐκείνων ἐφρόντισεν, ἀλλὰ τῇ τε ἐν τῇ Μεσοποταμίᾳ διατριβῇ ἀχθεσεὶς καὶ τῆς ἐν τῇ Συρίᾳ ῥᾳστώνης ἐπιθυμήσας παρέσχετο τοῖς Πάρθοις καιρὸν παρασκευάσασθαι καὶ τοὺς ἐγκαταλειφθέντας ἐν τῇ χώρᾳ στρατιώτας κακῶσαι.", "st": "40.13"}, {"sp": "N", "t": "αὕτη μὲν ἡ ἀρχὴ τοῖς Ῥωμαίοις τοῦ πρὸς αὐτοὺς πολέμου ἐγένετο· οἰκοῦσι δὲ ὑπὲρ τοῦ Τίγριδος τὸ μὲν πολὺ τείχη καὶ φρούρια, ἤδη δὲ καὶ πόλεις, ἄλλας τε καὶ Κτησιφῶντα, ἐν ᾗ καὶ βασίλεια ἔχουσι. τὸ γὰρ γένος σφῶν ἦν μέν που καὶ παρὰ τοῖς πάλαι βαρβάροις, καὶ τό γε ὄνομα τοῦτο καὶ ὑπὸ τὴν Περσικὴν βασιλείαν εἶχον· ἀλλὰ τότε μὲν αὐτοί τε ἐν μέρει χώρας βραχεῖ ᾤκουν καὶ δυναστείαν ὑπερόριον οὐκ ἐκέκτηντο, ἐπεὶ δὲ ἥ τε τῶν Περσῶν ἀρχὴ κατελύθη καὶ τὰ τῶν Μακεδόνων ἤκμασεν, οἵ τε τοῦ Ἀλεξάνδρου διάδοχοι στασιάσαντες ἄλλοι ἄλλα ἀπετέμοντο καὶ βασιλείας ἰδίας κατεσκευάσαντο, ἔς τε τὸ μέσον τότε πρῶτον ὑπ’ Ἀρσάκου τινὸς ἀφίκοντο, ὅθενπερ καὶ οἱ ἔπειτα βασιλεύσαντες αὐτῶν Ἀρσακίδαι ἐπωνομάσθησαν, καὶ εὐτυχήσαντες τήν τε πλησιόχωρον ἐκτήσαντο πᾶσαν καὶ τὴν Μεσοποταμίαν σατραπείαις κατέσχον, τελευτῶντες δὲ ἐπὶ τοσοῦτον καὶ τῆς δόξης καὶ τῆς δυνάμεως ἐχώρησαν ὥστε καὶ τοῖς Ῥωμαίοις τότε τε ἀντιπολεμῆσαι καὶ δεῦρο ἀεὶ ἀντίπαλοι νομίζεσθαι. εἰσὶ μὲν γὰρ καὶ ἄλλως ἰσχυροὶ τὰ πολέμια, μεῖζον δ’ ὅμως ὄνομα, καίτοι μήτε τῶν Ῥωμαίων τι παρῃρημένοι καὶ προσέτι καὶ τῆς ἑαυτῶν ἔστιν ἃ προέμενοι, ἔχουσιν, ὅτι μηδέπω δεδούλωνται, ἀλλὰ καὶ νῦν ἔτι τοὺς πολέμους τοὺς πρὸς ἡμᾶς,", "st": "40.14"}, {"sp": "N", "t": "ὁσάκις ἂν συνενεχθῶσι, διαφέρουσι. περὶ μὲν οὖν τοῦ τε γένους καὶ τῆς χώρας τῆς τε ἰδιότητος τῶν ἐπιτηδευμάτων αὐτῶν πολλοῖς τε εἴρηται καὶ ἐγὼ οὐκ ἐν γνώμῃ ποιοῦμαι συγγράψαι· τῇ δὲ δὴ ὁπλίσει καὶ τῇ τῶν πολέμων διαχειρίσει (τούτων γὰρ ὁ ἐξετασμὸς τῷδε τῷ λόγῳ, ὅτι καὶ ἐς χρείαν αὐτῶν ἀφικνεῖται, προσήκει) τοιᾷδε χρῶνται. ἀσπίδι μὲν οὐδὲν νομίζουσιν, ἱπποτοξόται δὲ καὶ κοντοφόροι, τὰ πολλὰ κατάφρακτοι, στρατεύονται. πεζοί τε ὀλίγοι μὲν καὶ οἱ ἀσθενέστεροι, τοξόται δ’ οὖν καὶ ἐκεῖνοι πάντες εἰσίν. ἔκ τε γὰρ παίδων ἀσκοῦνται, καὶ ὁ οὐρανὸς ἥ τε χώρα αὐτοῖς συναίρεται πρὸς ἀμφότερα. αὕτη τε γὰρ πεδιὰς ὡς πλήθει οὖσα ἀρίστη τε ἵππους τρέφειν ἐστὶ καὶ ἐπιτηδειοτάτη καθιππεύεσθαι· ἀγέλας γοῦν ὅλας καὶ ἐν τοῖς πολέμοις, ὥστ’ ἄλλοτε ἄλλοις ἵπποις χρῆσθαι καὶ πόρρωθέν τε ἐξαπιναίως ἐπελαύνειν καὶ μακράν ποι ἐξ αἰφνιδίου ἀποχωρεῖν, ἐπάγονται· καὶ ὁ οὐρανὸς ὁ ὑπὲρ αὐτῶν, ξηρότατός τε ὢν καὶ ἰκμάδα οὐδὲ ἐλαχίστην ἔχων, ἐντονωτάτας σφίσι τὰς τοξείας πλὴν τοῦ πάνυ χειμῶνος παρέχεται. καὶ διὰ τοῦτο τὴν ὥραν ἐκείνην οὐδαμῇ στρατεύονται. τῷ δὲ δὴ λοιπῷ ἔτει δυσμαχώτατοι ἔν τε τῇ σφετέρᾳ καὶ ἐν τῇ ὁμοιοτρόπῳ εἰσί· τόν τε γὰρ ἥλιον φλογωδέστατον ὄντα ἀνέχονται τῇ συνηθείᾳ, καὶ τῆς ὀλιγότητος τῆς τε δυσχερείας τοῦ ποτοῦ πολλὰ ἀλεξιφάρμακα ἀνευρήκασιν, ὥστε καὶ ἐκ τούτου μὴ χαλεπῶς τοὺς ἐς τὴν χώραν αὐτῶν ἐσβάλλοντας ἀμύνεσθαι. ἔξω γὰρ ἐκείνης ὑπὲρ τὸν Εὐφράτην μάχαις μέν τισι καὶ καταδρομαῖς αἰφνιδίοις ἤδη ποτὲ ἴσχυσάν τι, πολεμῆσαι δέ τισιν ἀπαυστὶ καὶ διαρκῶς οὐ δύνανται, καὶ ἐς ἀλλοτριωτάτην σφίσι καὶ τῆς γῆς καὶ τοῦ οὐρανοῦ κατάστασιν ἀπαρτῶντες, καὶ μήτε σίτου μήτε μισθοφορᾶς παρασκευὴν ποιούμενοι.", "st": "40.15"}, {"sp": "N", "t": "τοιαῦτα μὲν τὰ τῶν Πάρθων ἐστίν, ἐσβαλόντος δὲ ἐς τὴν Μεσοποταμίαν τοῦ Κράσσου ὥσπερ εἴρηται, ὁ Ὀρώδης ἔπεμψε μὲν καὶ πρὸς ἐκεῖνον ἐς τὴν Συρίαν πρέσβεις, τῆς τε ἐσβολῆς αἰτιώμενος καὶ τὰς αἰτίας τοῦ πολέμου πυνθανόμενος, ἔπεμψε δὲ πρός τε τὰ ἑαλωκότα τά τε μεθεστηκότα Σουρήναν σὺν στρατῷ· αὐτὸς γὰρ τῇ Ἀρμενίᾳ τῇ τοῦ Τιγράνου ποτὲ γενομένῃ διενοεῖτο ἐπιστρατεῦσαι, ὅπως ὁ Ἀρταβάζης ὁ τοῦ Τιγράνου παῖς ὁ τότε αὐτῆς βασιλεύων μηδεμίαν τοῖς Ῥωμαίοις, ἅτε καὶ περὶ τῇ οἰκείᾳ δεδιώς, βοήθειαν πέμψῃ. ὁ οὖν Κράσσος ἐκείνῳ τε ἐν Σελευκείᾳ (ἔστι δὲ πόλις ἐν τῇ Μεσοποταμίᾳ, πλεῖστον τὸ Ἑλληνικὸν καὶ νῦν ἔχουσα) τὰς αἰτίας τοῦ πολέμου ἐρεῖν ἔφη· καὶ αὐτῷ τῶν Πάρθων τις ἐς τὴν χεῖρα τὴν ἀριστερὰν τοῖς τῆς ἑτέρας δακτύλοις κρούσας εἶπεν ὅτι “θᾶσσον ἐντεῦθεν τρίχες ἀναφύσονται ἢ σὺ ἐν Σελευκείᾳ γενήσῃ.”", "st": "40.16"}, {"sp": "N", "t": "καὶ ἐπειδὴ ὁ χειμὼν ἐν ᾧ Γναῖός τε Καλουῖνος καὶ Οὐαλέριος Μεσσάλας ὑπάτευσαν ἐνέστη, πολλὰ μὲν καὶ ἐν αὐτῇ τῇ Ῥώμῃ τέρατα τότε ἐγένετο· καὶ γὰρ βύαι καὶ λύκοι ὤφθησαν, οἵ τε κύνες περιφοιτῶντες ὠρύοντο, καὶ ἀγάλματα τὰ μὲν ἵδρωσε τὰ δὲ ἐκεραυνώθη, τάς τε ἀρχὰς τὸ μέν τι φιλονεικίᾳ, τὸ δὲ δὴ πλεῖστον ὑπό τε τῶν ὀρνίθων καὶ ὑπὸ διοσημιῶν μόλις ποτὲ τῷ ἑβδόμῳ μηνὶ ἀπέδειξαν· ἀλλ’ ἐκεῖνα μὲν οὐδὲν σαφὲς διεδήλου ἐς ὅ τι τελευτήσει· τά τε γὰρ ἐν τῷ ἄστει ἐταράττετο καὶ οἱ Γαλάται ἐκινήθησαν αὖθις, πρός τε τοὺς Πάρθους οὐδ’ εἰδότες πω ὅπως συνερρώγεσαν· τῷ δὲ δὴ Κράσσῳ τὸν Εὐφράτην κατὰ τὸ Ζεῦγμα (οὕτω γὰρ ἀπὸ τῆς τοῦ Ἀλεξάνδρου στρατείας τὸ χωρίον ἐκεῖνο, ὅτι ταύτῃ ἐπεραιώθη, κέκληται) διαβαίνοντι καὶ προφανῆ καὶ εὐσύμβολα", "st": "40.17"}, {"sp": "N", "t": "συνηνέχθη. ὁ γὰρ ἀετὸς ὠνομασμένος (ἔστι δὲ νεὼς μικρός, καὶ ἐν αὐτῷ ἀετὸς χρυσοῦς ἐνίδρυται· καθίσταταί τε ἐν πᾶσι τοῖς ἐκ τοῦ καταλόγου στρατοπέδοις, καὶ οὐδαμόσε ἐκ τῶν χειμαδίων, πλὴν εἴ ποι σύμπας ὁ στρατὸς ἐξίοι, κινεῖται· καὶ αὐτὸν εἷς ἀνὴρ ἐπὶ δόρατος μακροῦ, ἐς ὀξὺ τὸν στύρακα ἀπηγμένου ὥστε καὶ ἐς τὸ δάπεδον καταπήγνυσθαι, φέρει) — τούτων οὖν τῶν ἀετῶν εἷς οὐκ ἠθέλησε τὸν Εὐφράτην αὐτῷ τότε συνδιαβῆναι, ἀλλὰ ἐν τῇ γῇ ἐνέσχετο ὥσπερ ἐμπεφυκώς, πρὶν δὴ πολλοὶ περιστάντες βίᾳ αὐτὸν ἀνέσπασαν. καὶ ὁ μὲν καὶ ἄκων ἐπηκολούθησε, σημεῖον δέ τι τῶν μεγάλων, τῶν τοῖς ἱστίοις ἐοικότων καὶ φοινικᾶ γράμματα ἐπ’ αὐτοῖς πρὸς δήλωσιν τοῦ τε στρατοῦ καὶ τοῦ στρατηγοῦ σφων τοῦ αὐτοκράτορος ἐχόντων, ἐς τὸν ποταμὸν ἀπὸ τῆς γεφύρας περιτραπὲν ἐνέπεσε. καὶ τοῦτο μὲν ὑπὸ πνεύματος ὄντος σφοδροῦ ἐγένετο· ὁ δὲ δὴ Κράσσος καὶ τἆλλα τὰ ἰσομήκη οἱ συντεμών, ὅπως βραχύτερα καὶ ἐκ τούτου καὶ βεβαιότερα φέρειν εἴη, προσεπηύξησε τὰ τέρατα. καὶ γὰρ ὁμίχλη ἐν αὐτῇ τῇ τοῦ ποταμοῦ διαβάσει τοσαύτη τοῖς στρατιώταις περιεχύθη ὥστε περί τε ἀλλήλοις αὐτοὺς σφαλῆναι καὶ μηδὲν τῆς πολεμίας, πρὶν ἐπιβῆναι αὐτῆς, ἰδεῖν· καὶ τὰ διαβατήρια τά τε ἀπόβαθρά σφισι δυσχερέστατα ἐγένετο. κἀν τούτῳ ἄνεμός τε πολὺς ἐπέπεσε καὶ κεραυνοὶ κατέσκηψαν, ἥ τε γέφυρα, πρὶν πάντας αὐτοὺς διελθεῖν, διελύθη. καὶ ἦν γὰρ τὰ γιγνόμενα οἷα πάντα τινὰ καὶ τῶν πάνυ ἀγνωμόνων τε καὶ ἀσυνέτων ἐκδιδάξαι ὅτι κακῶς ἀπαλλάξουσι καὶ οὐκ ἀνακομισθήσονται, φόβος καὶ κατήφεια ἐν τῷ", "st": "40.18"}, {"sp": "N", "t": "στρατοπέδῳ ἐγένετο δεινή. ὁ οὖν Κράσσος παραμυθούμενος αὐτούς εἶπεν ὅτι “μὴ καταπλήττεσθε, ἄνδρες στρατιῶται, εἰ ἡ γέφυρα διέφθαρται, μηδὲ οἴεσθε ἐκ τούτου χαλεπόν τι ἐπισημαίνεσθαι· ἐγὼ γὰρ ὑμῖν αὐτὸς ἐπομνὺς λέγω ὅτι δι’ Ἀρμενίας τὴν ἐπάνοδον ποιήσασθαι ἔγνωκα.” ἐκ μὲν δὴ οὖν τούτου ἐθάρσυνε, νῦν δὲ προσεπειπών τινα ἔφη, μέγα ἀναβοήσας, “θαρσεῖτε· οὐδεὶς γὰρ ἡμῶν ἐντεῦθεν ἐπανήξει.” ἀκούσαντες γὰρ τοῦθ’ οἱ στρατιῶται οἰωνόν τέ σφισιν οὐδενὸς τῶν ἄλλων ἥττω γεγονέναι ἐνόμισαν καὶ ἐς ἀθυμίαν πλείω κατέπεσον, ὥστε μηδὲν ἔτι μηδὲ τῶν λοιπῶν αὐτοῦ παραινέσεων φροντίσαι, δι’ ὧν τόν τε βάρβαρον ἐφαύλιζε καὶ τὰ τῶν Ῥωμαίων ἐνεκωμίαζε, χρήματά τε αὐτοῖς ἐδίδου καὶ γέρα ἐπηγγέλλετο. ἀλλὰ καὶ ὣς εἵποντο, καὶ οὔτε ἀντεῖπέν οἱ οὐδεὶς οὔτ’ ἀντέπραξε, τάχα μὲν καὶ ὑπὸ τοῦ νόμου, ἤδη δὲ καὶ ἐκπεπληγμένοι καὶ μήτε τι βουλεῦσαι μήτε πρᾶξαι σωτήριον δυνάμενοι. πάντα γοῦν καὶ τὰ ἄλλα, καθάπερ ὑπὸ δαιμονίου τινὸς κατακεκριμένοι, καὶ ταῖς γνώμαις καὶ τοῖς σώμασιν ἐσφάλλοντο.", "st": "40.19"}, {"sp": "N", "t": "μέγιστον δὲ ὅμως αὐτοὺς ὁ Ἄβγαρος ὁ Ὀρροηνὸς ἐλυμήνατο· ἔνσπονδος γὰρ τοῖς Ῥωμαίοις ἐπὶ τοῦ Πομπηίου γενόμενος ἀνθείλετο τὰ τοῦ βαρβάρου. καὶ τοῦτο μὲν καὶ ὁ Ἀλχαυδόνιος ὁ Ἀράβιος ἐποίησε· πρὸς γὰρ τὸ ἰσχυρὸν ἀεὶ μεθίστατο. ἀλλ’ ἐκεῖνος μὲν ἐκ τοῦ προφανοῦς ἀπέστη, καὶ κατὰ τοῦτο οὐ δυσφύλακτος ἦν· ὁ δ’ Ἄβγαρος ἐφρόνει μὲν τὰ τοῦ Πάρθου, ἐπλάττετο δὲ τῷ Κράσσῳ φιλικῶς ἔχειν, καὶ χρήματά τε ἀφειδῶς αὐτῷ ἀνήλισκε, καὶ τά τε βουλεύματα αὐτοῦ πάντα καὶ ἐμάνθανε καὶ ἐκείνῳ διήγγελλε, καὶ προσέτι εἰ μέν τι χρηστόν σφων ἦν, ἀπέτρεπεν αὐτόν, εἰ δ’ ἀσύμφορον, ἐπέσπερχε. καὶ δὴ καὶ τοιόνδε τι τελευτῶν ἔπραξε. τοῦ γὰρ Κράσσου πρὸς Σελεύκειαν ὁρμῆσαι διανοουμένου, ὥστε ἐκεῖσέ τε ἀσφαλῶς παρά τε τὸν Εὐφράτην καὶ δι’ αὐτοῦ τῷ τε στρατῷ καὶ τοῖς ἐπιτηδείοις κομισθῆναι, καὶ μετ’ αὐτῶν (προσποιήσεσθαι γάρ σφας ἅτε καὶ Ἕλληνας ῥᾳδίως ἤλπιζεν) ἐπὶ Κτησιφῶντα μὴ χαλεπῶς περαιωθῆναι, τούτου μὲν ὡς καὶ χρονίου ἐσομένου ἀμελῆσαι αὐτὸν ἐποίησε, τῷ δὲ δὴ Σουρήνᾳ ὡς καὶ ἐγγὺς καὶ μετ’", "st": "40.20"}, {"sp": "N", "t": "ὀλίγων ὄντι συμμῖξαι ἔπεισε. καὶ μετὰ τοῦτο παρασκευάσας τὸν μὲν ὅπως ἀπόληται τὸν δ’ ὅπως κρατήσῃ (συνεχῶς γὰρ προφάσει κατασκοπῆς τῷ Σουρήνᾳ συνεγίγνετο), ἐξήγαγε τοὺς Ῥωμαίους ἀφροντιστοῦντας ὡς ἐπὶ νίκην ἕτοιμον, καὶ αὐτοῖς ἐν αὐτῷ τῷ ἔργῳ συνεπέθετο. ἐπράχθη δὲ ὧδε. οἱ Πάρθοι τὸ πλεῖον τοῦ στρατοῦ σφων ἀποκρύψαντες (ἡ γὰρ χώρα ἀνώμαλός τέ πῃ ἦν καὶ δένδρα εἶχεν) ἀπήντησαν τοῖς Ῥωμαίοις. ἰδὼν οὖν αὐτοὺς ὁ Κράσσος, οὐκ ἐκεῖνος ἀλλ’ ὁ νεώτερος (πρὸς γὰρ τὸν πατέρα ἐκ τῆς Γαλατίας παρῆν), καὶ καταφρονήσας σφῶν ὡς καὶ μόνων, ἀντεξήγαγε τῷ ἱππικῷ, καὶ τραπομένους ἐξεπίτηδες αὐτοὺς ἐπιδιώκων ὡς καὶ κρατῶν ἀπήχθη πολὺ ἀπὸ τῆς φάλαγγος, κἀνταῦθα", "st": "40.21"}, {"sp": "N", "t": "περιστοιχισθεὶς κατεκόπη. γενομένου δὲ τούτου οἱ πεζοὶ τῶν Ῥωμαίων οὐκ ἀπετράποντο μέν, ἀλλὰ καὶ προθύμως τοῖς Πάρθοις, ὡς καὶ τιμωρήσοντες αὐτῷ, συνέμιξαν· οὐ μέντοι καὶ ἄξιόν σφων οὐδὲν ἔκ τε τοῦ πλήθους καὶ ἐκ τοῦ τρόπου τῆς μάχης αὐτῶν, ἄλλως τε καὶ ὑπὸ τοῦ Ἀβγάρου ἐπιβουλευθέντες, ἐποίησαν. εἴτε γὰρ συνασπίσαι γνοίησαν ὡς καὶ τῇ πυκνότητι τῆς τάξεώς σφων τὰ τοξεύματα αὐτῶν ἐκφευξόμενοι, προσπίπτοντές σφισιν οἱ κοντοφόροι ῥύμῃ τοὺς μὲν κατέβαλλον, τοὺς δὲ πάντως γοῦν ἐσκεδάννυσαν· εἴτε καὶ διασταῖεν ὅπως τοῦτό γε ἐκκλίνοιεν, ἐτοξεύοντο. κἀν τούτῳ πολλοὶ μὲν καὶ ἐξ αὐτῆς τῆς προσελάσεως τῶν κοντοφόρων ἐκπληττόμενοι ἔθνησκον, πολλοὶ δὲ καὶ ὑπὸ τῶν ἱππέων ἐγκαταλαμβανόμενοι ἐφθείροντο· ἄλλοι τοῖς κοντοῖς ἀνετρέποντο ἢ καὶ ἀναπειρόμενοι ἐφέροντο. τά τε βέλη καὶ πυκνὰ καὶ πανταχόθεν ἅμα αὐτοῖς ἐμπίπτοντα συχνοὺς μὲν καιρίᾳ πληγῇ κατέβαλλε, συχνοὺς δὲ ἀπομάχους εἰργάζετο, πᾶσι δ’ ἀσχολίαν ἐνεποίει· ἔς τε γὰρ τοὺς ὀφθαλμούς σφων ἐσπετόμενα καὶ πρὸς τὰς χεῖρας τό τε ἄλλο σῶμα πᾶν καὶ διὰ τῶν ὅπλων χωροῦντα τήν τε προφυλακὴν αὐτῶν ἀφῃρεῖτο, καὶ γυμνοῦσθαί σφας πρὸς τὸ ἀεὶ τιτρῶσκον ἠνάγκαζεν, ὥστε ἐν ᾧ τις τόξευμα ἐφυλάττετο ἢ καὶ ἐμπαγὲν ἐξῃρεῖτο, πλείω τραύματα ἄλλα ἐπ’ ἄλλοις ἐλάμβανε. κἀκ τούτου ἄπορον μέν σφισι κινηθῆναι, ἄπορον δὲ καὶ ἀτρεμίζειν ἦν· οὔτε γὰρ ἀσφάλειαν οὐδέτερον αὐτοῖς εἶχε, καὶ τὸν ὄλεθρον ἀμφότερα ἐπέφερε, τὸ μὲν ὅτι οὐκ ἐδύναντο, τὸ δὲ ὅτι ῥᾷον ἐτιτρώσκοντο.", "st": "40.22"}, {"sp": "N", "t": "καὶ ταῦτα μέν, ἕως ἔτι πρὸς μόνους τοὺς ἐμφανεῖς πολεμίους ἐμάχοντο, ἔπασχον· ὁ γὰρ Ἄβγαρος οὐκ εὐθὺς αὐτοῖς ἐπεχείρησεν· ἐπεὶ δὲ καὶ ἐκεῖνος ἐπέθετο, ἐνταῦθα οἱ Ὀρροηνοὶ αὐτοί τε ὄπισθεν ἐς τὰ γυμνὰ ἀπεστραμμένους σφᾶς ἔπαιον καὶ τοῖς ἄλλοις ῥᾷον φονεύειν παρεῖχον. τὴν γὰρ τάξιν, ὅπως ἀντιπρόσωποι αὐτοῖς γένωνται, ἐξελίξαντες ὄπισθέν σφων τοὺς Πάρθους ἐποιήσαντο. αὖθίς τε οὖν πρὸς αὐτοὺς μετεστράφησαν, καὶ πάλιν αὖθις πρὸς ἐκείνους, εἶτα πρὸς τούτους. κἀκ τοῦ τοιούτου μᾶλλον ἐπιταραχθέντες, ἅτε καὶ συνεχῶς δεῦρο κἀκεῖσε μεθιστάμενοι καὶ πρὸς τὸ ἀεὶ τιτρῶσκον ἀποβλέπειν ἀναγκαζόμενοι, τοῖς τε ξίφεσι τοῖς σφετέροις περιέπιπτον καὶ πολλοὶ καὶ ὑπ’ ἀλλήλων ἀπώλοντο. τέλος δὲ ἐς στενὸν οὕτω κατεκλείσθησαν, ἀναγκαζόμενοι, τῶν πολεμίων ἀεί σφισι πανταχόθεν ἅμα προσπιπτόντων, ταῖς τῶν παραστατῶν ἀσπίσι τὰς γυμνώσεις σφῶν προστέλλειν, ὥστε μηδὲ κινηθῆναι ἔτι δυνηθῆναι. οὐ μὴν οὐδὲ τὴν στάσιν βεβαίαν ὑπὸ τοῦ πλήθους τῶν νεκρῶν εἶχον, ἀλλὰ καὶ περὶ ἐκείνοις ἀνετρέποντο. τό τε καῦμα καὶ τὸ δίψος (μεσοῦντός τε γὰρ τοῦ θέρους καὶ ἐν μεσημβρίᾳ ταῦτ’ ἐγίγνετο) καὶ ὁ κονιορτός (ὅπως γὰρ ὅτι πλεῖστος αἴροιτο, πάντες σφᾶς οἱ βάρβαροι περιίππευον) δεινῶς τοὺς λοιποὺς συνῄρει, καὶ συχνοὶ καὶ ὑπὸ", "st": "40.23"}, {"sp": "N", "t": "τούτων ἄτρωτοι ἔπεσον. κἂν πασσυδὶ ἀπώλοντο, εἰ μὴ οἵ τε κοντοὶ τῶν βαρβάρων οἱ μὲν ἀπεστράφησαν οἱ δὲ ἐκλάσθησαν, καὶ αἱ νευραὶ τῇ συνεχείᾳ τῆς βολῆς ἐρράγησαν, τά τε βέλη ἐξετοξεύθη, καὶ τὰ ξίφη πάντα ἀπημβλύνθη, τό τε μέγιστον οἱ ἄνδρες αὐτοὶ φονεύοντες ἐξέκαμον. οὕτω γὰρ δή (καὶ γὰρ νὺξ ἐγίγνετο καὶ πόρρω ποι ἀφιππεῦσαι αὐτοὺς ἐχρῆν) ἀπεχώρησαν· οὐδέποτε γὰρ πλησίοι οὐδὲ τοῖς ἀσθενεστάτοις στρατοπεδεύονται διὰ τὸ μηδεμιᾷ ταφρείᾳ χρῆσθαι καὶ διὰ τό, ἄν τις ἐπέλθῃ σφίσιν ἐν τῷ σκότῳ, ἀδύνατοι μὲν τῇ ἵππῳ ἀδύνατοι δὲ καὶ τῇ τοξείᾳ ἰσχυρίσασθαι εἶναι. οὐ μέντοι καὶ ζῶντά τινα τῶν Ῥωμαίων τόθ’ εἷλον· ἑστῶτάς τε γὰρ αὐτοὺς ἐν τοῖς ὅπλοις ὁρῶντες, καὶ μήτε τινὰ ἐκεῖνα ἀπορριπτοῦντα μήτ’ αὐτὸν φεύγοντα αἰσθανόμενοι, ἰσχύειν τε ἔτι σφᾶς ἐνόμισαν καὶ ἐφοβήθησαν αὐτῶν ἐπιλαβέσθαι.", "st": "40.24"}, {"sp": "N", "t": "οὕτως ὅ τε Κράσσος καὶ ἄλλοι ὅσοι γε ἠδυνήθησαν ἐς τὰς Κάρρας ὥρμησαν, βεβαίους σφίσιν ὑπὸ τῶν καταμεινάντων ἔνδον Ῥωμαίων τηρηθείσας· πολλοὶ γὰρ δὴ τῶν τετρωμένων μήτε βαδίσαι οἷοί τε ὄντες μήτ’ ὀχημάτων εὐποροῦντες ἢ καὶ ποδηγέτας ἔχοντες (ἀγαπητῶς γὰρ οἱ λοιποὶ ἑαυτοὺς ἀνέφερον) κατὰ χώραν ἔμειναν. καὶ ἐκείνων τε οἱ μὲν ἀπέθανον ἐκ τῶν τραυμάτων ἢ καὶ ἑαυτοὺς καταχρησάμενοι, οἱ δὲ ἑάλωσαν τῇ ὑστεραίᾳ· καὶ τῶν διαδεδρακότων συχνοὶ μὲν ἐν τῇ ὁδῷ προλιπόντων σφᾶς τῶν σωμάτων, συχνοὶ δὲ καὶ μετὰ τοῦτ’ ἐφθάρησαν, θεραπείας παραχρῆμα ἀκριβοῦς μὴ δυνηθέντες τυχεῖν. ὁ γὰρ Κράσσος ἀθυμήσας οὐδὲ ἐν τῇ πόλει ἀσφαλῶς ἔθ’ ὑπομεῖναι δυνήσεσθαι ἐνόμισεν, ἀλλὰ δρασμὸν εὐθὺς ἐβουλεύσατο. καὶ ἐπειδὴ οὐχ οἷόν τε ἦν αὐτῷ μεθ’ ἡμέραν ἐξιόντι μὴ οὐ καταφώρῳ γενέσθαι, ἐπεχείρησε μὲν νυκτὸς ἀποδρᾶναι, προδοθεὶς δὲ ὑπὸ τῆς σελήνης, πανσελήνου οὔσης, οὐκ ἔλαθεν. προσέμεινάν τε οὖν μέχρι τῶν ἀσελήνων νυκτῶν, καὶ οὕτως ἄραντες δή, οἷα ἐν σκότῳ καὶ ἐν ἀλλοτρίᾳ καὶ προσέτι καὶ πολεμίᾳ γῇ φόβῳ τε ἰσχυρῷ, ἐσκεδάσθησαν, καὶ αὐτῶν οἱ μὲν ἁλόντες ἡμέρας γενομένης ἀπώλοντο, οἱ δὲ ἐς τὴν Συρίαν μετὰ Κασσίου Λογγίνου τοῦ ταμίου διεσώθησαν· ἄλλοι τῶν ὀρῶν μετ’ αὐτοῦ τοῦ Κράσσου λαβόμενοι παρεσκευάζοντο ὡς καὶ δι’ ἐκείνων ἐς τὴν Ἀρμενίαν φευξόμενοι.", "st": "40.25"}, {"sp": "N", "t": "γνοὺς δὲ τοῦτο ὁ Σουρήνας, καὶ φοβηθεὶς μὴ μεταστάντες ποι αὖθίς σφισι προσπολεμῶσι, προσβαλεῖν μὲν πρὸς τὰ μετέωρα ἄφιππα ὄντα οὐκ ἠθέλησεν (ὁπλῖταί τε γὰρ ὄντες καὶ ἐξ ὑπερδεξίων μαχόμενοι, καί τι καὶ ἀπονοίας ὑπ’ ἀπογνώσεως ἔχοντες, οὐ ῥᾴδιοι προσμῖξαί οἱ ἐγένοντο), πέμπει δὲ πρὸς αὐτοὺς ἐς σπονδὰς δῆθέν σφας προκαλούμενος, ἐφ’ ᾧ τὴν ἐντὸς τοῦ Εὐφράτου πᾶσαν ἐκλίπωσι. καὶ αὐτῷ ὁ Κράσσος οὐδὲν ἐνδοιάσας ἐπίστευσεν· ἔν τε γὰρ ἀκμῇ τοῦ δέους ὢν καὶ ὑπ’ ἐκπλήξεως τῆς τε ἰδίας ἅμα καὶ τῆς δημοσίας συμφορᾶς τεθολωμένος, καὶ προσέτι καὶ τοὺς στρατιώτας τήν τε ὁδὸν ὡς πολλὴν καὶ τραχεῖαν ὀκνοῦντας καὶ τὸν Ὀρώδην φοβουμένους ὁρῶν, οὐδὲν τῶν δεόντων προϊδέσθαι ἠδυνήθη. ἑτοίμου οὖν αὐτοῦ πρὸς τὰς σπονδὰς γενομένου ὁ Σουρήνας οὐκ ἠθέλησε δι’ ἑτέρων σπείσασθαι, ἀλλ’ ὅπως αὐτὸν μετ’ ὀλίγων ἀπολαβὼν συλλάβῃ, αὐτῷ ἐκείνῳ ἔφη βούλεσθαι ἐς λόγους ἐλθεῖν. κἀκ τούτου δόξαν σφίσιν ἐν τῷ μεταιχμίῳ μετ’ ἴσων ἀνδρῶν ἑκατέρωθεν συμβαλεῖν ἀλλήλοις, ὅ τε Κράσσος ἐς τὸ ὁμαλὸν ὑποκατέβη, καὶ ὁ Σουρήνας ἵππον αὐτῷ δῶρον, ἵνα δὴ θᾶσσον πρὸς αὐτὸν", "st": "40.26"}, {"sp": "N", "t": "ἀφίκηται, ἔπεμψε. καὶ οὕτω διαμέλλοντα τὸν Κράσσον, καὶ βουλευόμενον ὅ τι ποιήσῃ, συναρπάσαντες οἱ βάρβαροι βίᾳ ἐπὶ τὸν ἵππον ἀνέβαλον. κἀν τούτῳ ἀντιλαμβανομένων αὐτοῦ τῶν Ῥωμαίων ἔς τε χεῖράς σφισιν ἦλθον, καὶ τέως μὲν ἰσοπαλεῖς ἐγίγνοντο, ἔπειτα δὲ προσβοηθησάντων τινῶν αὐτοῖς ἐπεκράτησαν· οἱ γὰρ βάρβαροι ἔν τε τῷ πεδίῳ ὄντες καὶ προπαρεσκευασμένοι ἔφθησαν τοὺς ἄνω Ῥωμαίους ἀμύναντες σφίσι. καὶ οἵ τε ἄλλοι ἔπεσον καὶ ὁ Κράσσος, εἴτ’ οὖν ὑπὸ τῶν σφετέρων τινὸς ὅπως μὴ ζωγρηθῇ, εἴτε καὶ ὑπὸ τῶν πολεμίων ἐπειδὴ κακῶς ἐτέτρωτο, ἐσφάγη. καὶ ἐκείνῳ μὲν τοῦτο τὸ τέλος ἐγένετο, καὶ αὐτοῦ χρυσὸν ἐς τὸ στόμα οἱ Πάρθοι, ὥς γέ τινες λέγουσιν, ἐνέτηξαν ἐπισκώπτοντες· οὕτω γὰρ δὴ περὶ τὰ χρήματα, καίτοι πολυχρήματος ὤν, ἐσπουδάκει ὥστε καὶ ὡς πένητας οἰκτείρειν τοὺς μὴ δυναμένους στρατόπεδον ἐκ καταλόγου οἴκοθεν θρέψαι· τῶν δὲ δὴ στρατιωτῶν τὸ μὲν πλεῖον διὰ τῶν ὀρῶν ἐς τὴν φιλίαν ἀπέφυγε, τὸ δέ τι καὶ ἐς τοὺς πολεμίους ἑάλω.", "st": "40.27"}, {"sp": "N", "t": "οἱ δὲ δὴ Πάρθοι τότε μὲν οὐ περαιτέρω τοῦ Εὐφράτου προεχώρησαν, ἀλλὰ τὴν ἐντὸς αὐτοῦ πᾶσαν ἀνεκτήσαντο· μετὰ δὲ τοῦτο καὶ ἐς τὴν Συρίαν, οὐ μέντοι καὶ ἐν πλήθει τινί, ὡς μήτε στρατηγὸν μήτε στρατιώτας ἔχουσαν, ἐνέβαλον· ἀφ’ οὗπερ Κάσσιος ῥᾳδίως αὐτούς, ἅτε μὴ πολλοὺς ὄντας, ἀπεώσατο. οὗτος γὰρ ἐν μὲν ταῖς Κάρραις τῶν τε στρατιωτῶν τὴν αὐτοκράτορα αὐτῶν ἡγεμονίαν μίσει τοῦ Κράσσου διδόντων, καὶ προσέτι καὶ αὐτοῦ ἐκείνου ἐθελοντὶ διὰ τὸ τῆς συμφορᾶς μέγεθος ἐπιτρέποντος, οὐκ ἐδέξατο, τότε δὲ καὶ ἀνάγκῃ τῆς Συρίας ἔν τε τῷ παρόντι καὶ μετὰ ταῦτα προέστη. οἱ γὰρ βάρβαροι οὐκ ἀπέσχοντο αὐτῆς, ἀλλὰ χειρὶ αὖθις μείζονι, Πακόρου μὲν ὀνόματι, τοῦ υἱέος τοῦ Ὀρώδου, ἔργῳ δέ (παῖς γὰρ ἔτι ἐκεῖνος ἦν) Ὠσάκου ἡγουμένου σφίσιν, ἐστράτευσαν, καὶ μέχρι τῆς Ἀντιοχείας ἦλθον, πᾶσαν τὴν ἐν ποσὶ χειρούμενοι. καὶ ἐλπίδα εἶχον καὶ τὰ λοιπὰ καταστρέψεσθαι, μήτε τῶν Ῥωμαίων ἀξιομάχῳ τινὶ δυνάμει παρόντων, καὶ τῶν δήμων τῇ τε ἐκείνων δεσποτείᾳ ἀχθομένων καὶ πρὸς αὐτοὺς ἅτε καὶ γείτονας καὶ συνήθεις σφίσιν ὄντας", "st": "40.28"}, {"sp": "N", "t": "ἀποκλινόντων. ἁμαρτόντες δὲ τῆς Ἀντιοχείας (ὅ τε γὰρ Κάσσιος ἰσχυρῶς αὐτοὺς ἀπεκρούσατο, καὶ ἐκεῖνοι ἀδύνατοι πολιορκῆσαί τι ἦσαν) ἐπ’ Ἀντιγόνιαν ἐτράποντο. καὶ ἐπειδὴ τό τε προάστειον αὐτῆς σύμφυτον ἦν, καὶ οὐκ ἐθάρσησαν, ἀλλ’ οὐδὲ ἠδυνήθησαν ἐς αὐτὸ ἐσελάσαι, ἐνενόησαν μὲν τά τε δένδρα κόψαι καὶ τὸ χωρίον πᾶν ψιλῶσαι, ὅπως καὶ θαρσούντως καὶ ἀσφαλῶς τῇ πόλει προσμίξωσι, μὴ δυνηθέντες δέ (ὅ τε γὰρ πόνος πολὺς ἐγίγνετο καὶ ὁ χρόνος ἄλλως ἀναλοῦτο, ὅ τε Κάσσιος τοὺς ἀποσκεδαννυμένους σφῶν ἐλύπει) ἀπανέστησαν ὡς καὶ ἐπ’ ἄλλο τι ἐπιστρατεύσοντες. κἀν τούτῳ ὁ Κάσσιος ἔς τε τὴν ὁδὸν δι’ ἧς ἀποπορεύεσθαι ἔμελλον ἐλόχισε, κἀνταῦθα ἐπιφανείς σφισι μετ’ ὀλίγων ἔς τε δίωξιν αὐτοὺς ὑπηγάγετο, καὶ περιστοιχισάμενος ἄλλους τε καὶ τὸν Ὠσάκην ἀπέκτεινε. τελευτήσαντος δ’ ἐκείνου πᾶσαν τὴν Συρίαν ὁ Πάκορος ἐξέλιπε, καὶ οὐδ’ αὖθίς ποτε ἐς αὐτὴν ἐσέβαλεν.", "st": "40.29"}, {"sp": "N", "t": "ἅμα δὲ οὗτος ἀνεκεχωρήκει καὶ ὁ Βίβουλος ἄρξων τῆς Συρίας ἀφίκετο, καίπερ ἐψηφισμένου μηδένα μήτε στρατηγὸν μήθ’ ὕπατον μήτε εὐθὺς μήτε πρὸ πέμπτου ἔτους ἐς τὰς ἔξω ἡγεμονίας ἐξιέναι, ἵνα μὴ διὰ τοῦτο σπουδαρχοῦντες στασιάζωσι. καὶ αὐτὸς μὲν ἐν ἡσυχίᾳ τὸ ὑπήκοον διήγαγε, τοὺς δὲ δὴ Πάρθους ἐπ’ ἀλλήλους ἔτρεψε· Ὀρνοδαπάτην γάρ τινα σατράπην ἀχθόμενον τῷ Ὀρώδῃ προσποιησάμενος, ἀνέπεισε δι’ ἀγγέλων τόν τε Πάκορον βασιλέα στήσασθαι καὶ ἐπ’ ἐκεῖνον μετ’ αὐτοῦ στρατεῦσαι. ὁ μὲν οὖν πόλεμος οὗτος, ὅ τε τῶν Ῥωμαίων καὶ ὁ τῶν Πάρθων, τετάρτῳ ἔτει ἀφ’ οὗ ἤρξατο, ἐπί τε Μάρκου Μαρκέλλου καὶ ἐπὶ Σουλπικίου", "st": "40.30"}, {"sp": "N", "t": "Ῥούφου ὑπάτων, ἐπαύσατο· ἐν δὲ τῷ αὐτῷ ἐκείνῳ χρόνῳ καὶ ὁ Καῖσαρ τὰ ἐν τῇ Γαλατίᾳ ταραχθέντα αὖθις μάχαις κατέλαβε, πολλὰ πάνυ τὰ μὲν αὐτὸς τὰ δὲ καὶ διὰ τῶν ὑποστρατήγων πράξας, ὧν ἐγὼ τὰ ἀξιολογώτατα διηγήσομαι μόνα. ὁ γὰρ Ἀμβιόριξ τοὺς Τρηουήρους χαλεπῶς ἔτι καὶ τότε τῷ τοῦ Ἰνδουτιομάρου θανάτῳ ἔχοντας παραλαβὼν τά τε αὐτόθεν ἐπὶ πλεῖον συνέστησε, καὶ παρὰ τῶν Κελτῶν μισθοφορικὸν μετεπέμψατο. βουληθεὶς οὖν ὁ Λαβιῆνος, πρὶν ἐκείνους ἐπελθεῖν, συμμῖξαί σφισι, προενέβαλεν ἐς τὴν τῶν Τρηουήρων χώραν. καὶ ἐπειδὴ μὴ ἠμύνοντο τὴν ἐπικουρίαν ἀναμένοντες, ἀλλὰ ποταμόν τινα διὰ μέσου ποιησάμενοι ἡσύχαζον, συνεκάλεσε τοὺς στρατιώτας, καὶ ἐδημηγόρησε τοιάδε ἀφ’ ὧν τούς τε σφετέρους καταπλήξειν καὶ ἐκείνους … ἔμελλε, χρῆναί τέ σφας ἔλεγε, πρὶν τοὺς Κελτοὺς αὐτοῖς ἐπαμῦναι, πρός τε τὸν Καίσαρα καὶ ἐς τὸ ἀσφαλὲς ἀποχωρῆσαι, ἐσήμηνέ τε εὐθὺς συσκευάσασθαι. καὶ ἐξανέστη οὐ πολλῷ ὕστερον, προσδοκήσας ἔσεσθαι τοῦτο ὃ καὶ ἐγένετο. οἱ γὰρ βάρβαροι ἀκούσαντες ταῦτα (ἦν γὰρ αὐτοῖς ἐπιμελές, καὶ δι’ αὐτό γε τοῦτο καὶ φανερῶς ἐλέχθη) δεδιέναι τε αὐτὸν ὄντως καὶ φυγὴν ὡς ἀληθῶς ποιεῖσθαι ἐπίστευσαν, καὶ τὸν ποταμὸν σπουδῇ διαβάντες θυμῷ ἐπ’ αὐτοὺς ἐχώρουν, ὡς τάχους ἕκαστος εἶχε. καὶ οὕτως ὁ Λαβιῆνος ὑπέστη τέ σφας ἐσκεδασμένους, καὶ τοὺς πρώτους ἐκπλήξας ῥᾳδίως καὶ τοὺς λοιποὺς δι’ αὐτῶν ἐκείνων ἐτρέψατο. κἀκ τούτου φευγόντων τέ σφων τεταραγμένως καὶ ἀλλήλοις ἐμπιπτόντων καὶ πρὸς τὸν ποταμὸν ὠθουμένων πολλοὺς ἀπέκτεινε.", "st": "40.31"}, {"sp": "N", "t": "διαφυγόντων τε καὶ ὣς συχνῶν, ὁ Καῖσαρ τῶν μὲν ἄλλων οὐδένα λόγον ἐποιεῖτο, τὸν δὲ Ἀμβιόριγα διαδιδράσκοντα ἄλλοτε ἄλλῃ καὶ πολλὰ κακουργοῦντα καὶ ζητῶν καὶ διώκων πράγματα ἔσχε. καὶ ἐκεῖνον μὲν οὐδένα τρόπον λαβεῖν ἠδυνήθη, ἐπὶ δὲ δὴ τοὺς Κελτοὺς ὡς καὶ τοῖς Τρηουήροις βοηθῆσαι ἐθελήσαντας ἐστράτευσε. καὶ ἔπραξε μὲν οὐδὲ τότε οὐδέν, ἀλλὰ καὶ διὰ ταχέων φόβῳ τῶν Σουήβων ἐπανεχώρησεν, ἔδοξε δ’ οὖν αὖθις τὸν Ῥῆνον διαβεβηκέναι, καὶ τῆς τε γεφύρας μόνα τὰ προσεχῆ τοῖς βαρβάροις ἔλυσε, καὶ φρούριον ἐπ’ αὐτῆς ὡς καὶ ἀεὶ διαβησείων ᾠκοδόμησε. καὶ μετὰ τοῦτο ὀργῇ τὴν τοῦ Ἀμβιόριγος διάφευξιν φέρων, τὴν πατρίδα αὐτοῦ καίτοι μηδὲν νεωτερίσασαν διαρπάσαι τοῖς βουλομένοις ἐπέτρεψε, προεπαγγείλας σφίσιν αὐτὸ τοῦθ’, ὅπως ὅτι πλεῖστοι συνέλθωσιν· ὅθενπερ πολλοὶ μὲν Γαλάται πολλοὶ δὲ καὶ Σύγαμβροι πρὸς τὰς ἁρπαγὰς ἦλθον. οὐ μέντοι καὶ ἀπέχρησε τοῖς Συγάμβροις τὰ ἐκείνων λῄσασθαι, ἀλλὰ καὶ αὐτοῖς τοῖς Ῥωμαίοις ἐπέθεντο· τηρήσαντες γάρ σφας πρὸς σίτου κομιδὴν ἀπιόντας ἐπεχείρησαν τῷ στρατοπέδῳ αὐτῶν, κἀν τούτῳ προσβοηθησάντων σφῶν, ἐπείπερ ᾔσθοντο, συχνοὺς ἐφόνευσαν. καὶ οἱ μὲν φοβηθέντες διὰ τοῦτο τὸν Καίσαρα οἴκαδε σπουδῇ ἀνεχώρησαν· ἐκεῖνος δὲ τούτων μὲν οὐδενός, διά τε τὸν χειμῶνα καὶ διὰ τὸ τὰ ἐν τῇ Ῥώμῃ στασιάζεσθαι, οὐδεμίαν τιμωρίαν ἐποιήσατο, τοὺς δὲ δὴ στρατιώτας πρὸς τὰ χειμάδια διαπέμψας αὐτός τε ἐς τὴν Ἰταλίαν, πρόφασιν μὲν τῆς ἐκεῖ Γαλατίας ἕνεκα, τὸ δ’ ἀληθὲς ὅπως ἐγγύθεν τοῖς ἐν τῇ πόλει δρωμένοις ἐφεδρεύῃ, ἀπῆλθεν.", "st": "40.32"}, {"sp": "N", "t": "κἀν τούτῳ οἱ Γαλάται αὖθις ἐνεόχμωσαν. Ἀρουερνοὶ γὰρ ἡγουμένου σφῶν Οὐερκιγγετόριγος ἀπέστησαν, καὶ τούς τε Ῥωμαίους, ὅσους ἔν τε ταῖς πόλεσιν ἔν τε τῇ χώρᾳ σφῶν εὗρον, πάντας ἀπέκτειναν, καὶ ἐπὶ τὴν συμμαχίδα αὐτῶν χωρήσαντες τοὺς μὲν συναποστῆναί σφισιν ἐθελήσαντας περιεῖπον, τοὺς δὲ λοιποὺς ἐκακούργουν. μαθὼν οὖν ταῦθ’ ὁ Καῖσαρ ἀνεκομίσθη, καὶ καταλαβὼν αὐτοὺς ἐς Βιτούριγας ἐσβεβληκότας ἐκείνοις μέν (οὐ γάρ πω πάντες οἱ στρατιῶται αὐτοῦ παρῆσαν) οὐκ ἐπήμυνεν, ἐς δὲ δὴ τὴν Ἀρουερνίδα ἀντεμβαλὼν ἐπανήγαγεν οἴκαδε τοὺς πολεμίους καὶ (οὐ γὰρ ἐδόκει πω ἀξιόμαχος αὐτοῖς εἶναι)", "st": "40.33"}, {"sp": "N", "t": "προαπεχώρησεν. αὖθις οὖν ἐκεῖνοι πρός τε τοὺς Βιτούριγας ἐπανῆλθον, καὶ πόλιν αὐτῶν Ἀουαρικὸν ἑλόντες ἐπὶ πλεῖστον ἐν αὐτῇ ἀντέσχον. ὕστερον δὲ ὑπὸ τῶν Ῥωμαίων πολιορκούμενοι — τό τε γὰρ τεῖχος δυσπρόσιτον ἦν, τῇ μὲν ἑλῶν δυσδιαβάτων τῇ δὲ ποταμοῦ ῥοώδους αὐτὸ περιέχοντος, καὶ αὐτοὶ παμπληθεῖς ὄντες τάς τε προσβολάς σφων ῥᾳδίως ἀπεκρούοντο, καὶ ἐπεξιόντες πολλὰ αὐτοὺς ἐλύπουν. καὶ τέλος τά τε πέριξ πάντα, οὐχ ὅπως ἀγροὺς ἢ κώμας, ἀλλὰ καὶ πόλεις ἀφ’ ὧν ὠφελίαν τινὰ ἔσεσθαί σφισι προσεδόκων, κατέφλεξαν, εἴ τέ τι παρὰ τῶν πόρρωθεν συμμάχων ἐκομίζετο αὐτοῖς, ἥρπαζον, ὥστε πολιορκεῖν τὴν πόλιν τοὺς Ῥωμαίους δοκοῦντας τὰ τῶν πολιορκουμένων πάσχειν, πρὶν δὴ ὑετός τε λάβρος καὶ πνεῦμα μέγα προσβάλλουσί πῃ αὐτοῖς ἐπιγενόμενον (ὁ γὰρ χειμὼν ἐνειστήκει) πρώτους μὲν ἐκείνους ἀπήλασε καὶ ἐς τὰς σκηνὰς ἐπανήγαγεν, ἔπειτα δὲ καὶ τοὺς βαρβάρους ἐς τὰς οἰκίας κατέκλεισεν. ἀπελθόντων γὰρ αὐτῶν ἀπὸ τῶν ἐπάλξεων οἱ Ῥωμαῖοι προσέβαλον ἐξαίφνης αὖθις αὐταῖς ἐρήμοις ἀνδρῶν οὔσαις· καὶ πύργον τινὰ παραχρῆμα, πρὶν καὶ αἰσθέσθαι τοὺς πολεμίους τῆς παρουσίας σφῶν, ἑλόντες ἔπειτα καὶ τὰ λοιπὰ οὐ χαλεπῶς ἐχειρώσαντο, καὶ τήν τε πόλιν πᾶσαν διήρπασαν, καὶ τοὺς ἀνθρώπους πάντας ὀργῇ τῆς τε προσεδρείας καὶ τῆς ταλαιπωρίας ἔσφαξαν.", "st": "40.34"}, {"sp": "N", "t": "πράξας δὲ ταῦτα ὁ Καῖσαρ ἐπὶ τὴν χώραν αὐτῶν ἐπεστράτευσε. καὶ ἐπειδὴ πολεμούμενοι τὰς γεφύρας οἱ λοιποὶ Ἀρουερνοὶ προεκεκρατήκεσαν δι’ ὧν διαβῆναι αὐτὸν ἐχρῆν, ἀπορήσας ὅπως περαιωθῇ, ἐπιπαρῆλθεν ἐπὶ πολὺ παρὰ τὴν ὄχθην, εἴ πως ἐπιτηδείου τινὸς χωρίου ὥστε πεζῇ δι’ αὐτοῦ τοῦ ὕδατος διελθεῖν λάβοιτο. κἀκ τούτου ἔν τε ὑλώδει τινὶ καὶ ἐν συσκίῳ τόπῳ γενόμενος τὰ μὲν σκευοφόρα καὶ τοῦ στρατοῦ τὸ πλεῖον προέπεμψε, μακρὰν ἐκτεταμένῃ τάξει κελεύσας αὐτοὺς προϊέναι, ὥστε καὶ πάντας σφᾶς ἐνταῦθα εἶναι δοκεῖν· αὐτὸς δὲ μετὰ τῶν ἐρρωμενεστάτων ὑπέμεινε, καὶ ξύλα τε ἔτεμε καὶ σχεδίας ἐποίησε καὶ ἐπ’ αὐτῶν διέβη τὸ ῥεῦμα, τῶν βαρβάρων πρός τε τοὺς ἐν τῷ πρόσθεν πορευομένους τὸν νοῦν ἐχόντων καὶ τὸν Καίσαρα μετ’ αὐτῶν εἶναι λογιζομένων. καὶ μετὰ τοῦτο τούς τε προεληλυθότας νυκτὸς ἀνεκαλέσατο, καὶ διαβιβάσας αὐτοὺς ὁμοίως τῆς μὲν χώρας ἐκράτησε, τῶν δ’ ἀνθρώπων ἐς Γεργοουίαν συγκαταφυγόντων καὶ ἐκεῖσε πάντα τὰ τιμιώτατά σφισι συγκομισάντων πλεῖστον", "st": "40.35"}, {"sp": "N", "t": "πόνον μάτην αὐτοῖς προσεδρεύων ἔσχε. τό τε γὰρ φρούριον ἐπί τε λόφου καρτεροῦ ἦν καὶ τείχεσιν ἰσχυρῶς ἐκεκράτυντο, καὶ οἱ βάρβαροι πέριξ αὐτὸ πάντα τὰ μετέωρα κατειληφότες περιεφρούρουν, ὥστε καὶ μένειν αὐτοῖς κατὰ χώραν ἀσφαλῶς ὑπάρχειν καὶ ἐπικαταθέουσι πλεονεκτεῖν τὰ πλείω. ἔν τε γὰρ πεδίῳ ὁ Καῖσαρ ηὐλίζετο (οὐ γὰρ εὐπόρησεν ἐχυροῦ χωρίου), καὶ αὐτὸς μὲν οὔτε προεγίγνωσκεν. … οἱ δὲ δὴ βάρβαροι, ὡς καὶ ὑπερδεξίων κρατοῦντες, τό τε στρατόπεδον αὐτοῦ κατεθεῶντο καὶ ταῖς καταδρομαῖς ἐπικαίροις ἐχρῶντο. εἴ τέ πῃ περαιτέρω τοῦ καιροῦ προχωρήσαντες ἀνεκόπτοντο, δι’ ὀλίγου αὖθις ἐντὸς τῆς ἐπικρατείας σφῶν ἐγίγνοντο· οἱ γὰρ Ῥωμαῖοι οὐδένα τρόπον, ἐφ’ ὅσον οἵ τε λίθοι καὶ τὰ ἀκόντια ἐξικνεῖτο, πελάσαι τοῖς χωρίοις ἐδύναντο. ὁ οὖν Καῖσαρ, ἐπειδὴ ὅ τε χρόνος ἄλλως ἀναλοῦτο, καὶ πολλάκις καὶ πρὸς αὐτὸ τὸ ὄρθιον, ἐφ’ οὗ τὸ πόλισμα ἦν, προσβαλὼν μέρους μέν τινος ἐκράτησεν αὐτοῦ ὥστε καὶ ἐντειχίσασθαί τι ῥᾴω τε ἐκεῖθεν τὴν ἐπὶ τἆλλα ἔφοδον ποιεῖσθαι, τὸ δ’ ὅλον ἀπεκρούετο, καὶ τῶν τε στρατιωτῶν συχνοὺς ἀπέβαλε καὶ ἐκείνους ἀλήπτους ἑώρα ὄντας, τά τε τῶν Αἰδούων ἐν τούτῳ ἐκινήθη, καὶ προσέτι καὶ πρὸς τούτους ἀπελθόντος αὐτοῦ κακῶς οἱ καταλειφθέντες ἀπήλλαξαν, ἀνέστη.", "st": "40.36"}, {"sp": "N", "t": "οἱ γὰρ Αἴδουοι κατ’ ἀρχὰς μὲν ταῖς τε ὁμολογίαις ἐνέμειναν καὶ ἐπικουρίας αὐτῷ ἔπεμπον, ἔπειτα δὲ καὶ ἄκοντες ἐπολέμησαν, ἀπατησάντων σφᾶς ἄλλων τε καὶ Λιταουίκου. ἐπειδὴ γὰρ οὐκ ἔπειθεν αὐτοὺς ἄλλως τοῦτο ποιῆσαι, διεπράξατο προσταχθῆναί οἱ πρὸς τὸν Καίσαρα ἀπαγαγεῖν τινας ἐπὶ συμμαχίᾳ δῆθεν αὐτοῦ, καὶ ὥρμησε μὲν ὡς καὶ τοῦτο ποιήσων, προπέμψας δὲ ἱππέας, καὶ κελεύσας τισὶν αὐτῶν ἐπανελθοῦσιν εἰπεῖν ὅτι οἵ τε συμπεμφθέντες σφίσι καὶ οἱ ἄλλοι οἱ παρὰ τοῖς Ῥωμαίοις σφῶν ὄντες συνειλημμένοι τε ὑπ’ αὐτῶν εἰσι καὶ ἀπολώλασι, προσπαρώξυνε τοὺς στρατιώτας δημηγορήσας ἀκόλουθα τοῖς ἀγγέλοις. καὶ οὕτως αὐτοί τε ἐπανέστησαν καὶ τοὺς ἄλλους συμμετέστησαν. καὶ τότε μέν (ὁ γὰρ Καῖσαρ ὡς τάχιστα τοῦτ’ ᾔσθετο, τούς τε Αἰδούους οὓς εἶχε καὶ ἐδόκει πεφονευκέναι ἔπεμψεν αὐτοῖς, ὥστε φανεροὺς πᾶσι ζῶντας γενέσθαι, καὶ τῷ ἱππικῷ", "st": "40.37"}, {"sp": "N", "t": "ἐφέσπετο) μετενόησαν καὶ συνηλλάγησαν· αὖθις δὲ τῶν Ῥωμαίων πρός τε τῇ Γεργοουίᾳ τῇ τοῦ Καίσαρος ἀπουσίᾳ πταισάντων, καὶ μετὰ τοῦτο παντάπασιν ἀπ’ αὐτῆς ἀποχωρησάντων, ἐφοβήθησαν οἱ τήν τε ἐπανάστασιν πράξαντες καὶ νεωτέρων ἀεὶ πραγμάτων ἐφιέμενοι μὴ σχολάζοντες … ποιήσωνται, καὶ ἐνεόχμωσαν. μαθόντες δὲ τοῦθ’ οἱ συστρατεύοντες αὐτῶν τῷ Καίσαρι ᾐτήσαντο ἐπιτραπῆναί σφισιν οἴκαδε ἀπελθεῖν, ὑποσχόμενοι πάντα καταστήσειν. καὶ οὕτως ἀφεθέντες πρός τε Νοουιοδουνόν, ἔνθα τά τε χρήματα καὶ τὸν σῖτον ὁμήρους τε πολλοὺς οἱ Ῥωμαῖοι κατετέθειντο, ἦλθον, καὶ τούς τε φρουροὺς αὐτῶν, συναιρομένων σφίσι τῶν ἐπιχωρίων, μὴ προσδεχομένους ἔφθειραν, καὶ ἐν κράτει πάντων αὐτῶν ἐγένοντο. καὶ ἐκείνην τε τὴν πόλιν ἐπίκαιρον οὖσαν κατέπρησαν, ὅπως μὴ οἱ Ῥωμαῖοι ὁρμητήριον αὐτὴν τοῦ πολέμου ποιήσωνται, καὶ τὰ λοιπὰ τῶν Αἰδούων προσαπέστησαν. ὁ οὖν Καῖσαρ ἐπεχείρησε μὲν παραχρῆμα ἐπ’ αὐτοὺς στρατεῦσαι, μὴ δυνηθεὶς δὲ διὰ τὸν ποταμὸν τὸν Λίγρον ἐπὶ Λίγγονας ἐτράπετο. καὶ ὁ μὲν οὐδ’ ἐκεῖ κατώρθωσεν, ὁ δὲ δὴ Λαβιῆνος τὴν νῆσον τὴν ἐν τῷ Σηκουανῷ ποταμῷ οὖσαν, τούς τε προκινδυνεύσαντας ἐν τῇ ἠπείρῳ κρατήσας καὶ τὴν διάβασιν πολλαχῇ ἅμα κατά τε τὸν ῥοῦν καὶ ἀνάπαλιν, ὅπως μὴ καθ’ ἓν περαιούμενος κωλυθῇ, ποιησάμενος, κατέσχε.", "st": "40.38"}, {"sp": "N", "t": "πρὶν δὲ τοῦτο γενέσθαι, καταφρονήσας ὁ Οὐερκιγγετόριξ τοῦ Καίσαρος ἐξ ὧν ἐπταίκει ἐπ’ Ἀλλόβριγας ἐστράτευσε. κἀν τούτῳ ὁρμήσαντα αὐτὸν ὡς καὶ βοηθήσοντά σφισιν, ἀπέλαβεν ἐν Σηκουανοῖς γενόμενον καὶ ἐνεκυκλώσατο, οὐ μέντοι κακόν τι εἰργάσατο, ἀλλὰ καὶ πᾶν τοὐναντίον τούς τε Ῥωμαίους ἠνάγκασεν ἀγαθοὺς εἶναι ἀπογνώσει τῆς σωτηρίας, καὶ αὐτὸς ὑπό τε τοῦ πλήθους καὶ ὑπὸ τοῦ θράσους ἔπταισε, καί τι καὶ ὑπὸ τῶν Κελτῶν τῶν τοῖς Ῥωμαίοις συμμαχούντων ἐσφάλη· ταῖς τε γὰρ ὁρμαῖς ἄπληστοι ὄντες καὶ τοῖς σώμασι τὴν τόλμαν προσεπισχυρίσαντες διέρρηξαν τὴν περίσχεσιν. εὑρὼν δὲ δὴ τὸ εὕρημα τοῦτο ὁ Καῖσαρ οὐκ ἀνῆκεν, ἀλλ’ ἐς Ἀλεσίαν τοὺς διαφυγόντας αὐτῶν κατακλείσας ἐπολιόρκει.", "st": "40.39"}, {"sp": "N", "t": "κἀν τούτῳ ὁ Οὐερκιγγετόριξ τὸ μὲν πρῶτον τοὺς ἱππέας, πρὶν παντελῶς ἀποτειχισθῆναι, ἐξέπεμψε, τῆς τε τροφῆς τῶν ἵππων ἕνεκα (οὐ γὰρ ἦν) καὶ ὅπως ἐς τὰς πατρίδας ἕκαστοί σφων κομισθέντες τά τε ἐπιτήδεια καὶ ἐπικουρίαν αὐτῷ ἀγάγωσιν. ἐπεὶ δ’ οὗτοί τε ἐχρόνιζον καὶ τὰ σιτία σφᾶς ἐπιλείπειν ἤρξατο, τούς τε παῖδας καὶ τὰς γυναῖκας καὶ τῶν ἄλλων τοὺς ἀχρειοτάτους ἐξέβαλεν, ἐλπίσας μάτην ὅτι ἢ καὶ ἐκεῖνοι πρὸς τῶν Ῥωμαίων τῆς λείας ἕνεκα σωθήσονται, ἢ οἵ γε λοιποὶ ταῖς τροφαῖς αὐτῶν ἐπὶ πλεῖον χρησάμενοι περιγενήσονται. ὁ γὰρ Καῖσαρ ἄλλως μὲν οὐδ’ αὐτὸς τῶν ἐπιτηδείων, ὥστε καὶ ἑτέρους τρέφειν, εὐπόρει· τοῖς δ’ οὖν πολεμίοις ἰσχυροτέραν τὴν σιτοδείαν ἐπανελθόντων αὐτῶν, ἐλπίδι τοῦ πάντως σφᾶς καταδεχθήσεσθαι, ποιήσειν νομίσας πάντας αὐτοὺς ἀπεώσατο. καὶ οἱ μὲν οὕτως ἐν τῷ μέσῳ τῆς πόλεως καὶ τοῦ στρατοπέδου, μηδετέρων σφᾶς δεχομένων, οἰκτρότατα ἀπώλοντο· ἡ δὲ ἐπικουρία τῶν τε ἱππέων καὶ τῶν ἄλλων τῶν ὑπ’ αὐτῶν ἀχθέντων ἐπῆλθε μὲν οὐκ ἐς μακρὰν τοῖς βαρβάροις, ἱππομαχίᾳ δὲ δὴ τῶν Ῥωμαίων τῇ βοηθείᾳ. … καὶ μετὰ τοῦτο πειράσαντες νυκτὸς διὰ τῶν περιτειχισμάτων ἐς τὴν πόλιν ἐσελθεῖν ἰσχυρῶς ἐπόνησαν· τάφρους τε γὰρ οἱ Ῥωμαῖοι κρυπτὰς ἐν τοῖς ἱππασίμοις ἐπεποιήκεσαν καὶ σκόλοπας ἐς αὐτὰς ἐνεπεπήχεσαν, πάντα ἐπιπολῆς τῷ ἄλλῳ τῷ πέριξ χωρίῳ ὁμοιώσαντες, ὥστε καὶ τοὺς ἄνδρας καὶ τοὺς ἵππους ὅτι μάλιστα ἀπερισκέπτως ἐς αὐτὰ ἐμπεσόντας σφαλῆναι. οὐ μέντοι καὶ ἐνέδοσαν πρὶν ἐκ παρατάξεως αὖθις πρὸς αὐτοῖς τοῖς τειχίσμασιν αὐτοί τε ἅμα καὶ οἱ ἐκ τῆς πόλεως ἐπεξελθόντες πταῖσαι.", "st": "40.40"}, {"sp": "N", "t": "ὁ δ’ οὖν Οὐερκιγγετόριξ ἠδυνήθη μὲν ἐκφυγεῖν (οὔτε γὰρ ἑάλω καὶ ἄτρωτος ἦν), ἐλπίσας δ’, ὅτι ἐν φιλίᾳ ποτὲ τῷ Καίσαρι ἐγεγόνει, συγγνώμης παρ’ αὐτοῦ τεύξεσθαι, ἦλθε πρὸς αὐτὸν μὴ ἐπικηρυκευσάμενος, καὶ καθημένῳ οἱ ἐπὶ βήματος ἐξαίφνης ὤφθη, ὥστε καὶ ταραχθῆναί τινας· ἄλλως τε γὰρ περιμήκης ἦν καὶ ἐν τοῖς ὅπλοις δεινῶς ἐνέπρεπεν· ἡσυχίας δ’ οὖν γενομένης εἶπε μὲν οὐδέν, πεσὼν δὲ ἐς γόνυ τώ τε χεῖρε πιέσας ἐδεῖτο. ταῦτα τοῖς μὲν ἄλλοις οἶκτον τῇ τε τῆς προτέρας αὐτοῦ τύχης ἀναμνήσει καὶ τῷ τῆς παρούσης ὄψεως περιπαθεῖ ἐνέβαλεν· ὁ δὲ δὴ Καῖσαρ αὐτό τε αὐτῷ τοῦτο, δι’ ὃ μάλιστα σωθήσεσθαι προσεδόκησεν, ἐπεκάλεσε (τῆς γὰρ φιλίας τὴν ἀντίταξιν ἀντιθεὶς χαλεπωτέραν τὴν ἀδικίαν αὐτοῦ ἀπέφηνε), καὶ διὰ τοῦτο οὔτε ἐν τῷ παραχρῆμα αὐτὸν ἠλέησεν ἀλλ’ εὐθὺς ἐν δεσμοῖς ἔδησε, καὶ ἐς τὰ ἐπινίκια μετὰ τοῦτο πέμψας ἀπέκτεινε.", "st": "40.41"}, {"sp": "N", "t": "τοῦτο μὲν οὖν ὕστερον ἐγένετο, τότε δὲ τοὺς μὲν ὁμολογίᾳ τῶν λοιπῶν προσέθετο, τοὺς δὲ καὶ μάχῃ κρατήσας ἐδουλώσατο. οἵ τε γὰρ Βελγικοὶ οἱ πλησιόχωροι, Κόμμιόν τινα Ἀτρέβαν προστησάμενοί σφων, ἐπὶ πλεῖστον ἀντέσχον, καὶ δύο τε ἱππομαχίαις ἀγχώμαλά πῃ ἠγωνίσαντο, καὶ τρίτῃ πεζομαχίᾳ ἰσοπαλεῖ τὸ πρῶτον συνενεχθέντες ἔπειτα ὑπὸ τοῦ ἱππικοῦ κατὰ νώτου σφίσιν ἀνελπίστως προσπεσόντος ἐτράπησαν. κἀκ τούτου τό τε στρατόπεδον τῆς νυκτὸς οἱ περιλιπεῖς ἐξέλιπον, καὶ διελθόντες ὕλην τινὰ ἐκείνην τε ἐνέπρησαν καὶ τὰς ἁμάξας μόνας ὑπελίποντο, ὅπως τῶν πολεμίων διά τε ταύτας καὶ διὰ τὸ πῦρ χρονισάντων φθάσωσιν ἐς τὸ ἀσφαλὲς ἀποχωρήσαντες. οὐ μέντοι καὶ ἐπιτυχεῖς τῆς ἐλπίδος ἐγένοντο· οἱ γὰρ Ῥωμαῖοι ὡς τάχιστα τῆς φυγῆς αὐτῶν ᾔσθοντο, ἐπεδίωξάν σφας, καὶ ἐντυχόντες τῷ πυρὶ τὰ μὲν κατέσβεσαν τὰ δὲ καὶ διέκοψαν, καὶ τινες καὶ διὰ μέσης τῆς φλογὸς δραμόντες κατέλαβον αὐτοὺς ἀπροσδόκητοι καὶ παμπληθεῖς", "st": "40.42"}, {"sp": "N", "t": "ἐφόνευσαν. ἐκ δὲ τούτου τῶν μὲν ἄλλων τινὲς ὡμολόγησαν, ὁ δὲ Ἀτρέβας διαφυγὼν οὐδ’ ὣς ἡσύχασεν, ἀλλὰ καὶ τὸν Λαβιῆνον ἐπεχείρησεν ἐνεδρεῦσαί ποτε. ἡττηθεὶς δὲ τῇ μάχῃ ἀνεπείσθη μὲν ἐς λόγους αὐτῷ ἐλθεῖν, πρὶν δὲ ἢ ὁτιοῦν συμβῆναι τρωθεὶς ὑπό τινος τῶν Ῥωμαίων ἀπιστίᾳ τοῦ μὴ ἂν ἀκριβῶς εἰρηνῆσαι διέφυγε, καὶ χαλεπὸς αὖθις αὐτοῖς ἐγένετο, μέχρις οὗ ἀπογνοὺς τὰ πράγματα τοῖς μὲν ἄλλοις τοῖς συνοῦσίν οἱ ἀκέραιον τὴν ἄδειαν ἐπὶ πᾶσι τοῖς σφετέροις ἔπραξεν, αὐτὸς δὲ ἑαυτῷ τὸ μηδέποτε, ὥς γέ τινές φασιν, ἐς ὄψιν μηδενὸς Ῥωμαίου ἐλθεῖν. ἐκεῖνοί τε οὖν οὕτω κατελύσαντο, καὶ οἱ λοιποὶ μετὰ τοῦτο, οἱ μὲν ἑκούσιοι οἱ δὲ καὶ καταπολεμηθέντες, ἐχειρώθησαν, καὶ αὐτοὺς ὁ Καῖσαρ καὶ φρουραῖς καὶ δικαιώσεσι χρημάτων τε ἐσπράξεσι καὶ φόρων ἐπιτάξεσι τοὺς μὲν ἐταπείνωσε τοὺς δὲ ἡμέρωσε.", "st": "40.43"}, {"sp": "N", "t": "ταῦτα μὲν οὕτως ἐπί τε Λουκίου Παύλου καὶ ἐπὶ Γαΐου Μαρκέλλου ὑπάτων ἐτελευτήθη, ὁ δὲ δὴ Καῖσαρ τῶν μὲν Γαλατῶν ἕνεκα καὶ τοῦ χρόνου τοῦ πρὸς τὴν ἡγεμονίαν αὐτοῦ δοθέντος ἔκ τε τῆς Γαλατίας ἀπαλλαγῆναι καὶ ἐς τὴν Ῥώμην ἐπανακομισθῆναι ὤφειλεν· ἐκεῖνός τε γὰρ ἐπ’ ἐξόδῳ ἦν καὶ ὁ πόλεμος ἐπέπαυτο, καὶ οὐδεμίαν ἔτ’ εὐπρεπῆ σκῆψιν πρὸς τὸ μὴ οὐ τά τε στρατόπεδα ἀφεῖναι καὶ ἰδιωτεῦσαι εἶχεν· ἐπεὶ δὲ τά τε ἐν τῷ ἄστει ἐστασιάζετο, καὶ ὁ Κράσσος ἐτεθνήκει, ὅ τε Πομπήιος ἔν τε δυνάμει αὖθις, ἅτε τρίτον ὑπατευκὼς καὶ τὴν ἐν τῇ Ἰβηρίᾳ ἀρχὴν ἐπὶ πέντε ἄλλα ἔτη δοθῆναί οἱ διαπεπραγμένος, ἐγένετο, καὶ αὐτῷ οὐκέτ’ οἰκείως, ἄλλως τε καὶ τοῦ παιδίου, ὅπερ που καὶ μόνον ἐν τῇ φιλίᾳ αὐτοὺς κατεῖχε, τετελευτηκότος, διέκειτο, ἐφοβήθη μὴ τῶν στρατιωτῶν ψιλωθεὶς ἐπί τε ἐκείνῳ καὶ ἐπὶ τοῖς ἄλλοις ἐχθροῖς γένηται, καὶ οὐ διῆκεν αὐτούς.", "st": "40.44"}, {"sp": "N", "t": "ἐν γὰρ δὴ τοῖς αὐτοῖς τούτοις ἔτεσιν ἄλλα τε ἐν τῇ πόλει στασιώδη πολλὰ κἀν ταῖς ἀρχαιρεσίαις μάλιστα ἐγένετο, ὥστε μόλις ἑβδόμῳ μηνὶ τόν τε Καλουῖνον καὶ τὸν Μεσσάλαν ὑπάτους ἀποδειχθῆναι· καὶ οὐδ’ ἂν τότε ᾑρέθησαν, εἰ μὴ Κύιντός τε Πομπήιος ὁ Ῥοῦφος ἐς τὸ δεσμωτήριον ὑπὸ τῆς βουλῆς, καίτοι τοῦ τε Σύλλου θυγατριδοῦς ὢν καὶ δημαρχῶν, ἐνεβλήθη, καὶ τοῦτο καὶ τοῖς ἄλλοις τοῖς κακουργῆσαί τι ἐθελήσασιν ἐψηφίσθη, τῷ τε Πομπηίῳ ἡ πρὸς αὐτοὺς βοήθεια ἐνεχειρίσθη. ἔστι μὲν γὰρ ὅτε καὶ οἱ ὄρνιθες τὰς ἀρχαιρεσίας ἐπέσχον, οὐ βουλόμενοι τοῖς μεσοβασιλεῦσι γενέσθαι· μάλιστα δὲ οἱ δήμαρχοι, τὰ πράγματα τὰ ἐν τῇ πόλει διέποντες ὥστε καὶ τὰς πανηγύρεις καὶ ἀντὶ τῶν στρατηγῶν ποιεῖν, ἐκώλυον τὰς λοιπὰς ἀρχὰς αἱρεθῆναι. καὶ διὰ τοῦτο καὶ ὁ Ῥοῦφος ἐς τὸ οἴκημα ἐσέπεσε. καὶ οὗτος μὲν τὸν Φαουώνιον ἀγορανομοῦντα ἐς αὐτὸ ὕστερον ἀπό τινος οὐ μεγάλης αἰτίας, ἵνα δὴ κοινωνὸν τῆς ἀτιμίας λάβῃ, κατέθετο· πάντες δὲ οἱ δήμαρχοι ἄλλας τε σκήψεις ἐμποδίους ἐσέφερον, καὶ χιλιάρχους ἀντὶ τῶν ὑπάτων, ὅπως πλείους ἄρχοντες ὥσπερ ποτὲ ἀποδεικνύωνται, καθίστασθαι ἐσηγοῦντο. ἐπειδή τ’ οὐδεὶς αὐτῶν ἐπείσθη, δικτάτορα γοῦν τὸν Πομπήιον λεχθῆναι δεῖν ἔφασκον. καὶ ἐπὶ πλεῖστον ἐπὶ τῇ προφάσει ταύτῃ διέτριψαν· ἐκεῖνός τε γὰρ ἀπεδήμει, καὶ ἐκ τῶν παρόντων οὔτε ψηφίσασθαί τις αὐτό (πρὸς γὰρ τὴν τοῦ Σύλλου ὠμότητα ἐμίσουν πάντες τὸ πολίτευμα) οὔτ’ αὖ μὴ ἑλέσθαι διὰ", "st": "40.45"}, {"sp": "N", "t": "τὸν τοῦ Πομπηίου φόβον ὑπέμεινε. τέλος δὲ ὀψέ ποτε αὐτὸς ἐλθὼν τὴν μὲν δικτατορίαν διδομένην οἱ δῆθεν οὐκ ἐδέξατο, τοὺς δὲ ὑπάτους ἀποδειχθῆναι παρεσκεύασεν. οὐ μέντοι οὐδὲ ἐκεῖνοι διαδόχους σφίσι διὰ τὸν ἐκ τῶν σφαγῶν τάραχον κατέστησαν, καίπερ καὶ τὴν βουλευτικὴν ἐσθῆτα καταθέμενοι κἀν τῇ ἱππάδι τὴν γερουσίαν ὥσπερ ἐπὶ μεγάλῳ τινὶ πένθει συνάγοντες. δόγμα τε ἐποιήσαντο μηδένα μήτε στρατηγήσαντα μήθ’ ὑπατεύσαντα τὰς ἔξω ἡγεμονίας, πρὶν ἂν πέντε ἔτη διέλθῃ, λαμβάνειν, εἴ πως ὑπὸ τοῦ μὴ παραυτίκα ἐν δυνάμει τινὶ αὐτοὺς γίγνεσθαι παύσαιντο σπουδαρχοῦντες. οὔτε γὰρ ἐμετρίαζον οὔθ’ ὑγιὲς οὐδὲν ἐποίουν, ἀλλ’ ἐπ’ ἀλλήλους παρώρμηντο πολλὰ μὲν δαπανώμενοι πολλῷ δ’ ἔτι πλείω μαχόμενοι, ὥστε καὶ τὸν ὕπατόν ποτε τὸν Καλουῖνον τρωθῆναι. οὔκουν οὔθ’ ὕπατος οὔτε στρατηγὸς οὔτε πολίαρχός τίς σφας διεδέξατο, ἀλλὰ ἄναρκτοι κατὰ τοῦτο παντελῶς οἱ Ῥωμαῖοι τὰ πρῶτα τοῦ ἔτους ἐγένοντο.", "st": "40.46"}, {"sp": "N", "t": "κἀκ τούτου οὔτε τι ἄλλο χρηστὸν συνέβη, καὶ ἡ ἀγορὰ ἡ διὰ τῶν ἐννέα ἀεὶ ἡμερῶν ἀγομένη ἐν αὐτῇ τῇ τοῦ Ἰανουαρίου νουμηνίᾳ ἤχθη. καὶ τοῦτό τε αὐτούς, ὡς οὐκ ἀπὸ ταὐτομάτου συμβὰν ἀλλ’ ἐν τέρατος λόγῳ γενόμενον, ἐθορύβει, καὶ ὅτι βύας ἐν τῇ πόλει καὶ ὤφθη καὶ συνελήφθη, ἄγαλμά τέ τι ἐπὶ τρεῖς ἡμέρας ἵδρωσε, καὶ λαμπὰς ἐκ τῶν νοτίων πρὸς ἀνατολὰς διέδραμε, καὶ πολλοὶ μὲν κεραυνοὶ πολλοὶ δὲ καὶ βῶλοι λίθοι τε καὶ ὄστρακα καὶ αἷμα διὰ τοῦ ἀέρος ἠνέχθη. δοκεῖ δὲ ἔμοιγε καὶ ἐκεῖνο τὸ τῷ προτέρῳ ἔτει, ἐπ’ ἐξόδῳ αὐτοῦ, περί τε τὸν Σάραπιν καὶ περὶ τὴν Ἶσιν ψηφισθὲν τέρας οὐδενὸς ἧττον γενέσθαι· τοὺς γὰρ ναοὺς αὐτῶν, οὓς ἰδίᾳ τινὲς ἐπεποίηντο, καθελεῖν τῇ βουλῇ ἔδοξεν. οὐ γὰρ δὴ τοὺς θεοὺς τούτους ἐπὶ πολὺ ἐνόμισαν, καὶ ὅτε γε καὶ ἐξενίκησεν ὥστε καὶ δημοσίᾳ αὐτοὺς σέβεσθαι, ἔξω τοῦ πωμηρίου σφᾶς ἱδρύσαντο.", "st": "40.47"}, {"sp": "N", "t": "τοιαύτης οὖν τότε τῆς ἐν τῷ ἄστει καταστάσεως οὔσης, καὶ μηδενὸς τοῖς πράγμασιν ἐπιτεταγμένου, σφαγαὶ καθ’ ἑκάστην ἡμέραν ὡς εἰπεῖν ἐγίγνοντο, τάς τε ἀρχαιρεσίας, καίτοι σπεύδοντες ἐπὶ τὰς ἀρχὰς καὶ δεκασμοῖς καὶ φόνοις δι’ αὐτὰς χρώμενοι, οὐκ ἐπετέλουν. ὁ γοῦν Μίλων ὑπατείαν αἰτῶν τὸν Κλώδιον ἐν τῇ Ἀππίᾳ ὁδῷ συντυχόντα οἱ τὸ μὲν πρῶτον ἁπλῶς πως ἔτρωσεν, ἔπειτα δὲ φοβηθεὶς μὴ ἐπεξέλθῃ τῷ γεγονότι κατέσφαξεν, ἐλπίσας, ἐπειδὴ πάντας τοὺς οἰκέτας τοὺς τοῦτο ποιήσαντας εὐθὺς ἠλευθέρωσε, ῥᾷον τοῦ φόνου τελευτήσαντος αὐτοῦ ἢ τοῦ τραύματος εἰ περιγίγνοιτο ἀφεθήσεσθαι. ἀκούσαντες οὖν τοῦθ’ οἱ ἐν τῇ πόλει πρὸς ἑσπέραν δεινῶς ἐταράχθησαν· ταῖς τε γὰρ στάσεσιν ἀφορμὴ πολέμου καὶ κακῶν ἐγίγνετο, καὶ οἱ διὰ μέσου, εἰ καὶ ἐμίσουν τὸν Κλώδιον, ὅμως διά τε τὸ ἀνθρώπινον καὶ ὅτι καὶ τοῦ Μίλωνος στερηθῆναι ἐπὶ τῇ προφάσει ταύτῃ", "st": "40.48"}, {"sp": "N", "t": "ἤθελον, ἠγανάκτουν. παραλαβόντες δὲ αὐτοὺς οὕτως ἔχοντας ὅ τε Ῥοῦφος καὶ Τίτος Μουνάτιος Πλάγκος προσπαρώξυναν· δημαρχοῦντες γὰρ ἔς τε τὴν ἀγορὰν τὸν νεκρὸν ὑπὸ τὴν ἕω ἐσεκόμισαν καὶ ἐπὶ τὸ βῆμα ἐπέθεσαν πᾶσί τε ἐπεδείκνυσαν, καὶ ἐπέλεγον οἷα εἰκὸς ἦν ὀδυρόμενοι, ὥστε τὸν ὅμιλον καὶ ἐξ ὧν ἑώρων καὶ ἐξ ὧν ἤκουον συνταραχθῆναι, καὶ μήτε τοῦ ὁσίου μήτε τοῦ θείου ἔτι φροντίσαι, ἀλλὰ πάντα μὲν τὰ περὶ τὰς ταφὰς νόμιμα συγχέαι, πᾶσαν δὲ ὀλίγου τὴν πόλιν καταπρῆσαι. τὸ γὰρ σῶμα τοῦ Κλωδίου ἀράμενοι ἔς τε τὸ βουλευτήριον ἐσήνεγκαν, καὶ εὐθέτησαν, καὶ μετὰ τοῦτο πυρὰν ἐκ τῶν βάθρων συννήσαντες ἔκαυσαν καὶ ἐκεῖνο καὶ τὸ συνέδριον. οὕτω τε οὐχ ὁρμῇ τινι, οἵα που τοὺς ὄχλους ἐξαπιναία καταλαμβάνει, ἀλλὰ ἐκ προαιρέσεως αὐτὸ ἔπραξαν ὥστε καὶ τὴν ἐνάτην τὸ περίδειπνον ἐν αὐτῇ τῇ ἀγορᾷ, τυφομένου ἔτι τοῦ βουλευτηρίου, ποιῆσαι, καὶ προσέτι καὶ τὴν οἰκίαν τὴν τοῦ Μίλωνος καταφλέξαι ἐπιχειρῆσαι. ἐκείνη μὲν οὖν πολλῶν αὐτῇ ἀμυνάντων οὐκ ἐκαύθη· ὁ δὲ δὴ Μίλων τέως μὲν περίφοβος ἐπὶ τῷ φόνῳ ὢν ἐκρύπτετο, οὐχ ὑπὸ ἰδιωτῶν μόνον ἀλλὰ καὶ ἱππέων βουλευτῶν τέ τινων φρουρούμενος· ἐπεὶ δὲ τοῦτό τε ἐγένετο καὶ τὴν ὀργὴν τῆς γερουσίας ἐς τὸ τῶν ἀντιστασιωτῶν μίασμα περιχωρήσειν ἤλπισεν (εὐθὺς γοῦν τῆς δείλης ἐς τὸ Παλάτιον δι’ αὐτὸ τοῦτο συλλεγέντες τόν τε μεσοβασιλέα προχειρισθῆναι, καὶ τῆς φυλακῆς τῆς πόλεως καὶ ἐκεῖνον καὶ τοὺς δημάρχους καὶ προσέτι καὶ τὸν Πομπήιον ἐπιμεληθῆναι ὥστε μηδὲν ἀπ’ αὐτῆς ἀποτριβῆναι, ἐψηφίσαντο), προῄει τε ἐς τὸ μέσον καὶ τῆς ἀρχῆς ὁμοίως ἢ καὶ μᾶλλον ἀντεποιεῖτο.", "st": "40.49"}, {"sp": "N", "t": "μάχαι τε οὖν ἐκ τούτου πολλαὶ καὶ σφαγαὶ αὖθις ἐγίγνοντο, ὥστε τὴν βουλὴν τά τε προειρημένα ἐπικυρῶσαι, καὶ τὸν Πομπήιον μεταπέμψασθαι, καταλόγους τε αὐτῷ καινοὺς ποιήσασθαι ἐπιτρέψαι, καὶ τὰ ἐσθήματα ἀλλάξασθαι. ἐλθόντος τε αὐτοῦ οὐ πολλῷ ὕστερον ἔξω τε τοῦ πωμηρίου πρὸς τῷ θεάτρῳ αὐτοῦ σὺν φρουρᾷ ἠθροίσθησαν καὶ τὰ τοῦ Κλωδίου ὀστᾶ ἀνελέσθαι ἔγνωσαν, τό τε βουλευτήριον τῷ Φαύστῳ τῷ τοῦ Σύλλου υἱεῖ ἀνοικοδομῆσαι προσέταξαν. ἦν μὲν γὰρ τὸ Ὁστίλιον, μετεσκεύαστο δὲ ὑπὸ τοῦ Σύλλου· διὸ τοῦτό τε περὶ αὐτοῦ ἔδοξε, καὶ ὅπως ἐξοικοδομηθὲν τὸ ἐκείνου ὄνομα ἀπολάβῃ. μετεώρου δὲ τῆς πόλεως οὔσης ἐπὶ τοῖς ἄρξουσί σφων, καὶ διαθροούντων τῶν μὲν ὡς δικτάτορα τὸν Πομπήιον, τῶν δὲ ὡς ὕπατον τὸν Καίσαρα αἱρεθῆναι δεῖ (οὕτω γάρ που ἐκ προαιρέσεως ἐπὶ τοῖς κατειργασμένοις αὐτὸν ἐτίμων ὥστε καὶ ἑξήκονθ’ ἡμέρας θῦσαι ἐπ’ αὐτοῖς ψηφίσασθαι), φοβηθέντες ἑκάτερον οἵ τε ἄλλοι βουλευταὶ καὶ Βίβουλος, ὅσπερ που τὴν γνώμην πρῶτος ἐρωτηθεὶς ποιήσεσθαι ἔμελλε, προκατέλαβον τὴν τοῦ πλήθους ὁρμήν, τῷ Πομπηίῳ τὴν ὑπατείαν, ὥστε μὴ δικτάτορα αὐτὸν λεχθῆναι, καὶ μόνῳ γε, ἵνα μὴ ὁ Καῖσαρ αὐτῷ συνάρξῃ, δόντες. ξένον μὲν δὴ τοῦτο καὶ ἐπὶ μηδενὸς ἄλλου γενόμενον ἔπραξαν, καίτοι ὀρθῶς αὐτὸ πεποιηκέναι ἔδοξαν· ἐπειδὴ γὰρ ἧττον τοῦ Καίσαρος τῷ ὁμίλῳ προσέκειτο, ἀπορρήξειν τε αὐτὸν ἀπ’ ἐκείνου παντάπασι καὶ σφετεριεῖσθαι ἤλπισαν. καὶ ἔσχεν οὕτως· τῷ τε γὰρ καινῷ καὶ τῷ παραδόξῳ τῆς τιμῆς ἐπαρθεὶς οὐκέτ’ οὐδὲν ἐς τὴν τῶν πολλῶν χάριν ἐβούλευσεν, ἀλλ’ ἀκριβῶς πάντα τὰ τῇ βουλῇ ἀρέσκοντα ἔπραξεν.", "st": "40.50"}, {"sp": "N", "t": "οὐ μέντοι καὶ μόνος ἄρξαι ἠθέλησεν· τὴν γὰρ εὔκλειαν ἐν τῷ δεδόχθαι τοῦτ’ ἔχων, τὸν φθόνον τὸν ἐπ’ αὐτῇ ἐξέκλινε. καὶ φοβηθεὶς μήποτε κενῆς τῆς χώρας οὔσης ὁ Καῖσαρ ἔκ τε τῆς τῶν δυνάμεων καὶ ἐκ τῆς τοῦ πλήθους σπουδῆς συνάρχων αὐτῷ δοθῇ, ἐκείνῳ μέν, ἵνα μὴ καὶ παντελῶς παρημελῆσθαι νομίσῃ κἀκ τούτου τινὰ ὀργὴν δικαίαν ποιήσηται, παρεσκεύασε διὰ τῶν δημάρχων ἐπιτραπῆναι καὶ ἀπόντι τὴν ἀρχήν, ὅταν ἐκ τῶν νόμων καθήκῃ, αἰτῆσαι, αὐτὸς δὲ Κύιντον Σκιπίωνα πενθερόν τέ οἱ ὄντα καὶ δεκασμοῦ αἰτίαν ἔχοντα προσείλετο. οὗτος γὰρ γόνῳ μὲν υἱὸς τοῦ Νασικοῦ ὤν, ἐκ δὲ δὴ κλήρου διαδοχῆς ἐς τὸ τοῦ Μετέλλου τοῦ Εὐσεβοῦς γένος ποιηθεὶς καὶ διὰ τοῦτο καὶ τὴν ἐπίκλησιν αὐτοῦ φέρων, τήν τε θυγατέρα τῷ Πομπηίῳ ἐξέδωκε, καὶ παρ’ αὐτοῦ τήν τε ὑπατείαν καὶ τὸ μὴ κατηγορηθῆναι ἀντέλαβε.", "st": "40.51"}, {"sp": "N", "t": "πάνυ γὰρ πολλοὶ ἐπὶ τῷ ἐγκλήματι τούτῳ εὐθύνθησαν, καὶ μάλισθ’ ὅτι τὰ δικαστήρια ἀκριβέστερον ἐκ τῶν τοῦ Πομπηίου νόμων συνήγετο. πάντας τε γὰρ τοὺς ἄνδρας ἐξ ὧν τοὺς δικάσοντας ἀποκληροῦσθαι ἔδει αὐτὸς ἐπελέγετο, καὶ τὸν τῶν συναγορευσόντων ἑκατέρῳ τῷ μέρει ἀριθμὸν ὥρισεν, ὥστε μὴ ὑπὸ τοῦ πλήθους αὐτῶν τοὺς δικαστὰς θορυβουμένους ἐκταράττεσθαι. χρόνον τε τῷ μὲν διώκοντι δύο ὥρας, τῷ δὲ φεύγοντι τρεῖς δίδοσθαι ἐκέλευσε. καὶ ὃ δὴ μάλιστα πλείστοις ἐλυμαίνετο, τό τινας ἐπαινέτας ὑπὸ τῶν κρινομένων δίδοσθαι (πάμπολλοι γὰρ ὑπὸ τῶν ἀξιοπίστων ἐπαινούμενοι ἐξηρπάζοντο), ἐπηνώρθωσε, νομοθετήσας μηδένα ἔτι τὸ παράπαν ἐπαινέτην τοῖς τοιούτοις γίγνεσθαι. καὶ ταῦτα μὲν ἄλλα τέ τινα κατὰ πάντων ὁμοίως τῶν δικαστηρίων ἐτάχθη, τοῖς δὲ δὴ περὶ τὰς ἀρχὰς δεκάζουσι καὶ τοὺς προεαλωκότας ἐπὶ τοιούτῳ τινὶ κατηγόρους ἐπέστησεν, ἆθλόν σφισιν οὐκ ἐλάχιστον προθείς· εἰ γάρ τις ἤτοι δύο τῶν ὁμοίων τῶν τε ἐλαττόνων ἢ καὶ ἕνα τῶν μειζόνων τῆς καθ’ ἑαυτὸν αἰτίας εἷλεν, ἄδειαν εὑρίσκετο.", "st": "40.52"}, {"sp": "N", "t": "ἄλλοι τε οὖν ἐκ τούτου πολλοὶ ἑάλωσαν καὶ Πλαύτιος Ὑψαῖος ἀνταιτήσας τῷ τε Μίλωνι καὶ τῷ Σκιπίωνι τὴν ὑπατείαν. τῶν γὰρ δὴ τριῶν δωροφορησάντων μόνος ἐκεῖνος κατεδικάσθη. ὅ τε γὰρ Σκιπίων ἐγράφη μὲν καὶ ὑπὸ δυοῖν γε, οὐκ ἐκρίθη δὲ διὰ τὸν Πομπήιον· καὶ ὁ Μίλων ἐπὶ μὲν τούτῳ οὐκ ἐσήχθη (τὸ γὰρ τοῦ φόνου ἔγκλημα μεῖζον εἶχεν), ὑπαχθεὶς δὲ ἐπ’ ἐκείνῳ ἑάλω, μηδὲν δυνηθεὶς βίαιον δρᾶσαι. ὁ γὰρ Πομπήιος τήν τε ἄλλην πόλιν διὰ φυλακῆς ἐποιήσατο, καὶ ἐς τὸ δικαστήριον σὺν ὁπλίταις ἐσῆλθε, θορυβησάντων τε ἐπὶ τούτῳ τινῶν προσέταξε τοῖς στρατιώταις ἐκδιῶξαι αὐτοὺς ἐκ τῆς ἀγορᾶς πλαγίοις καὶ πλατέσι τοῖς ξίφεσι παίοντας. ἐπειδή τε οὐχ ὑπεῖκον ἀλλὰ καὶ καθάπερ ἐν παιδιᾷ τινι πλαγιαζόμενοι ὕβριζον, καὶ ἐτρώθησάν τινες αὐτῶν καὶ ἀπέθανον.", "st": "40.53"}, {"sp": "N", "t": "τά τε οὖν δικαστήρια ἡσύχως ἐκ τούτων συνήγετο, καὶ ἐδικαιώθησαν ἐπί τε ἑτέροις τισὶ πολλοὶ καὶ ἐπὶ τῷ τοῦ Κλωδίου φόνῳ ἄλλοι τε καὶ ὁ Μίλων, καίτοι τὸν Κικέρωνα συναγωνιστὴν ἔχων. ὁ γὰρ ῥήτωρ ἐκεῖνος τόν τε Πομπήιον καὶ τοὺς στρατιώτας ἐν τῷ δικαστηρίῳ παρὰ τὸ καθεστηκὸς ἰδὼν ἐξεπλάγη καὶ κατέδεισεν, ὥστε τῶν μὲν παρεσκευασμένων μηδὲν εἰπεῖν, βραχὺ δέ τι καὶ τεθνηκὸς χαλεπῶς φθεγξάμενος ἀγαπητῶς μεταστῆναι. τοῦτον γὰρ τὸν λόγον τὸν νῦν φερόμενον ὡς καὶ ὑπὲρ τοῦ Μίλωνος τότε λεχθέντα χρόνῳ ποθ’ ὕστερον καὶ κατὰ σχολὴν ἀναθαρσήσας ἔγραψε· καὶ δὴ καὶ τοιόνδε τι περὶ αὐτοῦ παραδέδοται. ὁ Μίλων τῷ λόγῳ πεμφθέντι οἱ ὑπ’ αὐτοῦ ἐντυχών (ἐπεφυγάδευτο γὰρ) ἀντεπέστειλε λέγων ὅτι ἐν τύχῃ αὐτῷ ἐγένετο τὸ μὴ ταῦθ’ οὕτω καὶ ἐν τῷ δικαστηρίῳ λεχθῆναι· οὐ γὰρ ἂν τοιαύτας ἐν τῇ Μασσαλίᾳ (ἐν ᾗ κατὰ τὴν φυγὴν ἦν) τρίγλας ἐσθίειν, εἴπερ τι τοιοῦτον ἀπελελόγητο. τοῦτο δὲ ἔγραψεν οὐχ ὅτι τοῖς παροῦσιν ἠρέσκετο (πολλὰ γὰρ ἐπὶ τῇ καθόδῳ ἐπετόλμησεν) ἀλλ’ ἐς τὸν Κικέρωνα ἀποσκώπτων, ὅτι μηδὲν χρηστὸν ἐν τῷ τῆς ἀπολογίας καιρῷ εἰπὼν ἔπειτα ἀκάρπους λόγους καὶ ἐμελέτα καὶ ἔπεμπεν αὐτῷ, ὥσπερ τι ὠφελῆσαι τότε αὐτὸν δυναμένους.", "st": "40.54"}, {"sp": "N", "t": "ὅ τε οὖν Μίλων οὕτως ἑάλω, καὶ ὁ Ῥοῦφος ὅ τε Πλάγκος ἐπειδὴ πρῶτον ἐκ τῆς ἀρχῆς ἐξῆλθον, ἄλλοι τε σὺν αὐτοῖς συχνοὶ διὰ τὴν τοῦ βουλευτηρίου ἔμπρησιν, καίτοι τῷ Πλάγκῳ καὶ τοῦ Πομπηίου συσπουδάσαντος, ὥστε καὶ βιβλίον ἔπαινόν τε ἅμα αὐτοῦ καὶ ἱκετείαν ἔχον ἐς τὸ δικαστήριον ἔπεμψεν· ὁ γὰρ Κάτων ὁ Μᾶρκος (δικάζειν δὲ ἔμελλεν) οὐκ ἔφη τὸν ἐπαινέτην ἐπὶ τῇ τῶν ἑαυτοῦ νόμων καταλύσει προσίεσθαι. καὶ ὁ μὲν οὐκέτι τὴν ψῆφον ἔδωκεν· ὁ γὰρ Πλάγκος ὡς καὶ τὴν καθαιρήσουσαν αὐτὸν οἴσοντα ἐξέκρινεν (ἐξῆν γάρ, ἐκ τῶν Πομπηίων νόμων, πέντε ἑκατέρῳ τῶν διαδικούντων ἐκ τῶν δικάσειν σφίσι μελλόντων ἀπολέγειν)· οἱ μέντοι ἄλλοι δικασταὶ κατεψηφίσαντο αὐτοῦ. οὔτε γὰρ ἄλλως ὀρθῶς ἔχειν ἔδοξέ σφισι, τοῦ Ῥούφου κατεγνωκόσιν, ἐκεῖνον ἐπὶ τοῖς αὐτοῖς κρινόμενον ἀφεῖναι· καὶ ἐπειδὴ τὸν Πομπήιον συναιρόμενόν οἱ εἶδον, ἀντεσπούδασαν αὐτῷ, μὴ καὶ δοῦλοί τινες ἄντικρυς αὐτοῦ μᾶλλον ἢ δικασταὶ νομισθῶσιν εἶναι. καίπερ καὶ τότε ὁ Κικέρων οὐδὲν βέλτιον τοῦ Πλάγκου κατηγόρησεν ἢ ὑπὲρ τοῦ Μίλωνος ἀπελογήσατο· ἥ τε γὰρ τοῦ δικαστηρίου ὄψις ἡ αὐτὴ ἦν, καὶ ὁ Πομπήιος ἐν ἑκατέρῳ τἀναντία οἱ καὶ ἐβουλεύετο καὶ ἔπραττεν, ὅθεν οὐχ ἥκιστα αὗθις αὐτῷ προσέκρουσε.", "st": "40.55"}, {"sp": "N", "t": "ταῦτά τε οὖν ἅμα διῴκει, καὶ τὸν περὶ τῶν ἀρχαιρεσιῶν νόμον τὸν κελεύοντα τοὺς ἀρχήν τινα ἐπαγγέλλοντας ἐς τὴν ἐκκλησίαν πάντως ἀπαντᾶν, ὥστε μηδένα ἀπόντα αἱρεῖσθαι, παρημελημένον πως ἀνενεώσατο· τό τε δόγμα τὸ μικρὸν ἔμπροσθε γενόμενον, ὥστε τοὺς ἄρξαντας ἐν τῇ πόλει μὴ πρότερον ἐς τὰς ἔξω ἡγεμονίας, πρὶν πέντε ἔτη παρελθεῖν, κληροῦσθαι, ἐπεκύρωσεν. οὐδ’ ᾐσχύνθη τότε μὲν τοιαῦτα γράψας, ὕστερον δὲ οὐ πολλῷ αὐτός τε τὴν Ἰβηρίαν ἐς πέντε ἄλλα ἔτη λαβών, καὶ τῷ Καίσαρι καὶ ἀπόντι (οἱ γὰρ φίλοι αὐτοῦ δεινῶς ἠγανάκτουν) αἰτῆσαι τὴν ὑπατείαν, ὥσπερ ἐψήφιστο, δούς. προσέγραψε μὲν γὰρ τῷ νόμῳ τὸ μόνοις αὐτὸ ἐξεῖναι ποιεῖν οἷς ἂν ὀνομαστί τε καὶ ἄντικρυς ἐπιτραπῇ, διέφερε δ’ οὐδὲν τοῦτο τοῦ μηδ’ ἀρχὴν κεκωλῦσθαι· πάντως γὰρ οἵ τι δυνάμενοι καὶ ἐκεῖνο ψηφισθῆναί σφισι διαπράξασθαι ἔμελλον.", "st": "40.56"}, {"sp": "N", "t": "ὁ μὲν οὖν Πομπήιος τοιαῦτ’ ἐπολιτεύετο, ὁ δὲ δὴ Σκιπίων οὔτε ἐνομοθέτησέ τι, καὶ τὰ πρὸς τοῦ Κλωδίου περὶ τῶν τιμητῶν γραφέντα κατέλυσε. καὶ ἔδοξε μὲν τὴν ἐκείνων χάριν τοῦτο πεποιηκέναι, ἐπειδὴ τὴν ἐξουσίαν αὐτοῖς ἣν καὶ πρὶν εἶχον ἀπέδωκε, περιέστη δὲ ἐς τοὐναντίον. ὑπὸ γὰρ τοῦ πολλοὺς ἔν τε τῇ ἱππάδι καὶ ἐν τῷ βουλευτικῷ φλαύρους ἄνδρας εἶναι, τέως μὲν μηδένα μήτε κατηγορηθέντα μήθ’ ἁλόντα διαγράψαι σφίσιν ἐξῆν, οὐδεμίαν τῶν οὐκ ἀπαλειφομένων αἰτίαν εἶχον· ἀπολαβόντες δὲ τὴν ἀρχαίαν ἰσχύν, ὑφ’ ἧς αὐτοῖς καὶ καθ’ ἑαυτοὺς τὸν ἑκάστου βίον ἐξετάζουσι τοῦτο ποιεῖν ἐδέδοτο, οὔτε πολλοῖς προσκρούειν ὑπέμενον, οὔτ’ αὖ ἐν μέμψει τινὶ ὡς μὴ διαγράφοντες τοὺς οὐκ ἐπιτηδείους γίγνεσθαι ἤθελον, καὶ διὰ τοῦτο οὐδὲ ἐφίετο ἔτι τῆς ἀρχῆς τῶν ἐμφρόνων οὐδὲ εἷς.", "st": "40.57"}, {"sp": "N", "t": "περὶ μὲν δὴ τοὺς τιμητὰς ταῦτ’ ἐψηφίσθη, ὁ δὲ δὴ Κάτων ἄλλως μὲν οὐδεμιᾶς ἀρχῆς ἐδεῖτο, ἰδὼν δὲ τόν τε Καίσαρα καὶ τὸν Πομπήιον ὑπὲρ τὴν κατάστασιν τῆς πολιτείας αὐξανομένους, καὶ ὑποτοπήσας ἤτοι καὶ ἀμφοτέρους σφᾶς τὰ πράγματα ἕξειν, ἢ καὶ διενεχθέντας ἀλλήλοις στάσιν τε μεγίστην ποιήσειν καὶ τὸν κρατήσαντα αὐτῶν μοναρχήσειν, ἠθέλησε μέν σφας πρὶν ἀνταγωνιστὰς γενέσθαι καταλῦσαι, καὶ τὴν ὑπατείαν ἐπ’ αὐτοὺς ᾔτησεν, ἐπειδήπερ ἰδιωτεύων οὐδὲν ἰσχύσειν ἔμελλεν, ὑποπτευθεὶς δὲ ὑπὸ τῶν τὰ ἐκείνων πραττόντων τοιοῦτόν τι δράσειν οὐκ ἀπεδείχθη, ἀλλ’ ὅ τε Μάρκελλος ὁ Μᾶρκος καὶ ὁ Ῥοῦφος ὁ Σουλπίκιος, ὁ μὲν διὰ τὴν τῶν νόμων ἐμπειρίαν ὁ δὲ διὰ τὴν τῶν λόγων δύναμιν, ᾑρέθησαν, ἄλλως τε καὶ ὅτι αὐτοὶ μέν, εἰ καὶ μὴ χρήμασιν ἢ βιαίῳ τινὶ ἔργῳ, ἀλλὰ τῇ γε θεραπείᾳ καὶ τῇ παρακλήσει πολλῇ πρὸς πάντας ἐχρήσαντο, ὁ δὲ δὴ Κάτων οὐδένα αὐτῶν ἐθεράπευσε. καὶ ὁ μὲν οὐκέτ’ αὖθις τῆς ἀρχῆς ἀντεποιήσατο, λέγων ἀγαθοῦ ἀνδρὸς ἔργον εἶναι μήτ’ ἀποδιδράσκειν τὴν προστασίαν τῶν κοινῶν, ἄν γέ τινες χρῆσθαι αὐτῷ ἐθελήσωσι, μήθ’ ὑπὲρ", "st": "40.58"}, {"sp": "N", "t": "τὸ προσῆκον αὐτῆς ἐφίεσθαι· Μάρκελλος δὲ πάντ’ εὐθὺς ἐπὶ τῇ τοῦ Καίσαρος καταλύσει (τῆς γὰρ τοῦ Πομπηίου μερίδος ἦν) ἔπραττε, καὶ ἄλλα τε ἐπ’ αὐτῷ πολλά, καὶ ὥστε καὶ διάδοχόν οἱ ἤδη καὶ πρὸ τοῦ καθήκοντος χρόνου πεμφθῆναι, ἐσηγήσατο. καὶ αὐτῷ ὅ τε Σουλπίκιος καὶ τῶν δημάρχων τινὲς ἀντέπραξαν, οὗτοι μὲν τῇ πρὸς τὸν Καίσαρα χάριτι· ἐκεῖνος δ’ αὐτοῖς ἐκοινώσατο καὶ τοῖς πολλοῖς ὅτι οὐκ ἤρεσκε τό τινα μεταξὺ ἄρχοντα μηδὲν ἠδικηκότα παυθῆναι. μαθὼν οὖν ταῦθ’ ὁ Πομπήιος (ἀπῆρε μὲν γὰρ ἐκ τοῦ ἄστεως ὡς καὶ ἐς τὴν Ἰβηρίαν στρατεύσων, οὐ μὴν οὐδὲ τότε ἐκ τῆς Ἰταλίας ἐξεχώρησεν, ἀλλὰ τοῖς ὑποστρατήγοις πάντα τὰ ἐκεῖ προστάξας αὐτὸς τῇ πόλει ἐφήδρευε) τὸ μὲν δὴ τὸν Καίσαρα τῆς ἡγεμονίας παραλυθῆναι οὐδὲ ἑαυτῷ ἀρέσκειν ἐπλάττετο, ἔπραττε δ’ ὅπως, ὅταν τὸν δεδομένον οἱ χρόνον διάρξῃ (τοῦτο δὲ οὐκ ἐς μακρὰν ἀλλ’ εὐθὺς τῷ ὑστέρῳ ἔτει γενήσεσθαι ἔμελλε), τά τε ὅπλα κατάθηται καὶ ἰδιωτεύσων οἴκαδε ἐπανέλθῃ. καὶ διὰ τοῦτο Γάιόν τε Μάρκελλον τὸν τοῦ Μάρκου ἀνεψιὸν ἢ καὶ ἀδελφόν (λέγεται γὰρ ἑκάτερον) ὑπατεῦσαι, ἐπειδὴ τῷ Καίσαρι καίπερ ἐξ ἐπιγαμίας προσήκων ἐχθρὸς ἦν, καὶ τὸν Κουρίωνα τὸν Γάιον, δι’ ἔχθρας καὶ αὐτὸν ἐκ παλαιοῦ οἱ ὄντα, δημαρχῆσαι ἐποίησεν.", "st": "40.59"}, {"sp": "N", "t": "ὁ οὖν Καῖσαρ μήτ’ ἄλλως ὑπομένων ἔκ τε τηλικαύτης καὶ ἐκ χρονίου ἡγεμονίας ἰδιωτεῦσαι, καὶ φοβηθεὶς μὴ καὶ ἐπὶ τοῖς ἐχθροῖς γένηται, παρεσκευάζετο ὡς καὶ ἀκόντων αὐτῶν ἐν τῇ ἀρχῇ ἐμμενῶν, καὶ στρατιώτας προσκατελέγετο καὶ χρήματα ἤθροιζεν ὅπλα τε ἐποίει, καὶ καθ’ ἡδονὴν πᾶσιν ἡγεῖτο. κἀν τούτῳ καὶ τὰ οἴκοι τρόπον τινά, τοῦ μὴ πάντα βίᾳ ἀλλὰ καὶ πειθοῖ πράττειν δοκεῖν, προδιοικήσασθαι ἐθελήσας ἔγνω συναλλαγῆναι τῷ Κουρίωνι· τοῦ τε γὰρ τῶν Κουριώνων γένους ἦν, καὶ τὴν γνώμην ὀξύς, εἰπεῖν τε δεινός, τῷ τε πλήθει πιθανώτατος, καὶ χρήματων ἐς πάντα ἁπλῶς ἐξ ὧν ἢ αὐτός τι πλεονεκτήσειν ἢ καὶ ἑτέρῳ διαπράξειν ἤλπιζεν ἀφειδέστατος. καὶ αὐτὸν πολλὰ μὲν ἐπελπίσας, πάντων δὲ τῶν ὀφειλημάτων, συχνῶν διὰ τὸ πολλὰ δαπανᾶσθαι ὄντων, ἀπαλλάξας ἀνηρτήσατο. πρὸς γὰρ τὴν παροῦσαν ὧν ἔπραττε σπουδὴν οὔτε ἀργυρίου, ἅτε καὶ ἐξ αὐτῶν ἐκείνων ἀργυρολογῶν, ἐφείδετο, καὶ προσυπισχνεῖτό τισι παμπληθῆ ὧν οὐδὲ πολλοστὸν μέρος δώσειν ἔμελλε. καὶ οὐ μόνον γε τοὺς ἐλευθέρους ἀλλὰ καὶ τοὺς δούλους τούς τι καὶ ὁπωσοῦν παρὰ τοῖς δεσπόταις σφῶν δυναμένους ἐθεράπευσε· καὶ συχνοὶ αὐτῷ καὶ ἐκ τούτου καὶ τῶν ἱππέων καὶ τῶν βουλευτῶν ὑπῆρξαν.", "st": "40.60"}, {"sp": "N", "t": "ὁ δ’ οὖν Κουρίων ἐφρόνησε μὲν τὰ τοῦ Καίσαρος, οὐ μέντοι καὶ παραχρῆμα φανερῶς αὐτὰ πράττειν ἤρξατο· πρόφασίν τε γὰρ εὐπρεπῆ τοῦ μὴ καὶ ἑκὼν ἀλλὰ ἀναγκασθεὶς δὴ μεθεστηκέναι δόξαι ἐζήτει, καὶ ἐνόμισεν, ὅσῳ ἂν ἐπὶ πλεῖον τοῖς ἐχθροῖς αὐτοῦ ὡς καὶ φίλος σφῶν συγγένηται, καὶ πλείω καὶ μείζω τῶν ἀπορρήτων αὐτῶν μαθήσεσθαι. δι’ οὖν ταῦτα ἐπὶ μακρότατόν τε ἐπεκρύψατο, καὶ ὅπως μηδένα τρόπον ὑποπτευθῇ μεταβεβλῆσθαί τε καὶ οὐκ ἀνὰ πρώτους καὶ πάντα τὰ ἐναντία τῷ Καίσαρι καὶ τότε ἔτι καὶ φρονεῖν καὶ λέγειν, καὶ ἐδημηγόρει κατ’ αὐτοῦ ἀφ’ οὗ γε καὶ δημαρχεῖν ἤρξατο, καὶ ἐσηγεῖτο πολλὰ καὶ ἄτοπα. καί τινα καὶ ἐπὶ τῇ βουλῇ τοῖς τε δυνατωτάτοις σφῶν, οἵπερ που καὶ τὰ τοῦ Πομπηίου μάλιστ’ ἔπραττον, ἔγραφεν, οὐχ ὅτι καὶ ἤθελεν ἢ καὶ ἤλπιζέ τι αὐτῶν γενήσεσθαι, ἀλλ’ ἵνα μὴ προσδεχομένων μήτε κατὰ τοῦ Καίσαρός τι ψηφισθείη (πολλὰ γὰρ ἐπ’ αὐτῷ ὑπὸ πολλῶν ἐγράφετο) καὶ αὐτὸς ἐπὶ τῇ προφάσει ταύτῃ", "st": "40.61"}, {"sp": "N", "t": "μετασταίη. συχνὸν οὖν ἐκ τούτου χρόνον ἄλλοτε ἄλλαις σκήψεσιν, ὥστε μηδὲν αὐτῶν τὸ παράπαν κυρωθῆναι, κατατρίψας ἀγανακτεῖν τε προσεποιεῖτο, καὶ ἠξίου μῆνα ἄλλον πρὸς τὰς ὑπ’ αὐτῶν δὴ νομοθεσίας ἐπεμβληθῆναι. τοῦτο δὲ ἐγίγνετο μὲν ὁσάκις γε καὶ καθῆκον ἦν, οὐ μέντοι καὶ κατ’ ἐκεῖνο συνέβαινεν, ὥσπερ που καὶ αὐτὸς ἅτε ποντίφιξ ὢν ἠπίστατο. ὅμως δ’ οὖν δεῖν τε αὐτὸ γενέσθαι ἔλεγε, καὶ τοὺς συνιερέας ὅσον ἀπὸ βοῆς ἐξεβιάζετο· καὶ τέλος μὴ δυνηθεὶς αὐτοὺς πεῖσαι συγκαταθέσθαι οἱ, ὥσπερ οὐδὲ ἐβούλετο, οὐδ’ ἄλλο τι διὰ τοῦτο ψηφισθῆναι ἐπέτρεψεν, ἀλλὰ καὶ ἐκ τοῦ φανεροῦ ἤδη τὰ τοῦ Καίσαρος διαδικαιῶν, ἐπειδὴ μηδὲν κατ’ αὐτοῦ δῆθεν ἠδυνήθη ποιῆσαι, πᾶν ὅ τι ποτὲ ἐνεδέχετο οὐ δεχθῆναι προΐσχετο, καὶ μάλισθ’ ὅτι πάντας τοὺς τὰ ὅπλα ἔχοντας ταῦτά τε καταθέσθαι καὶ τὰ στρατόπεδα διαλῦσαι χρή, ἢ μηδ’ ἐκεῖνον ψιλώσαντας αὐτῶν ταῖς δυνάμεσι ταῖς τῶν ἀντιστασιωτῶν ἐκδοῦναι. ἔλεγε δὲ τοῦτο οὐχ ὅτι καὶ τὸν Καίσαρα ποιῆσαι αὐτὸ ἤθελεν, ἀλλ’ ὅτι τὸν Πομπήιον εὖ ἠπίστατο μὴ πειθαρχήσοντα αὐτῷ· καὶ ἐκ τούτου καὶ ἐκείνῳ πρόφασις εὔλογος τοῦ μὴ διιέναι τοὺς στρατιώτας ἐδίδοτο.", "st": "40.62"}, {"sp": "N", "t": "ὁ οὖν Πομπήιος ἐπεὶ μηδὲν ἄλλως πράττων ἤνυτε, πρός τε τὸ τραχὺ ἀπαρακαλύπτως ὥρμησε, καὶ ἐκ τοῦ προφανοῦς πάντα καὶ ἔλεγε καὶ ἐποίει κατὰ τοῦ Καίσαρος. οὐ μέντοι καὶ κατέπραξέ τι. ἄλλοι τε γὰρ ἐκείνῳ πολλοὶ καὶ Λούκιος Παῦλος ὁ τοῦ Μαρκέλλου συνάρχων, ὁ τε Πίσων ὁ Λούκιος ὁ πενθερὸς αὐτοῦ τιμητὴς ὢν συνηγωνίζοντο· καὶ γὰρ τιμηταὶ τὸν χρόνον τοῦτον ὅ τε Κλαύδιος ὁ Ἄππιος καὶ ὁ Πίσων, καίτοι μὴ βουληθείς, ἐγένοντο. καὶ οὗτος μὲν διὰ τὴν συγγένειαν ὑπῆρχε τῷ Καίσαρι, ὁ δὲ δὴ Κλαύδιος ἠναντιοῦτο μὲν αὐτῷ (τὰ γὰρ τοῦ Πομπηίου ᾑρεῖτο), οὐκ ἐλάχιστα δὲ καὶ ἄκων ὠφέλησε· πλείστους γὰρ καὶ τῶν ἱππέων καὶ τῶν βουλευτῶν διέγραψεν, ἐκβιασάμενος τὸν συνάρχοντα, κἀκ τούτου πάντας αὐτοὺς τὰ τοῦ Καίσαρος φρονεῖν ἐποίησεν. ὁ γὰρ Πίσων οὔτ’ ἄλλως πράγματ’ ἔχειν ἐθέλων καὶ πρὸς τὴν τοῦ γαμβροῦ φιλίαν πολλοὺς θεραπεύων αὐτὸς μὲν οὐδὲν τοιοῦτον ἐποίησεν, ἐκείνῳ δὲ οὐκ ἀντέπραξε πάντας μὲν τοὺς ἐκ τῶν ἀπελευθέρων συχνοὺς δὲ καὶ τῶν πάνυ γενναίων, ἄλλους τε καὶ τὸν Κρίσπον τὸν Σαλούστιον τὸν τὴν ἱστορίαν γράψαντα, ἀπελάσαντι ἐκ τοῦ συνεδρίου. τὸν μέντοι Κουρίωνα μελλήσαντα καὶ αὐτὸν ἀπαλειφθήσεσθαι ἐξῃτήσατο μετὰ τοῦ Παύλου, οὗπερ", "st": "40.63"}, {"sp": "N", "t": "συγγενὴς ἦν· καὶ ὃς οὐκ ἀπήλλαξε μὲν αὐτὸν διὰ τοῦτο, τὴν μέντοι γνώμην ἣν περὶ αὐτοῦ εἶχεν ἐδημοσίευσεν ἐν τῷ βουλευτηρίῳ, ὥστε ἐκεῖνον ἀγανακτήσαντα τὴν ἐσθῆτα αὐτοῦ περιρρῆξαι. παραλαβὼν οὖν τοῦτον ὁ Μάρκελλος, καὶ νομίσας ἐπί τε τῷ Κουρίωνι καὶ δι’ αὐτὸν καὶ ἐπὶ τῷ Καίσαρι δεινόν τι τὴν γερουσίαν ψηφιεῖσθαι, γνώμας περὶ αὐτοῦ προέθηκεν. ὁ οὖν Κουρίων τὸ μὲν πρῶτον ἠναντιοῦτο μηδεμίαν περὶ αὑτοῦ γνώμην δοθῆναι· γνοὺς δὲ τὸ πολὺ τῶν βουλευτῶν τῶν τότε παρόντων τοὺς μὲν καὶ φρονοῦντας ὄντως τὰ τοῦ Καίσαρος τοὺς δὲ πάνυ αὐτὸν δεδιότας, ἐπέτρεψέ σφισι διαγνῶναι, τοσοῦτον ὑπειπὼν ὅτι σύνοιδα μὲν ἐμαυτῷ τά τε ἄριστα καὶ τὰ συμφορώτατα τῇ πατρίδι πράττοντι, ὑμῖν μέντοι καὶ τὸ σῶμα καὶ τὴν ψυχὴν παραδίδωμι χρήσασθαι ὅ τι βούλεσθε. κατηγορήσας οὖν αὐτοῦ ὁ Μάρκελλος ὡς καὶ πάντως ἁλωσομένου, ἔπειτ’ ἐπειδὴ πρὸς τῶν πλειόνων ἀφείθη, δεινόν τε ἐποιήσατο καὶ ἐκπηδήσας ἐκ τοῦ συνεδρίου πρὸς τὸν Πομπήιον ἐν τῷ προαστείῳ ὄντα ἦλθε, καὶ τήν τε φυλακὴν αὐτῷ τῆς πόλεως καὶ δύο στρατόπεδα πολιτικά αὐτὸς καθ’ ἑαυτόν, μηδενὸς ἐψηφισμένου, ἔδωκεν. οἱ δὲ δὴ στρατιῶται οὗτοι ὧδέ τε καὶ ἐπὶ τῷδε", "st": "40.64"}, {"sp": "N", "t": "συνειλεγμένοι καὶ παρόντες τότε ἦσαν. ὁ Πομπήιος πρότερον μέν, ἕως ἔτι τὸν Καίσαρα διὰ φιλίας εἶχε, στράτευμα ἓν τῶν ἐκ τοῦ καταλόγου αὐτῷ στρατευομένῳ ἐδεδώκει (οὔτε γὰρ οὗτος πόλεμόν τινα διεχείριζε, καὶ ἐκείνῳ χρεία στρατιωτῶν ἐγένετο), ἐπεὶ δὲ διηνέχθησαν, ἐθελήσας τοῦτό τε ἀπολαβεῖν παρ’ αὐτοῦ καὶ ἔτι καὶ ἄλλο αὐτὸν προσαφελέσθαι ἐλογοποίησεν ὡς τοῦ Βιβούλου στρατιωτῶν πρὸς τοὺς Πάρθους δεομένου, καὶ ἵνα γε μὴ καινοὶ δή τινες κατάλογοι γένωνται (τό τε γὰρ πρᾶγμα κατεπείγειν καὶ περιουσίαν σφίσι στρατοπέδων εἶναι ἔλεγε), ψηφισθῆναι ἐποίησεν ὥστε ἑκάτερόν σφων, ἑαυτόν τε καὶ τὸν Καίσαρα, ἓν δεῖν αὐτῷ πέμψαι. κἀκ τούτου τῶν μὲν συστρατευομένων οἱ οὐδένα ἀπέστειλε, τὸ δὲ δὴ στράτευμα ἐκεῖνο ὅπερ τῷ Καίσαρι ἐδεδώκει ἐκέλευσε τοῖς ἐπὶ τοῦτο ταχθεῖσιν αἰτῆσαι. καὶ οὕτω τῷ μὲν λόγῳ ἀμφότεροι, τὸ δ’ ἀληθὲς ὁ Καῖσαρ μόνος τὰ δύο ἔπεμψεν· ᾔδει μὲν γὰρ τὸ γιγνόμενον, ἐπειθάρχησε δὲ μὴ βουληθεὶς αἰτίαν ὡς καὶ ἀνηκουστηκὼς λαβεῖν, ἄλλως τε καὶ μέλλων ἐπὶ τῇ προφάσει ταύτῃ πολλῷ πλείους στρατιώτας ἀντικαταλέξειν.", "st": "40.65"}, {"sp": "N", "t": "ταῦτα οὖν τὰ στρατόπεδα παρεσκευάσθη μὲν ὡς καὶ ἐπὶ τοὺς Πάρθους πεμφθησόμενα, ἐπεὶ δ’ οὐδὲν αὐτῶν ἐδέησε (οὐδὲ γὰρ χρεία σφῶν ἦν), ὁ Μάρκελλος πρότερον μέν, φοβηθεὶς μὴ τῷ Καίσαρι ἀποδοθῇ, ἐν τῇ Ἰταλίᾳ δεῖν εἶναι ἔλεγεν, τότε δὲ τῷ Πομπηίῳ, ὥσπερ εἶπον, ἐνεχείρισε. καὶ ἦν γὰρ ἐπ’ ἐξόδῳ τοῦ ἔτους τὰ γιγνόμενα, καὶ ἔμελλεν οὐκ ἐπὶ πολύ, ἅτε μήτε τῇ βουλῇ μήτε τῷ δήμῳ δόξαντα, ἰσχύσειν, ἐπήγετο πρὸς τὸν Πομπήιον Κορνήλιόν τε Λέντουλον καὶ Γάιον Κλαύδιον τοὺς τῷ ὑστέρῳ ἔτει ὑπατεύσειν μέλλοντας, καὶ ἐποίησε καὶ ἐκείνους τὰ αὐτὰ προστάξαι· ἐπειδὴ γὰρ καὶ γράμματα τοῖς ἀποδεδειγμένοις ἐς τὰς ἀρχὰς ἐκτιθέναι καὶ ἄλλα τινὰ τῶν τῇ ἡγεμονίᾳ σφῶν προσηκόντων, καὶ πρὶν ἐνίστασθαι αὐτήν, πράττειν ἔτι καὶ τότε ἐξῆν, καὶ τούτου κύριοι ἐνόμιζον εἶναι. καὶ ὅ γε Πομπήιος, καίπερ ἐς πάντα τἆλλα ἀκριβὴς ὤν, ὅμως οὐδὲν διὰ τὴν στρατιωτῶν χρείαν ἐπολυπραγμόνησεν, οὔτε ἀφ’ ὧν οὔθ’ ὅπως αὐτοὺς λαμβάνει, ἀλλὰ καὶ πάνυ ἄσμενός σφας ἐδέξατο. οὐ μέντοι καὶ ἐπράχθη τι οἷον ἄν τις ἐπὶ τηλικούτῳ τολμήματι γενήσεσθαι προσεδόκησεν, ἀλλὰ τὴν ἔχθραν μόνον τὴν πρὸς τὸν Καίσαρα ἐνδειξάμενοι αὐτοὶ μὲν οὐδὲν ἄλλο ἰσχυρὸν παρεσκευάσαντο, ἐκείνῳ δὲ καὶ ἐκ τούτου πρόφασιν εὔλογον ἐς τὸ τὰ στρατόπεδα τὰ συνόντα οἱ κατασχεῖν παρέσχον. ὁ γὰρ Κουρίων ἐπί τε τούτοις πολλὴν ἐν τῷ πλήθει κατηγορίαν κατά τε τῶν ὑπάτων καὶ κατὰ τοῦ Πομπηίου ἐποιήσατο, καὶ ἐπειδὴ διῆρξε, πρὸς τὸν Καίσαρα εὐθὺς ἀφωρμήθη.", "st": "40.66"}], []);})();
